// src/Access.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Challenge\Secret;
use CjwNetwork\RequestShield\Store\Store;

if (true) {
/**
 * Who may read the statistics (proposal 0023, phase 4): the admin ('*')
 * everything, a principal (a customer) only what the pages let it see. Three ways in:
 *
 *  - a token, once, by the login form: a signed session cookie for
 *    dashboard-session (8 hours); the token never in an address;
 *  - a signed link the customer's own hosting panel or CMS makes on its
 *    server (Access::link(), 10 minutes, at most an hour): opened, it sets the
 *    cookie and redirects to the address without the signature;
 *  - Authorization: Bearer <token>, for the JSON.
 *
 * Only tokens' SHA-256 hashes are in the rule file (dashboard-access); a token is
 * 32 random bytes, so a fast hash is enough (a slow one is for passwords
 * people choose). Wrong tokens and signatures count against a budget of their
 * own (10 a minute per address, then 429) and are logged without the token.
 * Without dashboard-access lines nothing is asked: the site's own rules (restrict)
 * decide, as before.
 */
final class Access
{
    public const COOKIE = 'rsd';

    /** Wrong tokens or signatures a minute per address before 429. */
    public const TRIES = 10;

    /** The longest a signed link may last, in seconds. */
    public const LINK_MAX = 3600;

    private const T = [
        'en' => [
            'title' => 'Statistics', 'intro' => 'Please sign in with the access token you were given.', 'token' => 'Access token', 'go' => 'Sign in',
            'wrong' => 'That token is not right (or no longer valid).', 'link' => 'That link is not right, or it has expired -- ask for a new one.',
            'many' => 'Too many tries from this address -- please wait a minute.', 'out' => 'Signed out.', 'origin' => 'This form can only be sent from this page.',
            'signout' => 'Sign out',
        ],
        'de' => [
            'title' => 'Statistik', 'intro' => 'Bitte mit dem Zugangs-Token anmelden, das Sie bekommen haben.', 'token' => 'Zugangs-Token', 'go' => 'Anmelden',
            'wrong' => 'Dieses Token stimmt nicht (oder gilt nicht mehr).', 'link' => 'Dieser Link stimmt nicht oder ist abgelaufen -- bitte einen neuen anfordern.',
            'many' => 'Zu viele Versuche von dieser Adresse -- bitte eine Minute warten.', 'out' => 'Abgemeldet.', 'origin' => 'Dieses Formular kann nur von dieser Seite gesendet werden.',
            'signout' => 'Abmelden',
        ],
    ];

    /** Whether the dashboard asks who is reading (dashboard-access lines are there). */
    public static function enabled(Settings $s): bool
    {
        return $s->dashboardAccess !== [];
    }

    /**
     * A new token: 32 random bytes, URL-safe -- and the SHA-256 the rule file keeps.
     *
     * @return array{0: string, 1: string}
     */
    public static function token(): array
    {
        $token = rtrim(strtr(base64_encode(random_bytes(32)), '+/', '-_'), '=');
        return [$token, hash('sha256', $token)];
    }

    /** Whose a token is ('*' or a principal's id), or null. */
    public static function whoseToken(Settings $s, string $token): ?string
    {
        if ($token === '' || strlen($token) > 200) {
            return null;
        }
        $hash = hash('sha256', $token);
        $who = null;
        foreach ($s->dashboardAccess as $a) {
            if (hash_equals($a['hash'], $hash)) {
                $who = $a['who'];                      // no early return: every line compared
            }
        }
        return $who;
    }

    /**
     * A signed link's query for a principal (or '*'), made on the customer's
     * panel or CMS with the shared secret -- no token in it, valid $ttl
     * seconds (at most an hour). The principal is opaque to the shield: what
     * it may see is the pages' business (the statistics: its group's websites).
     */
    public static function link(Settings $s, string $principal, int $ttl = 600, ?int $now = null): string
    {
        $who = $principal === '*' ? '*' : Settings::principal($principal);
        $exp = ($now ?? time()) + max(1, min(self::LINK_MAX, $ttl));
        return http_build_query(['rs-g' => $who, 'rs-exp' => $exp, 'rs-sig' => self::sign($s, "link|$who|$exp")]);
    }

    /**
     * The answer to a request for a dashboard page: who reads ('*', a
     * principal's id), or a page to send instead (the login form, a redirect, 429).
     *
     * @param array<mixed> $get $_GET
     * @param array<mixed> $post $_POST
     * @param array<string, mixed> $o store, now, lang, accept, action (the page's address), home, homeLabel, always (ask even without dashboard-access lines),
     *                                admin (the site's own login says this reader is the admin -- a CMS's signed-in administrator; a customer's
     *                                cookie or link still wins, and ?rs-login=1 shows the form)
     * @return array{who: ?string, status: int, headers: list<string>, body: ?string}
     */
    public static function gate(Settings $s, Request $request, array $get, array $post, array $o = []): array
    {
        $now = is_int($o['now'] ?? null) ? $o['now'] : time();
        $headers = self::headers($s);
        if (!self::enabled($s) && !($o['always'] ?? false)) {
            return self::answer('*', 200, $headers, null);
        }
        $store = ($o['store'] ?? null) instanceof Store ? $o['store'] : Shield::storeFor($s);
        $lang = Texts::language(is_string($o['lang'] ?? null) ? $o['lang'] : 'auto', is_string($o['accept'] ?? null) ? $o['accept'] : $request->header('accept-language'));
        $lang = $lang === 'de' ? 'de' : 'en';
        $t = self::T[$lang];
        $here = self::without((string) ($request->rawUri), ['rs-g', 'rs-exp', 'rs-sig', 'rs-logout']);
        $bucket = 'access:' . IpAddress::bucket($request->clientIp, $s->ipv6Prefix);
        $tooMany = static fn (): bool => $store->peek($bucket, 60, (float) $now) >= self::TRIES;
        $wrong = static function (string $why) use ($s, $request, $store, $bucket, $now): void {
            $store->hit($bucket, 60, (float) $now);
            Log::note($s, $request, Decision::reject(401, 'access'), $why, (float) $now);
        };
        $page = static fn (int $status, string $message, string ...$more): array => self::answer(null, $status, array_merge($headers, array_values($more)), self::page($s, $lang, $message, $here, ['status' => $status] + $o));

        if (isset($get['rs-logout'])) {
            return $page(200, $t['out'], self::cookieHeader($s, '', 1, $request));
        }
        // A signed link from the customer's own panel: the cookie, then the address without the signature.
        if (isset($get['rs-sig'])) {
            if ($tooMany()) {
                return $page(429, $t['many'], 'Retry-After: 60');
            }
            $who = self::fromLink($s, $get, $now);
            if ($who === null) {
                $wrong('dashboard-access link');
                return $page(403, $t['link']);
            }
            return self::answer(null, 303, array_merge($headers, [self::cookieHeader($s, $who, $now + $s->dashboardSession, $request), 'Location: ' . $here]), null);
        }
        // The login form: a token, by POST, from this very page.
        if (isset($post['rs-token'])) {
            if ($tooMany()) {
                return $page(429, $t['many'], 'Retry-After: 60');
            }
            $origin = (string) $request->header('origin');
            if ($origin !== '' && strcasecmp((string) parse_url($origin, PHP_URL_HOST), (string) preg_replace('/:\d+$/', '', $request->host)) !== 0) {
                return $page(403, $t['origin']);
            }
            $who = self::whoseToken($s, is_string($post['rs-token']) ? trim($post['rs-token']) : '');
            if ($who === null) {
                $wrong('dashboard-access token');
                return $page(401, $t['wrong']);
            }
            return self::answer(null, 303, array_merge($headers, [self::cookieHeader($s, $who, $now + $s->dashboardSession, $request), 'Location: ' . $here]), null);
        }
        // A program: Authorization: Bearer <token>.
        $auth = (string) $request->header('authorization');
        if (strncasecmp($auth, 'Bearer ', 7) === 0) {
            if ($tooMany()) {
                return self::answer(null, 429, array_merge($headers, ['Retry-After: 60']), null);
            }
            $who = self::whoseToken($s, trim((string) substr($auth, 7)));
            if ($who === null) {
                $wrong('dashboard-access bearer');
                return self::answer(null, 401, $headers, null);
            }
            return self::answer($who, 200, $headers, null);
        }
        $who = self::fromCookie($s, (string) $request->cookie(self::COOKIE), $now);
        if ($who !== null) {
            return self::answer($who, 200, $headers, null);
        }
        if (($o['admin'] ?? false) === true && !isset($get['rs-login'])) {
            return self::answer('*', 200, $headers, null);       // the site knows its administrator
        }
        return $page(401, $t['intro']);
    }

    /**
     * @param list<string> $headers
     * @return array{who: ?string, status: int, headers: list<string>, body: ?string}
     */
    private static function answer(?string $who, int $status, array $headers, ?string $body): array
    {
        return ['who' => $who, 'status' => $status, 'headers' => $headers, 'body' => $body];
    }

    /** Who a session cookie says (checked: its signature, its end, the tokens it was made with), or null. */
    public static function fromCookie(Settings $s, string $value, ?int $now = null): ?string
    {
        if (preg_match('/^(\*|[a-z0-9-]{1,61})\.(\d{1,12})\.([0-9a-f]{8})\.([0-9a-f]{32})$/', $value, $m) !== 1) {
            return null;
        }
        [, $who, $exp, $gen, $sig] = $m;
        if ((int) $exp < ($now ?? time()) || !hash_equals(self::sign($s, "session|$who|$exp|$gen"), $sig) || !hash_equals(self::generation($s, $who), $gen)) {
            return null;
        }
        return $who;
    }

    /**
     * Who a signed link says, or null (wrong, expired, or longer than an hour).
     *
     * @param array<mixed> $get
     */
    public static function fromLink(Settings $s, array $get, ?int $now = null): ?string
    {
        $who = is_string($get['rs-g'] ?? null) ? $get['rs-g'] : '';
        $exp = is_string($get['rs-exp'] ?? null) && ctype_digit($get['rs-exp']) ? (int) $get['rs-exp'] : 0;
        $sig = is_string($get['rs-sig'] ?? null) ? $get['rs-sig'] : '';
        $now ??= time();
        if (($who !== '*' && preg_match('/^[a-z0-9][a-z0-9-]{0,60}$/', $who) !== 1) || $exp < $now || $exp > $now + self::LINK_MAX || !hash_equals(self::sign($s, "link|$who|$exp"), $sig)) {
            return null;
        }
        return $who;
    }

    /**
     * The dashboard's tabs for a reader: the admin ('*') gets every link, a
     * customer the pages whose route is a reader's (its statistics: all its
     * websites, visitors and pages, the protection) -- never Rules & setup,
     * the overview of the server, the live view or the lists.
     *
     * @param array<string, string> $links
     * @return array<string, string>
     */
    public static function links(Settings $s, string $who, array $links): array
    {
        if ($who === '*') {
            return $links;
        }
        $reader = [];
        foreach ($s->routes as $r) {
            if ($r['role'] === 'reader') {
                $reader[$r['key']] = 1;
            }
        }
        return array_intersect_key($links, $reader);
    }

    /**
     * The headers every statistics page sends: never indexed, never kept, never framed elsewhere.
     *
     * @return list<string>
     */
    public static function headers(Settings $s): array
    {
        return ['X-Robots-Tag: noindex, nofollow', 'Cache-Control: private, no-store', 'Referrer-Policy: same-origin', "Content-Security-Policy: frame-ancestors 'self'"];
    }

    /** The Set-Cookie header: who, until when, signed; HttpOnly, SameSite=Lax (a signed link arrives from another site), Secure on HTTPS. */
    private static function cookieHeader(Settings $s, string $who, int $until, Request $request): string
    {
        $value = $who === '' ? '' : $who . '.' . $until . '.' . self::generation($s, $who) . '.' . self::sign($s, "session|$who|$until|" . self::generation($s, $who));
        return 'Set-Cookie: ' . self::COOKIE . '=' . $value . '; Path=/; Max-Age=' . ($who === '' ? 0 : max(0, $until - time())) . '; HttpOnly; SameSite=Lax'
            . ($request->scheme === 'https' ? '; Secure' : '');
    }

    /** The tokens a reader's sessions were made with: a token removed or changed ends them. */
    private static function generation(Settings $s, string $who): string
    {
        $hashes = [];
        foreach ($s->dashboardAccess as $a) {
            if ($a['who'] === $who) {
                $hashes[] = $a['hash'];
            }
        }
        sort($hashes);
        return substr(hash('sha256', $who . '|' . implode(',', $hashes)), 0, 8);
    }

    private static function sign(Settings $s, string $data): string
    {
        return substr(hash_hmac('sha256', 'stats|' . $data, Secret::resolve($s->challenge->secret, $s->storeDir)), 0, 32);
    }

    /** @param list<string> $drop */
    private static function without(string $uri, array $drop): string
    {
        $q = strpos($uri, '?');
        if ($q === false) {
            return $uri;
        }
        parse_str((string) substr($uri, $q + 1), $params);
        foreach ($drop as $d) {
            unset($params[$d]);
        }
        return substr($uri, 0, $q) . ($params === [] ? '' : '?' . http_build_query($params));
    }

    /** @param array<string, mixed> $o */
    private static function page(Settings $s, string $lang, string $message, string $action, array $o): string
    {
        $t = self::T[$lang];
        $e = static fn (string $v): string => htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $body = '<form class="card" method="post" action="' . $e($action) . '" style="max-width:520px">'
            . '<p>' . $e($message) . '</p><label>' . $e($t['token']) . '<br><input type="password" name="rs-token" autocomplete="current-password" required style="width:100%"></label>'
            . '<p><button class="primary">' . $e($t['go']) . '</button></p></form>';
        $title = is_string($o['title'] ?? null) ? $o['title'] : $t['title'];
        // The site's own login form (the Pages hook, 0031 B.10), else the shield's.
        return PageHook::ask($s, Pages::ACCESS_LOGIN, ['status' => is_int($o['status'] ?? null) ? $o['status'] : 401, 'message' => $message, 'action' => $action, 'lang' => $lang, 'texts' => $t,
            'home' => $o['home'] ?? null, 'homeLabel' => $o['homeLabel'] ?? null, 'title' => $title]) ?? Frame::page($title, $lang, $body, $o + ['help' => \CjwNetwork\RequestShield\Help::link('RSF06-03', 'who-sees-what-tokens-a-login-signed-links', $s->docsUrl, $lang)]);
    }

    /** A sign-out link for the pages: the current address with rs-logout. */
    public static function signOut(string $uri, string $lang = 'en'): string
    {
        $t = self::T[$lang === 'de' ? 'de' : 'en'];
        $url = self::without($uri, ['rs-logout']);
        return '<a href="' . htmlspecialchars($url . (strpos($url, '?') === false ? '?' : '&') . 'rs-logout=1', ENT_QUOTES) . '">' . htmlspecialchars($t['signout'], ENT_QUOTES) . '</a>';
    }
}
}
}

// src/ApiProblem.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * An answer of the API that is no data: a problem, as RFC 9457 has it --
 * status, a short title, the detail in one sentence. Thrown by a service,
 * answered by the API plugin as application/problem+json.
 */
final class ApiProblem extends \RuntimeException
{
    public int $status;
    public string $title;
    public function __construct(
        int $status,
        string $title,
        string $detail = ''
    ) {
        /** @readonly */
        $this->status = $status;
        /** @readonly */
        $this->title = $title;
        parent::__construct($detail);
    }

    /** @return array{type: string, title: string, status: int, detail: string} the body */
    public function body(): array
    {
        return ['type' => 'about:blank', 'title' => $this->title, 'status' => $this->status, 'detail' => $this->getMessage()];
    }
}
}
}

// src/ApiProvider.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * An extension that offers endpoints to the API (RSF06-05, 0031 G.0): the
 * API plugin (plugins/api) asks every offered extension that implements it
 * when the rules are compiled, and serves what they return below
 * <dashboard-path>/api/v1. Static, like Extension: nothing runs per request.
 */
interface ApiProvider
{
    /** @return list<Endpoint> */
    public static function api(): array;
}
}
}

// src/ApiService.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * What answers an endpoint of the API (RSF06-05): it gets the settings in
 * force, the parameters (the query of a GET, the JSON body of a POST) and
 * who asks, and returns the "data" of the answer -- or throws an ApiProblem.
 * It never writes output; it counts nothing unless it is a write.
 */
interface ApiService
{
    /**
     * @param array<string, mixed> $params
     * @param array{who: string, ruleFile: ?string, now: int, ip: string, lang: string} $ctx who: '*' (the administrator) or a group's id;
     *   ruleFile: the main rule file the shield runs from (null: settings from a PHP array)
     * @return array<mixed>
     */
    public static function handle(Settings $s, array $params, array $ctx): array;
}
}
}

// src/Budget.php
namespace CjwNetwork\RequestShield {
if (true) {
/** One budget: requests (or events) per client and window. */
final class Budget
{
    public string $name;
    public int $limit;
    public int $window;
    public ?int $challengeAt;
    public bool $onDemand;
    public bool $earnBack = false;
    public ?string $site = null;
    /**
     * @var list<string>
     */
    public array $paths = [];
    /** @param list<string> $paths */
    private function __construct(string $name, int $limit, int $window, ?int $challengeAt, bool $onDemand, bool $earnBack = false, ?string $site = null, array $paths = [])
    {
        /** @readonly */
        $this->name = $name;
        /** @readonly */
        $this->limit = $limit;
        /** @readonly */
        $this->window = $window;
        /** @readonly */
        $this->challengeAt = $challengeAt;
        /** @readonly */
        $this->onDemand = $onDemand;
        /** @readonly past the limit: false a pause (429), true the browser check that frees the counter */
        $this->earnBack = $earnBack;
        /** @readonly the site block it is written in (rules per website): counted on that website only; null: across all */
        $this->site = $site;
        /**
         * The area (limit inside a match block, or "at <paths>"): only requests there count; [] everywhere.
         *
         * @readonly
         * @var list<string>
         */
        $this->paths = $paths;
    }

    /** Whether a request to this path counts: everywhere, or inside the budget's area. */
    public function covers(string $matchPath): bool
    {
        foreach ($this->paths as $p) {
            if (preg_match($p, $matchPath) === 1) {
                return true;
            }
        }
        return $this->paths === [];
    }

    /** The counter's name: the budget's -- for one written in a site block, "<site>@<name>", so equal names in two blocks never share a counter. */
    public function counter(): string
    {
        return $this->site === null ? $this->name : $this->site . '@' . $this->name;
    }

    /**
     * @param array<mixed> $b
     * @return self|null null for a budget that is switched off (limit 0)
     */
    public static function from(string $name, array $b, bool $strict = false): ?self
    {
        $limit = Settings::int($b, 'limit', "budgets.$name.limit");
        if ($limit <= 0) {
            return null;
        }
        $challengeAt = Settings::intOrNull($b, 'challengeAt', "budgets.$name.challengeAt");
        // strict: the check from a quarter of the limit, unless the budget says when.
        if ($strict && ($challengeAt === null || $challengeAt <= 0)) {
            $challengeAt = max(1, intdiv($limit, 4));
        }
        return new self(
            $name,
            $limit,
            max(1, Settings::int($b, 'window', "budgets.$name.window", 60)),
            $challengeAt !== null && $challengeAt > 0 ? $challengeAt : null,
            Settings::bool($b, 'onDemand', "budgets.$name.onDemand"),
            self::onExceeded($b, $name),
            is_string($b['site'] ?? null) ? $b['site'] : null,
            self::paths($b, $name),
        );
    }

    /**
     * @param array<mixed> $b
     * @return list<string>
     */
    private static function paths(array $b, string $name): array
    {
        $paths = $b['paths'] ?? [];
        if (!is_array($paths)) {
            throw Settings::wrong("budgets.$name.paths", 'a list of regular expressions');
        }
        $out = [];
        foreach ($paths as $p) {
            if (!is_string($p) || @preg_match($p, '') === false) {
                throw Settings::wrong("budgets.$name.paths", 'a list of regular expressions (#^/search#)');
            }
            $out[] = $p;
        }
        return $out;
    }

    /** @param array<mixed> $b */
    private static function onExceeded(array $b, string $name): bool
    {
        $v = Settings::string($b, 'onExceeded', "budgets.$name.onExceeded", 'throttle');
        if ($v !== 'throttle' && $v !== 'challenge') {
            throw Settings::wrong("budgets.$name.onExceeded", 'throttle (a pause, the default) or challenge (the check that frees the counter)');
        }
        return $v === 'challenge';
    }

    /** @return array<string, mixed> */
    public function export(): array
    {
        /** @var array<string, mixed> */
        return get_object_vars($this);
    }

    /** @param array<string, mixed> $e what export() returned (trusted: no checks) */
    public static function import(array $e): self
    {
        // Positional, in declaration order (what export() returns): unpacking
        // string keys into named arguments needs PHP 8.1.
        /** @phpstan-ignore argument.type */
        return new self(...array_values($e));
    }
}
}
}

// src/Capability.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * What this PHP can do (ADR 0013): asked in one place, so every use of an
 * optional extension sits behind the same check and has a way without it.
 */
final class Capability
{
    /** APCu, enabled for this SAPI (the CLI needs apc.enable_cli=1). */
    public static function apcu(): bool
    {
        return function_exists('apcu_enabled') && apcu_enabled();
    }
}
}
}

// src/Challenge/ChallengeLogo.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * The picture in the middle of the check page's ring: a plain shield, or the
 * site's own logo (set challenge-logo logo.svg). A site's logo is read once,
 * when the settings are compiled, checked strictly -- an SVG is a document
 * that can carry scripts -- and inlined: no extra request, nothing per page.
 *
 * Refused: more than 16 KB, not well-formed XML, a DOCTYPE, a root other than
 * <svg>, <script>, <foreignObject>, <iframe>, <object>, <embed>, <style>
 * (it would style the whole page), on…= attributes, links other than local
 * "#…" fragments, "javascript:" anywhere in a value, url() other than
 * url(#…) and @import in a style, animations that change links or handlers.
 * IDs get a prefix, so the logo cannot take over the page's own.
 */
final class ChallengeLogo
{
    public const MAX_BYTES = 16384;

    /** Where the logo sits in the ring's 120 x 120 picture. */
    private const BOX = 'x="32" y="32" width="56" height="56"';

    /** A plain shield in the page's accent colour (currentColor): nobody's logo. */
    public const DEFAULT = '<svg ' . self::BOX . ' viewBox="0 0 24 26" class="d"><path d="M12 1.5 21.5 5.2V12c0 6.1-4 10.8-9.5 12.5C6.5 22.8 2.5 18.1 2.5 12V5.2Z" fill="currentColor" fill-opacity=".12" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M12 6.5 17 8.4V12c0 3.3-2 6-5 7.2-3-1.2-5-3.9-5-7.2V8.4Z" fill="currentColor" fill-opacity=".35"/></svg>';

    /**
     * The logo in $file, checked, as markup for the ring's middle.
     *
     * @throws \InvalidArgumentException naming $setting, with the reason
     */
    public static function load(string $file, string $setting): string
    {
        $size = @filesize($file);
        $svg = $size === false ? false : @file_get_contents($file);
        if ($svg === false) {
            throw new \InvalidArgumentException("$setting: cannot read the logo $file");
        }
        return self::check($svg, $setting);
    }

    /** @throws \InvalidArgumentException */
    public static function check(string $svg, string $setting): string
    {
        $no = static function (string $why) use ($setting): \InvalidArgumentException {
            return new \InvalidArgumentException("$setting: the logo is refused -- $why (a site's own logo must be an SVG it trusts, without scripts or outside links)");
        };
        if (strlen($svg) > self::MAX_BYTES) {
            throw $no('larger than 16 KB (' . strlen($svg) . ' bytes); simplify it, e.g. with svgo');
        }
        if (stripos($svg, '<!DOCTYPE') !== false || stripos($svg, '<!ENTITY') !== false) {
            throw $no('it has a DOCTYPE or entities');
        }
        if (!class_exists(\DOMDocument::class)) {
            throw $no('PHP has no DOM extension here to check it');
        }
        $doc = new \DOMDocument();
        $previous = libxml_use_internal_errors(true);
        try {
            $ok = $doc->loadXML($svg, LIBXML_NONET | LIBXML_NOBLANKS);
        } finally {
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
        }
        $root = $doc->documentElement;
        if (!$ok || $root === null) {
            throw $no('it is not well-formed XML');
        }
        if (strtolower((string) $root->localName) !== 'svg') {
            throw $no("its root is <{$root->localName}>, not <svg>");
        }
        $ids = [];
        foreach ($doc->getElementsByTagName('*') as $el) {
            $name = strtolower((string) $el->localName);
            if (in_array($name, ['script', 'foreignobject', 'iframe', 'object', 'embed', 'style', 'handler', 'listener'], true)) {
                throw $no("it has a <{$el->localName}> element" . ($name === 'style' ? ' (it would style the whole page; use attributes, e.g. svgo --enable=inlineStyles)' : ''));
            }
            foreach (iterator_to_array($el->attributes) as $attr) {
                /** @var \DOMAttr $attr */
                $a = strtolower((string) $attr->localName);
                $v = (string) $attr->value;
                $flat = strtolower((string) preg_replace('/[\s\x00-\x1f]+/', '', html_entity_decode($v, ENT_QUOTES | ENT_HTML5)));
                if (strncmp($a, 'on', 2) === 0) {
                    throw $no("it has an event handler ({$attr->nodeName}=…)");
                }
                if (($a === 'href' || $a === 'src') && strncmp($v, '#', 1) !== 0) {
                    throw $no("it links outside itself ({$attr->nodeName}=\"" . substr($v, 0, 40) . '")');
                }
                if (strpos($flat, 'javascript:') !== false || strpos($flat, 'vbscript:') !== false) {
                    throw $no("a value holds a script address ({$attr->nodeName})");
                }
                if ($a === 'style' && (preg_match('/url\((?!#)|url\(\s*[\'"](?!#)/', $flat) === 1 || strpos($flat, '@import') !== false || strpos($flat, 'expression(') !== false)) {
                    throw $no('a style loads something from outside (url(), @import)');
                }
                if (in_array($a, ['fill', 'stroke', 'filter', 'clip-path', 'mask', 'marker-start', 'marker-mid', 'marker-end'], true) && preg_match('/url\((?!#)/', $flat) === 1) {
                    throw $no("{$attr->nodeName} points outside (url())");
                }
                if ($a === 'attributename' && ($flat === 'href' || $flat === 'xlink:href' || strncmp($flat, 'on', 2) === 0)) {
                    throw $no('an animation changes a link or a handler');
                }
                if ($a === 'id') {
                    $ids[$v] = true;
                }
            }
        }
        // Where it goes and how large: its own viewBox, the ring's box.
        $viewBox = $root->getAttribute('viewBox');
        if ($viewBox === '') {
            $w = (float) $root->getAttribute('width');
            $h = (float) $root->getAttribute('height');
            if ($w <= 0 || $h <= 0) {
                throw $no('it has neither a viewBox nor a width and height');
            }
            $viewBox = "0 0 $w $h";
        }
        foreach (['x', 'y', 'width', 'height', 'viewBox', 'class', 'style'] as $a) {
            $root->removeAttribute($a);
        }
        // No comments or processing instructions in the page: nothing but the picture.
        $extra = (new \DOMXPath($doc))->query('//comment()|//processing-instruction()');
        foreach ($extra === false ? [] : iterator_to_array($extra) as $node) {
            if ($node instanceof \DOMNode && $node->parentNode !== null) {
                $node->parentNode->removeChild($node);
            }
        }
        // IDs prefixed (and their references), so the logo keeps its own.
        foreach ($doc->getElementsByTagName('*') as $el) {
            foreach (iterator_to_array($el->attributes) as $attr) {
                /** @var \DOMAttr $attr */
                $v = (string) $attr->value;
                if (strtolower((string) $attr->localName) === 'id') {
                    $attr->value = 'rsl-' . $v;
                } elseif ($ids !== [] && (strncmp($v, '#', 1) === 0 || strpos($v, 'url(#') !== false)) {
                    $attr->value = (string) preg_replace_callback('/(^#|url\(#)([^)\s]+)/', static fn (array $m): string => isset($ids[$m[2]]) ? $m[1] . 'rsl-' . $m[2] : $m[0], $v);
                }
            }
        }
        $markup = (string) $doc->saveXML($root);
        return (string) preg_replace('/^<svg\b/', '<svg ' . self::BOX . ' viewBox="' . htmlspecialchars($viewBox, ENT_QUOTES) . '"', $markup, 1);
    }
}
}
}

// src/Challenge/ChallengePage.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * The page a challenged client gets instead of the one it asked for: a few
 * kilobytes, no external resource, nothing to click. Its script finds the
 * proof of work, puts the solution in a cookie and loads the same URL again;
 * the shield checks it there, hands out the pass cookie and lets the request
 * through. Without JavaScript or cookies it says what is missing.
 *
 * The script is ES5 with its own SHA-256: crypto.subtle only exists on HTTPS
 * pages, and for strings this short plain JavaScript is faster anyway.
 */
final class ChallengePage
{
    /**
     * @param array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string} $challenge
     * @param array<string, string> $texts in the visitor's language (Texts::all()); missing ones in English
     * @param array{action: string, fields: list<array{0: string, 1: string}>}|false|null $resend
     *   a form that was sent without a pass: its fields, to send it again after the check;
     *   false when it cannot be (files, too large): the visitor is asked to send it again
     * @param string|null $logo the site's logo for the ring's middle (ChallengeLogo, checked when the settings were read); null: a plain shield
     * @param string|null $about where the check is explained for visitors (Help::explained(): set docs-url); null: no link
     */
    public static function render(array $challenge, string $cookieName, bool $secure, array $texts = [], $resend = null, ?string $home = null, ?string $logo = null, ?string $about = null): string
    {
        $t = $texts + \CjwNetwork\RequestShield\Texts::all('en');
        if ($resend !== null) {
            $t['text'] = $resend === false ? $t['resend-lost'] : $t['sending'];
        }
        $e = static fn (string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $js = static fn ($v): string => json_encode($v, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT);
        $config = $js([
            'resend' => is_array($resend),
            'back' => $resend === false,
            'c' => $challenge,
            'cookie' => $cookieName,
            'secure' => $secure,
            'nocookies' => $t['nocookies'],
            'failed' => $t['failed'],
        ]);

        return '<!doctype html><html lang="' . $e($t['lang']) . '"><head><meta charset="utf-8">'
            . '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow">'
            . '<title>' . $e($t['title']) . '</title><style>' . self::CSS . '</style></head><body><main>'
            . self::ring($logo)
            . '<h1>' . $e($t['title']) . '</h1><p id="m" role="status">' . $e($t['text']) . '</p>'
            . '<noscript><p><strong>' . $e($t['noscript']) . '</strong></p></noscript>'
            . self::resendForm($resend, $t, $e)
            . ($home !== null ? '<p class="home"><a href="' . $e($home) . '">' . $e($t['home']) . '</a></p>' : '')
            . ($about !== null ? '<p class="home"><a href="' . $e($about) . '" target="_blank" rel="noopener">' . $e($t['about']) . '</a></p>' : '')
            . '</main>'
            . '<script>var RS=' . $config . ';' . self::SCRIPT . '</script></body></html>';
    }

    /** The ring: its track, the arc that fills, the circling dot, the logo, the smile, the "!". */
    private static function ring(?string $logo): string
    {
        return '<svg id="r" viewBox="0 0 120 120" width="120" height="120" aria-hidden="true" focusable="false">'
            . '<circle class="t" cx="60" cy="60" r="52"/><circle id="b" class="f" cx="60" cy="60" r="52" transform="rotate(-90 60 60)"/>'
            . '<g class="o"><circle cx="60" cy="8" r="5"/></g>'
            . '<g class="l">' . ($logo ?? ChallengeLogo::DEFAULT) . '</g>'
            . '<g class="s"><circle cx="60" cy="60" r="27"/><circle class="e" cx="50" cy="54" r="3.2"/><circle class="e" cx="70" cy="54" r="3.2"/><path d="M47 66q13 12 26 0"/></g>'
            . '<g class="x"><path d="M60 43v20"/><circle cx="60" cy="75" r="3.4"/></g></svg>';
    }

    /**
     * The check page as a visitor sees it, for a page about it (the showcase): the same
     * ring, styles and words, no task and no cookie -- the ring fills and smiles three
     * times, then rests on the smile (no motion that goes on; with reduced motion only
     * the smile). A whole document, for an iframe's srcdoc.
     *
     * @param array<string, string> $texts in the visitor's language (Texts::all())
     */
    public static function preview(array $texts = [], ?string $logo = null): string
    {
        $t = $texts + \CjwNetwork\RequestShield\Texts::all('en');
        $e = static fn (string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        return '<!doctype html><html lang="' . $e($t['lang']) . '"><head><meta charset="utf-8"><title>' . $e($t['title']) . '</title>'
            . '<style>' . self::CSS . 'body{min-height:0;height:100vh}main{padding:1rem}</style></head><body><main>'
            . self::ring($logo)
            . '<h1>' . $e($t['title']) . '</h1><p>' . $e($t['text']) . '</p></main>'
            . '<script>(function(){var r=document.getElementById("r"),b=document.getElementById("b"),n=0;'
            . 'function show(p){b.style.strokeDashoffset=(326.7*(1-p)).toFixed(1);}'
            . 'if(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches){show(1);r.setAttribute("class","ok");return;}'
            . 'function once(){var t0=Date.now();r.setAttribute("class","run");show(0);'
            . 'var i=setInterval(function(){var p=Math.min(1,(Date.now()-t0)/2200);show(p);if(p>=1){clearInterval(i);r.setAttribute("class","ok");if(++n<3){setTimeout(once,2000);}}},50);}'
            . 'once();})();</script></body></html>';
    }

    /**
     * The ring fills with the solver's progress while a dot circles the logo;
     * done, the logo gives way to a smile; failed, a calm "!". Without
     * JavaScript nothing moves (the dot only circles once the script runs).
     * With prefers-reduced-motion: no circling, no fading -- the ring fills.
     */
    private const CSS = ':root{--bg:#f6f7f9;--fg:#222;--acc:#3b6fd4;--trk:#dde1e6;--ok:#1e7b43;--okbg:#e6f4ea;--warn:#a86b00}'
        . '@media(prefers-color-scheme:dark){:root{--bg:#16181c;--fg:#e6e6e6;--acc:#7aa2ff;--trk:#2b3038;--ok:#6fcf97;--okbg:#17301f;--warn:#e0b050}}'
        . 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;font:16px/1.5 system-ui,sans-serif;background:var(--bg);color:var(--fg)}'
        . 'main{max-width:28rem;padding:2rem;text-align:center}.home{margin-top:2rem;font-size:.9rem}.home a{color:inherit;opacity:.7}h1{font-size:1.3rem;margin:.8rem 0 .5rem}'
        . '#r{display:block;margin:0 auto;color:var(--acc);overflow:visible}.t,.f,#r .s path,#r .x path{fill:none;stroke-linecap:round}'
        . '.t{stroke:var(--trk);stroke-width:6}.f{stroke:var(--acc);stroke-width:6;stroke-dasharray:326.7;stroke-dashoffset:326.7;transition:stroke-dashoffset .25s,stroke .3s}'
        . '#r .o circle{fill:var(--acc);opacity:0}.o{transform-origin:60px 60px}#r.run .o circle{opacity:.9}.run .o{animation:rs-o 1.4s linear infinite}@keyframes rs-o{to{transform:rotate(1turn)}}'
        . '.l,.s,.x{transform-origin:60px 60px;transition:opacity .3s,transform .3s}.s,.x{opacity:0;transform:scale(.6)}'
        . '#r .s circle{fill:var(--okbg);stroke:var(--ok);stroke-width:3.5}#r .s .e{fill:var(--ok);stroke:none}#r .s path{stroke:var(--ok);stroke-width:3.5}'
        . '#r .x path{stroke:var(--warn);stroke-width:6}#r .x circle{fill:var(--warn)}'
        . '.ok .l,.no .l{opacity:0;transform:scale(.6)}.ok .s,.no .x{opacity:1;transform:none}.ok .f{stroke:var(--ok)}.no .f{stroke:var(--warn)}.ok .o,.no .o{display:none}'
        . '@media(prefers-reduced-motion:reduce){.run .o{animation:none}#r.run .o circle{opacity:0}.l,.s,.x,.f{transition:none}}';

    /**
     * The form that was sent, as hidden fields: the script sends it again once
     * the check is done; without JavaScript the button does. Nothing of it is
     * kept on the server.
     *
     * @param array{action: string, fields: list<array{0: string, 1: string}>}|false|null $resend
     * @param array<string, string> $t
     * @param \Closure(string): string $e
     */
    private static function resendForm($resend, array $t, \Closure $e): string
    {
        if ($resend === false) {
            return '<p><a href="javascript:history.back()" id="back" hidden>' . $e($t['back']) . '</a></p>';
        }
        if ($resend === null) {
            return '';
        }
        $h = '<form id="resend" method="post" action="' . $e($resend['action']) . '">';
        foreach ($resend['fields'] as [$name, $value]) {
            $h .= '<input type="hidden" name="' . $e($name) . '" value="' . $e($value) . '">';
        }
        return $h . '<noscript><button type="submit">' . $e($t['send-again']) . '</button></noscript></form>';
    }

    /** The solver. Kept in one place so tests can run exactly this code. */
    public const SCRIPT = <<<'JS'
(function (R) {
var K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
var W = new Array(64);
function sha256(s) {
var n = s.length, w = [], i, j, t;
for (i = 0; i < n; i++) { w[i >> 2] |= (s.charCodeAt(i) & 255) << (24 - (i % 4) * 8); }
w[n >> 2] |= 0x80 << (24 - (n % 4) * 8);
var len = (((n + 8) >> 6) + 1) * 16;
for (i = 0; i < len; i++) { w[i] = w[i] | 0; }
w[len - 1] = n * 8;
var h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a, h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;
for (j = 0; j < len; j += 16) {
var a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;
for (t = 0; t < 64; t++) {
if (t < 16) { W[t] = w[j + t]; }
else {
var x = W[t - 15], y = W[t - 2];
W[t] = (W[t - 16] + ((x >>> 7 | x << 25) ^ (x >>> 18 | x << 14) ^ (x >>> 3)) + W[t - 7] + ((y >>> 17 | y << 15) ^ (y >>> 19 | y << 13) ^ (y >>> 10))) | 0;
}
var t1 = (h + ((e >>> 6 | e << 26) ^ (e >>> 11 | e << 21) ^ (e >>> 25 | e << 7)) + ((e & f) ^ (~e & g)) + K[t] + W[t]) | 0;
var t2 = (((a >>> 2 | a << 30) ^ (a >>> 13 | a << 19) ^ (a >>> 22 | a << 10)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
}
h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
h4 = (h4 + e) | 0; h5 = (h5 + f) | 0; h6 = (h6 + g) | 0; h7 = (h7 + h) | 0;
}
var out = '', hs = [h0, h1, h2, h3, h4, h5, h6, h7];
for (i = 0; i < 8; i++) { out += ('0000000' + (hs[i] >>> 0).toString(16)).slice(-8); }
return out;
}
function b64url(s) { return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
function solve(c, done, progress) {
var n = 0, start = Date.now();
(function step() {
var end = Math.min(n + 4000, c.maxnumber);
for (; n <= end; n++) {
if (sha256(c.salt + n) === c.challenge) { return done(n, Date.now() - start); }
}
if (n > c.maxnumber) { return done(-1, 0); }
if (progress) { progress(n / c.maxnumber); }
setTimeout(step, 0);
})();
}
function payload(c, number, took) {
return b64url(JSON.stringify({ algorithm: c.algorithm, challenge: c.challenge, number: number, salt: c.salt, signature: c.signature, took: took }));
}
R.sha256 = sha256;
R.solve = solve;
R.payload = payload;
if (typeof document === 'undefined' || !R.c) { return; }
var m = document.getElementById('m'), ring = document.getElementById('r'), bar = document.getElementById('b');
function show(p) { if (bar && bar.style) { bar.style.strokeDashoffset = (326.7 * (1 - p)).toFixed(1); } }
function state(s) { if (ring && ring.setAttribute) { ring.setAttribute('class', s); } }
function failed(text) { m.textContent = text; state('no'); }
state('run');
var here = location.pathname + location.search, now = Date.now(), tries = 0;
try {
var last = JSON.parse(sessionStorage.getItem('rs-tries') || 'null');
if (last && last.u === here && now - last.t < 60000) { tries = last.n; }
sessionStorage.setItem('rs-tries', JSON.stringify({ u: here, n: tries + 1, t: now }));
} catch (e) {}
if (tries >= 3) { failed(R.failed); try { sessionStorage.removeItem('rs-tries'); } catch (e) {} return; }
solve(R.c, function (number, took) {
if (number < 0) { failed(R.failed); return; }
document.cookie = R.cookie + '=' + payload(R.c, number, took) + '; path=/; max-age=300; SameSite=Lax' + (R.secure ? '; Secure' : '');
if (document.cookie.indexOf(R.cookie + '=') < 0) { failed(R.nocookies); return; }
show(1);
state('ok');
setTimeout(function () {
if (R.resend) { document.getElementById('resend').submit(); return; }
if (R.back) { var b = document.getElementById('back'); b.hidden = false; return; }
location.reload();
}, 40);
}, show);
})(RS);
JS;
}
}
}

// src/Challenge/Crawlers.php
namespace CjwNetwork\RequestShield\Challenge {
use CjwNetwork\RequestShield\IpAddress;
use CjwNetwork\RequestShield\Settings;

if (true) {
/**
 * The known crawlers (proposal 0011): which one a User-Agent names, and
 * whether the request really comes from it -- by the operator's published
 * address list (a comparison, no network) or by DNS (reverse and forward). A
 * name proves nothing; only the address does.
 *
 * Asked only when it matters (a crawler that would be checked, or one the site
 * refuses). A DNS answer is remembered per address and crawler for a day.
 */
final class Crawlers
{
    /**
     * @var array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>
     */
    private array $crawlers;
    private string $index;
    /**
     * @var list<string>
     */
    private array $ids;
    /**
     * @var string
     */
    private string $verify = 'both';
    /**
     * @var \Closure(string): ?string|null
     */
    private ?\Closure $cacheGet = null;
    /**
     * @var \Closure(string, string): void|null
     */
    private ?\Closure $cacheSet = null;
    /**
     * @var callable(string): (string|false)|null
     */
    private $reverse = null;
    /**
     * @var callable(string): list<string>|null
     */
    private $forward = null;
    /**
     * @var \Closure(): bool|null
     */
    private ?\Closure $mayLookUp = null;
    /**
     * @param array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}> $crawlers
     * @param list<string> $ids the crawler of each (*MARK:n) in $index
     * @param string $verify both, ranges (no DNS) or dns
     * @param (\Closure(string): ?string)|null $cacheGet
     * @param (\Closure(string, string): void)|null $cacheSet
     * @param (callable(string): (string|false))|null $reverse
     * @param (callable(string): list<string>)|null $forward
     * @param (\Closure(): bool)|null $mayLookUp asked before every new DNS lookup (see SearchEngines)
     */
    public function __construct(array $crawlers, string $index, array $ids, string $verify = 'both', ?\Closure $cacheGet = null, ?\Closure $cacheSet = null, $reverse = null, $forward = null, ?\Closure $mayLookUp = null)
    {
        $this->crawlers = $crawlers;
        $this->index = $index;
        $this->ids = $ids;
        $this->verify = $verify;
        $this->cacheGet = $cacheGet;
        $this->cacheSet = $cacheSet;
        $this->reverse = $reverse;
        $this->forward = $forward;
        $this->mayLookUp = $mayLookUp;
    }

    /** The shipped or configured crawlers of the settings, with these caches and DNS functions. */
    public static function of(Settings $s, ?\Closure $cacheGet = null, ?\Closure $cacheSet = null, ?\Closure $mayLookUp = null, ?callable $reverse = null, ?callable $forward = null): self
    {
        return new self($s->crawlers, $s->crawlerIndex, $s->crawlerIds, $s->crawlerVerify, $cacheGet, $cacheSet, $reverse, $forward, $mayLookUp);
    }

    /** The ID of the crawler a User-Agent names, or null. One expression for all of them. */
    public function claims(string $userAgent): ?string
    {
        if ($this->index === '' || $userAgent === '' || preg_match($this->index, $userAgent, $m) !== 1 || !isset($m['MARK'])) {
            return null;
        }
        return $this->ids[(int) $m['MARK']] ?? null;
    }

    /** What the site does with it: allow, check or block. */
    public function policy(string $id): string
    {
        return $this->crawlers[$id]['policy'] ?? 'check';
    }

    public function kind(string $id): string
    {
        return $this->crawlers[$id]['kind'] ?? '';
    }

    /** Whether the address is one of the crawler's: its published list, or its DNS names. */
    public function verified(string $ip, string $id): bool
    {
        $x = $this->crawlers[$id] ?? null;
        if ($x === null) {
            return false;
        }
        // The published list: a lookup of about half a microsecond, no need to remember it.
        if ($this->verify !== 'dns' && $x['nets'] !== [] && IpAddress::inIndex($ip, $x['nets'])) {
            return true;
        }
        if ($this->verify === 'ranges' || $x['dns'] === []) {
            return false;
        }
        // DNS: remembered for a day, a lookup costs milliseconds.
        $key = 'crawler:' . $id . ':' . $ip;
        if ($this->cacheGet !== null) {
            $known = ($this->cacheGet)($key);
            if ($known === '1' || $known === '0') {
                return $known === '1';
            }
        }
        // Past the lookups allowed: not verified, at once -- and not
        // remembered, so a real crawler is known again once the flood is over.
        if ($this->mayLookUp !== null && !($this->mayLookUp)()) {
            return false;
        }
        $ok = SearchEngines::dns($ip, $x['dns'], $this->reverse, $this->forward);
        if ($this->cacheSet !== null) {
            ($this->cacheSet)($key, $ok ? '1' : '0');
        }
        return $ok;
    }
}
}
}

// src/Challenge/Gate.php
namespace CjwNetwork\RequestShield\Challenge {
use CjwNetwork\RequestShield\ChallengeSettings;
use CjwNetwork\RequestShield\Decision;
use CjwNetwork\RequestShield\IpAddress;
use CjwNetwork\RequestShield\Request;
use CjwNetwork\RequestShield\Store\Store;

if (true) {
/**
 * What becomes of a request the budgets want challenged:
 *
 *   a valid pass cookie             -> through, as the rest of the checks decided
 *   a valid solution cookie         -> through, with a pass cookie set
 *   a verified known crawler (allow) -> through (past a limit: 429)
 *   a path exempt from challenges   -> through (the budget's limit still applies)
 *   not GET or HEAD                 -> 429: a reload cannot repeat a form's POST
 *   anything else                   -> the challenge page
 */
final class Gate
{
    private ChallengeSettings $config;
    private string $secret;
    private ?Crawlers $crawlers = null;
    private int $ipv6Prefix = 64;
    private ?Store $store = null;
    private $pages = null;
    private string $docs = '';
    public function __construct(ChallengeSettings $config, string $secret, ?Crawlers $crawlers = null, int $ipv6Prefix = 64, ?Store $store = null, $pages = null, string $docs = '')
    {
        $this->config = $config;
        $this->secret = $secret;
        $this->crawlers = $crawlers;
        $this->ipv6Prefix = $ipv6Prefix;
        $this->store = $store;
        /** @var (callable(string, array<string, mixed>): ?string)|null the Pages hook (PageHook::asker()): the site's own check page, or null for the shield's */
        $this->pages = $pages;
        /** where the docs are (set docs-url): the check page links to the check in plain words; "" no link */
        $this->docs = $docs;
    }

    /**
     * @param Decision $base what every check but the budgets decided (cacheable or not)
     * @param array{forced?: bool, fresh?: ?int, resend?: array{action: string, fields: list<array{0: string, 1: string}>}|false|null, solution?: ?string, api?: bool, earn?: array{window: int, counter?: string}|null} $o
     *   forced: the application asks for the check (Shield::requirePass()): exempt paths do not count;
     *   fresh: only a pass issued in the last so many seconds counts;
     *   resend: a form sent without a pass, to be sent again after the check (false: it cannot be);
     *   solution: an answer the check inside the form sent in a hidden field;
     *   api: answer with the task as JSON (json in the result), the solution from Request-Shield-Solution;
     *   earn: for a spent budget (Decision::spent), its window: a solution starts its counter again
     * @return array{decision: Decision, cookies: list<string>, page: ?string, json: ?array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string}}
     *         cookies are complete Set-Cookie header values; json: the task for an API
     */
    public function resolve(Decision $challenged, Decision $base, Request $request, float $now, array $o = []): array
    {
        $forced = $o['forced'] ?? false;
        // An answer from the check inside the form (a hidden field), or none.
        $posted = $o['solution'] ?? null;
        $fresh = $o['fresh'] ?? null;
        $resend = $o['resend'] ?? null;
        $api = $o['api'] ?? false;
        $earn = $o['earn'] ?? null;
        // A budget past its limit that lets its client earn it back: no pass
        // gets past it -- only a solution made for this budget, which starts
        // its counter again.
        $spent = $challenged->spent;
        $budget = $challenged->reason;
        $bucket = IpAddress::bucket($request->clientIp, $this->ipv6Prefix);
        $ua = (string) $request->header('user-agent');
        $pass = new PassCookie($this->secret, $this->config->bindUserAgent);
        $passName = $this->config->cookie;
        $solutionName = $this->config->solutionCookie;
        $secure = $request->scheme === 'https';

        if (!$spent && $pass->valid($request->cookie($passName), $bucket, $ua, $now)
            && ($fresh === null || $pass->expires((string) $request->cookie($passName)) - $this->config->passTtl >= $now - $fresh)) {
            return ['decision' => $base, 'cookies' => [], 'page' => null, 'json' => null];
        }

        // A solution comes with the reload of a page, a form sent again (the
        // check page carried it: resend), the check inside the form (a field),
        // or an API's header.
        $solution = $posted ?? ($api ? $request->header('request-shield-solution') : null) ?? $request->cookie($solutionName);
        $cookies = [];
        if ($solution !== null && ($request->method === 'GET' || $request->method === 'HEAD' || $forced || $resend !== null || $posted !== null || $spent || $api)) {
            if ($request->cookie($solutionName) !== null) {
                $cookies[] = self::cookie($solutionName, '', 0, $secure);
            }
            $pow = new ProofOfWork($this->secret);
            if ($pow->verify($solution, $bucket, $now) && (!$spent || ProofOfWork::budgetOf($solution) === $budget) && $this->firstUse($solution, $now)) {
                if ($spent && $earn !== null && $this->store !== null) {
                    $this->store->reset(($earn['counter'] ?? $budget) . ':' . $bucket, $earn['window'], $now);
                    $this->store->hit('solved:' . ($earn['counter'] ?? $budget) . ':' . $bucket, 3600, $now);
                }
                $ttl = $this->config->passTtl;
                $cookies[] = self::cookie($passName, $pass->issue($bucket, $ua, (int) $now + $ttl), $ttl, $secure);
                // The page this request gets is for a challenged client:
                // answered, but kept out of every cache.
                return ['decision' => Decision::allowUncached('challenge solved'), 'cookies' => $cookies, 'page' => null, 'json' => null];
            }
            // A wrong or stale solution: a new challenge below, without the old cookie.
        }

        // A known crawler the site lets through (policy allow), verified by its
        // address: it cannot solve the check -- past a limit, the pause it
        // understands. One that only claims the name is an ordinary visitor,
        // noted in the log.
        $crawler = $this->crawlers !== null ? $this->crawlers->claims($ua) : null;
        if ($crawler !== null && $this->crawlers->policy($crawler) === 'allow') {
            if ($this->crawlers->verified($request->clientIp, $crawler)) {
                return $spent
                    ? ['decision' => Decision::throttle($budget, $challenged->retryAfter), 'cookies' => $cookies, 'page' => null, 'json' => null]
                    : ['decision' => $base, 'cookies' => $cookies, 'page' => null, 'json' => null];
            }
            $challenged = $challenged->claiming($crawler);
        }
        foreach ($forced || $spent ? [] : $this->config->exemptPaths as $pattern) {
            if (@preg_match($pattern, $request->path) === 1) {
                return ['decision' => $base, 'cookies' => $cookies, 'page' => null, 'json' => null];
            }
        }
        if ($request->method !== 'GET' && $request->method !== 'HEAD' && $resend === null && !$api) {
            return ['decision' => Decision::throttle($budget, max(10, $challenged->retryAfter)), 'cookies' => $cookies, 'page' => null, 'json' => null];
        }

        $c = $this->config;
        if ($spent) {
            // Harder with every solve in the hour: from difficulty-min, doubled,
            // at most difficulty-max.
            $solves = $this->store !== null ? (int) floor($this->store->peek('solved:' . ($earn['counter'] ?? $budget) . ':' . $bucket, 3600, $now)) : 0;
            $maxNumber = (int) min($c->difficultyMax, $c->difficultyMin * 2 ** min($solves, 20));
        } else {
            $maxNumber = (int) round($c->difficultyMin + ($c->difficultyMax - $c->difficultyMin) * $challenged->level);
        }
        $challenge = (new ProofOfWork($this->secret))->create($bucket, $maxNumber, (int) $now + $c->solutionTtl, $spent ? $budget : null);
        if ($api) {
            return ['decision' => $challenged, 'cookies' => $cookies, 'page' => null, 'json' => $challenge];
        }
        $texts = \CjwNetwork\RequestShield\Texts::all(\CjwNetwork\RequestShield\Texts::language($c->language, $request->header('accept-language'), $c->texts), $c->texts);
        if ($spent && $resend === null) {
            $texts['text'] = $texts['spent'];
        }
        // The site's own check page (the Pages hook, 0031 B.10), else the shield's.
        $page = $this->pages !== null ? ($this->pages)(\CjwNetwork\RequestShield\Pages::CHALLENGE, ['challenge' => $challenge, 'field' => $solutionName, 'secure' => $secure, 'texts' => $texts,
            'lang' => $texts['lang'] ?? 'en', 'resend' => $resend, 'home' => $c->home, 'logo' => $c->logo, 'status' => $challenged->status,
            'about' => \CjwNetwork\RequestShield\Help::explained($this->docs)]) : null;
        $page ??= ChallengePage::render($challenge, $solutionName, $secure, $texts, $resend, $c->home, $c->logo, \CjwNetwork\RequestShield\Help::explained($this->docs));
        return ['decision' => $challenged, 'cookies' => $cookies, 'page' => $page, 'json' => null];
    }

    /**
     * A task for the check inside the form (Widget), or null when the visitor
     * holds a pass already.
     *
     * @return array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string}|null
     */
    public function widgetTask(Request $request, float $now): ?array
    {
        // A pass about to run out gets a task anyway: the form may be sent after it.
        if ($this->passUntil($request, $now) > $now + 30) {
            return null;
        }
        $bucket = IpAddress::bucket($request->clientIp, $this->ipv6Prefix);
        return (new ProofOfWork($this->secret))->create($bucket, $this->config->widgetDifficulty, (int) $now + $this->config->solutionTtl);
    }

    /**
     * Until when the visitor's pass is valid (a Unix time), 0 without one --
     * the check inside the form fetches a task before it runs out.
     */
    public function passUntil(Request $request, float $now): int
    {
        $bucket = IpAddress::bucket($request->clientIp, $this->ipv6Prefix);
        $pass = new PassCookie($this->secret, $this->config->bindUserAgent);
        $cookie = $request->cookie($this->config->cookie);
        return $cookie !== null && $pass->valid($cookie, $bucket, (string) $request->header('user-agent'), $now) ? $pass->expires($cookie) : 0;
    }

    /**
     * Whether this is the first time the solution is used: a solved challenge
     * buys one pass cookie, not one per replay while it is valid. Counted in
     * the store for the challenge's lifetime; without a store, always true.
     */
    private function firstUse(string $solution, float $now): bool
    {
        $challenge = ProofOfWork::challengeOf($solution);
        if ($this->store === null || $challenge === null) {
            return $this->store === null;
        }
        return $this->store->hit('pow:' . $challenge, $this->config->solutionTtl, $now) <= 1.0;
    }

    /** A Set-Cookie value; $maxAge 0 deletes the cookie. */
    public static function cookie(string $name, string $value, int $maxAge, bool $secure): string
    {
        return $name . '=' . $value . '; Path=/; Max-Age=' . $maxAge . '; HttpOnly; SameSite=Lax' . ($secure ? '; Secure' : '');
    }
}
}
}

// src/Challenge/PassCookie.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * The cookie a client gets for a solved challenge:
 * "2.<expires base36>.<tag base64url, 11>.<mac base64url, 22>" -- 43 bytes,
 * sent by the browser on every request while the pass lasts. Signed, bound
 * to the client's bucket (and its User-Agent, unless switched off), checked
 * without any storage -- so it works across every process and server that
 * shares the secret. The tag is 64 bits of an HMAC, the MAC 128 bits.
 */
final class PassCookie
{
    private string $secret;
    private bool $bindUserAgent = true;
    /** How long the encoded expiry may be: base36 of a Unix time (6 digits until 2038, 7 until 2059). */
    private const EXPIRES = '/^[0-9a-z]{1,8}$/';

    public function __construct(string $secret, bool $bindUserAgent = true)
    {
        $this->secret = $secret;
        $this->bindUserAgent = $bindUserAgent;
    }

    public function issue(string $bucket, string $userAgent, int $expires): string
    {
        $tag = $this->tag($bucket, $userAgent);
        $exp = base_convert((string) max(0, $expires), 10, 36);
        return '2.' . $exp . '.' . $tag . '.' . $this->mac($exp, $tag);
    }

    /** When a pass cookie expires (0 for none): with the pass lifetime, when it was issued. Check valid() first. */
    public function expires(string $cookie): int
    {
        $parts = explode('.', $cookie, 3);
        return isset($parts[1]) && preg_match(self::EXPIRES, $parts[1]) === 1 ? (int) base_convert($parts[1], 36, 10) : 0;
    }

    public function valid(?string $cookie, string $bucket, string $userAgent, float $now): bool
    {
        if ($cookie === null || strlen($cookie) > 64) {
            return false;
        }
        $parts = explode('.', $cookie);
        if (count($parts) !== 4 || $parts[0] !== '2' || preg_match(self::EXPIRES, $parts[1]) !== 1) {
            return false;
        }
        [, $exp, $tag, $mac] = $parts;
        return (int) base_convert($exp, 36, 10) >= $now
            && hash_equals($this->tag($bucket, $userAgent), $tag)
            && hash_equals($this->mac($exp, $tag), $mac);
    }

    private function tag(string $bucket, string $userAgent): string
    {
        return self::encode(substr(hash_hmac('sha256', 'pass|' . $bucket . '|' . ($this->bindUserAgent ? $userAgent : ''), $this->secret, true), 0, 8));
    }

    private function mac(string $exp, string $tag): string
    {
        return self::encode(substr(hash_hmac('sha256', '2|' . $exp . '|' . $tag, $this->secret, true), 0, 16));
    }

    /** base64url without padding: cookie-safe, 4 characters per 3 bytes. */
    private static function encode(string $raw): string
    {
        return rtrim(strtr(base64_encode($raw), '+/', '-_'), '=');
    }
}
}
}

// src/Challenge/ProofOfWork.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * An ALTCHA-compatible proof of work (https://altcha.org, protocol v1).
 *
 * The server picks a secret number n up to maxnumber and sends
 * challenge = sha256(salt . n) with an HMAC of it; the browser tries every n
 * until the hash matches. That costs the browser maxnumber/2 hashes on
 * average -- a fraction of a second for one visitor, real work for a bot
 * that has to do it for every address it rotates through -- and the server
 * one hash and one HMAC to check it.
 *
 * The salt carries the expiry and a tag of the client's bucket
 * ("<random>?expires=<ts>&c=<tag>"), both covered by the challenge's hash and
 * signature, so a solution is neither reusable later nor from elsewhere.
 */
final class ProofOfWork
{
    private string $secret;
    public const ALGORITHM = 'SHA-256';

    public function __construct(string $secret)
    {
        $this->secret = $secret;
    }

    /**
     * @return array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string}
     */
    public function create(string $bucket, int $maxNumber, int $expires, ?string $budget = null): array
    {
        $maxNumber = max(1000, $maxNumber);
        // The salt is covered by the signature (the challenge is made from it):
        // a solution stays bound to its client -- and, for a spent budget, to it.
        $salt = bin2hex(random_bytes(12)) . '?expires=' . $expires . '&c=' . $this->tag($bucket)
            . ($budget !== null ? '&b=' . rawurlencode($budget) : '');
        $challenge = hash('sha256', $salt . random_int(0, $maxNumber));
        return [
            'algorithm' => self::ALGORITHM,
            'challenge' => $challenge,
            'maxnumber' => $maxNumber,
            'salt' => $salt,
            'signature' => hash_hmac('sha256', $challenge, $this->secret),
        ];
    }

    /**
     * Whether $payload (base64 of the widget's JSON: algorithm, challenge,
     * number, salt, signature) solves a challenge this server made for
     * $bucket that has not expired.
     */
    public function verify(string $payload, string $bucket, float $now): bool
    {
        $b64 = strtr($payload, '-_', '+/');
        $json = base64_decode($b64 . str_repeat('=', (4 - strlen($b64) % 4) % 4), true);
        $data = is_string($json) && strlen($json) < 2048 ? json_decode($json, true) : null;
        if (!is_array($data) || ($data['algorithm'] ?? '') !== self::ALGORITHM) {
            return false;
        }
        $challenge = $data['challenge'] ?? null;
        $salt = $data['salt'] ?? null;
        $signature = $data['signature'] ?? null;
        $number = $data['number'] ?? null;
        if (!is_string($challenge) || !is_string($salt) || !is_string($signature)
            || !(is_int($number) || (is_string($number) && ctype_digit($number)))) {
            return false;
        }
        if (!hash_equals(hash_hmac('sha256', $challenge, $this->secret), $signature)
            || !hash_equals($challenge, hash('sha256', $salt . $number))) {
            return false;
        }
        $query = strpos($salt, '?');
        if ($query === false) {
            return false;
        }
        parse_str((string) substr($salt, $query + 1), $params);
        return isset($params['expires'], $params['c'])
            && is_string($params['expires']) && ctype_digit($params['expires'])
            && (int) $params['expires'] >= $now
            && is_string($params['c']) && hash_equals($this->tag($bucket), $params['c']);
    }

    /** The budget a solution was made for (a spent budget's check), or null. */
    public static function budgetOf(string $payload): ?string
    {
        $b64 = strtr($payload, '-_', '+/');
        $json = base64_decode($b64 . str_repeat('=', (4 - strlen($b64) % 4) % 4), true);
        $data = is_string($json) && strlen($json) < 2048 ? json_decode($json, true) : null;
        $salt = is_array($data) && is_string($data['salt'] ?? null) ? $data['salt'] : '';
        $query = strpos($salt, '?');
        if ($query === false) {
            return null;
        }
        parse_str((string) substr($salt, $query + 1), $params);
        return isset($params['b']) && is_string($params['b']) ? $params['b'] : null;
    }

    /** The challenge a payload answers (to use a solution only once), or null. */
    public static function challengeOf(string $payload): ?string
    {
        $b64 = strtr($payload, '-_', '+/');
        $json = base64_decode($b64 . str_repeat('=', (4 - strlen($b64) % 4) % 4), true);
        $data = is_string($json) && strlen($json) < 2048 ? json_decode($json, true) : null;
        $challenge = is_array($data) ? ($data['challenge'] ?? null) : null;
        return is_string($challenge) && preg_match('/^[0-9a-f]{64}$/', $challenge) ? $challenge : null;
    }

    private function tag(string $bucket): string
    {
        return substr(hash_hmac('sha256', 'client|' . $bucket, $this->secret), 0, 16);
    }
}
}
}

// src/Challenge/SearchEngines.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * Whether a client that says it is a search engine's crawler is one: its
 * address resolves to a host of that engine, and the host back to the
 * address (the check the engines themselves document). Only asked when a
 * crawler would be challenged or throttled, and remembered for a day, since
 * a DNS round trip costs more than everything else the shield does.
 */
final class SearchEngines
{
    /**
     * @var array<string, list<string>>
     */
    private array $engines;
    private ?\Closure $cacheGet = null;
    private ?\Closure $cacheSet = null;
    /**
     * @var callable(string): (string|false)|null
     */
    private $reverse = null;
    /**
     * @var callable(string): list<string>|null
     */
    private $forward = null;
    /**
     * @var \Closure(): bool|null
     */
    private ?\Closure $mayLookUp = null;
    /**
     * User-Agent pattern => host suffixes its crawlers resolve to.
     *
     * @return array<string, list<string>>
     */
    public static function defaults(): array
    {
        return [
            '/Googlebot|Google-InspectionTool|GoogleOther|AdsBot-Google|Mediapartners-Google/i' => ['.googlebot.com', '.google.com', '.googleusercontent.com'],
            '/bingbot|BingPreview|msnbot|adidxbot/i' => ['.search.msn.com'],
            '/DuckDuckBot/i' => ['.duckduckgo.com'],
            '/Applebot/i' => ['.applebot.apple.com'],
            '/YandexBot|YandexImages|YandexMobileBot/i' => ['.yandex.ru', '.yandex.net', '.yandex.com'],
            '/Baiduspider/i' => ['.baidu.com', '.baidu.jp'],
            '/Qwantbot|Qwantify/i' => ['.qwant.com'],
            '/SeznamBot/i' => ['.seznam.cz'],
        ];
    }

    /**
     * @param array<string, list<string>> $engines
     * @param (callable(string): (string|false))|null $reverse gethostbyaddr, replaceable for tests
     * @param (callable(string): list<string>)|null $forward addresses of a host, replaceable for tests
     * @param (\Closure(): bool)|null $mayLookUp asked before every new lookup (and counting it): false, and
     *   the address counts as not verified, at once -- DNS that does not answer (a DMZ) must not let
     *   a flood of fake crawlers make every request wait for its timeout
     */
    public function __construct(array $engines, ?\Closure $cacheGet = null, ?\Closure $cacheSet = null, $reverse = null, $forward = null, ?\Closure $mayLookUp = null)
    {
        $this->engines = $engines;
        $this->cacheGet = $cacheGet;
        $this->cacheSet = $cacheSet;
        $this->reverse = $reverse;
        $this->forward = $forward;
        $this->mayLookUp = $mayLookUp;
    }

    /**
     * The engine's suffixes the User-Agent claims, or null for no crawler.
     *
     * @return list<string>|null
     */
    public function claims(string $userAgent): ?array
    {
        foreach ($this->engines as $pattern => $suffixes) {
            if (@preg_match($pattern, $userAgent) === 1) {
                return $suffixes;
            }
        }
        return null;
    }

    public function verified(string $ip, string $userAgent): bool
    {
        $suffixes = $this->claims($userAgent);
        if ($suffixes === null) {
            return false;
        }
        $key = 'se:' . $ip;
        if ($this->cacheGet !== null) {
            $known = ($this->cacheGet)($key);
            if ($known === '1' || $known === '0') {
                return $known === '1';
            }
        }
        // Past the lookups allowed: not verified, without waiting -- and not
        // remembered, so a real crawler is known again once the flood is over.
        if ($this->mayLookUp !== null && !($this->mayLookUp)()) {
            return false;
        }
        $ok = self::dns($ip, $suffixes, $this->reverse, $this->forward);
        if ($this->cacheSet !== null) {
            ($this->cacheSet)($key, $ok ? '1' : '0');
        }
        return $ok;
    }

    /**
     * Reverse and forward DNS: the address's host ends in one of the
     * suffixes, and resolves back to the address.
     *
     * @param list<string> $suffixes
     * @param (callable(string): (string|false))|null $reverse
     * @param (callable(string): list<string>)|null $forward
     */
    public static function dns(string $ip, array $suffixes, $reverse = null, $forward = null): bool
    {
        $host = $reverse !== null ? $reverse($ip) : @gethostbyaddr($ip);
        if (!is_string($host) || $host === '' || $host === $ip) {
            return false;
        }
        $host = strtolower(rtrim($host, '.'));
        $matches = false;
        foreach ($suffixes as $suffix) {
            if ((string) substr($host, -strlen($suffix)) === $suffix) {
                $matches = true;
                break;
            }
        }
        if (!$matches) {
            return false;
        }
        $addresses = $forward !== null ? $forward($host) : self::addressesOf($host);
        return in_array(inet_ntop((string) inet_pton($ip)), array_map(static fn ($a) => inet_ntop((string) inet_pton($a)), array_filter($addresses, static fn ($a) => @inet_pton($a) !== false)), true);
    }

    /** @return list<string> */
    private static function addressesOf(string $host): array
    {
        $out = [];
        foreach (@dns_get_record($host, DNS_A | DNS_AAAA) ?: [] as $record) {
            $ip = $record['ip'] ?? ($record['ipv6'] ?? null);
            if (is_string($ip)) {
                $out[] = $ip;
            }
        }
        return $out;
    }
}
}
}

// src/Challenge/Secret.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * The key challenges and pass cookies are signed with: the configured one, or
 * one made once and kept in the store directory (0600), so a site works
 * without being told a secret. Every server of a site must share it.
 */
final class Secret
{
    public static function resolve(?string $configured, string $dir): string
    {
        if ($configured !== null && strlen($configured) >= 32) {
            return $configured;
        }
        $file = rtrim($dir, '/') . '/secret';
        $secret = @file_get_contents($file);
        if (is_string($secret) && strlen($secret) >= 64) {
            return $secret;
        }
        // store-dir in dir-mode (it holds more than the secret); the secret itself is 0600 whatever is set.
        \CjwNetwork\RequestShield\Files::dir($dir);
        $secret = bin2hex(random_bytes(32));
        $tmp = $file . '.' . bin2hex(random_bytes(4));
        // Made in 0600, then the key: store-dir may be a group's (dir-mode), the key never is.
        $h = \CjwNetwork\RequestShield\Files::create($tmp, 0600);
        if ($h === false) {
            return $secret;
        }
        $written = @fwrite($h, $secret) === strlen($secret);
        fclose($h);
        // Two first requests at once: the second rename wins, and both
        // processes read the same file on their next request.
        if (!$written || !@rename($tmp, $file)) {
            @unlink($tmp);
            return $secret;
        }
        $kept = @file_get_contents($file);
        return is_string($kept) && strlen($kept) >= 64 ? $kept : $secret;
    }
}
}
}

// src/Challenge/Widget.php
namespace CjwNetwork\RequestShield\Challenge {
if (true) {
/**
 * The browser check inside a form (proposal 0010): a placeholder
 *
 *   <div data-request-shield></div>
 *   <script src="/request-shield/widget.js" defer></script>
 *
 * becomes a small box that fetches a task from the shield's endpoint when the
 * visitor starts typing, solves it, and puts the answer into a hidden field of
 * the form; Shield::requirePass() (or a checked path) takes it from there. The
 * page itself carries no task, so it stays cacheable. Without JavaScript,
 * nothing changes: the check page as before.
 *
 * Options on the placeholder: data-start="input" (default: the first input
 * into the form), "load", or "submit"; data-endpoint (default: next to the
 * script).
 */
final class Widget
{
    /** The placeholder and, once per page, the script. */
    public static function html(string $path, string $start = 'input'): string
    {
        static $script = false;
        $e = static fn (string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $h = '<div data-request-shield' . ($start !== 'input' ? ' data-start="' . $e($start) . '"' : '') . '></div>';
        if (!$script) {
            $script = true;
            // Versioned: the browser keeps the script a day, and a changed one
            // must reach it at once.
            $h .= '<script src="' . $e($path . '/widget.js?v=' . self::version()) . '" defer></script>';
        }
        return $h;
    }

    /** A short hash of the script, for its address. */
    public static function version(): string
    {
        /** @var string|null $v */
        static $v = null;
        return $v ??= substr(hash('sha256', self::script()), 0, 10);
    }

    /** widget.js: the solver of the check page, and the box. */
    public static function script(): string
    {
        return "var RS = {};\n" . ChallengePage::SCRIPT . "\n" . self::BOX;
    }

    private const BOX = <<<'JS'
(function (R) {
if (typeof document === 'undefined') { return; }
var me = document.currentScript, base = ((me && me.src) || '').replace(/\/widget\.js(\?.*)?$/, '');
function formOf(el) { while (el && el.nodeName !== 'FORM') { el = el.parentNode; } return el; }
function run(box) {
var form = formOf(box), endpoint = box.getAttribute('data-endpoint') || (base + '/challenge');
var start = box.getAttribute('data-start') || 'input';
var state = 'idle', waiting = null, field = null, expires = 0, texts = { checking: '', checked: '✓', failed: '' };
box.className += ' rs-widget';
box.setAttribute('role', 'status');
box.setAttribute('aria-live', 'polite');
box.innerHTML = '<span class="rs-icon" aria-hidden="true"></span> <span class="rs-text"></span>';
var text = box.querySelector('.rs-text'), icon = box.querySelector('.rs-icon');
function show(s, t) { box.setAttribute('data-state', s); text.textContent = t; icon.textContent = s === 'done' ? '✓' : (s === 'failed' ? '!' : '…'); }
function finish(s, t) {
state = s; show(s, t);
if (waiting) { var b = waiting; waiting = null; if (form.requestSubmit) { form.requestSubmit(b === true ? undefined : b); } else { form.submit(); } }
}
function go() {
if (state !== 'idle') { return; }
state = 'checking';
show('checking', texts.checking);
if (!window.fetch) { finish('failed', ''); return; }
fetch(endpoint, { credentials: 'same-origin', cache: 'no-store', headers: { Accept: 'application/json' } })
.then(function (r) { return r.ok ? r.json() : null; })
.then(function (j) {
if (!j) { finish('failed', texts.failed); return; }
texts = j.texts || texts;
var next = box.nextSibling;
if (j.about && j.about.url && !(next && next.className === 'rs-about')) {
var a = document.createElement('a');
a.className = 'rs-about'; a.href = j.about.url; a.target = '_blank'; a.rel = 'noopener';
a.textContent = '?'; a.title = j.about.text || ''; a.setAttribute('aria-label', j.about.text || '?');
a.style.marginLeft = '.4em';
box.parentNode.insertBefore(a, box.nextSibling);
}
if (j.passed) {
expires = j.until ? +j.until * 1000 : 0;
finish('done', texts.checked); return;
}
show('checking', texts.checking);
R.solve(j.challenge, function (n, took) {
if (n < 0) { finish('failed', texts.failed); return; }
if (!field) { field = document.createElement('input'); field.type = 'hidden'; field.name = j.field; form.appendChild(field); }
field.value = R.payload(j.challenge, n, took);
var until = /[?&]expires=(\d+)/.exec(j.challenge.salt || '');
expires = until ? +until[1] * 1000 : 0;
finish('done', texts.checked);
});
}, function () { finish('failed', texts.failed); });
}
function reset() {
state = 'idle'; waiting = null; expires = 0;
if (field) { field.value = ''; }
show('idle', '');
if (start === 'load') { go(); }
}
window.addEventListener('pageshow', function (ev) { if (ev.persisted) { reset(); } });
show('idle', '');
if (!form) { return; }
if (start === 'load') { go(); }
if (start === 'input') { form.addEventListener('input', go); form.addEventListener('change', go); }
form.addEventListener('submit', function (ev) {
if (state === 'done' && expires && Date.now() > expires - 20000) { state = 'idle'; if (field) { field.value = ''; } }
if (state === 'done' || state === 'failed') { return; }
ev.preventDefault();
waiting = ev.submitter || true;
go();
});
}
var boxes = document.querySelectorAll('[data-request-shield]');
for (var i = 0; i < boxes.length; i++) { run(boxes[i]); }
})(RS);
JS;
}
}
}

// src/ChallengeSettings.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Challenge\SearchEngines;

if (true) {
/** Config's 'challenge' section, typed. */
final class ChallengeSettings
{
    public ?string $secret;
    public int $passTtl;
    public int $solutionTtl;
    public int $difficultyMin;
    public int $difficultyMax;
    public string $cookie;
    public string $solutionCookie;
    public bool $bindUserAgent;
    /**
     * @var array<string, list<string>>|null
     */
    public ?array $searchEngines;
    /**
     * @var list<string>
     */
    public array $exemptPaths;
    /**
     * @var array<string, string>
     */
    public array $texts;
    /**
     * @var list<string>
     */
    public array $alwaysPaths = [];
    public string $language = 'auto';
    public ?string $home = null;
    public ?string $widgetPath = null;
    public int $widgetDifficulty = 25000;
    /**
     * @var list<string>
     */
    public array $apiPaths = [];
    public int $dnsLookups = 30;
    public array $alwaysMaxAge = [];
    public ?string $logo = null;
    public array $alwaysMethods = [];
    /**
     * @param array<string, list<string>>|null $searchEngines null: no crawler is exempt
     * @param list<string> $exemptPaths
     * @param array<string, string> $texts
     * @param list<string> $alwaysPaths
     * @param list<string> $apiPaths
     */
    private function __construct(?string $secret, int $passTtl, int $solutionTtl, int $difficultyMin, int $difficultyMax, string $cookie, string $solutionCookie, bool $bindUserAgent, ?array $searchEngines, array $exemptPaths, array $texts, array $alwaysPaths = [], string $language = 'auto', ?string $home = null, ?string $widgetPath = null, int $widgetDifficulty = 25000, array $apiPaths = [], int $dnsLookups = 30, array $alwaysMaxAge = [], ?string $logo = null, array $alwaysMethods = [])
    {
        /** @readonly */
        $this->secret = $secret;
        /** @readonly */
        $this->passTtl = $passTtl;
        /** @readonly */
        $this->solutionTtl = $solutionTtl;
        /** @readonly */
        $this->difficultyMin = $difficultyMin;
        /** @readonly */
        $this->difficultyMax = $difficultyMax;
        /** @readonly */
        $this->cookie = $cookie;
        /** @readonly */
        $this->solutionCookie = $solutionCookie;
        /** @readonly */
        $this->bindUserAgent = $bindUserAgent;
        /** @readonly */
        $this->searchEngines = $searchEngines;
        /** @readonly */
        $this->exemptPaths = $exemptPaths;
        /** @readonly */
        $this->texts = $texts;
        /** @readonly */
        $this->alwaysPaths = $alwaysPaths;
        /** @readonly */
        $this->language = $language;
        /** @readonly the address the shield's own pages link to ("To the home page"); null: none */
        $this->home = $home;
        /** @readonly where the check-in-the-form endpoint answers (/request-shield); null: off */
        $this->widgetPath = $widgetPath;
        /** @readonly the widget's difficulty (maxnumber): the visitor is still typing */
        $this->widgetDifficulty = $widgetDifficulty;
        /** @readonly paths of the site's API: a check there is sent as a header, not as a page */
        $this->apiPaths = $apiPaths;
        /** @readonly new DNS lookups a minute to verify search engines, for all requests together; 0: none */
        $this->dnsLookups = $dnsLookups;
        /**
         * @readonly alwaysPaths entry => seconds: a pass issued at most that long ago (challenge … max-age 5m)
         * @var array<string, int>
         */
        $this->alwaysMaxAge = $alwaysMaxAge;
        /** @readonly the site's logo for the check page, checked (Challenge\ChallengeLogo), as markup; null: a plain shield */
        $this->logo = $logo;
        /**
         * @readonly alwaysPaths entry => the methods it checks (challenge POST **: every form); none: every method
         * @var array<string, list<string>>
         */
        $this->alwaysMethods = $alwaysMethods;
    }

    /**
     * @param array<mixed> $c
     * @param bool $strict mode strict: a pass for at most 15 minutes, the difficulty from twice its minimum
     */
    public static function from(array $c, bool $strict = false): self
    {
        $difficulty = Settings::map($c, 'difficulty', 'challenge.difficulty');
        $min = max(1000, Settings::int($difficulty, 'min', 'challenge.difficulty.min', 50000));
        $max = max($min, Settings::int($difficulty, 'max', 'challenge.difficulty.max', 500000));
        $passTtl = max(60, Settings::int($c, 'passTtl', 'challenge.passTtl', 3600));
        if ($strict) {
            $min = min($max, $min * 2);
            $passTtl = min($passTtl, 900);
        }
        $always = Settings::strings($c, 'alwaysPaths', 'challenge.alwaysPaths');
        $ages = [];
        foreach (Settings::map($c, 'alwaysMaxAge', 'challenge.alwaysMaxAge') as $pattern => $age) {
            if (!is_int($age) || $age < 1 || !in_array((string) $pattern, $always, true)) {
                throw Settings::wrong("challenge.alwaysMaxAge.$pattern", 'seconds (at least 1) for one of alwaysPaths');
            }
            $ages[(string) $pattern] = $age;
        }
        $methods = [];
        foreach (Settings::map($c, 'alwaysMethods', 'challenge.alwaysMethods') as $pattern => $list) {
            if (!is_array($list) || $list === [] || !in_array((string) $pattern, $always, true)) {
                throw Settings::wrong("challenge.alwaysMethods.$pattern", 'the methods (POST, PUT …) for one of alwaysPaths');
            }
            $names = [];
            foreach ($list as $m) {
                if (!is_string($m) || preg_match('/^[A-Z]{1,20}$/', $m) !== 1) {
                    throw Settings::wrong("challenge.alwaysMethods.$pattern", 'methods in capitals (POST, PUT, PATCH, DELETE)');
                }
                $names[] = $m;
            }
            $methods[(string) $pattern] = array_values(array_unique($names));
        }

        $secret = $c['secret'] ?? null;
        if ($secret !== null && (!is_string($secret) || strlen($secret) < 32)) {
            throw Settings::wrong('challenge.secret', 'null or a string of at least 32 characters');
        }

        $engines = $c['searchEngines'] ?? true;
        if ($engines === true) {
            $engines = SearchEngines::defaults();
        } elseif ($engines === false) {
            $engines = null;
        } elseif (is_array($engines)) {
            $list = [];
            foreach ($engines as $pattern => $suffixes) {
                $list[(string) $pattern] = Settings::strings(['s' => $suffixes], 's', 'challenge.searchEngines');
            }
            $engines = $list;
        } else {
            throw Settings::wrong('challenge.searchEngines', 'true, false or an array of pattern => host suffixes');
        }

        $texts = [];
        foreach (Settings::map($c, 'texts', 'challenge.texts') as $key => $text) {
            if (!is_string($text)) {
                throw Settings::wrong("challenge.texts.$key", 'a string');
            }
            $texts[(string) $key] = $text;
        }

        return new self(
            $secret,
            $passTtl,
            max(30, Settings::int($c, 'solutionTtl', 'challenge.solutionTtl', 300)),
            $min,
            $max,
            self::cookieName($c, 'cookie', 'rsp'),
            self::cookieName($c, 'solutionCookie', 'rss'),
            Settings::bool($c, 'bindUserAgent', 'challenge.bindUserAgent', true),
            $engines,
            Settings::strings($c, 'exemptPaths', 'challenge.exemptPaths'),
            $texts,
            $always,
            self::language($c),
            self::home($c),
            self::widgetPath($c),
            max(1000, Settings::int($c, 'widgetDifficulty', 'challenge.widgetDifficulty', 25000)),
            Settings::strings($c, 'apiPaths', 'challenge.apiPaths'),
            max(0, Settings::int($c, 'dnsLookups', 'challenge.dnsLookups', 30)),
            $ages,
            self::logo($c),
            $methods,
        );
    }

    /** Whether an alwaysPaths entry checks this method (challenge POST **: not a GET). */
    public function alwaysFor(string $pattern, string $method): bool
    {
        $methods = $this->alwaysMethods[$pattern] ?? null;
        return $methods === null || in_array($method, $methods, true);
    }

    /** @param array<mixed> $c */
    private static function logo(array $c): ?string
    {
        $file = $c['logo'] ?? null;
        if ($file === null || $file === '') {
            return null;
        }
        if (!is_string($file)) {
            throw Settings::wrong('challenge.logo', 'null or the path of an SVG file');
        }
        return \CjwNetwork\RequestShield\Challenge\ChallengeLogo::load($file, 'challenge.logo');
    }

    /** @param array<mixed> $c */
    private static function widgetPath(array $c): ?string
    {
        $p = $c['widgetPath'] ?? null;
        if ($p === null || $p === '') {
            return null;
        }
        if (!is_string($p) || !preg_match('#^(/[A-Za-z0-9._~-]+)+$#', $p) || preg_match('#/\.+(/|$)#', $p)) {
            throw Settings::wrong('challenge.widgetPath', 'null or a path such as /request-shield');
        }
        return $p;
    }

    /** @param array<mixed> $c */
    private static function home(array $c): ?string
    {
        $home = $c['home'] ?? null;
        if ($home === null || $home === '') {
            return null;
        }
        if (!is_string($home) || !preg_match('#^(/|https?://)[^\s"<>]*$#i', $home)) {
            throw Settings::wrong('challenge.home', 'null, a path (/) or an http(s) address');
        }
        return $home;
    }

    /** @param array<mixed> $c */
    private static function language(array $c): string
    {
        $lang = strtolower(Settings::string($c, 'language', 'challenge.language', 'auto'));
        if ($lang !== 'auto' && !preg_match('/^[a-z]{2,3}(-[a-z0-9]{2,8})?$/', $lang)) {
            throw Settings::wrong('challenge.language', '"auto" or a language code such as de, en, fr, de-at');
        }
        return $lang;
    }

    /** @param array<mixed> $c */
    private static function cookieName(array $c, string $key, string $default): string
    {
        $name = Settings::string($c, $key, "challenge.$key", $default);
        if (!preg_match('/^[A-Za-z0-9_-]{1,64}$/', $name)) {
            throw Settings::wrong("challenge.$key", 'a cookie name of letters, digits, "_" and "-"');
        }
        return $name;
    }

    /** @return array<string, mixed> */
    public function export(): array
    {
        /** @var array<string, mixed> */
        return get_object_vars($this);
    }

    /** @param array<string, mixed> $e what export() returned (trusted: no checks) */
    public static function import(array $e): self
    {
        // Positional, in declaration order (what export() returns): unpacking
        // string keys into named arguments needs PHP 8.1.
        /** @phpstan-ignore argument.type */
        return new self(...array_values($e));
    }
}
}
}

// src/Cli.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Rules\CrawlerLists;
use CjwNetwork\RequestShield\Rules\RuleFile;
use CjwNetwork\RequestShield\Rules\RuleFileException;
use CjwNetwork\RequestShield\Rules\Shipped;

if (true) {
/**
 * The command line (bin/request-shield, and the single file run directly --
 * 0031 E.2): Cli::main($argv) is the whole tool. A command ends the process
 * with its exit code (exit()), as the script did; main() returns 0 when the
 * last command ("show") falls through.
 *
 *   php bin/request-shield check  site.rules [--source=<glob>]...
 *   php bin/request-shield show   site.rules [--source=<glob>]...
 *   php bin/request-shield reload site.rules [--source=<glob>]...
 *   php bin/request-shield trace  site.rules "GET https://www.example.org/wp-login.php" [--ip=<address>] [--ua=<User-Agent>]
 *   php bin/request-shield test   site.rules [--source=<glob>]... [--only=<ID>] [--as-written] [--junit=<file>]
 *   php bin/request-shield crawlers site.rules [update] [--force]
 *   php bin/request-shield access-token site.rules "<principal>"|'*'
 *   php bin/request-shield feeds site.rules [list|update|export] [--force] [--format=plain|nginx|nftables|ipset] [--write=<file>]
 *   php bin/request-shield <an extension's command> site.rules …   (stats: the statistics plugin's, see its usage)
 *   -- stats site.rules [--days=7 | --from=2026-01-01 --to=2026-09-30] [--by=day|week|month|year] [--crawler=<ID>] [--path=/news/] [--sort=views|blocked|refused|checked|throttled] [--site=<website>|other | --group=<group>] [--json]
 *   php bin/request-shield version [site.rules]
 *   php request-shield.php init --app=plain|wordpress|symfony|exponential [--docroot=<dir>] [--out=<file>] [--force]
 *   php request-shield.php verify request-shield.php [--sums=SHA256SUMS] [--sig=request-shield.php.minisig] [--key=<public key>]
 *   php request-shield.php self-update [--check] [--to=vX.Y.Z] [--major]     (the single file only)
 *
 * version: the library's version and build, PHP, whether APCu is there and
 *         the shipped rule sets' versions; with a rule file also the store in
 *         use, the mode and the versions of the site's own rule files.
 * check:  reads every file, reports the first error with file and line, and
 *         warns about rule files anyone else could change.
 * show:   the rules in effect after merging, each with the line it comes from.
 * reload: check, then mark the main file changed (touch), so every server
 *         reads the rules again on its next check -- for files added or changed
 *         where servers without APCu do not look by themselves (extensions).
 * trace:  what happens to a request, check by check, in plain words (nothing
 *         is counted); the visitor's address with --ip (default 198.51.100.7).
 * test:   decides every example next to the rules (expect lines), each on a
 *         fresh store, with the rules switched on (monitor as enforce; as they
 *         are with --as-written); lists the site's rules without an example.
 *         Exit 0: all pass, 1: one fails, 2: a mistake in the files.
 * replay: sends a recording of requests known to be good through the rules
 *         -- a session clicked through in a browser or by end-to-end tests
 *         (a HAR file), a web server's access log (its 2xx and 3xx), or a
 *         list of addresses -- each once, on a fresh store, nothing counted,
 *         the rules switched on as for test; says which the rules would
 *         refuse or check, and by which rule. Static files and other
 *         websites' addresses are left out (--all keeps the static files);
 *         every request comes from --ip (log: each line's own address).
 *         Exit 0: none refused, 1: one is, 2: a mistake in the files.
 * advise: suggests rules from a learning run (store-dir/learned.jsonl, or the
 *         file named): the query parameters and their types, query strict and
 *         allow watched first, post-origin same, api-path -- only what the rules
 *         do not say yet; each line checked by the parser, then the run replayed
 *         with all of them enforced. --write keeps them in store-dir/advice.rules
 *         for an include, --json for tools. Site blocks are not looked at: the
 *         main rules' settings. Exit 0; 1: a suggestion the parser refused (the
 *         advisor's mistake -- please report it); 2: no learning run to read.
 * crawlers: the known crawlers, what the site does with each, and how old
 *         their address lists are. "update" fetches the operators' current
 *         lists into store-dir (cron, a deploy -- or where there is internet,
 *         copying store-dir/crawlers/ into a DMZ); the servers read them on their
 *         next check. A list that shrank to less than half is kept unless --force.
 * access-token: a new token for the dashboard (proposal 0023): printed once,
 *         with the dashboard-access line to paste -- only its hash goes into the
 *         rule file. "*" for everything, a group's name for its websites only.
 * feeds:  the public blocklists the rules name (feed …): how many entries, how
 *         old. "update" fetches those that are due (cron, e.g. hourly; each at
 *         most as often as its terms allow) into store-dir/feeds; a list that
 *         shrank to less than half is kept unless --force. "export" writes the
 *         addresses kept out (the deny list and the feeds named deny) for the
 *         level below PHP: a firewall (nftables, ipset), nginx, a plain list.
 *         Not .htaccess: Apache reads it on every request -- measured far too
 *         slow for lists (see docs/proposals/0025-blocklist-feeds.md).
 * stats:  what the counters (set stats on) say about the last days: requests
 *         let through, checked, refused, the rules behind them, the answers'
 *         status codes, pages not found and who links to them, what each known
 *         crawler did, other bots -- in words, or as JSON for a CMS.
 * examples: the "# demo:" groups of a rule file (one per feature): as Markdown
 *         tables for the docs (--markdown, --feature=RSF02-06 for one), as a
 *         page that needs no server with what test decided for each row
 *         (--html, --out=<file>), or how much is covered (--coverage).
 * vocabulary: every rule and set key, how it is written and the feature it
 *         belongs to (--json: with what each does) -- docs/reference's source.
 * init:   a commented starter rule file for an application, in monitor mode;
 *         never inside --docroot, never over a file without --force.
 * verify: is a downloaded file the released one: its checksum from SHA256SUMS
 *         and, with the release key and sodium, its minisign signature.
 * self-update: the single file replaces itself with a signed release, every
 *         file checked before any is replaced (--check: exit 10 when a newer
 *         one exists); the command line only, never by itself.
 */
final class Cli
{
    /**
     * @param list<string> $argv the script's arguments, its own name first
     */
    public static function main(array $argv): int
    {
        $args = array_slice($argv, 1);
        // Where the rule files named are: a mistake names its file by name only (mistake()).
        foreach ($args as $a) {
            $named = strncmp($a, '--source=', 9) === 0 ? (string) substr($a, 9) : $a;
            if (substr($named, -6) === '.rules' || $named !== $a) {
                self::$dirs[] = dirname($named);
            }
        }
        $sources = [];
        $rest = [];
        $ip = '198.51.100.7';
        $force = false;
        $ua = null;
        $days = 7;
        $json = false;
        $period = [];
        $listFor = null;
        $listUntil = null;
        $listReason = '';
        $feedOpts = ['format' => 'plain', 'write' => null];
        // init, verify, self-update (0031 E.6): their options.
        $release = ['app' => null, 'docroot' => null, 'out' => null, 'sums' => null, 'sig' => null, 'key' => null, 'check' => false, 'to' => null, 'major' => false];
        // examples (0031 F.5): what to write.
        $show = ['markdown' => false, 'html' => false, 'coverage' => false, 'feature' => null];
        $testOpts = ['only' => null, 'asWritten' => false, 'junit' => null];
        $replayAll = false;
        $replayFound = 'note';
        $ipGiven = false;
        $learn = ['from' => [], 'keep' => false];
        $adviseWrite = false;
        foreach ($args as $a) {
            if ($a === '--force') {
                $force = true;
            } elseif ($a === '--json') {
                $json = true;
            } elseif (strncmp($a, '--days=', 7) === 0) {
                $days = max(1, (int) substr($a, 7));
            } elseif (preg_match('/^--(from|to)=(\d{4})-(\d{2})-(\d{2})$/', $a, $m) === 1) {
                $period[$m[1]] = $m[2] . $m[3] . $m[4];
            } elseif (strncmp($a, '--from=', 7) === 0) {
                $learn['from'] = array_merge($learn['from'], array_values(array_filter(array_map('trim', explode(',', (string) substr($a, 7))), static fn (string $x): bool => $x !== '')));
            } elseif ($a === '--keep') {
                $learn['keep'] = true;
            } elseif (preg_match('/^--by=(day|week|month|year)$/', $a, $m) === 1) {
                $period['by'] = $m[1];
            } elseif (strncmp($a, '--site=', 7) === 0) {
                $period['site'] = strtolower((string) substr($a, 7));
            } elseif (strncmp($a, '--group=', 8) === 0) {
                $period['site'] = 'group:' . \CjwNetwork\RequestShield\Settings::principal((string) substr($a, 8));
            } elseif (strncmp($a, '--crawler=', 10) === 0) {
                $period['crawler'] = (string) substr($a, 10);
            } elseif (strncmp($a, '--path=', 7) === 0) {
                $period['path'] = '/' . ltrim((string) substr($a, 7), '/');
            } elseif (strncmp($a, '--tag=', 6) === 0) {
                $period['tag'] = (string) substr($a, 6);
            } elseif (preg_match('/^--sort=(views|blocked|refused|checked|throttled)$/', $a, $m) === 1) {
                $period['sort'] = $m[1];
            } elseif (strncmp($a, '--ua=', 5) === 0) {
                $ua = (string) substr($a, 5);
            } elseif (strncmp($a, '--ip=', 5) === 0) {
                $ip = (string) substr($a, 5);
                $ipGiven = true;
            } elseif (strncmp($a, '--source=', 9) === 0) {
                $sources[] = (string) substr($a, 9);
            } elseif (preg_match('/^--for=(\d+)(s|m|h|d|w)$/', $a, $m) === 1) {
                $listFor = (int) $m[1] * ['s' => 1, 'm' => 60, 'h' => 3600, 'd' => 86400, 'w' => 604800][$m[2]];
            } elseif (strncmp($a, '--until=', 8) === 0) {
                $listUntil = (string) substr($a, 8);
            } elseif (strncmp($a, '--reason=', 9) === 0) {
                $listReason = (string) substr($a, 9);
            } elseif (strncmp($a, '--format=', 9) === 0) {
                $feedOpts['format'] = (string) substr($a, 9);
            } elseif ($a === '--write') {
                $adviseWrite = true;                    // advise: <store-dir>/advice.rules
            } elseif (strncmp($a, '--write=', 8) === 0) {
                $feedOpts['write'] = (string) substr($a, 8);
            } elseif (strncmp($a, '--only=', 7) === 0) {
                $testOpts['only'] = trim((string) substr($a, 7), '[]');
            } elseif ($a === '--all') {
                $replayAll = true;
            } elseif (preg_match('/^--found=(note|fail)$/', $a, $m) === 1) {
                $replayFound = $m[1];
            } elseif ($a === '--as-written') {
                $testOpts['asWritten'] = true;
            } elseif (strncmp($a, '--junit=', 8) === 0) {
                $testOpts['junit'] = (string) substr($a, 8);
            } elseif (preg_match('/^--(app|docroot|out|sums|sig|key|to)=(.*)$/s', $a, $m) === 1) {
                $release[$m[1]] = $m[2];
            } elseif ($a === '--markdown' || $a === '--html' || $a === '--coverage') {
                $show[substr($a, 2)] = true;
            } elseif (strncmp($a, '--feature=', 10) === 0) {
                $show['feature'] = (string) substr($a, 10);
            } elseif ($a === '--check' || $a === '--major') {
                $release[substr($a, 2)] = true;
            } else {
                $rest[] = $a;
            }
        }
        [$command, $file, $what] = $rest + [null, null, null];

        // The rule file's words and set keys, each with how it is written and its feature
        // (0031 F.5) -- from the same data as docs/reference.
        if ($command === 'vocabulary') {
            $features = [];
            foreach (array_merge(Rules\RuleFile::coreWords(), Rules\RuleFile::coreSettings(), Rules\Vocabulary::known()['words'], Rules\Vocabulary::known()['settings']) as $w) {
                $features[$w] = Rules\Vocabulary::featureOf($w);
            }
            if ($json) {
                echo json_encode(['rules' => Rules\Reference::RULES, 'settings' => Rules\Reference::SETTINGS, 'features' => $features], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), "\n";
                exit(0);
            }
            foreach (Rules\Reference::RULES as $r) {
                echo str_pad(str_replace('`', '', $r['syntax']), 70) . ' ' . ($features[$r['words'][0]] ?? '') . "\n";
            }
            echo "\n";
            foreach (Rules\Reference::SETTINGS as $r) {
                echo str_pad('set ' . implode(' | ', $r['keys']), 70) . ' ' . ($features[$r['keys'][0]] ?? '') . "\n";
            }
            exit(0);
        }
        // Commands without a rule file (0031 E.6).
        if ($command === 'init') {
            exit(Rules\Starter::run($release['app'], $release['docroot'], $release['out'], $force, STDOUT, STDERR));
        }
        if ($command === 'verify') {
            if ($file === null) {
                fwrite(STDERR, "usage: request-shield verify <request-shield.php> [--sums=<SHA256SUMS>] [--sig=<file.minisig>] [--key=<public key>]\n");
                exit(2);
            }
            exit(Release\Verify::run($file, $release['sums'], $release['sig'], $release['key'] ?? Shipped::PUBKEY, STDOUT, STDERR));
        }
        if ($command === 'self-update') {
            if (!Shipped::embedded()) {
                fwrite(STDERR, "request-shield: self-update replaces the single file, and this is a source checkout or a Composer install -- update it with git or composer\n");
                exit(2);
            }
            $self = (string) (new \ReflectionClass(Shipped::class))->getFileName();
            exit((new Release\SelfUpdate($self, Shipped::PUBKEY, Shield::VERSION))->run($release['check'], $release['to'], $release['major'], STDOUT, STDERR));
        }

        if ($command === 'version' || $command === '--version') {
            // What is installed: for a bug report, a support call, or an agent that
            // checks what it downloaded. Never on a request path.
            $v = \CjwNetwork\RequestShield\Shield::VERSION;
            $apcu = \CjwNetwork\RequestShield\Store\ApcuStore::usable();
            echo 'request-shield ' . $v . ' (' . \CjwNetwork\RequestShield\Shield::BUILD . ")\n";
            echo 'PHP ' . PHP_VERSION . ', APCu ' . ($apcu ? 'available' : 'not available' . (PHP_SAPI === 'cli' ? ' here (apc.enable_cli=1 switches it on for the CLI)' : '')) . "\n";
            $shipped = [];
            foreach (Shipped::sets() as $set) {
                if (preg_match('/^version[ \t]+(\S+)/m', (string) Shipped::rules($set), $m) === 1) {
                    $shipped[] = '@' . $set . ' ' . $m[1];
                }
            }
            echo 'shipped rule sets: ' . ($shipped !== [] ? implode(' · ', $shipped) : 'none') . "\n";
            if ($file !== null) {
                if (substr($file, -6) !== '.rules') {
                    fwrite(STDERR, "request-shield: $file is not a rule file (.rules)\n");
                    exit(2);
                }
                try {
                    $read = RuleFile::read(array_merge($sources, [$file]));
                    $s = Settings::from($read['config']);
                } catch (\InvalidArgumentException $e) {
                    self::mistake($e->getMessage());
                    exit(1);
                }
                $store = \CjwNetwork\RequestShield\Shield::storeFor($s);
                $kind = ['ApcuStore' => 'apcu', 'FileStore' => 'file', 'MemoryStore' => 'memory'][substr(strrchr(get_class($store), '\\') ?: '', 1)] ?? get_class($store);
                echo "rules: $file, mode $s->mode" . ($s->sites !== [] ? ', ' . count(array_unique(array_values($s->sites))) . ' site block(s)' : '') . "\n";
                echo "store: $kind (set store $s->store)" . ($kind === 'file' ? ", $s->storeDir" : '') . "\n";
                $tier = \CjwNetwork\RequestShield\Tier::of($s, Settings::cacheDirFor($file));
                echo "tier: {$tier['tier']} -- " . implode('; ', $tier['why']) . "\n";
                foreach (array_merge($tier['chosen'], $tier['off']) as $off) {
                    echo "  not active: $off\n";
                }
                $own = [];
                foreach ($s->origins['versions'] ?? [] as $name => $version) {
                    $own[] = "$name $version";
                }
                echo 'versions in the rule files: ' . ($own !== [] ? implode(' · ', $own) : 'none (version <v> names one)') . "\n";
            }
            exit(0);
        }

        // The extensions' commands (Extension::commands(), 0031 D.1): name => the Command class, a dispatch table.
        $commands = [];
        foreach (\CjwNetwork\RequestShield\Rules\Vocabulary::extensions() as $extension) {
            /** @var array<mixed> $declared an extension's code: checked, not trusted */
            $declared = $extension::commands();
            foreach ($declared as $name => $class) {
                if (is_string($name) && is_string($class) && class_exists($class) && is_subclass_of($class, \CjwNetwork\RequestShield\Cli\Command::class)) {
                    $commands[$name] = $class;
                }
            }
        }
        $core = ['check', 'show', 'reload', 'trace', 'test', 'replay', 'crawlers', 'feeds', 'access-token', 'deny', 'allow', 'unlist', 'lists', 'learn', 'advise'];
        if (!in_array($command, array_merge($core, array_keys($commands)), true) || $file === null
            || ($command === 'access-token' && $what === null)
            || ($command === 'feeds' && $what !== null && !in_array($what, ['list', 'update', 'export'], true))
            || (in_array($command, ['trace', 'deny', 'allow', 'unlist', 'replay'], true) && $what === null)
            || ($command === 'crawlers' && $what !== null && $what !== 'update')
            || ($command === 'learn' && !in_array($what, ['start', 'stop', 'status'], true))) {
            fwrite(STDERR, "usage: request-shield check|show|reload <main.rules> [--source=<glob>]...\n"
                . "       request-shield trace <main.rules> \"GET https://www.example.org/path\" [--ip=<address>] [--ua=<User-Agent>] [--source=<glob>]...\n"
                . "       request-shield test <main.rules> [--source=<glob>]... [--only=<ID>] [--as-written] [--junit=<file>]\n"
                . "       request-shield replay <main.rules> <session.har|access.log|urls.txt|learned.jsonl> [--ip=<address>|log] [--all] [--found=note|fail] [--as-written] [--junit=<file>]\n"
                . "       request-shield crawlers <main.rules> [update] [--force]\n"
                . "       request-shield access-token <main.rules> \"<principal>\"|'*'\n"
                . "       request-shield feeds <main.rules> [list|update|export] [--force] [--format=plain|nginx|nftables|ipset] [--write=<file>]\n"
                . implode('', array_map(static fn (string $class): string => '       ' . $class::usage() . "\n", $commands))
                . "       request-shield deny|allow <main.rules> <address|range> [--for=7d | --until=2026-10-07[T15:30]] [--reason=\"…\"] [--force]\n"
                . "       request-shield unlist <main.rules> <address|range>\n"
                . "       request-shield lists <main.rules>\n"
                . "       request-shield learn <main.rules> start [--for=2h] [--from=<address|range>,…] [--keep] | stop | status\n"
                . "       request-shield advise <main.rules> [learned.jsonl] [--write] [--json]\n"
                . "       request-shield version [<main.rules>]\n"
                . "       request-shield init --app=" . implode('|', Shipped::starters()) . " [--docroot=<dir>] [--out=<file>] [--force]\n"
                . "       request-shield verify <request-shield.php> [--sums=<SHA256SUMS>] [--sig=<file.minisig>] [--key=<public key>]\n"
                . "       request-shield self-update [--check] [--to=vX.Y.Z] [--major]\n"
                . "       request-shield vocabulary [--json]\n");
            exit(2);
        }
        if (substr($file, -6) !== '.rules') {
            fwrite(STDERR, "request-shield: $file is not a rule file (.rules)\n");
            exit(2);
        }

        $files = $sources;
        $files[] = $file;

        if ($command === 'replay') {
            // Requests known to be good, through the rules (proposal 0016, the replay).
            $source = (string) $what;
            $text = is_file($source) ? @file_get_contents($source) : false;
            if ($text === false) {
                fwrite(STDERR, "request-shield: cannot read the recording $source\n");
                exit(2);
            }
            try {
                $recording = \CjwNetwork\RequestShield\Rules\Replay::read($text);
                $config = $testOpts['asWritten'] ? RuleFile::read($files)['config'] : RuleFile::switchedOn($files);
                $base = Settings::from($config);
                $bySite = [];
                $settingsFor = static function (string $host) use ($base, $files, $testOpts, &$bySite): Settings {
                    $siteId = $host === '' || $base->sites === [] ? null : $base->siteFor(['SERVER_NAME' => $host, 'HTTP_HOST' => $host]);
                    if ($siteId === null) {
                        return $base;
                    }
                    return $bySite[$siteId] ??= Settings::from($testOpts['asWritten'] ? RuleFile::read($files, $siteId)['config'] : RuleFile::switchedOn($files, $siteId));
                };
                $run = \CjwNetwork\RequestShield\Rules\Replay::run($recording['requests'], $settingsFor, $ipGiven ? ($ip === 'log' ? null : $ip) : null, $replayAll);
            } catch (\InvalidArgumentException $e) {
                self::mistake($e->getMessage());
                exit(2);
            }
            $kinds = ['pass' => 0, 'check' => 0, 'refused' => 0, 'offered' => 0];
            $left = [];
            foreach ($run['results'] as $i => $r) {
                if ($r['kind'] === 'refused' && $r['found'] && $replayFound === 'note') {
                    // Only found on a page, never clicked in the run: a page offers addresses a rule
                    // refuses on purpose (/logout, /admin) -- a note, unless --found=fail.
                    $r['kind'] = $run['results'][$i]['kind'] = 'offered';
                }
                $kinds[$r['kind']]++;
                if ($r['kind'] !== 'pass') {
                    $left[] = $r;
                }
            }
            $out = [];
            foreach (['static' => 'static files (--all keeps them)', 'foreign' => 'of other websites'] as $k => $why) {
                if ($run[$k] > 0) {
                    $out[] = "{$run[$k]} $why";
                }
            }
            if ($recording['skipped'] > 0) {
                $out[] = $recording['skipped'] . ($recording['format'] === 'access log' ? ' the site answered with 4xx or 5xx'
                    : ($recording['format'] === 'learning run' ? ' refused or failed in the run' : ' not for a website'));
            }
            echo "replay: " . basename($source) . " ({$recording['format']}): {$run['total']} requests, " . count($run['results']) . ' different'
                . ($out !== [] ? '; left out: ' . implode(', ', $out) : '') . "\n\n";
            usort($left, static fn (array $a, array $b): int => [$b['kind'] === 'refused', $b['kind'] === 'offered', $b['count']] <=> [$a['kind'] === 'refused', $a['kind'] === 'offered', $a['count']]);
            foreach ($left as $r) {
                $url = (string) preg_replace('#^https?://[^/]+#i', '', $r['url']);
                echo '  ' . ['refused' => '✕', 'offered' => '?', 'check' => '!'][$r['kind']] . ' ' . str_pad($r['method'] . ' ' . (strlen($url) > 60 ? substr($url, 0, 59) . '…' : $url), 68)
                    . ' ' . $r['got'] . ($r['rule'] !== null ? ' by ' . $r['rule'] : '') . ($r['count'] > 1 ? "  ({$r['count']}×)" : '') . "\n";
            }
            echo ($left !== [] ? "\n" : '') . count($run['results']) . ' different requests: ' . $kinds['pass'] . ' pass'
                . ($kinds['check'] > 0 ? ', ' . $kinds['check'] . ' get the browser check (a browser passes it; an end-to-end test needs a pass)' : '')
                . ($kinds['refused'] > 0 ? ', ' . $kinds['refused'] . ' refused' : '')
                . ($kinds['offered'] > 0 ? ', ' . $kinds['offered'] . ' only offered on a page would be refused (never clicked in the run -- a note; --found=fail counts them)' : '') . ".\n";
            if ($kinds['refused'] > 0) {
                echo '  ' . Help::see('RSF05-04', 'the-replay-your-own-clicks-as-a-test') . "\n";
            }
            if ($testOpts['junit'] !== null) {
                $xml = new \DOMDocument('1.0', 'UTF-8');
                $xml->formatOutput = true;
                $suite = $xml->appendChild($xml->createElement('testsuite'));
                $suite->setAttribute('name', 'replay ' . basename($source));
                $suite->setAttribute('tests', (string) count($run['results']));
                $suite->setAttribute('failures', (string) $kinds['refused']);
                foreach ($run['results'] as $r) {
                    $case = $suite->appendChild($xml->createElement('testcase'));
                    $case->setAttribute('classname', $r['rule'] ?? 'replay');
                    $case->setAttribute('name', $r['method'] . ' ' . $r['url'] . ' -- ' . $r['got']);
                    if ($r['kind'] === 'refused') {
                        $case->appendChild($xml->createElement('failure'))->setAttribute('message', $r['got'] . ($r['rule'] !== null ? ' by ' . $r['rule'] : ''));
                    } elseif ($r['kind'] === 'offered') {
                        $case->appendChild($xml->createElement('skipped'))->setAttribute('message', 'only offered on a page: ' . $r['got'] . ($r['rule'] !== null ? ' by ' . $r['rule'] : ''));
                    }
                }
                if (@file_put_contents($testOpts['junit'], (string) $xml->saveXML()) === false) {
                    fwrite(STDERR, "request-shield: cannot write {$testOpts['junit']}\n");
                    exit(2);
                }
            }
            exit($kinds['refused'] > 0 ? 1 : 0);
        }

        if ($command === 'test') {
            // The examples next to the rules (expect lines, proposal 0029), decided.
            try {
                $run = \CjwNetwork\RequestShield\Rules\Examples::run($files, $testOpts['asWritten'], $testOpts['only']);
            } catch (\InvalidArgumentException $e) {
                self::mistake($e->getMessage());
                exit(2);
            }
            $counts = ['pass' => 0, 'fail' => 0, 'skip' => 0];
            $last = null;
            foreach ($run['results'] as $r) {
                $counts[$r['status']]++;
                $x = $r['example'];
                $label = $r['about'] ?? '';
                $what = ($x['times'] > 1 ? $x['times'] . ' × ' : '') . $x['method'] . ' ' . $x['url'] . ($x['from'] !== RuleFile::EXAMPLE_FROM ? ' from ' . $x['from'] : '') . ($x['pass'] ? ' with pass' : '') . ($x['headers'] !== [] ? ' ' . implode(' ', array_map(static fn (string $k, string $v): string => "$k:$v", array_keys($x['headers']), $x['headers'])) : '');
                $mark = ['pass' => '✓', 'fail' => '✕', 'skip' => '–'][$r['status']];
                $said = $r['status'] === 'pass' ? $x['outcome'] . ($r['gotRule'] !== null && !in_array($x['outcome'], ['passes', 'uncached', 'answered'], true) ? ' by ' . $r['gotRule'] : '') : $r['why'];
                echo str_pad($label === $last ? '' : $label, 18) . "$mark " . str_pad($what, 52) . " $said\n";
                if ($r['status'] !== 'pass' && $x['text'] !== null) {
                    echo str_repeat(' ', 22) . $x['text'] . '   (' . $x['at'] . ")\n";
                } elseif ($r['status'] !== 'pass') {
                    echo str_repeat(' ', 22) . '(' . $x['at'] . ")\n";
                }
                $last = $label;
            }
            $n = count($run['results']);
            echo "\n$n example" . ($n === 1 ? '' : 's') . ': ' . $counts['pass'] . ' pass' . ($counts['fail'] > 0 ? ', ' . $counts['fail'] . ' fail' . ($counts['fail'] === 1 ? 's' : '') : '')
                . ($counts['skip'] > 0 ? ', ' . $counts['skip'] . ' skipped' : '') . '.'
                . ($run['without'] !== [] && $testOpts['only'] === null ? ' ' . count($run['without']) . ' rule' . (count($run['without']) === 1 ? '' : 's') . ' without an example: ' . implode(', ', $run['without']) : '') . "\n";
            if ($counts['fail'] > 0) {
                echo '  ' . Help::see('RSF05-04', 'request-shield-test') . "\n";   // how an example is read, and what a failure says
            }
            if ($testOpts['junit'] !== null) {
                $xml = new \DOMDocument('1.0', 'UTF-8');
                $xml->formatOutput = true;
                $suite = $xml->appendChild($xml->createElement('testsuite'));
                $suite->setAttribute('name', basename($file));
                $suite->setAttribute('tests', (string) $n);
                $suite->setAttribute('failures', (string) $counts['fail']);
                $suite->setAttribute('skipped', (string) $counts['skip']);
                foreach ($run['results'] as $r) {
                    $x = $r['example'];
                    $case = $suite->appendChild($xml->createElement('testcase'));
                    $case->setAttribute('classname', $r['about'] ?? basename($file));
                    $case->setAttribute('name', $x['method'] . ' ' . $x['url'] . ' ' . $x['outcome'] . ' (' . $x['at'] . ')');
                    if ($r['status'] === 'fail') {
                        $case->appendChild($xml->createElement('failure'))->setAttribute('message', $r['why']);
                    } elseif ($r['status'] === 'skip') {
                        $case->appendChild($xml->createElement('skipped'))->setAttribute('message', $r['why']);
                    }
                }
                if (@file_put_contents($testOpts['junit'], (string) $xml->saveXML()) === false) {
                    fwrite(STDERR, "request-shield: cannot write {$testOpts['junit']}\n");
                    exit(2);
                }
            }
            exit($counts['fail'] > 0 ? 1 : 0);
        }

        try {
            $read = RuleFile::read($files);
            $settings = Settings::from($read['config']);
            // Rules per website: every site block read and checked (base + block).
            $siteSettings = [];
            foreach (array_unique(array_values($settings->sites)) as $siteId) {
                $siteSettings[$siteId] = Settings::from(RuleFile::read($files, $siteId)['config']);
            }
        } catch (\InvalidArgumentException $e) {
            self::mistake($e->getMessage());
            exit(1);
        }

        if ($command === 'advise') {
            exit(self::advise($files, $settings, $what, $adviseWrite, $json));
        }

        // An extension's command: run from the table with what the script read and parsed.
        if (isset($commands[$command])) {
            exit($commands[$command]::run(new \CjwNetwork\RequestShield\Cli\Context($command, $settings, $file, $read, $sources, $what,
                ['days' => $days, 'json' => $json, 'force' => $force, 'ip' => $ip, 'ua' => $ua, 'period' => $period, 'feed' => $feedOpts, 'test' => $testOpts,
                    'list' => ['for' => $listFor, 'until' => $listUntil, 'reason' => $listReason], 'show' => $show + ['out' => $release['out']]], $args)));
        }

        if ($command === 'access-token') {
            // A token for the dashboard: shown once; the rule file keeps its hash. The
            // principal is an opaque id to the shield ("Customer A" -> customer-a); the
            // statistics map it to a group's websites (stats-group).
            $who = (string) $what;
            $id = $who === '*' ? '*' : \CjwNetwork\RequestShield\Settings::principal($who);
            if ($id === '') {
                fwrite(STDERR, "request-shield: a principal is a name of letters and digits (\"Customer A\"), or '*' for everything\n");
                exit(2);
            }
            $groups = class_exists(\CjwNetwork\RequestShield\Stats\StatsExtension::class) ? \CjwNetwork\RequestShield\Stats\StatsExtension::of($settings)['groups'] : [];
            if ($id !== '*' && $groups !== [] && !isset($groups[$id])) {
                fwrite(STDERR, "warning: no stats-group named \"$who\" (" . implode(', ', array_column($groups, 'name')) . ") -- the token opens the dashboard, but no statistics\n");
            }
            [$token, $hash] = \CjwNetwork\RequestShield\Access::token();
            $name = $id === '*' ? '*' : (isset($groups[$id]) ? '"' . $groups[$id]['name'] . '"' : $id);
            echo "the token (give it to whoever reads; it is not kept anywhere):\n\n    $token\n\n";
            echo "the line for the rule file (only the hash):\n\n    dashboard-access $name sha256:$hash\n\n";
            echo "then: request-shield reload $file -- the token opens " . ($id === '*' ? 'everything' : "the pages of $name only") . "\n";
            exit(0);
        }

        if ($command === 'feeds') {
            // The public blocklists (feed …): list, update (cron), export.
            $named = array_merge($settings->feeds, $settings->monitor !== null ? $settings->monitor->feeds : []);
            $dir = $settings->storeDir . '/feeds';
            try {
                if ($what === 'update') {
                    if ($named === []) {
                        echo "no feed in the rules (feed <name> <action>)\n";
                        exit(0);
                    }
                    if (($offline = \CjwNetwork\RequestShield\Http::offline()) !== null) {
                        fwrite(STDERR, "request-shield: $offline\n");
                        exit(1);
                    }
                    $failed = false;
                    $changed = false;
                    foreach (\CjwNetwork\RequestShield\Rules\Feeds::update($named, $dir, null, $force) as $name => $happened) {
                        echo str_pad($name, 18) . $happened . "\n";
                        $failed = $failed || strncmp($happened, 'failed', 6) === 0 || strncmp($happened, 'refused', 7) === 0;
                        $changed = $changed || strncmp($happened, 'updated', 7) === 0;
                    }
                    if ($changed) {
                        touch($file);                               // every server reads them within its recheck
                    }
                    exit($failed ? 1 : 0);
                }
                if ($what === 'export') {
                    $x = \CjwNetwork\RequestShield\Rules\FeedExport::cidrs($settings);
                    if ($x['left'] !== []) {
                        fwrite(STDERR, count($x['left']) . ' range(s) left out: they touch a trusted proxy or an address let in (' . implode(', ', array_slice($x['left'], 0, 5)) . ")\n");
                    }
                    $text = \CjwNetwork\RequestShield\Rules\FeedExport::render($x['cidrs'], $feedOpts['format']);
                    if ($feedOpts['write'] === null) {
                        echo $text;
                        exit(0);
                    }
                    $target = $feedOpts['write'];
                    // file-mode for a new file (it holds addresses); one there keeps its mode (a web server may read it)
                    if (!\CjwNetwork\RequestShield\Files::write($target, $text, '', true)) {
                        throw new \RuntimeException("cannot write $target");
                    }
                    echo 'wrote ' . count($x['cidrs']) . " range(s) to $target\n";
                    exit(0);
                }
                // list
                if ($named === []) {
                    echo "no feed in the rules -- the catalog (feed <name> deny|check|count|ban-signal <n>):\n";
                    foreach (\CjwNetwork\RequestShield\Rules\Feeds::catalog() as $name => $c) {
                        echo '  ' . str_pad($name, 16) . $c['title'] . ' -- ' . $c['about'] . ' (good for: ' . $c['suggested'] . ")\n" . str_repeat(' ', 18) . 'terms: ' . $c['terms'] . "\n";
                    }
                    exit(0);
                }
                foreach ($named as $f) {
                    $age = $f['fetched'] > 0 ? round((time() - $f['fetched']) / 3600, 1) . ' h ago' : 'never';
                    echo str_pad($f['name'], 16) . str_pad(($f['action'] === 'signal' ? 'ban-signal ' . $f['weight'] : $f['action']) . (in_array($f, $settings->feeds, true) ? '' : ' (count)'), 18)
                        . str_pad((string) $f['count'], 8, ' ', STR_PAD_LEFT) . ' entries  fetched ' . str_pad($age, 12) . str_pad($f['state'], 12) . $f['rule'] . "\n";
                    if ($f['terms'] !== '') {
                        echo str_repeat(' ', 16) . 'terms: ' . $f['terms'] . "\n";
                    }
                }
                exit(0);
            } catch (\InvalidArgumentException | \RuntimeException $e) {
                self::mistake('request-shield: ' . $e->getMessage());
                exit(1);
            }
        }

        if ($command === 'learn') {
            // A learning run (0016): the state file written or removed, then the main
            // file touched -- every server reads it within its recheck, as the lists.
            $dir = $settings->storeDir;
            $now = time();
            try {
                if ($what === 'start') {
                    if (isset($period['from'])) {
                        // --from=2026-10-01 is read as a day (the statistics' option): never a run "from anywhere".
                        throw new \InvalidArgumentException('--from takes an address or a range for learn, not a day');
                    }
                    $for = $listFor ?? 7200;
                    $token = \CjwNetwork\RequestShield\Learn::start($dir, $for, $learn['from'], $learn['keep'], $now);
                    touch($file);
                    $b = \CjwNetwork\RequestShield\Learn::bookmarks($token, $for);
                    echo 'learning until ' . date('Y-m-d H:i', $now + $for) . ($learn['from'] !== [] ? ', only from ' . implode(', ', $learn['from']) : '') . "\n"
                        . "recorded: the requests that carry the token -- their shape (paths, methods, the types of parameters and form fields), never a value\n\n"
                        . "in a browser, two bookmarks -- recording on, and off again:\n  on:  {$b['start']}\n  off: {$b['stop']}\n"
                        . "for tests, a header with every request:\n  Request-Shield-Learn: $token\n\n"
                        . "the token only marks requests, it lets none past a check; every server starts within its recheck\n"
                        . 'into: ' . \CjwNetwork\RequestShield\Learn::recordFile($dir) . "\n";
                    exit(0);
                }
                $run = \CjwNetwork\RequestShield\Learn::read($dir);
                if ($what === 'stop') {
                    $stopped = \CjwNetwork\RequestShield\Learn::stop($dir);
                    touch($file);
                    echo $stopped ? "learning stopped\n" : "no learning run\n";
                } else {
                    echo $run === null ? "no learning run\n" : ($now < $run['until'] ? 'learning until ' . date('Y-m-d H:i', $run['until']) : 'the learning run ended ' . date('Y-m-d H:i', $run['until']) . ' (learn stop clears it)')
                        . ($run['from'] !== [] ? ', only from ' . implode(', ', $run['from']) : '') . "\n";
                }
                $sum = \CjwNetwork\RequestShield\Learn::summary($dir);
                $methods = [];
                foreach ($sum['methods'] as $m => $n) {
                    $methods[] = "$n $m";
                }
                echo "recorded: {$sum['requests']} requests" . ($methods !== [] ? ' (' . implode(', ', $methods) . ')' : '') . ", {$sum['paths']} paths, {$sum['parameters']} parameters, {$sum['forms']} form" . ($sum['forms'] === 1 ? '' : 's') . ' -- '
                    . \CjwNetwork\RequestShield\Learn::recordFile($dir) . "\n";
                $o = $sum['offered'];
                $n = static fn (int $c, string $one, string $more): string => "$c " . ($c === 1 ? $one : $more);
                echo 'found on its pages: ' . $n($o['forms'], 'form', 'forms') . ', ' . $n($o['links'], 'link', 'links') . ', ' . $n($o['scripts'], 'address', 'addresses') . ' in scripts'
                    . ($o['hosts'] !== [] ? '; other hosts of the site: ' . implode(', ', $o['hosts']) : '') . "\n";
            } catch (\InvalidArgumentException | \RuntimeException $e) {
                self::mistake('request-shield: ' . $e->getMessage());
                exit(1);
            }
            exit(0);
        }

        if (in_array($command, ['deny', 'allow', 'unlist', 'lists'], true)) {
            // The list files (allow.rules, deny.rules in lists-dir): written whole, then
            // the main file touched, so every server reads them within its recheck.
            $dir = $settings->listsDir;
            if ($dir === null) {
                fwrite(STDERR, "no lists directory: set lists-dir (or store-dir) in the rule file\n");
                exit(1);
            }
            try {
                if ($command === 'lists') {
                    $now = time();
                    foreach (['deny' => 'kept out (deny)', 'exempt' => 'let in (allow)'] as $kind => $title) {
                        $entries = array_filter(\CjwNetwork\RequestShield\Rules\Lists::read($dir), static fn (array $e): bool => $e['kind'] === $kind);
                        echo "$title: " . count($entries) . "\n";
                        foreach ($entries as $e) {
                            $state = $e['until'] === null ? 'for good' : ($e['until'] > $now ? 'until ' . date('Y-m-d H:i', $e['until']) : 'ended ' . date('Y-m-d H:i', $e['until']));
                            echo '  ' . str_pad($e['id'], 10) . str_pad(implode(' ', $e['addresses']), 28) . str_pad($state, 24) . $e['note'] . "\n";
                        }
                    }
                    exit(0);
                }
                $address = (string) $what;
                \CjwNetwork\RequestShield\Rules\Lists::check($address);
                if ($command === 'unlist') {
                    $n = \CjwNetwork\RequestShield\Rules\Lists::remove($dir, $address);
                    touch($file);
                    echo "unlisted $address: $n entr" . ($n === 1 ? 'y' : 'ies') . " removed\n";
                    $bucket = strpos($address, '/') === false || strpos($address, ':') !== false ? \CjwNetwork\RequestShield\IpAddress::bucket((string) preg_replace('#/\d+$#', '', $address), $settings->ipv6Prefix) : null;
                    if ($bucket !== null && $settings->store === 'file') {
                        // The files are the servers' store too: a running ban is lifted at once.
                        if (\CjwNetwork\RequestShield\Shield::liftBan($settings, new \CjwNetwork\RequestShield\Store\FileStore($settings->storeDir), $bucket)) {
                            echo "its ban lifted\n";
                        }
                    } elseif ($bucket !== null && $settings->banKeep === 'file' && (new \CjwNetwork\RequestShield\Store\FileStore($settings->storeDir))->marked('ban:' . $bucket, time()) > 0) {
                        // Only the file can be reached from here; the servers' APCu keeps its copy.
                        (new \CjwNetwork\RequestShield\Store\FileStore($settings->storeDir))->mark('ban:' . $bucket, 0, time());
                        echo "its kept ban removed (ban-keep file); the servers' memory holds it until it ends -- lift it on the dashboard's lists page, or: request-shield allow $file $address --for=1h\n";
                    } elseif ($settings->bans !== []) {
                        echo "note: a running ban ends by itself (at most " . intdiv($settings->banMax, 3600) . " h) -- to lift it at once: the dashboard's lists page, or request-shield allow $file $address --for=1h\n";
                    }
                    exit(0);
                }
                $until = $listUntil !== null ? \CjwNetwork\RequestShield\Rules\Lists::time($listUntil) : ($listFor !== null ? time() + $listFor : null);
                if ($listUntil !== null && $until === null) {
                    throw new \InvalidArgumentException("--until takes a day (2026-10-07) or a moment (2026-10-07T15:30), not \"$listUntil\"");
                }
                if ($command === 'allow' && $until === null) {
                    throw new \InvalidArgumentException('allow takes --for or --until -- an address let in for good belongs in the rule file (exempt)');
                }
                if ($command === 'deny') {
                    // Never the proxies the site trusts (not even with --force); a wide range only on purpose.
                    $why = \CjwNetwork\RequestShield\Rules\Lists::refuse($address, $settings->trustedProxies, null, $force);
                    if ($why !== null) {
                        throw new \InvalidArgumentException(str_replace('confirm if that is meant', '--force if that is meant', $why));
                    }
                }
                $id = \CjwNetwork\RequestShield\Rules\Lists::add($dir, $command === 'deny' ? 'deny' : 'exempt', $address, $until, $listReason);
                touch($file);
                echo ($command === 'deny' ? 'kept out' : 'let in') . " $address" . ($until !== null ? ' until ' . date('Y-m-d H:i', $until) : ' for good') . " ($id); every server reads it within its recheck\n";
            } catch (\InvalidArgumentException | \RuntimeException $e) {
                self::mistake('request-shield: ' . $e->getMessage());
                exit(1);
            }
            exit(0);
        }

        if ($command === 'trace') {
            $parts = preg_split('/\s+/', trim((string) $what), 2) ?: [];
            [$method, $url] = count($parts) === 2 ? $parts : ['GET', $parts[0] ?? '/'];
            // The website from the address: its site block's rules.
            $urlHost = (string) parse_url($url, PHP_URL_HOST);
            $siteId = $settings->siteFor(['SERVER_NAME' => $urlHost, 'HTTP_HOST' => $urlHost]);
            if ($siteId !== null) {
                $settings = $siteSettings[$siteId];
                echo "site: $siteId\n";
            }
            // Only looks at the counters (APCu is the CLI's own; files are the site's).
            $t = (new Inspector($settings))->trace(Inspector::request($method, $url, $ip, $ua !== null ? ['User-Agent' => $ua] : []));
            $mark = ['pass' => '✓', 'note' => '!', 'stop' => '✕', 'skip' => '–'];
            echo strtoupper($method) . " $url from $ip\n\n";
            foreach ($t['steps'] as $st) {
                echo '  ' . $mark[$st['state']] . ' ' . str_pad($st['check'], 34) . $st['text'] . ($st['rule'] !== null ? "  [{$st['rule']}]" : '') . "\n";
            }
            echo "\nThis visitor {$t['verdict']}." . ($t['rule'] !== null ? " Decided by {$t['rule']}." : '') . "\n";
            echo $t['watched'] !== null ? "Watched: it {$t['watched']}.\n" : '';
            exit($t['decision']->passes() || in_array($settings->mode, ['off', 'monitor'], true) ? 0 : 4);     // 4: refused (a script can test for it)
        }


        if ($command === 'crawlers') {
            $dir = $settings->storeDir . '/crawlers';
            if ($what === 'update') {
                if (($offline = \CjwNetwork\RequestShield\Http::offline()) !== null) {
                    fwrite(STDERR, "request-shield: $offline\n");
                    exit(1);
                }
                // The file each list is read from now: an earlier update, else the shipped one.
                $lists = [];
                foreach (RuleFile::crawlerListFiles($read['config']) as $name => $shipped) {
                    $lists[$name] = is_file("$dir/$name.json") ? "$dir/$name.json" : $shipped;
                }
                $failed = 0;
                foreach (CrawlerLists::update($lists, $dir, null, $force) as $name => $happened) {
                    echo str_pad($name, 26) . $happened . "\n";
                    $failed += strncmp($happened, 'updated', 7) === 0 || strncmp($happened, 'unchanged', 9) === 0 ? 0 : 1;
                }
                echo "into $dir -- the servers read them on their next check\n";
                exit($failed > 0 ? 1 : 0);
            }
            echo "crawler-verify $settings->crawlerVerify\n\n";
            foreach ($settings->crawlers as $id => $x) {
                $lists = [];
                foreach ($x['lists'] as $name => $about) {
                    $lists[] = $name . ' (' . substr((string) ($about['created'] ?? '?'), 0, 10) . ', ' . ($about['from'] ?? '?') . ')';
                }
                echo str_pad($id, 24) . str_pad($x['kind'], 13) . str_pad($x['policy'], 7)
                    . ($lists !== [] ? ' ranges: ' . implode(', ', $lists) : '') . ($x['dns'] !== [] ? ' dns: ' . implode(' ', $x['dns']) : '') . "\n";
            }
            foreach (self::crawlerListsAge($settings) as $note) {
                echo "\nnote: $note";
            }
            echo "\n";
            exit(0);
        }

        $versions = $settings->origins['versions'] ?? [];
        $sets = $versions === [] ? '' : 'rule sets ' . implode(', ', array_map(static fn (string $n, string $v): string => "$n $v", array_keys($versions), $versions));

        if ($command === 'check' || $command === 'reload') {
            $warnings = 0;
            foreach (self::warnings($settings, $read, $file) as $w) {
                fwrite(STDERR, "warning: $w\n");
                $warnings++;
            }
            $files = count(array_filter(array_keys($read['seen']), static fn (string $f): bool => substr($f, -6) === '.rules' && !Shipped::isShipped($f)));
            $attacks = 0;
            foreach ($settings->contentRules as $r) {
                $attacks += count($r['patterns']);
            }
            echo "ok: $files file(s) + built-in rules, " . count($settings->blockedPaths) . ' blocked patterns, ' . count($settings->budgets) . ' budget(s)'
                . ($attacks > 0 ? ", $attacks attack patterns" : '') . ($sets !== '' ? "; $sets" : '') . "\n";
            // What this installation can do (ADR 0013): the tier, and what is not active in it.
            $tier = \CjwNetwork\RequestShield\Tier::of($settings, Settings::cacheDirFor($file));
            echo "tier: {$tier['tier']} -- " . implode('; ', $tier['why']) . "\n";
            foreach ($tier['chosen'] as $note) {
                echo "note: $note\n";                      // the settings chose it: no warning
            }
            foreach ($tier['off'] as $off) {
                fwrite(STDERR, "warning: $off\n");         // the environment leaves it inactive
                $warnings++;
            }
            if ($settings->sites !== []) {
                // site shop.a.de (a.de) · *.b.de · default -- and which name picks one.
                $byBlock = [];
                foreach ($settings->sites as $name => $siteId) {
                    $byBlock[$siteId][] = $name;
                }
                echo 'sites: ' . implode(' · ', array_map(static fn (string $siteId, array $names): string => $siteId . (count($names) > 1 ? ' (' . implode(', ', array_slice($names, 1)) . ')' : ''),
                    array_keys($byBlock), $byBlock)) . "; picked by $settings->siteFrom\n";
            }
            foreach (array_merge(self::crawlerListsAge($settings), self::sectionsPastLimit($settings)) as $note) {
                echo "note: $note";          // a note, not a warning: the exit code stays
            }
            if ($command === 'reload') {
                touch($file);
                echo "reload: $file marked changed; every server reads the rules again on its next check\n";
            }
            exit($warnings > 0 ? 3 : 0);
        }

        // show: the effective rules, as rule lines (patterns as the regular
        // expressions they became), each with its origin.
        // Each rule as a rule line: [ID] in front when it has one of its own, and as
        // the comment its description and where it is written.
        $o = static fn (string $setting, string $what): string => $settings->origin($setting, $what) ?? \CjwNetwork\RequestShield\Config::setName($what) ?? 'default';
        $line = static function (string $text, string $id = '') use ($settings): string {
            if ($id === '') {
                return $text . "\n";
            }
            $where = $settings->origin('at', $id);
            $about = $settings->origin('text', $id) ?? '';
            $rev = $settings->origin('rev', $id);
            return str_pad(($where !== null ? '[' . $id . ($rev !== null ? "@$rev" : '') . '] ' : '') . $text, 64) . ' # ' . trim($about . '  (' . ($where ?? $id) . ')') . "\n";
        };
        $regex = static fn (string $p): string => trim(preg_replace('/^#|#i?$/', '', $p) ?? $p);

        echo "# Effective rules of $file" . ($sources !== [] ? ' with ' . implode(' ', $sources) : '') . "\n";
        echo $sets !== '' ? "# $sets\n" : '';
        foreach ($settings->origins['warnings'] ?? [] as $w) {
            echo "# warning: $w\n";
        }
        if ($settings->hosts !== []) {
            echo $line('host ' . implode(' ', $settings->hosts), $o('hosts', '*'));
        }
        if ($settings->trustedProxies !== []) {
            echo $line('trust ' . implode(' ', $settings->trustedProxies));
        }
        echo $line('method none ' . implode(' ', $settings->methods), $o('methods', '*'));
        foreach ($settings->methodPaths as $m => $patterns) {
            echo $line("allow $m regex " . implode(' ', array_map($regex, $patterns)), $o('methodPaths', $m));
        }
        foreach ($settings->restricted as $r) {
            echo $line('restrict regex ' . implode(' ', array_map($regex, $r['paths'])) . ' to ' . implode(' ', $r['ips']), $o('restricted', $r['paths'][0] ?? ''));
        }
        foreach ($settings->blockedPaths as $p) {
            echo $line('block regex ' . $regex($p), $o('blockedPaths', $p));
        }
        foreach ($settings->contentRules as $r) {
            $where = strncmp((string) $r['target'], 'header:', 7) === 0 ? 'header ' . ucwords((string) substr((string) $r['target'], 7), '-') : $r['target'];
            foreach ($r['patterns'] as $p) {
                echo $line("block $where regex " . $regex($p), $o('contentRules', $p));
            }
        }
        foreach ($settings->blockExceptions as $x) {
            echo $line('unblock ' . ($x['patterns'] === null ? '' : 'regex ' . implode(' ', array_map($regex, $x['patterns'])) . ' ') . 'at regex '
                . implode(' ', array_map($regex, $x['paths'])) . ($x['ips'] !== [] ? ' for ' . implode(' ', $x['ips']) : ''), $o('blockExceptions', $x['paths'][0] ?? ''));
        }
        echo $settings->cacheablePaths === null ? $line('cache-path any') : '';
        foreach ($settings->cacheablePaths ?? [] as $p) {
            echo $line('cache-path regex ' . $regex($p), $o('cacheable.paths', $p));
        }
        foreach ($settings->queryParams as $q) {
            $pairs = [];
            foreach ($q['exact'] + $q['globs'] as $name => $type) {
                $pairs[] = (strncmp((string) $name, '#^', 2) === 0 ? stripslashes(str_replace('.*', '*', (string) substr((string) $name, 2, -2))) : $name) . ' ' . (strncmp($type, '#', 1) === 0 ? '/' . substr($type, 5, -3) . '/' : $type);
            }
            $first = (string) array_key_first($q['exact'] + $q['globs']);
            echo $line('query ' . implode('  ', $pairs) . ($q['paths'] !== null ? ' at regex ' . implode(' ', array_map($regex, $q['paths'])) : ''), $o('query', $first));
        }
        echo $settings->queryStrict ? $line('query strict', $o('query', 'strict')) : '';
        foreach ($settings->queryDrop as $p) {
            echo $line('query drop at regex ' . $regex($p), $o('queryDrop', $p));
        }
        echo $line('cache-query ' . ($settings->cacheableQuery === null ? 'any' : ($settings->cacheableQuery === [] ? 'none' : implode(' ', $settings->cacheableQuery))), $o('cacheable.query', '*'));
        echo $settings->cacheableIgnore !== [] ? $line('cache-ignore ' . implode(' ', $settings->cacheableIgnore), $o('cacheable.ignore', '*')) : '';
        echo $settings->cacheableUnknown !== 'uncached' ? $line('set cache-unknown-query ' . $settings->cacheableUnknown) : '';
        foreach ($settings->budgets as $b) {
            echo $line("limit $b->name $b->limit/{$b->window}s" . ($b->challengeAt !== null ? " challenge-at $b->challengeAt" : '') . ($b->onDemand ? ' on-demand' : '') . ($b->earnBack ? ' on-exceeded challenge' : ''), $o('budgets', $b->name));
        }
        foreach ($settings->challenge->alwaysPaths as $p) {
            $age = $settings->challenge->alwaysMaxAge[$p] ?? null;
            $methods = $settings->challenge->alwaysMethods[$p] ?? [];
            echo $line('challenge ' . ($methods !== [] ? implode(' ', $methods) . ' ' : '') . 'regex ' . $regex($p) . ($age !== null ? " max-age {$age}s" : ''), $o('challenge.alwaysPaths', $p));
        }
        foreach ($settings->challenge->exemptPaths as $p) {
            echo $line('challenge-exempt regex ' . $regex($p), $o('challenge.exemptPaths', $p));
        }
        foreach ($settings->origins['monitor'] ?? [] as $rid => $rule) {
            echo $line("monitor $rule", (string) $rid);
        }
        echo $line('exempt ' . ($settings->exemptIps === [] ? 'none' : implode(' ', $settings->exemptIps)));
        echo $line("set mode $settings->mode");
        echo $line('# ' . count($settings->crawlers) . ' known crawlers (bin/request-shield crawlers ' . basename($file) . ')');
        foreach ($settings->origins['crawlerPolicy'] ?? [] as $key => $rid) {
            $key = (string) $key;
            echo $line((isset($settings->crawlers[$key]) ? "crawler $key " : "crawlers $key ") . ($settings->crawlerPolicy[$key] ?? '?'), (string) $rid);
        }
        echo $line("set crawler-verify $settings->crawlerVerify");
        echo $line('set pass-ttl ' . $settings->challenge->passTtl . 's');
        echo $line('set store ' . $settings->store);
        echo $line('set store-dir ' . $settings->storeDir);
        echo $line('set secret ' . ($settings->challenge->secret === null ? '(generated in store-dir)' : '(set, not shown)'));
        echo $line('set log ' . ($settings->logFile ?? '(off)'));
        echo $line("set log-level $settings->logLevel");
        echo $line("set log-ip $settings->logIp");
        echo $line('set debug-header ' . ($settings->debugHeader ? 'on' : 'off'));
        echo $line("set recheck {$read['recheck']}s");
        return 0;
    }

    /**
     * Address lists older than 30 days (by the operator's date): a site whose
     * server cannot fetch them (a DMZ) should update them elsewhere and deploy.
     *
     * @return list<string>
     */
    private static function crawlerListsAge(Settings $settings): array
    {
        $old = [];
        foreach ($settings->crawlers as $x) {
            foreach ($x['lists'] as $name => $about) {
                $t = strtotime((string) ($about['fetched'] ?? $about['created'] ?? ''));
                if ($t !== false && $t < time() - 30 * 86400) {
                    $old[$name] = substr((string) ($about['fetched'] ?? $about['created']), 0, 10);
                }
            }
        }
        return $old === [] ? [] : ['address lists fetched more than 30 days ago: ' . implode(', ', array_map(static fn (string $n, string $d): string => "$n ($d)", array_keys($old), $old))
            . " -- php bin/request-shield crawlers <main.rules> update\n"];
    }

    /**
     * Section views that went to "(other)" in the last 7 days: some hour had more
     * sections on one folder level than the statistics keep (200 each). The levels
     * above stay exact (each has its own limit); a lower stats-depth drops the level
     * that overflows.
     *
     * @return list<string>
     */
    private static function sectionsPastLimit(Settings $settings): array
    {
        if (!class_exists(\CjwNetwork\RequestShield\Stats\StatsExtension::class) || !class_exists(\CjwNetwork\RequestShield\Stats\Stats::class)) {
            return [];
        }
        $so = \CjwNetwork\RequestShield\Stats\StatsExtension::of($settings);
        if (!$so['enabled'] || !in_array('pages', $so['parts'], true) || !is_dir($settings->storeDir . '/stats')) {
            return [];
        }
        $read = \CjwNetwork\RequestShield\Stats\Stats::of($settings)->read(gmdate('Ymd', time() - 6 * 86400), gmdate('Ymd'));
        $past = 0;
        foreach ($read['days'] as $counts) {          // a day holds its hours
            foreach ($counts as $k => $n) {
                $past += preg_match('/^pd:[a-z]+\|\(other\)$/', (string) $k) === 1 ? $n : 0;
            }
        }
        return $past === 0 ? [] : [number_format($past) . ' section views in the last 7 days were past the limit of ' . (\CjwNetwork\RequestShield\Stats\Stats::TOP * 2)
            . ' sections an hour on one folder level: the deepest levels are approximate there'
            . ($so['depth'] > 1 ? ' -- set stats-depth ' . ($so['depth'] - 1) . ' if the upper ones are enough' : '') . "\n"];
    }

    /** @var list<string> the folders of the rule files the command line names */
    private static array $dirs = [];

    /**
     * `request-shield advise` (proposal 0016, step 2): suggestions from a learning
     * run -- each checked by the rule parser, then the run replayed through the
     * rules with all of them enforced ("monitor" taken off), so the site sees
     * whether one would refuse its own clicks. --write keeps them in
     * <store-dir>/advice.rules (as watched, with "monitor"), for an include.
     *
     * @param list<string> $files
     */
    private static function advise(array $files, Settings $settings, ?string $source, bool $write, bool $json): int
    {
        $source ??= \CjwNetwork\RequestShield\Learn::recordFile($settings->storeDir);
        $text = is_file($source) ? @file_get_contents($source) : false;
        if ($text === false || trim($text) === '') {
            fwrite(STDERR, "request-shield: no learning run in $source -- record one: request-shield learn <main.rules> start\n");
            return 2;
        }
        $records = \CjwNetwork\RequestShield\Rules\Advise::read($text);
        try {
            $recording = \CjwNetwork\RequestShield\Rules\Replay::read($text);
        } catch (\InvalidArgumentException $e) {
            $recording = null;
        }
        if ($records === [] || $recording === null || $recording['format'] !== 'learning run') {
            fwrite(STDERR, "request-shield: $source is no learning run (request-shield learn writes one: one JSON line per request)\n");
            return 2;
        }
        $suggestions = \CjwNetwork\RequestShield\Rules\Advise::suggest($records, $settings);
        $advice = \CjwNetwork\RequestShield\Rules\Advise::file($suggestions, basename($source), time());
        // Checked as the rules will read them: the site's files, then the advice -- as written
        // (watched) and enforced. A line the parser refuses is the advisor's mistake: said, not written.
        $dir = sys_get_temp_dir() . '/rshield-advise-' . getmypid() . '-' . bin2hex(random_bytes(3));
        if (!@mkdir($dir, 0700, true) && !is_dir($dir)) {
            fwrite(STDERR, "request-shield: cannot make a temporary directory in " . sys_get_temp_dir() . "\n");
            return 2;
        }
        $tmp = "$dir/advice.rules";
        try {
            if (@file_put_contents($tmp, $advice) === false) {
                throw new \RuntimeException("cannot write $tmp");
            }
            RuleFile::read(array_merge($files, [$tmp]));
            file_put_contents($tmp, (string) preg_replace('/^(\[[A-Z0-9-]+\] )?monitor /m', '$1', $advice));
            $enforced = Settings::from(RuleFile::read(array_merge($files, [$tmp]))['config']);
            $run = \CjwNetwork\RequestShield\Rules\Replay::run($recording['requests'], static fn (string $host): Settings => $enforced, null);
        } catch (\RuntimeException $e) {
            fwrite(STDERR, 'request-shield: ' . $e->getMessage() . "\n");
            return 2;
        } catch (\InvalidArgumentException $e) {
            fwrite(STDERR, 'request-shield: the advice does not read as rules -- please report this: ' . $e->getMessage() . "\n");
            return 1;
        } finally {
            @unlink($tmp);
            @rmdir($dir);
        }
        $refused = array_values(array_filter($run['results'], static fn (array $r): bool => $r['kind'] === 'refused' && !$r['found']));
        $offered = array_values(array_filter($run['results'], static fn (array $r): bool => $r['kind'] === 'refused' && $r['found']));
        $written = null;
        if ($write && $suggestions !== []) {
            $written = rtrim($settings->storeDir, '/') . '/advice.rules';
            if (!\CjwNetwork\RequestShield\Files::write($written, $advice)) {
                fwrite(STDERR, "request-shield: cannot write $written\n");
                return 2;
            }
        }
        if ($json) {
            echo json_encode(['source' => $source, 'requests' => count($records), 'suggestions' => $suggestions,
                'replay' => ['different' => count($run['results']), 'refused' => count($refused), 'offeredRefused' => count($offered),
                    'refusedList' => array_map(static fn (array $r): array => ['method' => $r['method'], 'url' => $r['url'], 'got' => $r['got'], 'rule' => $r['rule']], $refused)],
                'written' => $written], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . "\n";
            return 0;
        }
        echo 'advise: ' . basename($source) . ', ' . count($records) . " requests recorded\n\n";
        if ($suggestions === []) {
            echo "Nothing to suggest: your rules say already what this run shows.\n";
            return 0;
        }
        foreach ($suggestions as $a) {
            echo '# ' . $a['text'] . "\n" . (strncmp($a['rule'], 'include ', 8) === 0 ? '' : '[' . $a['id'] . '] ') . $a['rule'] . "\n\n";
        }
        echo 'With all of them enforced ("monitor" taken off), the ' . count($run['results']) . ' different requests of your run: '
            . ($refused === [] ? 'none refused.' : count($refused) . ' refused -- leave those lines watched, or widen them:') . "\n";
        foreach ($refused as $r) {
            echo '  ✕ ' . $r['method'] . ' ' . (string) preg_replace('#^https?://[^/]+#i', '', $r['url']) . ' -- ' . $r['got'] . ($r['rule'] !== null ? ' by ' . $r['rule'] : '') . "\n";
        }
        if ($offered !== []) {
            echo '  (' . count($offered) . " address(es) only offered on a page, never clicked, would be refused -- request-shield replay lists them)\n";
        }
        echo $written !== null
            ? "\nWritten to $written -- add \"include $written\" to your rules, watch the log, then take \"monitor\" off.\n"
            : "\nTo keep them: --write (<store-dir>/advice.rules), or copy the lines into your rules.\n";
        return 0;
    }

    /**
     * A mistake on stderr, and where it is explained (0031 F.9): the feature
     * of the rule file's line it names, or the settings page -- from the
     * repository's docs, the command line has no settings to ask yet.
     */
    private static function mistake(string $message): void
    {
        $see = Help::forError($message, Help::DOCS, array_values(array_unique(self::$dirs)));
        fwrite(STDERR, $message . "\n" . ($see !== null ? '  ' . $see . "\n" : ''));
    }


    /**
     * The modes of what the shield writes (set file-mode, set dir-mode): a mode
     * everyone may read; files and folders already there that everyone may read
     * (made before, or by an umask); and store-dir owned by another user than
     * the one running the command -- what it writes there in file-mode 0600 the
     * web server's PHP could not read.
     *
     * @return list<string>
     */
    private static function modeWarnings(Settings $s): array
    {
        $out = [];
        if ((($s->fileMode | $s->dirMode) & 0004) !== 0) {
            $out[] = sprintf('file-mode 0%03o / dir-mode 0%03o: everyone on this machine may read what the shield writes -- the log, the lists, the statistics hold addresses; 0640/0750 shares them with a group only', $s->fileMode, $s->dirMode);
        }
        // store-dir and lists-dir with their folders (bans and caches lie one or two levels down), at
        // most 20,000 entries; the counters (*.c: newlines, their size counts) and empty files hold nothing.
        // A root may be a link (store-dir on /var/lib); a link inside is not followed; lists-dir inside
        // store-dir is looked at once.
        $roots = [$s->storeDir];
        $lists = $s->listsDir !== null ? (string) realpath($s->listsDir) : '';
        $store = (string) realpath($s->storeDir);
        if ($lists !== '' && ($store === '' || strpos($lists . '/', rtrim($store, '/') . '/') !== 0)) {
            $roots[] = $s->listsDir;
        }
        $paths = $roots;
        for ($i = 0; $i < count($paths) && count($paths) < 20000; $i++) {
            if (is_dir($paths[$i]) && ($i < count($roots) || !is_link($paths[$i]))) {
                foreach (@scandir($paths[$i]) ?: [] as $name) {
                    if ($name !== '.' && $name !== '..' && count($paths) < 20000) {
                        $paths[] = $paths[$i] . '/' . $name;
                    }
                }
            }
        }
        if ($s->logFile !== null) {
            $paths[] = $s->logFile;
        }
        $open = [];
        foreach ($paths as $path) {
            $st = @lstat($path);
            $perms = is_array($st) ? $st['mode'] : 0;
            $dir = ($perms & 0170000) === 0040000;
            if (($perms & 0004) !== 0 && ($perms & 0170000) !== 0120000 && ($dir ? ($s->dirMode & 0004) === 0 : ($s->fileMode & 0004) === 0 && is_array($st) && $st['size'] > 0 && substr($path, -2) !== '.c')) {
                $open[] = sprintf('%s (0%03o)', $path, $perms & 07777);
            }
        }
        if ($open !== []) {
            $out[] = 'everyone on this machine may read ' . implode(', ', array_slice($open, 0, 3)) . (count($open) > 3 ? ' and ' . (count($open) - 3) . ' more' : '')
                . ' -- made before file-mode/dir-mode, or by an umask: chmod o-rwx them (new ones get the modes set)';
        }
        $owner = @fileowner($s->storeDir);
        if ($owner !== false && function_exists('posix_geteuid') && $owner !== posix_geteuid() && ($s->fileMode & 0040) === 0) {
            $name = static fn (int $uid): string => function_exists('posix_getpwuid') && is_array($u = posix_getpwuid($uid)) ? $u['name'] : (string) $uid;
            $out[] = "store-dir belongs to {$name($owner)}, this command runs as {$name(posix_geteuid())}: what it writes there (lists, a learning run, advice) gets mode "
                . sprintf('0%03o', $s->fileMode) . " and this user -- the web server's PHP cannot read it. Run the command line as {$name($owner)} (sudo -u {$name($owner)} …), or set file-mode 0640 and dir-mode 0750 with a group both share";
        }
        return $out;
    }

    /**
     * What `check` warns about the compiled rules (the API's POST /check says the
     * same): rule files anyone could change, opened blocked paths, plugins not
     * there, the dashboard unguarded, the extensions' own warnings, feeds not in force.
     *
     * @param array{config: array<string, mixed>, seen: array<string, mixed>} $read RuleFile::read()
     * @return list<string>
     */
    public static function warnings(Settings $settings, array $read, string $file): array
    {
        $out = [];
        foreach ($settings->origins['warnings'] ?? [] as $w) {
            $out[] = "$w";
        }
        foreach (array_keys($read['seen']) as $path) {
            $perms = @fileperms($path);
            if ($perms !== false && ($perms & 0002) !== 0) {
                $out[] = "$path can be changed by anyone on this machine";
            }
        }
        foreach (self::modeWarnings($settings) as $w) {
            $out[] = $w;
        }
        foreach ($settings->blockExceptions as $n => $x) {
            if ($x['ips'] === []) {
                $out[] = ($settings->origin('blockExceptions', $x['paths'][0] ?? '') ?? "blockExceptions[$n]")
                    . ": blocked paths are open there for everyone -- add \"for <addresses>\", or make sure only admins reach it";
            }
        }
        // plugin … from <file>: a file that is not there (the rules warned at compile; here with the fix).
        foreach ($settings->pluginFiles as $class => $pluginFile) {
            if (!is_file($pluginFile)) {
                $out[] = ($settings->origin('plugins', $class) ?? 'plugins') . ": plugin $class from $pluginFile -- the file is not there; the plugin is left out until it is";
            }
        }
        // Plugins: a class that is not there, or no Plugin, is left out when the shield runs.
        foreach ($settings->plugins as $class) {
            if (!class_exists($class) || !is_subclass_of($class, \CjwNetwork\RequestShield\Plugin::class)) {
                $out[] = ($settings->origin('plugins', $class) ?? 'plugins') . ": plugin $class is not there, or is no " . \CjwNetwork\RequestShield\Plugin::class . " -- it is left out";
            }
        }
        foreach ((array) $settings->cacheableQuery as $name) {
            if (\CjwNetwork\RequestShield\Rule\CacheableRule::ignored($name, $settings->cacheableIgnore)) {
                $out[] = "cache-query names $name, and cache-ignore matches it -- it stays in the key (cache-query wins); narrow the cache-ignore name";
            }
        }
        if ($settings->cacheableUnknown === 'hit-only' && $settings->cacheableQuery === null) {
            $out[] = 'set cache-unknown-query hit-only, but no cache-query: every parameter is in the key, none is unknown -- name the parameters the pages use (cache-query page sort)';
        }
        if ($settings->sites !== [] && $settings->siteFrom === 'host' && $settings->hosts === []) {
            $out[] = "site blocks picked by the Host header (set site-from host), and no host rule -- a visitor names the website; list the names (host …), or use set site-from server-name";
        }
        // The dashboard's pages nobody guards (0031 B.6): no restrict rule covers them, no login is set up.
        $open = \CjwNetwork\RequestShield\Dashboard::unguarded($settings);
        if ($open !== []) {
            $out[] = "the dashboard's pages are open to everyone (" . implode(', ', array_slice($open, 0, 3)) . (count($open) > 3 ? ', …' : '')
                . ") -- add a rule such as \"restrict {$settings->dashboardPath}/** to <your addresses>\", or a login (dashboard-access)";
        }
        // The extensions' own warnings about the compiled settings (Extension::check(), 0031 B.4).
        foreach (\CjwNetwork\RequestShield\Rules\Vocabulary::extensions() as $extension) {
            foreach ($extension::check($settings) as $warning) {
                $out[] = "$warning";
            }
        }
        foreach (array_merge($settings->feeds, $settings->monitor !== null ? $settings->monitor->feeds : []) as $f) {
            if ($f['state'] !== 'in force') {
                $out[] = "{$f['rule']}: the feed {$f['name']} is " . ($f['file'] !== null ? "a file that cannot be read: {$f['file']} -- not used until it can"
                    : ($f['state'] === 'too old' ? 'older than feeds-max-age and not used' : 'not fetched yet') . " -- request-shield feeds $file update (cron, e.g. hourly)");
            }
        }
        return $out;
    }

}
}
}

// src/Cli/Command.php
namespace CjwNetwork\RequestShield\Cli {
if (true) {
/**
 * A command of bin/request-shield that an extension adds (Extension::commands(),
 * 0031 D.1): `request-shield <name> <main.rules> [options]`. The script reads
 * the rule file, compiles the settings and parses the common options into a
 * Context; the command prints to stdout and stderr and returns the exit code.
 */
interface Command
{
    /** The usage line, as the script prints it: "request-shield stats <main.rules> [--days=7] …". */
    public static function usage(): string;

    /** Runs it; the exit code (0 fine, 1 a mistake in the installation, 2 a mistake in the call). */
    public static function run(Context $c): int;
}
}
}

// src/Cli/Context.php
namespace CjwNetwork\RequestShield\Cli {
use CjwNetwork\RequestShield\Settings;

if (true) {
/**
 * What a command gets from the script (0031 D.1): the compiled settings, the
 * rule file, what the rule files held (RuleFile::read()), the word after the
 * file ("update", an address), and the common options as parsed.
 */
final class Context
{
    public string $command;
    public Settings $settings;
    public string $file;
    /**
     * @var array<string, mixed>
     */
    public array $read;
    /**
     * @var list<string>
     */
    public array $sources;
    public ?string $what;
    /**
     * @var array<string, mixed>
     */
    public array $options;
    /**
     * @var list<string>
     */
    public array $args;
    /**
     * @param array<string, mixed> $read what RuleFile::read() returned (config, seen, env, recheck, examples)
     * @param list<string> $sources the --source globs
     * @param array<string, mixed> $options the common options: days (int), json (bool), force (bool), ip, ua,
     *   period (from, to, by, site, crawler, path, tag, sort), feed (format, write), test (only, asWritten, junit),
     *   list (for, until, reason)
     * @param list<string> $args every argument as given
     */
    public function __construct(string $command, Settings $settings, string $file, array $read, array $sources, ?string $what, array $options, array $args)
    {
        /** @readonly */
        $this->command = $command;
        /** @readonly */
        $this->settings = $settings;
        /** @readonly */
        $this->file = $file;
        /** @readonly */
        $this->read = $read;
        /** @readonly */
        $this->sources = $sources;
        /** @readonly */
        $this->what = $what;
        /** @readonly */
        $this->options = $options;
        /** @readonly */
        $this->args = $args;
    }

    /**
     * An option's value, typed by its default.
     * @param mixed $default
     * @return mixed
     */
    public function option(string $name, $default = null)
    {
        return $this->options[$name] ?? $default;
    }
}
}
}

// src/Config.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The settings, as one PHP array (config/request-shield.dist.php shows every
 * key). A PHP file returning an array is cached by OPcache, so reading it
 * costs nothing after the first request.
 */
final class Config
{
    /** @return array<string, mixed> */
    public static function defaults(): array
    {
        return [
            // Addresses that may say who the client is (X-Forwarded-For, -Proto,
            // -Host): the load balancer, a reverse proxy, a CDN's ranges.
            'trustedProxies' => [],
            // Remove X-Forwarded-* from $_SERVER when the peer is not trusted, so
            // the application cannot be told another client, scheme or host either.
            'stripUntrustedForwarded' => true,
            'methods' => ['GET', 'HEAD', 'POST', 'OPTIONS'],
            // The site's hosts; empty: any host.
            'hosts' => [],
            'limits' => ['uri' => 4096, 'queryParameters' => 64, 'headerBytes' => 16384],
            'blockedPaths' => array_merge(self::scannerPaths(), self::devtoolsPaths()),
            // What may be cached. paths: regular expressions (null: every path);
            // query: parameter names (null: any, []: none); ignore: names no key holds,
            // taken out before a cache runs (0048); unknown: a parameter query does not
            // name -- "uncached" (never kept) or "hit-only" (answered from the key without it).
            'cacheable' => ['paths' => null, 'query' => null, 'ignore' => [], 'unknown' => 'uncached'],
            // Requests per client (IPv4 address, IPv6 /64) and window. Above
            // challengeAt: prove to be a browser (null: never); above limit: 429.
            'budgets' => [
                'requests' => ['limit' => 600, 'window' => 60, 'challengeAt' => null],
            ],
            'exempt' => ['ips' => ['127.0.0.1', '::1']],
            'ipv6Prefix' => 64,
            // auto: APCu when usable, else files in storeDir.
            'store' => 'auto',
            'storeDir' => rtrim(sys_get_temp_dir(), '/') . '/request-shield',
            // The browser check for clients past a budget's challengeAt: a proof of
            // work (ALTCHA-compatible) solved by a small script, then a signed pass
            // cookie. secret: shared by every server of the site (null: one is made
            // in storeDir). difficulty: maxnumber at the threshold and at the limit.
            'challenge' => [
                'secret' => null,
                'passTtl' => 3600,
                'solutionTtl' => 300,
                'difficulty' => ['min' => 50000, 'max' => 500000],
                'cookie' => 'rsp',
                'solutionCookie' => 'rss',
                'bindUserAgent' => true,
                // Verified crawlers are never challenged (the limit still applies).
                // true: the engines in Challenge\SearchEngines::defaults(); false: none.
                'searchEngines' => true,
                // Paths no browser loads as a page (APIs, feeds): never challenged.
                'exemptPaths' => [],
                // Paths every visitor has to pass the check for (once per pass
                // cookie), whatever the budgets say: a login or admin page.
                'alwaysPaths' => [],
                // An alwaysPaths entry => the methods it checks there (challenge POST **:
                // every form, not the pages); an entry not named here checks every method.
                'alwaysMethods' => [],
                // The language visitors read: auto (their browser's, among those
                // there are texts for; else English) or a code. Built in: en, de.
                'language' => 'auto',
                // Where the shield's own pages (404, a pause, the check page) link to,
                // "To the home page": a path (/) or an address; null: no link.
                'home' => null,
                // The browser check inside a form (Challenge\Widget): the endpoint's
                // path (/request-shield: .../challenge and .../widget.js); null: off.
                // widgetDifficulty: lower than the check page's -- the visitor types.
                'widgetPath' => null,
                'widgetDifficulty' => 25000,
                // The picture in the middle of the check page's ring: a path to an SVG
                // file of the site's own (checked strictly and inlined when the
                // settings are read -- use a rule file or Settings::load(), so that
                // happens once, not per request); null: a plain shield.
                'logo' => null,
                // The site's API: a check there (past a limit, say) is sent as JSON with
                // a Request-Shield-Challenge header; JSON requests count as API anyway.
                'apiPaths' => [],
                // New DNS lookups a minute to verify search engines, for all requests
                // together; past that a claimed crawler counts as not verified at once.
                // 0: no lookups (a DMZ without DNS).
                'dnsLookups' => 30,
                // Own texts: 'title' for every language, 'de.title' for one
                // (keys: Texts::KEYS).
                'texts' => [],
            ],
            // How hard the shield acts: off (nothing at all), monitor (everything
            // checked, counted and logged as it would be decided -- nobody is
            // refused), enforce, strict (enforce with tighter values, for a site
            // under attack). See docs/features/RSF05-03-modes.md.
            'mode' => 'enforce',
            // The rules again with those marked "monitor" in a rule file: they
            // are logged, not enforced (written by RuleFile; null: none).
            'monitorRules' => null,
            // Crawlers that behave, verified by where they come from (proposal 0011):
            // null: the shipped list (rules/crawlers.rules, compiled into
            // rules/crawlers.php); or ID => ['kind' => search|ai-search|ai-user|ai-training,
            // 'ua' => regex, 'dns' => [host suffixes], 'ranges' => [CIDR, ...]].
            // challenge.searchEngines false: none is recognised.
            'crawlers' => null,
            // What the site does with a verified crawler, by kind or by ID: allow
            // (never the browser check; the default), check (like any visitor),
            // block (403). ['ai-training' => 'block', 'CRAWL-GPTBOT' => 'check'].
            'crawlerPolicy' => [],
            // both | ranges (the address lists only, no DNS: a DMZ) | dns
            'crawlerVerify' => 'both',
            // X-RS: <action> <reason> on every response (for testing).
            'debugHeader' => false,
            // The application may ask for the browser check with a response header,
            // X-RS-Check: 1 (for a form page). Needs output buffering, so it is
            // off unless asked for; Shield::requirePass() works without it.
            'appChallenge' => false,
            // Paths only some addresses may open: [['paths' => [regex, ...], 'ips' => [range, ...]], ...].
            'restricted' => [],
            // Where blocked paths are let through anyway (an admin's file reader):
            // [['paths' => [regex, ...], 'patterns' => [blockedPaths entries] or null
            // (all), 'ips' => [range, ...] or [] (everyone)], ...]. Path sanity
            // (traversal, disguised paths) is never lifted.
            'blockExceptions' => [],
            // Attack patterns in the query and the headers (rules/attacks.rules):
            // [['target' => 'query'|'headers'|'anywhere'|'header:<name>',
            //   'patterns' => [regex, ...]], ...], matched against Request::content().
            'contentRules' => [],
            // Known query parameters and their types (Rule\QueryRule):
            // [['paths' => [regex, ...] or null (every path), 'exact' => [name => type],
            //   'globs' => [regex => type]], ...]; types: int, number, word, id, list,
            // text, any, or a regex. queryStrict: anything else is refused (404).
            // queryDrop: path patterns where anything else is dropped instead -- the
            // request goes on without it (GET and HEAD; attacks in it are still refused).
            'queryParams' => [],
            'queryStrict' => false,
            'queryDrop' => [],
            // Methods allowed only on some paths: ['POST' => [regex, ...]]; other
            // paths answer 405 for that method. Methods not listed: see 'methods'.
            'methodPaths' => [],
            // One line per request the shield did something about (Log). level:
            // stop (rejected, throttled, challenged), flag (also allow-uncached),
            // all (every request), off. ip: masked (/24, /48) or full.
            'log' => ['file' => null, 'level' => 'stop', 'ip' => 'masked', 'maxSize' => 10485760],
            // The live view's memory (APCu): the last requests stopped, with the full address, for keep seconds.
            'live' => ['enabled' => false, 'keep' => 3600],
            // Counters for the dashboard (proposals 0012, 0014): per hour in the
            // store (APCu, else files in storeDir/stats); hours kept for 'hours'
            // days, day totals for 'days' days. Off: nothing is counted.
            // 'parts': what is counted -- requests (actions, rules, status codes),
            // crawlers (0014), not-found (pages the site did not find, and the
            // links to them), bots (other bots by family), pages (the most visited
            // pages, by people, crawlers, bots). 'flush': with APCu,
            // every so many seconds the counts are written to the hour's file,
            // so a restart of PHP-FPM loses at most that much (0: only hourly).
            // Days past 'days' are summed into their month, kept 'months' months (0: for good).
            // 'depth': the folder levels a section's views are counted for exactly (1 to 4;
            // 2: /news/ and /news/2026/ -- 3 where a language takes the first: /de/news/2026/).
            // Where the dashboard's pages live (Settings::$routes, Routes): the core's
            // below <dashboardPath>/waf, the statistics' below <dashboardPath>/stats
            // (ext.stats.path). Something in front is fine: /admin/rs.
            'dashboardPath' => '/rs',
            // Where the pages' "?" links point: the docs' folder (Help::DOCS, the
            // repository's); a copy of your own, or 'off' for no links.
            'docsUrl' => 'https://github.com/cjw-network/request-shield/blob/main/docs',
            // The site's own error pages (proposal 0030): status or '4xx' => language ('' for
            // all) => HTML; a rule file's "set error-page 404 errors/404.html" reads them.
            'errorPages' => [],
            // A learning run (proposal 0016): what request-shield learn … start wrote to
            // <store-dir>/learn.json, read when the rules are compiled; null: none.
            'learn' => null,
            // The modes of the files and folders the shield makes (set file-mode, set
            // dir-mode): only PHP's user by default; a server's own rules exactly.
            'fileMode' => 0600,
            'dirMode' => 0700,
            // Plugins by class name: told what was decided and how a request ended
            // (proposal 0023). The statistics come with 'ext' => ['stats' => ['enabled' => true]].
            'plugins' => [],
            // The extensions' settings, by extension id (ext.<id>; proposal 0031). The
            // statistics' are the shipped extension's (StatsExtension, plugins/stats):
            // the keys described above, 'hosts' (websites with statistics of their
            // own) and 'skip' (path patterns not counted when they pass).
            // 'crawlerLog': one log file per known crawler and day
            // (dir/CRAWL-GPTBOT/2026-09-30.log), for the kinds listed ([]: all); kept
            // 'days' days; 'query' false leaves the query string out. dir null: none.
            'ext' => [
                'stats' => ['enabled' => false, 'parts' => ['requests', 'crawlers', 'not-found', 'bots', 'pages', 'forms'], 'hours' => 7, 'days' => 400, 'months' => 0, 'flush' => 60, 'depth' => 2, 'hosts' => [], 'skip' => [],
                    'crawlerLog' => ['dir' => null, 'kinds' => [], 'days' => 30, 'query' => true]],
            ],
            // Forms only from the website itself (post-origin same, proposal 0028):
            // ['missing' => 'check'|'allow'|'refuse', 'except' => [path patterns]]; null: off.
            'postOrigin' => null,
            // The editors' area (backend /admin/**, proposal 0028): its forms counted apart,
            // per area -- path patterns.
            'backend' => [],
        ];
    }

    /**
     * Paths only scanners ask for, on any PHP site.
     *
     * @return list<string>
     */
    public static function scannerPaths(): array
    {
        return [
            '#/\.(git|svn|hg|bzr|env|htpasswd|ds_store|idea|vscode)(/|$)#',
            '#\.(bak|old|orig|save|swp|sql|sql\.gz|tar|tar\.gz|tgz|zip|7z|rar|log)$#',
            '#/(phpinfo|php_info|info|test)\.php$#',
            '#/(vendor/phpunit|phpmyadmin|pma|adminer)(/|\.php|$)#',
            '#/(cgi-bin|\.well-known/(?!acme-challenge|security\.txt|change-password))#',
            '#/(composer\.(json|lock)|web\.config|docker-compose\.ya?ml|\.npmrc|id_(rsa|dsa|ecdsa|ed25519)(\.pub)?)$#',
            '#/\.(?:env[._-][a-z0-9._-]+$|(?:htaccess|user\.ini|aws|azure|gcloud|ssh|docker|dockerenv|kube|netrc|pgpass|my\.cnf|s3cfg|boto|pypirc|vault-token|terraform|bash_history|gitconfig|git-credentials|envrc|cursor|claude)(?:/|$))#',
            '#/(?:c(?:redentials?|lient[-_]secrets?)\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)|s(?:ecrets?\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)|ervice[-_]?account[a-z0-9_-]*\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)|erver\.key)|aws[-_]?(?:credentials|keys?)\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)|priv(?:ate(?:[-_]?key\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)|\.key)|key\.(?:json|ya?ml|env|pem|key|txt|ini|conf|cfg|properties|toml|xml)))$|\.(?:pem|p12|pfx|jks|keystore|ppk|kdbx|tfvars|tfstate(?:\.backup)?)$#',
        ];
    }

    /**
     * Addresses of other software's tools (rules/devtools.rules, @devtools):
     * build and settings files, debug and status pages, API consoles, a
     * development server's own addresses. Read by every site, as the
     * scanner paths are; a site that serves one through PHP takes that rule
     * back (unblock [DEV-APIDOCS]) or opens it for some addresses.
     *
     * @return list<string>
     */
    public static function devtoolsPaths(): array
    {
        return [
            '#/(?:package(?:-lock)?\\.json|yarn\\.lock|pnpm-lock\\.yaml|dockerfile|makefile|gemfile(?:\\.lock)?|requirements\\.txt|go\\.(?:mod|sum)|cargo\\.(?:toml|lock)|phpunit\\.xml(?:\\.dist)?|tsconfig\\.json|(?:webpack|vite|next|nuxt)\\.config\\.[cm]?[jt]s)$#',
            '#/(?:php\\.ini|appsettings(?:\\.[a-z]+)?\\.json|application(?:-[a-z]+)?\\.(?:ya?ml|properties)|(?:database|parameters|settings\\.local)\\.ya?ml|(?:local_)?settings\\.py)$#',
            '#^/(?:_profiler|_wdt|telescope|horizon|_ignition|_debugbar|debug/(?:vars|pprof|default)|actuator|jolokia|h2-console|server-status|server-info|elmah\\.axd|trace\\.axd|jmx-console|web-console|manager/html)(?:/|$)#',
            '#^/(?:swagger(?:-ui)?(?:\\.html)?|swagger\\.(?:json|ya?ml)|openapi\\.(?:json|ya?ml)|(?:v[1-3]/)?api-docs|graphiql)(?:/|$)#',
            '#\\.(?:js|css)\\.map$|^/@(?:fs|vite|id|react-refresh)(?:/|$)|^/(?:__vite[a-z_]*|__webpack_hmr|sockjs-node|webpack-dev-server)(?:/|$)#',
        ];
    }

    /**
     * Paths of WordPress, for every site that is not one.
     *
     * @return list<string>
     */
    public static function wordpressPaths(): array
    {
        return ['#^/(wp-admin|wp-includes|wp-content)(/|$)#', '#^/(wp-login|xmlrpc|wp-config)\.php$#'];
    }

    /**
     * The built-in blocks with their IDs and descriptions, for settings from a
     * PHP array. The source is rules/scanners.rules, rules/devtools.rules and rules/wordpress.rules
     * (a rule file reads those); a test keeps this copy the same.
     *
     * @return array<string, array{0: string, 1: string}> pattern => [ID, description]
     */
    public static function builtIns(): array
    {
        $s = self::scannerPaths();
        $d = self::devtoolsPaths();
        $w = self::wordpressPaths();
        return [
            $s[0] => ['SCAN-HIDDEN', 'hidden files and folders: .env, .git, .htpasswd, editor settings'],
            $s[1] => ['SCAN-BACKUP', 'backups, dumps and archives: .bak, .old, .sql, .zip, .tar.gz, .log …'],
            $s[2] => ['SCAN-TEST', 'test and info scripts: phpinfo.php, info.php, test.php'],
            $s[3] => ['SCAN-DBTOOL', 'database and test tools: phpMyAdmin, Adminer, PHPUnit'],
            $s[4] => ['SCAN-CGI', 'cgi-bin, and .well-known except certificates, security.txt and password change'],
            $s[5] => ['SCAN-CONFIG', 'project and key files: composer.json, web.config, docker-compose.yml, .npmrc, id_rsa'],
            $s[6] => ['SCAN-SECRETS', 'copies of .env and stored keys: .env.production, .aws, .ssh, .docker, .kube, .git-credentials, .htaccess'],
            $s[7] => ['SCAN-KEYS', 'credential files and key stores: credentials.json, service-account.json, secrets.yml, private.key, .pem, .p12, .tfstate'],
            $d[0] => ['DEV-BUILD', 'build files: package.json, yarn.lock, Dockerfile, Makefile, requirements.txt, phpunit.xml, webpack.config.js'],
            $d[1] => ['DEV-APPCONFIG', "other software's settings files: php.ini, appsettings.json, application.yml, database.yml, parameters.yml, settings.py"],
            $d[2] => ['DEV-DEBUG', "debug and status pages: Symfony's profiler, Laravel's Telescope and Horizon, Spring's actuator, server-status"],
            $d[3] => ['DEV-APIDOCS', 'API consoles and descriptions: swagger-ui, swagger.json, openapi.json, api-docs, graphiql'],
            $d[4] => ['DEV-SOURCE', "source maps and a development server's own addresses: main.js.map, /@fs/, /@vite/client, /__webpack_hmr"],
            $w[0] => ['WP-FOLDERS', 'WordPress folders: /wp-admin, /wp-includes, /wp-content'],
            $w[1] => ['WP-SCRIPTS', 'WordPress scripts: wp-login.php, xmlrpc.php, wp-config.php'],
        ];
    }

    /** A built-in pattern's ID ("SCAN-BACKUP"), or null. */
    public static function setName(string $pattern): ?string
    {
        return self::builtIns()[$pattern][0] ?? null;
    }

    /**
     * @param array<mixed> $config
     * @return array<mixed>
     */
    public static function merge(array $config): array
    {
        $merged = self::defaults();
        foreach ($config as $key => $value) {
            if (is_array($value) && isset($merged[$key]) && is_array($merged[$key])
                && !self::isList($value) && !self::isList($merged[$key])) {
                $merged[$key] = array_replace($merged[$key], $value);
            } else {
                $merged[$key] = $value;
            }
        }
        return $merged;
    }

    /**
     * array_is_list(), which PHP has only from 8.1.
     *
     * @param array<mixed> $a
     */
    private static function isList(array $a): bool
    {
        $i = 0;
        foreach ($a as $k => $_) {
            if ($k !== $i++) {
                return false;
            }
        }
        return true;
    }
}
}
}

// src/ContextHandler.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * A capability on a Plugin (0031 G.4, proposal 0039): the application tells
 * it who the visitor is, in the same PHP process -- an HTTP cache keeps a
 * page once per role instead of none for everyone with a login. Called
 * through Shield::active()?->cacheContext() by an adapter (a WordPress
 * plugin, an Exponential extension) while the application runs; nothing is
 * asked when no plugin has it. A plugin that throws is noted once a minute
 * and the application goes on.
 */
interface ContextHandler
{
    /**
     * The visitor of $request has the role $context (a hash of the user's
     * roles, "editor+author"): remembered for the session the request
     * carries. $shared: this answer is the same for everyone with the role
     * and may be kept for them.
     */
    public function cacheContext(Request $request, string $context, bool $shared): void;

    /** The visitor of $request signed out: the session's role is forgotten. */
    public function forgetContext(Request $request): void;
}
}
}

// src/Counts.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The numbers next to the rules: asked from the plugins that have the
 * RuleCounts capability (`$s->hooks['ruleCounts']`, recorded when the rules
 * were compiled), added up. The pages know no plugin by name; a plugin that
 * fails is left out (the page is drawn without its numbers).
 */
final class Counts
{
    /**
     * How often each rule decided in the last $days days, all plugins added up.
     *
     * @return array<string, int>
     */
    public static function rules(Settings $s, int $days, float $now): array
    {
        $sum = [];
        foreach (self::providers($s) as $plugin) {
            try {
                foreach ($plugin->ruleCounts($days, $now) as $rule => $n) {
                    $sum[(string) $rule] = ($sum[(string) $rule] ?? 0) + $n;
                }
            } catch (\Throwable $e) {
                // report only: the page comes without these numbers
            }
        }
        return $sum;
    }

    /**
     * What the known crawlers did in the last $days days: the first plugin
     * that counts them; null when none does.
     *
     * @return array<string, array{kind: string, policy: string, name: string, seen: int, verified: int, claimed: int, allowed: int, checked: int, refused: int, throttled: int, robots: int, pages: array<string, int>, last: array{0: int, 1: string}|null}>|null
     */
    public static function crawlers(Settings $s, int $days, float $now): ?array
    {
        foreach (self::providers($s) as $plugin) {
            try {
                $c = $plugin->crawlerCounts($days, $now);
                if ($c !== null) {
                    return $c;
                }
            } catch (\Throwable $e) {
                // report only
            }
        }
        return null;
    }

    /**
     * The plugins with the capability, made as the shield makes them (new $class($settings)).
     *
     * @return list<RuleCounts>
     */
    private static function providers(Settings $s): array
    {
        $out = [];
        foreach ($s->hooks['ruleCounts'] ?? [] as $class) {
            try {
                if (class_exists($class) && is_subclass_of($class, RuleCounts::class)) {
                    $out[] = new $class($s);
                }
            } catch (\Throwable $e) {
                // left out
            }
        }
        return $out;
    }
}
}
}

// src/Dashboard.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The shield serves the dashboard's pages itself (0031 B.6): a request the
 * rules let through whose path is a route (Routes) is answered here, before
 * the application -- behind Access::gate(), the route's role, with no-store
 * and noindex on every answer. A site wires nothing.
 *
 * Who may open a page: a `restrict` rule covering it (the address already
 * passed it when we get here: that is the administrator), or a login the
 * gate knows (dashboard-access). A route with
 * neither is refused -- `check` warns about it.
 *
 * In a build without the pages (the mini file alone, without the WAF plugin), a route
 * answers 404: the shield still never hands its own addresses to the site.
 */
final class Dashboard
{
    /**
     * The route of a request, or null -- cheap for the many requests that are
     * none: one stripos per place the routes lie (Routes::bases(); usually
     * just dashboard-path), then the table.
     *
     * @return array{key: string, ext: ?string, tab: ?array{0: string, 1: string}, role: string, order: int, page?: string, path: string}|null
     */
    public static function routeFor(Settings $s, Request $request): ?array
    {
        if ($s->routes === []) {
            return null;
        }
        foreach ($s->routeBases ?: [$s->dashboardPath] as $base) {
            if (stripos($request->path, $base) !== false) {
                /** @var array{key: string, ext: ?string, tab: ?array{0: string, 1: string}, role: string, order: int, page?: string, path: string}|null */
                return Routes::match($s, $request->matchPath());
            }
        }
        return null;
    }

    /**
     * Whether a `restrict` rule covers a path: the address that gets here passed it.
     */
    public static function restricted(Settings $s, string $path): bool
    {
        foreach ($s->restricted as $r) {
            foreach ($r['paths'] as $pattern) {
                if (@preg_match($pattern, $path) === 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * The routes nobody guards: no `restrict` rule covers them and the gate
     * has no logins -- for `check`.
     *
     * @return list<string>
     */
    public static function unguarded(Settings $s): array
    {
        if (Access::enabled($s)) {
            return [];
        }
        $open = [];
        foreach ($s->routes as $path => $route) {
            if (!self::restricted($s, $path)) {
                $open[] = $path;
            }
        }
        return $open;
    }

    /**
     * The answer for a route.
     *
     * @param array{key: string, ext: ?string, tab: ?array{0: string, 1: string}, role: string, order: int, page?: string, path: string} $route Routes::match()
     * @param array<mixed> $get $_GET
     * @param array<mixed> $post $_POST
     */
    public static function serve(Settings $s, Request $request, array $route, array $get, array $post, ?string $ruleFile = null): Response
    {
        $path = $request->matchPath();
        $prefix = (string) substr($path, 0, max(0, strlen(rtrim($path, '/')) - strlen(rtrim($route['path'], '/'))));
        $lang = is_string($get['lang'] ?? null) ? $get['lang'] : 'auto';
        $home = $prefix . '/';
        $homeLabel = $request->host;
        $admin = self::restricted($s, $path);
        $own = Access::headers($s);
        $api = $route['key'] === 'api';
        $cors = $api ? self::cors($s, $request) : [];
        if ($api && $request->method === 'OPTIONS') {
            // A browser's preflight carries no token: the API's page answers it (api-origins), before any login.
            $page = $route['page'] ?? null;
            if (is_string($page) && class_exists($page) && is_subclass_of($page, RoutePage::class)) {
                return $page::serve($s, $request, $route, ['who' => '', 'prefix' => '', 'get' => $get, 'post' => $post, 'method' => 'OPTIONS', 'lang' => $lang,
                    'accept' => null, 'links' => [], 'ip' => $request->clientIp, 'home' => '/', 'homeLabel' => '', 'ruleFile' => $ruleFile])->withHeaders($own);
            }
        }
        if (!$admin && !Access::enabled($s)) {
            if ($api) {
                return self::problem(403, 'Forbidden', 'The API is not set up: a restrict rule for ' . $s->dashboardPath . '/** or a login (dashboard-access) is needed.', array_merge($own, $cors));
            }
            // Nobody guards this page: refused, and check says what to do.
            return Response::html(403, self::plain($request, $lang, 'This page is not set up: a restrict rule for ' . $s->dashboardPath . '/** or a login (dashboard-access) is needed.',
                'Diese Seite ist nicht eingerichtet: eine restrict-Regel für ' . $s->dashboardPath . '/** oder ein Login (dashboard-access) fehlt.'), $own);
        }
        $gate = Access::gate($s, $request, $get, $post, ['admin' => $admin, 'lang' => $lang, 'home' => $home, 'homeLabel' => $homeLabel]);
        if ($gate['who'] === null && $api) {
            // A program gets JSON, never the login form (RFC 9457); a login's own answers (a signed link, sign-out) are no API's.
            $status = in_array($gate['status'], [401, 403, 429], true) ? $gate['status'] : 401;
            return self::problem($status, $status === 429 ? 'Too many requests' : ($status === 403 ? 'Forbidden' : 'Unauthorized'),
                $status === 429 ? 'Too many wrong tokens from this address: wait a minute.' : 'Send a token: Authorization: Bearer <token> (request-shield access-token).',
                array_merge(array_values(array_filter($gate['headers'], static fn (string $h): bool => stripos($h, 'Set-Cookie:') !== 0 && stripos($h, 'Location:') !== 0)), $status === 401 ? ['WWW-Authenticate: Bearer'] : [], $cors));
        }
        if ($gate['who'] === null) {
            return new Response($gate['status'], array_merge(['Content-Type: text/html; charset=utf-8'], $gate['headers']), (string) $gate['body']);
        }
        $who = $gate['who'];
        if ($route['role'] === 'admin' && $who !== '*' && $api) {
            return self::problem(403, 'Forbidden', 'This endpoint is the administrator\'s.', array_merge($gate['headers'], $cors));
        }
        if ($route['role'] === 'admin' && $who !== '*') {
            return Response::html(403, self::plain($request, $lang, 'This page is the administrator\'s.', 'Diese Seite ist dem Administrator vorbehalten.'), $gate['headers']);
        }
        $page = $route['page'] ?? null;
        if ($page === null || !class_exists($page) || !is_subclass_of($page, RoutePage::class)) {
            return Response::html(404, self::plain($request, $lang, 'This page is not part of this build.', 'Diese Seite ist nicht Teil dieser Ausgabe.'), $gate['headers']);
        }
        $links = Access::links($s, $who, Routes::links($s, $prefix));
        $ctx = ['who' => $who, 'prefix' => $prefix, 'get' => $get, 'post' => $post, 'method' => $request->method, 'lang' => $lang,
            'accept' => $request->header('accept-language'), 'links' => $links, 'ip' => $request->clientIp, 'home' => $home, 'homeLabel' => $homeLabel, 'ruleFile' => $ruleFile];
        return $page::serve($s, $request, $route, $ctx)->withHeaders($gate['headers']);
    }

    /**
     * CORS for an API answer: the Origin back, when api-origins names it (the API plugin's setting).
     *
     * @return list<string>
     */
    private static function cors(Settings $s, Request $request): array
    {
        $origin = (string) $request->header('origin');
        $allowed = $s->ext['api']['origins'] ?? [];
        return $origin !== '' && is_array($allowed) && in_array(strtolower(rtrim($origin, '/')), $allowed, true) ? ['Access-Control-Allow-Origin: ' . $origin, 'Vary: Origin'] : [];
    }

    /**
     * A problem for a program (RFC 9457): the API's answer when it cannot answer.
     *
     * @param list<string> $headers
     */
    private static function problem(int $status, string $title, string $detail, array $headers = []): Response
    {
        return new Response($status, array_merge(['Content-Type: application/problem+json; charset=utf-8', 'X-Content-Type-Options: nosniff'], $headers),
            (string) json_encode(['type' => 'about:blank', 'title' => $title, 'status' => $status, 'detail' => $detail], JSON_UNESCAPED_SLASHES));
    }

    /** A short page of the shield's own: one sentence, in the reader's language. */
    private static function plain(Request $request, string $lang, string $en, string $de): string
    {
        $german = Texts::language($lang, $request->header('accept-language')) === 'de';
        $e = static fn (string $v): string => htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        return '<!doctype html><html lang="' . ($german ? 'de' : 'en') . '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">'
            . '<title>request-shield</title><style>body{margin:0;padding:40px 20px;font:15px/1.5 system-ui,sans-serif;color:#1d2127;background:#f6f7f9}p{max-width:36em;margin:0 auto}</style></head><body>'
            . '<p>' . $e($german ? $de : $en) . '</p></body></html>';
    }
}
}
}

// src/Decision.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * What the shield decided about a request.
 *
 *   ALLOW           the application runs, and may cache the answer
 *   ALLOW_UNCACHED  the application runs, but must not keep the answer
 *                   (a URL outside the definition: rendered, never stored)
 *   CHALLENGE       the client has to prove it is a browser first
 *   THROTTLE        429 Too Many Requests, with Retry-After
 *   REJECT          an error status; the application never runs
 */
final class Decision
{
    public string $action;
    public int $status;
    public string $reason;
    public int $retryAfter = 0;
    public float $level = 0.0;
    public bool $spent = false;
    public ?string $claimed = null;
    public const ALLOW = 'allow';
    public const ALLOW_UNCACHED = 'allow-uncached';
    public const CHALLENGE = 'challenge';
    public const THROTTLE = 'throttle';
    public const REJECT = 'reject';

    private const RANK = [
        self::ALLOW => 0, self::ALLOW_UNCACHED => 1, self::CHALLENGE => 2,
        self::THROTTLE => 3, self::REJECT => 4,
    ];

    /** Immutable, so one is enough. */
    private static ?self $allow = null;

    private function __construct(string $action, int $status, string $reason, int $retryAfter = 0, float $level = 0.0, bool $spent = false, ?string $claimed = null)
    {
        /** @readonly */
        $this->action = $action;
        /** @readonly */
        $this->status = $status;
        /** @readonly */
        $this->reason = $reason;
        /** @readonly */
        $this->retryAfter = $retryAfter;
        /** @readonly */
        $this->level = $level;
        /** A budget past its limit that lets its client earn it back (onExceeded: challenge). */
        $this->spent = $spent;
        /** @readonly the known crawler the request named without coming from it (for the log), or null */
        $this->claimed = $claimed;
    }

    /** The same decision, noting that the request claimed to be a crawler it is not. */
    public function claiming(string $crawler): self
    {
        return new self($this->action, $this->status, $this->reason, $this->retryAfter, $this->level, $this->spent, $crawler);
    }

    public static function allow(): self
    {
        return self::$allow ??= new self(self::ALLOW, 200, '');
    }

    public static function allowUncached(string $reason): self
    {
        return new self(self::ALLOW_UNCACHED, 200, $reason);
    }

    /** @param float $level how far the client is past the threshold: 0 there, 1 at the limit */
    public static function challenge(string $reason, float $level = 0.0): self
    {
        return new self(self::CHALLENGE, 429, $reason, 0, max(0.0, min(1.0, $level)));
    }

    /**
     * A budget past its limit that asks for the browser check instead of a
     * pause: solved, the client's counter for it starts again. No pass cookie
     * gets past it -- only a solution made for this budget. $retryAfter: the
     * pause a client could wait instead (APIs).
     */
    public static function spent(string $budget, int $retryAfter): self
    {
        return new self(self::CHALLENGE, 429, $budget, max(1, $retryAfter), 1.0, true);
    }

    public static function throttle(string $reason, int $retryAfter): self
    {
        return new self(self::THROTTLE, 429, $reason, max(1, $retryAfter));
    }

    public static function reject(int $status, string $reason): self
    {
        return new self(self::REJECT, $status, $reason);
    }

    /** Whether the application gets to run. */
    public function passes(): bool
    {
        return $this->action === self::ALLOW || $this->action === self::ALLOW_UNCACHED;
    }

    /** Whether the application may keep its answer in a cache. */
    public function cacheable(): bool
    {
        return $this->action === self::ALLOW;
    }

    /** The more restrictive of two decisions. */
    public function stricter(self $other): self
    {
        $a = self::RANK[$this->action] ?? 0;
        $b = self::RANK[$other->action] ?? 0;
        // A spent budget's check outranks a plain one: a pass does not get past it.
        return $b > $a || ($b === $a && $other->spent && !$this->spent) ? $other : $this;
    }
}
}
}

// src/Describe.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * Settings and decisions in plain words, for people who do not read regular
 * expressions: the rules page and the command line use it.
 */
final class Describe
{
    /** A built-in pattern, as a site owner would say it. */
    public static function builtIn(string $pattern): ?string
    {
        return Config::builtIns()[$pattern][1] ?? null;
    }

    /**
     * A rule for people: its description (the comment after it in the rule
     * file), else the pattern as written.
     */
    public static function rule(Settings $s, string $setting, string $pattern): string
    {
        $id = $s->origin($setting, $pattern);
        $text = $id !== null ? $s->origin('text', $id) : null;
        return $text ?? self::pattern($s, $pattern);
    }

    /** Where a rule is written: "site.rules:12", "built-in scanners.rules:10". */
    public static function where(Settings $s, ?string $id): ?string
    {
        return $id === null ? null : $s->origin('at', $id);
    }

    /** A path pattern as it was written in a rule file, the built-in name, or the expression. */
    public static function pattern(Settings $s, string $pattern): string
    {
        $written = $s->origin('written', $pattern);
        if ($written !== null) {
            return $written;
        }
        return self::builtIn($pattern) ?? 'regex ' . trim((string) preg_replace('/^#|#i?$/', '', $pattern));
    }

    /** "minute", "10 seconds": a unit, or so many of it (German: "Minute", "10 Sekunden"). */
    public static function duration(int $seconds, string $lang = 'en'): string
    {
        $units = $lang === 'de' ? [86400 => ['Tag', 'Tage'], 3600 => ['Stunde', 'Stunden'], 60 => ['Minute', 'Minuten'], 1 => ['Sekunde', 'Sekunden']]
            : [86400 => ['day', 'days'], 3600 => ['hour', 'hours'], 60 => ['minute', 'minutes'], 1 => ['second', 'seconds']];
        foreach ($units as $size => [$one, $many]) {
            if ($seconds % $size === 0 && $seconds > 0) {
                $n = intdiv($seconds, $size);
                return $n === 1 ? $one : "$n $many";
            }
        }
        return "$seconds " . ($lang === 'de' ? 'Sekunden' : 'seconds');
    }

    /** "1 minute", "2 hours": a length of time rather than a unit. */
    public static function span(int $seconds, string $lang = 'en'): string
    {
        $d = self::duration($seconds, $lang);
        return ctype_digit($d[0]) ? $d : ($lang === 'de' ? ($seconds % 86400 === 0 ? 'einen ' : 'eine ') : '1 ') . $d;
    }

    /** What a visitor gets, in one sentence. */
    public static function verdict(Decision $d, string $lang = 'en'): string
    {
        if ($lang === 'de') {
            return self::verdictDe($d);
        }
        switch ($d->action) {
            case Decision::ALLOW:
                return 'sees the page — a cache may keep it';
            case Decision::ALLOW_UNCACHED:
                return 'sees the page — answered by the site, but a cache must not keep it';
            case Decision::CHALLENGE:
                return 'gets the browser check first: an invisible moment, then the page (not with a valid pass)';
            case Decision::THROTTLE:
                return "has to wait {$d->retryAfter} seconds (429 Too Many Requests)";
        }
        $what = [
            400 => 'a broken request (400) — the site never sees it',
            403 => 'no access (403) — the site never sees it',
            404 => '"not found" (404) — the site never sees it',
            405 => '"not allowed here" (405) — this kind of request is not accepted at this address',
            414 => 'an address that is too long (414)',
            431 => 'too much header data (431)',
        ];
        return 'gets ' . ($what[$d->status] ?? "an error ($d->status)");
    }

    /** What a visitor gets, in German. */
    private static function verdictDe(Decision $d): string
    {
        switch ($d->action) {
            case Decision::ALLOW:
                return 'sieht die Seite — ein Cache darf sie behalten';
            case Decision::ALLOW_UNCACHED:
                return 'sieht die Seite — von der Website beantwortet, aber ein Cache darf sie nicht behalten';
            case Decision::CHALLENGE:
                return 'bekommt zuerst den Browser-Check: ein unsichtbarer Moment, dann die Seite (nicht mit gültigem Pass)';
            case Decision::THROTTLE:
                return "muss {$d->retryAfter} Sekunden warten (429 Too Many Requests)";
        }
        $what = [
            400 => 'eine kaputte Anfrage (400) — die Website sieht sie nie',
            403 => 'kein Zugriff (403) — die Website sieht sie nie',
            404 => '„nicht gefunden“ (404) — die Website sieht sie nie',
            405 => '„hier nicht erlaubt“ (405) — diese Art von Anfrage wird an dieser Adresse nicht angenommen',
            414 => 'eine zu lange Adresse (414)',
            431 => 'zu viele Header-Daten (431)',
        ];
        return 'bekommt ' . ($what[$d->status] ?? "einen Fehler ($d->status)");
    }

    /** Whether a reason names a budget (a limit's name) rather than a check. */
    public static function isBudget(string $reason): bool
    {
        return self::reason($reason) === "the budget \"$reason\"";
    }

    /** Why, in words: a decision's reason (English or German). */
    public static function reason(string $reason, string $lang = 'en'): string
    {
        if ($lang === 'de') {
            $de = [
                'blocked path' => 'eine Adresse, die nur Angreifer aufrufen', 'restricted' => 'ein Bereich nur für bestimmte Adressen',
                'method' => 'diese Art von Anfrage ist nicht erlaubt', 'method not allowed here' => 'ein Formular, gesendet wohin keines gehört',
                'cross-site' => 'ein Formular, von einer anderen Website aus gesendet', 'origin missing' => 'ein Formular, das nicht sagt, woher es kommt (weder Origin noch Referer)',
                'host' => 'ein unbekannter Name der Website', 'uri length' => 'die Adresse ist zu lang', 'query parameters' => 'zu viele Parameter',
                'header size' => 'zu viele Header-Daten', 'path encoding' => 'eine getarnte Adresse', 'path traversal' => 'ein Versuch, den Ordner der Website zu verlassen',
                'query parameter' => 'ein Parameter, den ein Cache nicht behalten darf', 'path not cacheable' => 'eine Adresse, die ein Cache nicht behalten darf',
                'unknown url' => 'eine Adresse, die die Website nicht kennt', 'always' => 'eine Seite, auf der jeder Besucher geprüft wird',
                'app' => 'die Website hat den Browser-Check verlangt (ein Formular)', 'attack' => 'ein Angriffsmuster in der Adresse oder den Headern',
                'unknown parameter' => 'ein Parameter, den die Website nicht kennt, oder ein Wert nicht seines Typs', 'challenge solved' => 'der Browser-Check wurde gerade bestanden',
                'denied' => 'eine ausgesperrte Adresse (die Sperrliste)', 'banned' => 'für eine Weile gesperrt: sie ging immer wieder über die Grenzen',
                'crawler' => 'ein bekannter Crawler, den die Website so nicht will', 'feed' => 'auf einer öffentlichen Sperrliste',
                'access' => 'ein falsches Token oder ein ungültiger Link für die Statistik',
            ];
            return $de[$reason] ?? "das Budget „{$reason}“";
        }
        $words = [
            'blocked path' => 'an address only attackers ask for',
            'restricted' => 'an area only for certain addresses',
            'method' => 'this kind of request is not accepted',
            'method not allowed here' => 'a form sent where there is none',
            'cross-site' => 'a form sent from another website',
            'origin missing' => 'a form that does not say where it comes from (neither Origin nor Referer)',
            'host' => 'an unknown website name',
            'uri length' => 'the address is too long',
            'query parameters' => 'too many parameters',
            'header size' => 'too much header data',
            'path encoding' => 'a disguised address',
            'path traversal' => 'an attempt to leave the website\'s folder',
            'query parameter' => 'a parameter a cache must not keep',
            'path not cacheable' => 'an address a cache must not keep',
            'unknown url' => 'an address the site does not know',
            'always' => 'a page where every visitor is checked',
            'app' => 'the site asked for the browser check (a form)',
            'attack' => 'an attack pattern in the address or the headers',
            'unknown parameter' => 'a parameter the site does not know, or a value not of its type',
            'challenge solved' => 'the browser check was just passed',
            'denied' => 'an address kept out (the deny list)',
            'banned' => 'banned for a while: it kept going past the limits',
            'crawler' => 'a known crawler the site does not want this way',
            'feed' => 'on a public blocklist',
            'access' => 'a wrong token or link for the statistics',
        ];
        return $words[$reason] ?? "the budget \"$reason\"";
    }

    /**
     * What a rule the statistics counted is: its ID, its description, where it
     * is written -- for "site.rules:4" too (a rule without an ID).
     *
     * @return array{id: string, text: ?string, where: ?string}
     */
    public static function ruleInfo(Settings $s, string $counted): array
    {
        $id = str_replace('_', ' ', $counted);
        if ($s->origin('at', $counted) !== null || $s->origin('text', $counted) !== null) {
            $id = $counted;
        } elseif ($s->origin('at', $id) === null) {
            // A location, not an ID: the rule written there.
            foreach ($s->origins['at'] ?? [] as $rid => $at) {
                if ($at === $counted) {
                    $id = (string) $rid;
                    break;
                }
            }
        }
        return ['id' => $id, 'text' => $s->origin('text', $id), 'where' => $s->origin('at', $id)];
    }

    /** A rule ID as an anchor: letters, digits, "-", "_", "." only. */
    public static function anchor(string $id): string
    {
        return (string) preg_replace('/[^A-Za-z0-9_.-]/', '-', $id);
    }
}
}
}

// src/Endpoint.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * One endpoint of the API (RSF06-05): what it answers, for whom, and the
 * service that makes its data. The same service answers the HTTP request
 * and Api::call() in the same process, so both give the same array.
 */
final class Endpoint
{
    /**
     * @var string
     */
    public string $method;
    /**
     * @var string
     */
    public string $path;
    /**
     * @var string
     */
    public string $role;
    /**
     * @var bool
     */
    public bool $write;
    /**
     * @var class-string<ApiService>
     */
    public string $service;
    /**
     * @var array<string, mixed>
     */
    public array $schema;
    /**
     * @var string
     */
    public string $feature;
    /**
     * @var string
     */
    public string $summary;
    /**
     * @var array<string, array{type: string, required?: bool, about: string}>
     */
    public array $params = [];
    /**
     * @param string $method GET or POST (a write is a POST: DELETE is not among the methods a site accepts by default)
     * @param string $path below /api/v1, such as /lists/remove: fixed, the parameters come in the query (GET) or the JSON body (POST)
     * @param string $role reader (a customer's token may read it; the service shows that group only) or admin
     * @param bool $write changes something: only with set api-write on, and only for the administrator
     * @param class-string<ApiService> $service
     * @param array<string, mixed> $schema the shape of "data" in the answer (a JSON Schema subset: type, properties, items, required, enum)
     * @param string $feature the feature it belongs to (RSF<gg>-<nn>): its docs page
     * @param string $summary what it answers, in one sentence (OpenAPI, the reference)
     * @param array<string, array{type: string, required?: bool, about: string}> $params what it takes: name => type (string, int, bool), whether it must be there, what it is
     */
    public function __construct(string $method, string $path, string $role, bool $write, string $service, array $schema, string $feature, string $summary, array $params = [])
    {
        /** @readonly */
        $this->method = $method;
        /** @readonly */
        $this->path = $path;
        /** @readonly */
        $this->role = $role;
        /** @readonly */
        $this->write = $write;
        /** @readonly */
        $this->service = $service;
        /** @readonly */
        $this->schema = $schema;
        /** @readonly */
        $this->feature = $feature;
        /** @readonly */
        $this->summary = $summary;
        /** @readonly */
        $this->params = $params;
    }
}
}
}

// src/ErrorPage.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The shield's own page for a refusal (proposal 0030): the frame of the check
 * page -- a card, a quiet ring with a :-( or the site's logo, a title and one
 * sentence in the visitor's language, how long to wait after too many
 * requests, the way home. It never says why: no rule, no pattern, no list.
 * Self-contained -- inline CSS and SVG, no script, nothing loaded -- because a
 * visitor refused here is refused for the site's stylesheet too. An API gets
 * the same as JSON.
 */
final class ErrorPage
{
    /** For the built-in page only: it loads nothing and runs nothing, and nobody frames it. */
    public const CSP = "default-src 'none'; style-src 'unsafe-inline'; img-src data:; frame-ancestors 'none'";

    /** A face that is the same on every device: drawn, not an emoji. */
    private const FACE = '<g class="fc"><circle cx="60" cy="60" r="27"/><circle class="e" cx="50" cy="54" r="3.2"/><circle class="e" cx="70" cy="54" r="3.2"/><path d="M47 73q13-11 26 0"/></g>';

    private const CSS = ':root{--bg:#f6f7f9;--fg:#222;--m:#5b6470;--trk:#dde1e6}'
        . '@media(prefers-color-scheme:dark){:root{--bg:#16181c;--fg:#e6e6e6;--m:#a0a8b3;--trk:#2b3038}}'
        . 'body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;font:16px/1.5 system-ui,sans-serif;background:var(--bg);color:var(--fg)}'
        . 'main{max-width:28rem;padding:2rem;text-align:center}h1{font-size:1.3rem;margin:.8rem 0 .5rem}p{margin:.4rem 0}.ref{font-size:.85rem;color:var(--m)}'
        . '.home{margin-top:2rem;font-size:.9rem}.home a{color:inherit;opacity:.7}'
        . 'svg{display:block;margin:0 auto;color:var(--m)}.t{fill:none;stroke:var(--trk);stroke-width:6}'
        . '.fc circle{fill:none;stroke:var(--m);stroke-width:3.5}.fc .e{fill:var(--m);stroke:none}.fc path{fill:none;stroke:var(--m);stroke-width:3.5;stroke-linecap:round}';

    /**
     * The page.
     *
     * @param array<string, string> $texts in the visitor's language (Texts::all())
     * @param ?string $logo the site's logo for the ring's middle (set challenge-logo); null: the :-(
     */
    public static function render(Decision $d, array $texts, ?string $home = null, ?string $logo = null, ?string $reference = null, ?int $time = null): string
    {
        $t = $texts + Texts::all('en');
        $e = static fn (string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $title = Texts::status($d->status, $t);
        return '<!doctype html><html lang="' . $e($t['lang'] ?? 'en') . '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            . '<meta name="robots" content="noindex,nofollow"><title>' . $e($title) . '</title><style>' . self::CSS . '</style></head><body><main>'
            . '<svg viewBox="0 0 120 120" width="120" height="120" aria-hidden="true" focusable="false"><circle class="t" cx="60" cy="60" r="52"/>'
            . ($logo !== null ? '<g class="l">' . $logo . '</g>' : self::FACE) . '</svg>'
            . '<h1>' . $e($title) . '</h1><p>' . $e(self::sentence($d, $t)) . '</p>'
            . ($reference !== null ? '<p class="ref">' . $e(($t['reference'] ?? 'Reference') . ' ' . $reference . ($time !== null ? ' · ' . gmdate('H:i', $time) . ' UTC' : '')) . '</p>' : '')
            . ($home !== null ? '<p class="home"><a href="' . $e($home) . '">' . $e($t['home']) . '</a></p>' : '')
            . '</main></body></html>';
    }

    /**
     * The sentence for a status: what to do, never why; 429 with how long to wait.
     *
     * @param array<string, string> $t
     */
    public static function sentence(Decision $d, array $t): string
    {
        $text = Texts::sentence($d->status, $t);
        return str_replace('%s', (string) max(1, $d->retryAfter), $text);
    }

    /**
     * The same for an API: status, what it is in words, the reference, how long to wait.
     *
     * @return array{status: int, error: string, reference?: string, retryAfter?: int}
     */
    public static function json(Decision $d, ?string $reference = null): array
    {
        $out = ['status' => $d->status, 'error' => str_replace('-', ' ', Texts::key($d->status))];
        if ($reference !== null) {
            $out['reference'] = $reference;
        }
        if ($d->retryAfter > 0) {
            $out['retryAfter'] = $d->retryAfter;
        }
        return $out;
    }

    /** The statuses a page of the site's own may be for; 4xx: every one of them. */
    public const STATUSES = ['400', '403', '404', '405', '414', '429', '431', '4xx'];

    /** The largest page of the site's own: it lives in the compiled settings. */
    public const MAX = 65536;

    /**
     * A page of the site's own (set error-page <status> <file>): read when the
     * rules are compiled, checked -- there, not too large, UTF-8. "{lang}" in
     * the name gives one page per language (pause.{lang}.html: pause.de.html,
     * pause.en.html …); else one page for all ("" ).
     *
     * @return array{status: string, pages: array<string, string>, files: list<string>} the status, language => HTML, the files read
     * @throws \InvalidArgumentException saying what is wrong
     */
    public static function load(string $spec, string $dir): array
    {
        $parts = preg_split('/\s+/', trim($spec)) ?: [];
        if (count($parts) !== 2 || !in_array(strtolower($parts[0]), self::STATUSES, true)) {
            throw new \InvalidArgumentException('error-page <status> <file>: a status the shield refuses with (' . implode(', ', self::STATUSES) . ') and an HTML file');
        }
        [$status, $name] = [strtolower($parts[0]), $parts[1]];
        $path = $name[0] === '/' ? $name : rtrim($dir, '/') . '/' . $name;
        $files = [];
        if (strpos($path, '{lang}') !== false) {
            $re = '#^' . str_replace('\{lang\}', '([a-z]{2,3}(?:-[a-z0-9]{2,8})?)', preg_quote(basename($path), '#')) . '$#';
            // The folder read as it is (no glob: a folder's name may hold [ ] * ?).
            foreach (@scandir(dirname($path)) ?: [] as $f) {
                if (preg_match($re, $f, $m) === 1) {
                    $files[$m[1]] = dirname($path) . '/' . $f;
                }
            }
            ksort($files);
            if ($files === []) {
                throw new \InvalidArgumentException("error-page $status: no file $name for any language");
            }
        } else {
            $files[''] = $path;
        }
        $pages = [];
        foreach ($files as $lang => $f) {
            $html = is_file($f) && is_readable($f) ? @file_get_contents($f, false, null, 0, self::MAX + 1) : false;
            if ($html === false) {
                throw new \InvalidArgumentException("error-page $status: cannot read " . basename($f));
            }
            if (strlen($html) > self::MAX) {
                throw new \InvalidArgumentException("error-page $status: " . basename($f) . ' is larger than 64 KB');
            }
            if (preg_match('//u', $html) !== 1) {
                throw new \InvalidArgumentException("error-page $status: " . basename($f) . ' is not UTF-8');
            }
            $pages[(string) $lang] = $html;
        }
        // The folder too, for {lang}: a language's page added later is noticed like a changed rule file.
        return ['status' => $status, 'pages' => $pages, 'files' => array_merge(array_values($files), strpos($path, '{lang}') !== false ? [dirname($path)] : [])];
    }

    /**
     * The site's own page for a status in a language: its own status's, else
     * 4xx's -- each for the language, else the one for all; null: none (the
     * built-in one answers).
     *
     * @param array<int|string, array<string, string>> $pages status => language => HTML
     */
    public static function own(array $pages, int $status, string $lang): ?string
    {
        foreach ([(string) $status, '4xx'] as $key) {
            $byLang = $pages[$key] ?? [];
            $page = $byLang[$lang] ?? $byLang[explode('-', $lang)[0]] ?? $byLang[''] ?? null;
            if ($page !== null) {
                return $page;
            }
        }
        return null;
    }

    /**
     * The placeholders of a page of the site's own, filled in and escaped:
     * {status} {title} {text} {wait} {home} {lang} {reference}. Anything else
     * in braces stays as it is (CSS and scripts keep theirs).
     *
     * @param array<string, string> $texts
     */
    public static function fill(string $html, Decision $d, array $texts, ?string $home, ?string $reference): string
    {
        $t = $texts + Texts::all('en');
        $e = static fn (string $s): string => htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        return strtr($html, [
            '{status}' => (string) $d->status, '{title}' => $e(Texts::status($d->status, $t)), '{text}' => $e(self::sentence($d, $t)),
            '{wait}' => (string) max(0, $d->retryAfter), '{home}' => $e($home ?? '/'), '{lang}' => $e($t['lang'] ?? 'en'), '{reference}' => $e($reference ?? ''),
        ]);
    }

    /** Letters and digits that cannot be mistaken for each other when read aloud or typed (no 0/O, 1/I/L, U). */
    private const REFERENCE = '23456789ABCDEFGHJKMNPQRSTVWXYZ';

    /**
     * A reference for one refusal (0030): eight random characters, "7KQ2-M4XD"
     * -- on the page, in the JSON and in the log line (ref=…), so "I got an
     * error at 14:31" becomes one line in the log. It means nothing without the log.
     */
    public static function reference(): string
    {
        $out = '';
        for ($i = 0; $i < 8; $i++) {
            $out .= self::REFERENCE[random_int(0, strlen(self::REFERENCE) - 1)] . ($i === 3 ? '-' : '');
        }
        return $out;
    }
}
}
}

// src/Extension.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Rules\Vocabulary;

if (true) {
/**
 * An extension: words and settings of its own in the rule file, checked when
 * the rules are compiled -- never at request time (ADR 0008). Everything
 * here is static: the compiler asks, the answers end up in the compiled
 * settings (`$s->ext[<id>]`, `$s->routes`), and a request reads those.
 *
 * What runs per request is a `Plugin`, named by the rules or appended by
 * compile(); an extension may be both. The shield's own statistics are the
 * first extension (plugins/stats); `tests/support/RsTestExtension.php` is
 * the smallest one.
 */
interface Extension
{
    /** The id: letters, digits, "-" (stats, rs-test). Its settings live in ext.<id>. */
    public static function id(): string;

    /** Its words (rules) and set keys: $v->word(), $v->set(). */
    public static function vocabulary(Vocabulary $v): void;

    /**
     * Checks what the rule file wrote into ext.<id> and returns the values the
     * plugin reads at request time; the whole base settings are there to
     * check against (hosts, dashboard-path, …). A wrong value is an
     * InvalidArgumentException naming the setting (Settings::wrong('ext.<id>.<key>', …)):
     * on the request path the last good compiled settings stay in force.
     *
     * @param array<string, mixed> $raw what the parser collected (ext.<id>)
     * @return array<string, mixed> the checked values, as the plugin wants them
     */
    public static function compile(array $raw, Settings $base): array;

    /**
     * The Plugin classes to run per request, given the compiled slot: the
     * compiler appends them to the settings' plugins (0031 B.4), so a request
     * reads one list as before. [] for an extension that only speaks at
     * compile time.
     *
     * @param array<string, mixed> $compiled what compile() returned
     * @return list<class-string>
     */
    public static function plugins(array $compiled): array;

    /**
     * The pages it has, given its compiled slot (0031 B.5): full path =>
     * entry, as Routes carries them -- key (what the page is), tab ([English,
     * German] label; null: no tab, a start alias), role (admin or reader) and
     * order (the tabs' order); the compiler sets ext to the id. The paths
     * come from the slot (compile() keeps the base's dashboard-path there if
     * the pages live below it), so `set dashboard-path` moves them. [] for an
     * extension without pages. Two routes on one path refuse to compile.
     *
     * @param array<string, mixed> $compiled what compile() returned
     * @return array<string, array{key: string, tab: ?array{0: string, 1: string}, role: string, order: int}>
     */
    public static function routes(array $compiled): array;

    /**
     * Its command-line commands (0031 D.1): name => the class that runs it
     * (Cli\Command); `request-shield <name> <main.rules> …` reads the rules,
     * compiles the settings and hands the command a Cli\Context.
     *
     * @return array<string, class-string<\CjwNetwork\RequestShield\Cli\Command>>
     */
    public static function commands(): array;

    /**
     * Warnings for `request-shield check` about the compiled settings: a plugin
     * class that is not there, a page without access rules (0031 B.4).
     *
     * @return list<string>
     */
    public static function check(Settings $s): array;
}
}
}

// src/Failure.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * Something in the shield failed and the request went on (ADR 0007): noted
 * in PHP's error log, once a minute per cause -- the visitor never sees it.
 * Across requests and workers too (APCu, else a marker file in the given
 * directory): a broken deploy is one line a minute, not one a visitor.
 */
final class Failure
{
    /** @var array<string, int> the cause (what failed, and the message) => when it was last noted, this process */
    private static array $noted = [];

    /**
     * @param string $what which part failed: "shield", "settings", a plugin's class, a hook
     * @param string|false|null $dir where "already noted" is kept across requests: the site's
     *   store or cache directory; null for the temp dir (no settings yet); false for this process only
     */
    public static function note(string $what, string $message, $dir): void
    {
        $now = time();
        $cause = hash('crc32b', $what . '|' . substr($message, 0, 200));
        if ($now - (self::$noted[$cause] ?? 0) < 60) {
            return;
        }
        self::$noted[$cause] = $now;
        $dir ??= rtrim(sys_get_temp_dir(), '/') . '/request-shield';
        if ($dir !== false) {
            if (Capability::apcu()) {
                if (!apcu_add('rshield:failed:' . hash('crc32b', $dir) . ':' . $cause, $now, 60)) {
                    return;
                }
            } else {
                $marker = $dir . '/failed-' . $cause;
                $last = @filemtime($marker);
                if ($last !== false && $now - $last < 60) {
                    return;
                }
                Files::write($marker, '');
            }
        }
        error_log('request-shield: ' . $message);
    }
}
}
}

// src/Files.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The modes of what the shield creates: its folders (store-dir, the log's,
 * the statistics', the lists', the feeds', the HTTP cache's) and its files
 * (the log, the statistics, the lists, the feeds, marks, a learning run, the
 * advice) -- `set dir-mode` and `set file-mode`, by default 0700 and 0600:
 * only the user PHP runs as. A server's own rules for new folders (0750,
 * 02770 so the group is inherited, 0755) are set exactly: a new folder or
 * file gets its mode with chmod() after it is made and before anything is
 * written into it, so the umask takes nothing away and adds nothing. What
 * exists keeps its mode; a file written whole is a new file.
 *
 * Never allowed: writing for everyone, and a mode that keeps PHP itself from
 * writing (the owner's rw, for a folder rwx). The secret stays 0600 and the
 * compiled settings 0600 in a 0700 folder whatever is set: they hold the key.
 *
 * The modes are taken from the settings when they are made (Settings'
 * constructor) -- the one place every request and every command passes
 * before it writes.
 */
final class Files
{
    private static int $fileMode = 0600;

    private static int $dirMode = 0700;

    /** Whether to append as with threads (ZTS: no umask); null: as PHP is built (a test sets it) */
    /** @phpstan-ignore property.unusedType */
    private static ?bool $threads = null;

    /** Whether a mode may be a file's: the owner reads and writes, nobody else writes everyone's, no special bits. */
    public static function fileModeOk(int $mode): bool
    {
        return ($mode & ~0777) === 0 && ($mode & 0600) === 0600 && ($mode & 0002) === 0 && ($mode & 0111) === 0;
    }

    /** Whether a mode may be a folder's: the owner rwx, not writable for everyone; setgid and sticky allowed. */
    public static function dirModeOk(int $mode): bool
    {
        return ($mode & ~03777) === 0 && ($mode & 0700) === 0700 && ($mode & 0002) === 0;
    }

    /** "0640", "640", "02770" as a number; null when it is no mode. */
    public static function parseMode(string $value): ?int
    {
        return preg_match('/^0?[0-7]{3,4}$/', $value) === 1 ? (int) octdec($value) : null;
    }

    /** Takes the modes of the settings (Settings' constructor); a mode that is not allowed keeps the default. */
    public static function modes(int $file, int $dir): void
    {
        self::$fileMode = self::fileModeOk($file) ? $file : 0600;
        self::$dirMode = self::dirModeOk($dir) ? $dir : 0700;
    }

    public static function fileMode(): int
    {
        return self::$fileMode;
    }

    public static function dirMode(): int
    {
        return self::$dirMode;
    }

    /** A folder, with the parents it lacks, each in dir-mode exactly; true when it is there. */
    public static function dir(string $dir): bool
    {
        if (is_dir($dir)) {
            return true;
        }
        $missing = [];
        for ($d = $dir; $d !== '' && $d !== '.' && $d !== '/' && !is_dir($d); $d = dirname($d)) {
            $missing[] = $d;
            if (dirname($d) === $d) {
                break;
            }
        }
        if (!@mkdir($dir, self::$dirMode & 0777, true) && !is_dir($dir)) {
            return false;               // another process may have made it in between: is_dir() decides
        }
        foreach ($missing as $d) {
            @chmod($d, self::$dirMode);   // exactly: setgid, and what the umask took
        }
        return true;
    }

    /**
     * Whether a folder is gone, asked of the disk: a write into it failed,
     * and PHP's stat cache may still remember it from before logrotate or a
     * clean-up removed it -- is_dir() would say it is there, and nothing
     * would be made anew.
     */
    private static function lost(string $dir): bool
    {
        clearstatcache(true, $dir);
        return !is_dir($dir);
    }

    /**
     * A file written whole: a temporary file made exclusive in file-mode
     * (create()), then the data, then renamed -- a reader never sees half of it, and
     * the data is never in a file of another mode. $keep: the read and write
     * bits of the file it replaces (a file named by the user, read by
     * something else).
     */
    public static function write(string $file, string $data, string $suffix = '', bool $keep = false): bool
    {
        if (!self::dir(dirname($file))) {
            return false;
        }
        $tmp = $file . '.' . bin2hex(random_bytes(4)) . $suffix;
        $old = $keep ? @fileperms($file) : false;
        $h = self::create($tmp, $old !== false ? $old & 0666 : self::$fileMode);
        if ($h === false) {
            return false;
        }
        $ok = @fwrite($h, $data) === strlen($data);
        fclose($h);
        if (!$ok || !@rename($tmp, $file)) {
            @unlink($tmp);
            return false;
        }
        return true;
    }

    /**
     * A new file, exclusive, open for writing, in $mode from the start: made
     * with the umask $mode's complement (no x, no special bits: exact) -- a
     * handle opened on it in between could read what is written later. With
     * threads (ZTS, the umask is the process's) made, then chmod. A file
     * system without modes refuses chmod: written all the same.
     *
     * @return resource|false
     */
    public static function create(string $file, int $mode)
    {
        if (!(self::$threads ?? ZEND_THREAD_SAFE)) {
            $umask = umask(0777 & ~$mode);
            try {
                return @fopen($file, 'xb');
            } finally {
                umask($umask);
            }
        }
        $h = @fopen($file, 'xb');
        if ($h !== false) {
            @chmod($file, $mode);
        }
        return $h;
    }

    /**
     * A line added to a file (O_APPEND: the lines of parallel requests do not
     * overwrite each other). A new file is made in file-mode at once: the
     * umask is file-mode's complement for that one call (a file mode has no
     * x and no special bits, so the result is exact) -- no second look, no
     * moment in another mode. With threads (ZTS) the umask is the whole
     * process's: then the file is opened, and one still empty (just made, by
     * this request or a parallel one) gets file-mode before the line. A
     * missing folder is made. $lock: an exclusive lock while writing.
     */
    public static function append(string $file, string $data, bool $lock = false): bool
    {
        if (!(self::$threads ?? ZEND_THREAD_SAFE)) {
            $umask = umask(0777 & ~self::$fileMode);
            try {
                $ok = @file_put_contents($file, $data, FILE_APPEND | ($lock ? LOCK_EX : 0));
            } finally {
                umask($umask);
            }
            if ($ok === false && self::lost(dirname($file)) && self::dir(dirname($file))) {
                return self::append($file, $data, $lock);
            }
            return $ok !== false;
        }
        $h = @fopen($file, 'ab');
        if ($h === false && self::lost(dirname($file)) && self::dir(dirname($file))) {
            $h = @fopen($file, 'ab');
        }
        if ($h === false) {
            return false;
        }
        $st = fstat($h);
        if (is_array($st) && $st['size'] === 0 && ($st['mode'] & 07777) !== self::$fileMode) {
            @chmod($file, self::$fileMode);
        }
        if ($lock) {
            flock($h, LOCK_EX);
        }
        $ok = @fwrite($h, $data) === strlen($data);
        fclose($h);
        return $ok;
    }
}
}
}

// src/Frame.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The frame of the dashboard's own pages (live, lists): the same colours and
 * tabs as the statistics, inline CSS, no external file, never indexed.
 */
final class Frame
{
    /**
     * The addresses of the dashboard's pages (every route with a tab, in
     * the tabs' order): the statistics plugin's below stats-path, the
     * WAF plugin's below <dashboard-path>/waf -- from the compiled routes.
     *
     * @return array<string, string> key => address (sites with stats-hosts, all, site, shield, rules, live, lists …)
     */
    public static function links(Settings $s, string $prefix = ''): array
    {
        return Routes::links($s, $prefix);
    }

    /**
     * Whether a path is one of the dashboard's pages -- also below a prefix
     * (/demo/index.php/rs/waf/live): for what the dashboard's own requests may
     * skip (the pace), never for who may open them.
     */
    public static function isPage(Settings $s, string $path): bool
    {
        return Routes::match($s, $path) !== null;
    }

    /** Which page a path asks for (a key of links(); <dashboard-path>/waf is the firewall's start, live), or null; capitals do not matter. */
    public static function pageFor(Settings $s, string $path): ?string
    {
        return Routes::page($s, $path);
    }

    /**
     * The tabs as links, labelled from the routes; $current is marked.
     *
     * @param array<string, string> $links key => address
     */
    public static function tabs(Settings $s, array $links, string $current, string $lang): string
    {
        $e = static fn (string $v): string => htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $h = '';
        foreach (Routes::tabs($s) as $key => [$en, $de]) {
            if (isset($links[$key]) && $links[$key] !== '') {
                $h .= '<a class="tab' . ($key === $current ? ' on' : '') . '" href="' . $e($links[$key] . '?lang=' . $lang) . '">' . $e($lang === 'de' ? $de : $en) . '</a>';
            }
        }
        return $h === '' ? '' : '<nav class="tabs">' . $h . '</nav>';
    }

    /**
     * A section's heading with its "?" link into the docs (Help; nothing with the links off).
     *
     * @param string $anchor a heading of the feature's page (docs/tools/check-anchors.php finds them)
     */
    public static function h2(string $text, Settings $s, string $id, string $anchor, string $lang, string $attrs = ''): string
    {
        $link = Help::link($id, $anchor, $s->docsUrl, $lang);
        return '<h2' . ($attrs !== '' ? ' ' . $attrs : '') . '>' . htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . ($link !== '' ? ' ' . $link : '') . '</h2>';
    }

    /** @param array<string, mixed> $o home, homeLabel; help: the "?" link after the title (Help::link(), HTML) */
    public static function page(string $title, string $lang, string $body, array $o, string $css = '', string $script = ''): string
    {
        $e = static fn (string $v): string => htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        return '<!doctype html><html lang="' . $e($lang) . '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
            . '<meta name="robots" content="noindex,nofollow"><title>' . $e($title) . '</title><style>' . self::CSS . $css . '</style></head><body>'
            . (is_string($o['home'] ?? null) ? '<header><a href="' . $e($o['home']) . '">← ' . $e(is_string($o['homeLabel'] ?? null) ? $o['homeLabel'] : 'Back') . '</a></header>' : '')
            . '<main><h1>' . $e($title) . (is_string($o['help'] ?? null) && $o['help'] !== '' ? ' ' . $o['help'] : '') . '</h1>' . $body . '</main>' . ($script !== '' ? '<script>' . $script . '</script>' : '') . '</body></html>';
    }

    private const CSS = <<<'CSS'
:root{--bg:#f4f6f9;--fg:#1d2127;--m:#5b6470;--card:#fff;--line:#e3e7ec;--a:#2f62c9;--through:#1e8a52;--checked:#2f62c9;--throttled:#c07a00;--refused:#c2412d;--watched:#8b5cf6}
@media (prefers-color-scheme:dark){:root{--bg:#121519;--fg:#e7e9ec;--m:#9aa4b0;--card:#1b1f24;--line:#2d333b;--a:#7aa2ff;--through:#4cc38a;--checked:#6f9bff;--throttled:#e0a43c;--refused:#ff7a66;--watched:#a78bfa}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}
header{max-width:1240px;margin:0 auto;padding:14px 16px 0}a{color:var(--a)}main{max-width:1240px;margin:0 auto;padding:6px 16px 28px}
h1{font-size:26px;margin:8px 0 4px}h2{font-size:16px;margin:18px 0 8px}.note,.foot{color:var(--m)}.foot{font-size:13px;margin-top:14px}
.tabs{display:flex;flex-wrap:wrap;gap:4px;border-bottom:1px solid var(--line);margin:8px 0 12px}.tab{padding:6px 12px;text-decoration:none;color:var(--m);border-bottom:2px solid transparent;margin-bottom:-1px}
.tab.on{color:var(--fg);border-color:var(--a);font-weight:600}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:0 0 12px}
input,select,button,textarea{font:inherit;color:var(--fg);background:var(--card);border:1px solid var(--line);border-radius:8px;padding:5px 9px}
button{cursor:pointer}button.primary{background:var(--a);border-color:var(--a);color:#fff}button.danger{color:var(--refused)}
.msg{padding:8px 12px;border-radius:8px;margin:0 0 12px;border:1px solid var(--line);background:var(--card)}.msg.ok{border-color:var(--through)}.msg.bad{border-color:var(--refused);color:var(--refused)}
table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:var(--m);font-weight:500;font-size:12px;padding:4px 6px;border-bottom:1px solid var(--line)}
td{padding:5px 6px;border-bottom:1px solid var(--line);vertical-align:top}.mono,code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px}
.badge{display:inline-block;font-size:12px;padding:0 7px;border-radius:999px;border:1px solid var(--line);white-space:nowrap}
.wrap{overflow-x:auto}
CSS . Help::CSS;
}
}
