    /**
     * The release key (minisign, Ed25519; the public key's base64 line): what
     * `verify` and `self-update` check a download's signature with. Empty until
     * the owner makes the key (0031 step H.2a) -- then verify checks the
     * checksum only and says so, and self-update refuses.
     */
    public const PUBKEY = '';

    /** @var array{crawlers: array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>, index: string, ids: list<string>, names: array<string, string>}|null */
    private static ?array $crawlers = null;

    /** Whether the data is embedded (the single file), not read from rules/. */
    public static function embedded(): bool
    {
        return self::embeddedRules() !== [];
    }

    /** The contents of a shipped rule set ("scanners" or "@scanners"), null when there is none of that name. */
    public static function rules(string $name): ?string
    {
        $name = ltrim($name, '@');
        if (!self::valid($name)) {
            return null;
        }
        if (self::embedded()) {
            return self::embeddedRules()[$name] ?? null;
        }
        $text = @file_get_contents(self::dir() . "/$name.rules");
        return $text === false ? null : $text;
    }

    /** The file whose change means the set changed: rules/<name>.rules, or this file when embedded; null when there is no such set. */
    public static function rulesFile(string $name): ?string
    {
        $name = ltrim($name, '@');
        if (!self::valid($name)) {
            return null;
        }
        if (self::embedded()) {
            return isset(self::embeddedRules()[$name]) ? __FILE__ : null;
        }
        $file = self::dir() . "/$name.rules";
        return is_file($file) ? $file : null;
    }

    /**
     * The shipped rule sets' names, sorted (for `version`).
     *
     * @return list<string>
     */
    public static function sets(): array
    {
        if (self::embedded()) {
            $names = array_keys(self::embeddedRules());
        } else {
            $names = array_map(static fn (string $f): string => basename($f, '.rules'), glob(self::dir() . '/*.rules') ?: []);
        }
        sort($names, SORT_STRING);
        return $names;
    }

    /** The feed catalog (rules/feeds.json), '' when there is none. */
    public static function feeds(): string
    {
        if (self::embedded()) {
            return self::FEEDS;
        }
        return (string) @file_get_contents(self::dir() . '/feeds.json');
    }

    /** The starter rule file for an application (rules/starter/<app>.rules), null when there is none. */
    public static function starter(string $app): ?string
    {
        if (!self::valid($app)) {
            return null;
        }
        if (self::embedded()) {
            return self::embeddedStarters()[$app] ?? null;
        }
        $text = @file_get_contents(self::dir() . "/starter/$app.rules");
        return $text === false ? null : $text;
    }

    /**
     * The applications there is a starter for, sorted.
     *
     * @return list<string>
     */
    public static function starters(): array
    {
        $names = self::embedded() ? array_keys(self::embeddedStarters())
            : array_map(static fn (string $f): string => basename($f, '.rules'), glob(self::dir() . '/starter/*.rules') ?: []);
        sort($names, SORT_STRING);
        return $names;
    }

    /** A shipped address list (rules/crawlers/<name>.json) as JSON, null when there is none of that name. */
    public static function crawlerList(string $name): ?string
    {
        if (!self::valid($name)) {
            return null;
        }
        if (self::embedded()) {
            return self::embeddedLists()[$name] ?? null;
        }
        $json = @file_get_contents(self::dir() . "/crawlers/$name.json");
        return $json === false ? null : $json;
    }

    /** The file whose change means the list changed (rules/crawlers/<name>.json, or this file when embedded); null when there is none. */
    public static function crawlerListFile(string $name): ?string
    {
        if (!self::valid($name)) {
            return null;
        }
        if (self::embedded()) {
            return isset(self::embeddedLists()[$name]) ? __FILE__ : null;
        }
        $file = self::dir() . "/crawlers/$name.json";
        return is_file($file) ? $file : null;
    }

    /**
     * The shipped crawlers ready for Settings (rules/crawlers.php, made by
     * bin/update-crawler-lists): what settings from a PHP array use without
     * a compile. Not embedded (330 KB that only serves Shield::protect(array));
     * the single file builds the same from its rule set and lists, once per
     * process.
     *
     * @return array{crawlers: array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>, index: string, ids: list<string>, names: array<string, string>}
     */
    public static function crawlers(): array
    {
        if (self::$crawlers === null) {
            /** @var array{crawlers: array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>, index: string, ids: list<string>, names: array<string, string>} $ready */
            $ready = self::embedded() ? RuleFile::shippedReady() : require self::dir() . '/crawlers.php';
            self::$crawlers = $ready;
        }
        return self::$crawlers;
    }

    /** Whether a path is one of the shipped files -- a shipped set, not a site's file (for `check`). */
    public static function isShipped(string $path): bool
    {
        $real = realpath($path);
        if ($real === false) {
            return false;
        }
        if (self::embedded()) {
            return $real === realpath(__FILE__);
        }
        $dir = realpath(self::dir());
        return $dir !== false && strncmp($real, $dir . '/', strlen($dir) + 1) === 0;
    }

    /** The name a source is shown with: "built-in scanners.rules" for a shipped file, null for any other. */
    public static function label(string $path): ?string
    {
        if (self::embedded() || !self::isShipped($path)) {
            return null;
        }
        $dir = (string) realpath(self::dir());
        return 'built-in ' . substr((string) realpath($path), strlen($dir) + 1);
    }

    /** @return array<string, string> RULES, typed (empty in the repository) */
    private static function embeddedRules(): array
    {
        return self::RULES;
    }

    /** @return array<string, string> STARTERS, typed (empty in the repository) */
    private static function embeddedStarters(): array
    {
        return self::STARTERS;
    }

    /** @return array<string, string> CRAWLER_LISTS, typed (empty in the repository) */
    private static function embeddedLists(): array
    {
        return self::CRAWLER_LISTS;
    }

    /** A shipped name: letters, digits and "-" only, so it never leaves the directory. */
    private static function valid(string $name): bool
    {
        return preg_match('/^[a-z0-9-]+$/', $name) === 1;
    }

    /** rules/ in the repository; the build never calls it (the data is embedded). */
    private static function dir(): string
    {
        return __DIR__ . '/rules';         // never reached: the data is embedded
    }
}
}
}

// src/Rules/Starter.php
namespace CjwNetwork\RequestShield\Rules {
if (true) {
/**
 * `request-shield init --app=<app> [--docroot=<dir>] [--out=<file>] [--force]`
 * (0031 E.6): a commented starter rule file for an application
 * (rules/starter/<app>.rules, embedded in the single file), in monitor mode,
 * with an example for each rule. Written to --out, or printed. Refused: a
 * file that exists (unless --force), and a file inside the document root --
 * the rules, the log and the store never belong where a browser can read
 * them. The written file is compiled once, so it is known to work.
 * Exit 0: written or printed; 2: refused.
 */
final class Starter
{
    /**
     * @param resource $out
     * @param resource $err
     */
    public static function run(?string $app, ?string $docroot, ?string $file, bool $force, $out, $err): int
    {
        $apps = Shipped::starters();
        $text = $app === null ? null : Shipped::starter($app);
        if ($text === null) {
            fwrite($err, 'request-shield: init --app=' . implode('|', $apps) . " [--docroot=<dir>] [--out=<file>] [--force]\n"
                . ($app === null ? '' : "       no starter for \"$app\"\n"));
            return 2;
        }
        if ($file === null) {
            fwrite($out, $text);
            return 0;
        }
        $dir = realpath(dirname($file));
        if ($dir === false) {
            fwrite($err, 'request-shield: ' . dirname($file) . " does not exist -- create it first (outside the document root)\n");
            return 2;
        }
        if ($docroot !== null) {
            $root = realpath($docroot);
            if ($root === false) {
                fwrite($err, "request-shield: the document root $docroot does not exist\n");
                return 2;
            }
            if ($dir === $root || strncmp($dir . '/', $root . '/', strlen($root) + 1) === 0) {
                fwrite($err, "request-shield: $file is inside the document root $root -- a browser could read the rules, the log and the store; choose a directory beside it\n");
                return 2;
            }
        }
        $target = $dir . '/' . basename($file);
        if (substr($target, -6) !== '.rules') {
            fwrite($err, "request-shield: $file is not a rule file (.rules)\n");
            return 2;
        }
        if (is_file($target) && !$force) {
            fwrite($err, "request-shield: $target exists -- --force writes over it\n");
            return 2;
        }
        // Compiled beside the target first, moved in only when it works: a file that
        // exists (--force) stays as it was when the starter does not compile here.
        $tmp = $dir . '/.' . basename($target, '.rules') . '.' . bin2hex(random_bytes(4)) . '.rules';
        if (@file_put_contents($tmp, $text) === false) {
            fwrite($err, "request-shield: cannot write into $dir\n");
            return 2;
        }
        try {
            RuleFile::read([$tmp]);
        } catch (RuleFileException $e) {
            @unlink($tmp);
            fwrite($err, "request-shield: the starter does not compile here: " . $e->getMessage() . "\n");
            return 2;
        }
        if (!@rename($tmp, $target)) {
            @unlink($tmp);
            fwrite($err, "request-shield: cannot write $target\n");
            return 2;
        }
        fwrite($out, "written: $target ($app, monitor mode)\n"
            . "next: add the site's rules, then  request-shield check $target  and  request-shield test $target\n"
            . ($docroot === null ? "note: without --docroot nothing checked that the file lies outside the document root\n" : ''));
        return 0;
    }
}
}
}

// src/Rules/Vocabulary.php
namespace CjwNetwork\RequestShield\Rules {
use CjwNetwork\RequestShield\Extension;

if (true) {
/**
 * The words and set keys the extensions add to the rule file (ADR 0008).
 *
 * Static side: the registry. An extension is offered once per process --
 * the shipped ones named by the bootstrap (REQUEST_SHIELD_EXTENSIONS, loaded
 * and offered on the first lookup, so a passing request pays nothing for
 * them), a third-party one by its `plugin` line -- and the parser asks here
 * before it calls a word or a setting unknown.
 * Everything an extension registers writes into ext.<id> only; the core's
 * words and keys cannot be taken.
 *
 * Instance side: what Extension::vocabulary() gets to register with.
 */
final class Vocabulary
{
    private string $id;
    /**
     * The feature each of the core's words and set keys belongs to (0031 F.2):
     * the id of its page in docs/features (RSF<gg>-<nn>). The feature
     * contract (tests/FeatureContractTest.php) holds every word and key to
     * one, and the generated reference names it. An extension's words belong
     * to its feature (StatsExtension: RSF06-03). Data only: never read on a
     * request.
     *
     * @var array<string, string>
     */
    public const FEATURES = [
        // the words
        'host' => 'RSF02-01', 'trust' => 'RSF01-01', 'exempt' => 'RSF01-02', 'method' => 'RSF02-01', 'allow' => 'RSF02-03', 'restrict' => 'RSF02-03',
        'block' => 'RSF02-02', 'unblock' => 'RSF02-02', 'query' => 'RSF02-05', 'cache-path' => 'RSF04-01', 'cache-query' => 'RSF04-01', 'cache-ignore' => 'RSF04-01',
        'challenge' => 'RSF03-02', 'challenge-exempt' => 'RSF03-02', 'dashboard-access' => 'RSF06-01', 'api-path' => 'RSF03-02', 'post-origin' => 'RSF02-04',
        'backend' => 'RSF06-03', 'limit' => 'RSF03-01', 'no-limit' => 'RSF03-01', 'crawler' => 'RSF01-04', 'crawlers' => 'RSF01-04', 'plugin' => 'RSF06-04',
        'site' => 'RSF05-01', 'deny' => 'RSF01-02', 'ban' => 'RSF01-02', 'feed' => 'RSF01-03', 'set' => 'RSF05-02', 'include' => 'RSF05-01', 'match' => 'RSF05-01',
        'monitor' => 'RSF05-03', 'expect' => 'RSF05-04', 'ids' => 'RSF05-05', 'version' => 'RSF05-01', 'replace' => 'RSF05-01',
        // the set keys
        'store' => 'RSF03-01', 'store-dir' => 'RSF03-01', 'ipv6-prefix' => 'RSF03-01', 'debug-header' => 'RSF05-05', 'app-challenge' => 'RSF03-04',
        'strip-untrusted-forwarded' => 'RSF01-01', 'max-uri' => 'RSF02-01', 'max-query-parameters' => 'RSF02-01', 'max-header-bytes' => 'RSF02-01',
        'secret' => 'RSF03-02', 'pass-ttl' => 'RSF03-02', 'solution-ttl' => 'RSF03-02', 'difficulty-min' => 'RSF03-02', 'difficulty-max' => 'RSF03-02',
        'cookie' => 'RSF03-02', 'solution-cookie' => 'RSF03-02', 'bind-user-agent' => 'RSF03-02', 'search-engines' => 'RSF01-04', 'dns-lookups' => 'RSF01-04',
        'recheck' => 'RSF05-01', 'site-from' => 'RSF05-01', 'lists-dir' => 'RSF01-02', 'ban-growth' => 'RSF01-02', 'ban-max' => 'RSF01-02',
        'language' => 'RSF03-02', 'home' => 'RSF03-02', 'widget-path' => 'RSF03-03', 'widget-difficulty' => 'RSF03-03', 'challenge-logo' => 'RSF03-02',
        'mode' => 'RSF05-03', 'crawler-verify' => 'RSF01-04', 'log' => 'RSF05-05', 'dashboard-path' => 'RSF06-01', 'docs-url' => 'RSF06-01', 'error-page' => 'RSF05-06', 'dashboard-session' => 'RSF06-01',
        'log-level' => 'RSF05-05', 'live' => 'RSF06-02', 'live-keep' => 'RSF06-02', 'ban-keep' => 'RSF01-02', 'feeds-max-age' => 'RSF01-03',
        'log-ip' => 'RSF05-05', 'log-max-size' => 'RSF05-05', 'file-mode' => 'RSF05-02', 'dir-mode' => 'RSF05-02', 'cache-unknown-query' => 'RSF04-01',
    ];

    /**
     * Each feature's page and what it does in one sentence (0031 F.9): id =>
     * [the page's file name after the id, a short title, the sentence in
     * English, in German]. Help renders the pages' "?" links and sentences
     * from it; the feature contract holds it to docs/features. Data only:
     * never read on a request.
     *
     * @var array<string, array{0: string, 1: string, 2: string, 3: string}>
     */
    public const TOPICS = [
        'RSF01-01' => ['trusted-proxies', 'Trusted proxies',
            'Forwarded addresses are believed only from your own proxies, so nobody can claim another visitor\'s address.',
            'Weitergeleitete Adressen gelten nur von den eigenen Proxys, damit sich niemand als ein anderer Besucher ausgeben kann.'],
        'RSF01-02' => ['ip-lists', 'IP lists and bans',
            'Addresses kept out or let in by hand, and temporary bans for whoever keeps knocking at closed doors.',
            'Adressen, die von Hand ausgesperrt oder hereingelassen werden, und befristete Sperren für alle, die immer wieder an verschlossene Türen klopfen.'],
        'RSF01-03' => ['blocklist-feeds', 'Public blocklists',
