    /** @var array<string, string> the feature an extension's words and keys belong to, by the extension's id */
    public const EXTENSION_FEATURES = ['stats' => 'RSF06-03', 'api' => 'RSF06-05', 'cache' => 'RSF04-03', 'waf' => 'RSF06-01'];

    /** The feature a word or set key belongs to: the core's (FEATURES), else its extension's; null when none is known. */
    public static function featureOf(string $word): ?string
    {
        if (isset(self::FEATURES[$word])) {
            return self::FEATURES[$word];
        }
        $ext = self::wordFor($word)['id'] ?? self::settingFor($word)['id'] ?? null;
        return is_string($ext) ? self::EXTENSION_FEATURES[$ext] ?? null : null;
    }

    /** The types a set key may have; the parser checks the value like the core's own (path: relative to the rule file). */
    public const TYPES = ['bool', 'int', 'seconds', 'string', 'words', 'path'];

    /** @var array<string, class-string<Extension>> id => class */
    private static array $offered = [];

    /** The shipped extensions (REQUEST_SHIELD_EXTENSIONS) are offered: on the first lookup, or forgotten with the rest. */
    private static bool $shipped = false;

    /** @var array<string, array{id: string, parse: callable, help: string, paths: bool, serverWide: bool}>|null keyword => its owner; null: indexed on the next lookup */
    private static ?array $words = null;

    /** @var array<string, array{id: string, name: string, type: string, check: ?callable, help: string, serverWide: bool, many: bool}>|null set key => its owner */
    private static ?array $settings = null;

    /** @var array<string, array{id: string, parse: callable, help: string, paths: bool, serverWide: bool}> */
    private array $myWords = [];

    /** @var array<string, array{id: string, name: string, type: string, check: ?callable, help: string, serverWide: bool, many: bool}> */
    private array $mySettings = [];

    private function __construct(string $id)
    {
        $this->id = $id;
    }

    // ── The registry ──────────────────────────────────────────────────────

    /**
     * Makes an extension's words known. Offering the same class twice is
     * nothing; a second class with the same id is a mistake that names both.
     *
     * @param class-string $class
     */
    public static function offer(string $class): void
    {
        self::shipped();
        if (!is_subclass_of($class, Extension::class)) {
            throw new \InvalidArgumentException("request-shield: $class is not an extension (it does not implement " . Extension::class . ')');
        }
        $id = $class::id();
        if (!preg_match('/^[a-z][a-z0-9-]{0,31}$/', $id)) {
            throw new \InvalidArgumentException("request-shield: $class: an extension id is letters, digits and \"-\" (stats, rs-test), not \"$id\"");
        }
        if (isset(self::$offered[$id])) {
            if (self::$offered[$id] !== $class) {
                throw new \InvalidArgumentException("request-shield: two extensions with the id $id: " . self::$offered[$id] . " and $class");
            }
            return;
        }
        self::$offered[$id] = $class;
        self::$words = null;
        self::$settings = null;
    }

    /** Forgets every extension, the shipped ones too (tests re-offer what they need). */
    public static function forget(): void
    {
        self::$offered = [];
        self::$shipped = true;
        self::$words = null;
        self::$settings = null;
    }

    /** Back to the shipped extensions, offered again on the next lookup (tests, after forget()). */
    public static function reset(): void
    {
        self::forget();
        self::$shipped = false;
    }

    /** @return class-string<Extension>|null */
    public static function extension(string $id): ?string
    {
        self::shipped();
        return self::$offered[$id] ?? null;
    }

    /** @return array<string, class-string<Extension>> id => class */
    public static function extensions(): array
    {
        self::shipped();
        return self::$offered;
    }

    /**
     * The shipped extensions, offered on the first lookup: the bootstrap only
     * names them (REQUEST_SHIELD_EXTENSIONS, a list of class names) so that a
     * passing request, which never consults the registry, loads none of this.
     * A name whose class is not there (a build without plugins/stats) is skipped.
     */
    private static function shipped(): void
    {
        if (self::$shipped) {
            return;
        }
        self::$shipped = true;
        $named = defined('REQUEST_SHIELD_EXTENSIONS') ? (array) constant('REQUEST_SHIELD_EXTENSIONS') : [];
        foreach ($named as $class) {
            $class = (string) $class;
            if (class_exists($class)) {
                self::offer($class);
            }
        }
    }

    /**
     * Who owns a rule keyword the core does not have.
     *
     * @return array{id: string, parse: callable, help: string, paths: bool, serverWide: bool}|null
     */
    public static function wordFor(string $keyword): ?array
    {
        self::index();
        return self::$words[$keyword] ?? null;
    }

    /**
     * Who owns a set key the core does not have.
     *
     * @return array{id: string, name: string, type: string, check: ?callable, help: string, serverWide: bool, many: bool}|null
     */
    public static function settingFor(string $key): ?array
    {
        self::index();
        return self::$settings[$key] ?? null;
    }

    /**
     * Every word and set key the extensions add (for suggestions and the reference).
     *
     * @return array{words: list<string>, settings: list<string>}
     */
    public static function known(): array
    {
        self::index();
        return ['words' => array_keys(self::$words ?? []), 'settings' => array_keys(self::$settings ?? [])];
    }

    private static function index(): void
    {
        self::shipped();
        if (self::$words !== null) {
            return;
        }
        $words = [];
        $settings = [];
        foreach (self::$offered as $id => $class) {
            $v = new self($id);
            $class::vocabulary($v);
            foreach ($v->myWords as $keyword => $def) {
                if (isset($words[$keyword])) {
                    throw new \InvalidArgumentException("request-shield: the word $keyword is claimed by two extensions, {$words[$keyword]['id']} and $id");
                }
                $words[$keyword] = $def;
            }
            foreach ($v->mySettings as $key => $def) {
                if (isset($settings[$key])) {
                    throw new \InvalidArgumentException("request-shield: the setting $key is claimed by two extensions, {$settings[$key]['id']} and $id");
                }
                $settings[$key] = $def;
            }
        }
        self::$words = $words;
        self::$settings = $settings;
    }

    // ── What an extension registers ───────────────────────────────────────

    /**
     * A rule of its own: `<keyword> <args…>`. The parser calls $parse with the
     * line's words (environment variables resolved), the extension's values
     * so far (ext.<id>), the line's place ("site.rules:12") and the rule's id;
     * it returns the new values. A wrong line is a RuleFileException that
     * starts with the place.
     *
     * $paths: the word takes paths, like the core's challenge-exempt: the
     * parser compiles them (globs, `regex <expression>`, `none` first) to
     * patterns before $parse sees them, and inside a match block the word
     * takes no paths and gets the block's. Without it a word does not go
     * inside a match block.
     *
     * @param callable(list<string>, array<string, mixed>, string, string): array<string, mixed> $parse
     */
    public function word(string $keyword, callable $parse, string $help = '', bool $paths = false, bool $serverWide = false): void
    {
        if (!preg_match('/^[a-z][a-z0-9-]{1,31}$/', $keyword)) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: a word is letters, digits and \"-\", not \"$keyword\"");
        }
        if (in_array($keyword, RuleFile::coreWords(), true)) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: \"$keyword\" is a word of the core");
        }
        if (isset($this->myWords[$keyword])) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: the word $keyword is registered twice");
        }
        $this->myWords[$keyword] = ['id' => $this->id, 'parse' => $parse, 'help' => $help, 'paths' => $paths, 'serverWide' => $serverWide];
    }

    /**
     * A `set <key> <value>` of its own, typed like the core's: bool (on/off),
     * int, seconds (30s, 5m, 2h), string, words (split at spaces), path
     * (relative to the rule file). The value lands in ext.<id>.<name>; $name
     * defaults to the key in camelCase without the extension's own prefix
     * (stats-depth => depth, fail-at => failAt); a dotted name goes below
     * (crawlerLog.dir). $check sees the typed value and the line's place,
     * returns the value to keep or throws a RuleFileException.
     *
     * $serverWide: about the server, not a website -- refused inside a site
     * block, as the core's store or secret. $many: $check returns several
     * values at once, name => value, each put below ext.<id> (set stats
     * on|off|<parts> writes enabled and parts).
     *
     * @param callable(mixed, string): mixed|null $check
     */
    public function set(string $key, string $type, string $help = '', ?callable $check = null, ?string $name = null, bool $serverWide = false, bool $many = false): void
    {
        if (!preg_match('/^[a-z][a-z0-9-]{1,31}$/', $key)) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: a set key is letters, digits and \"-\", not \"$key\"");
        }
        if (in_array($key, RuleFile::coreSettings(), true) || strncmp($key, 'text.', 5) === 0) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: \"set $key\" is a setting of the core");
        }
        if (!in_array($type, self::TYPES, true)) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: set $key: the type is one of " . implode(', ', self::TYPES) . ", not \"$type\"");
        }
        if (isset($this->mySettings[$key])) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: the setting $key is registered twice");
        }
        if ($many && $check === null) {
            throw new \InvalidArgumentException("request-shield: extension {$this->id}: set $key: many needs a check that returns the values");
        }
        $name ??= self::camel(strncmp($key, $this->id . '-', strlen($this->id) + 1) === 0 ? (string) substr($key, strlen($this->id) + 1) : $key);
        $this->mySettings[$key] = ['id' => $this->id, 'name' => $name, 'type' => $type, 'check' => $check, 'help' => $help, 'serverWide' => $serverWide, 'many' => $many];
    }

    /** fail-at => failAt */
    private static function camel(string $key): string
    {
        return lcfirst(str_replace('-', '', ucwords($key, '-')));
    }
}
}
}

// src/Seen.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * What the shield knows about a request beyond its parts, for plugins: the
 * website, the known crawler it names and whether its address proves it, the
 * family of a bot that says it is one. Each is worked out on first use and
 * kept: a plugin that does not ask pays nothing.
 */
final class Seen
{
    private Request $request;
    private Shield $shield;
    private ?string $host = null;

    private ?string $crawler = null;

    private bool $crawlerKnown = false;

    private ?bool $verified = null;

    private ?string $family = null;

    private bool $familyKnown = false;

    public function __construct(Request $request, Shield $shield)
    {
        $this->request = $request;
        $this->shield = $shield;
    }

    /** The website: the host the request names, lower case, without its port and a trailing dot. */
    public function host(): string
    {
        return $this->host ??= rtrim(strtolower((string) preg_replace('/:\d+$/', '', $this->request->host)), '.');
    }

    /** The known crawler the User-Agent names (CRAWL-…), or null; proven or not. */
    public function crawler(): ?string
    {
        if (!$this->crawlerKnown) {
            $this->crawlerKnown = true;
            $this->crawler = $this->shield->settings->crawlers === [] ? null : $this->shield->crawlers()->claims((string) $this->request->header('user-agent'));
        }
        return $this->crawler;
    }

    /** The kind of the named crawler (search, ai-search, ai-user, ai-training), or null. */
    public function crawlerKind(): ?string
    {
        $id = $this->crawler();
        return $id === null ? null : $this->shield->crawlers()->kind($id);
    }

    /** Whether the named crawler's address proves it (false: none named, or only borrowed). */
    public function verified(): bool
    {
        $id = $this->crawler();
        return $this->verified ??= $id !== null && $this->shield->crawlers()->verified($this->request->clientIp, $id);
    }

    /** The family of a bot that says it is one (curl, python, headless …), or null: a browser, or a known crawler. */
    public function botFamily(): ?string
    {
        if (!$this->familyKnown) {
            $this->familyKnown = true;
            $this->family = $this->crawler() === null ? self::family((string) $this->request->header('user-agent')) : null;
        }
        return $this->family;
    }

    /** Who came: crawlers (verified), bots (one that says so, or only borrows a crawler's name), or people. */
    public function who(): string
    {
        if ($this->crawler() !== null) {
            return $this->verified() ? 'crawlers' : 'bots';
        }
        return $this->botFamily() !== null ? 'bots' : 'people';
    }

    /**
     * A client that says it is a tool, not a browser, by family (python, curl,
     * wget, go, java, node, php, perl, headless, scrapy, other), "empty" for
     * no User-Agent -- or null.
     */
    public static function family(string $userAgent): ?string
    {
        if ($userAgent === '') {
            return 'empty';
        }
        // One expression for all families; the first alternative that matches names it.
        $m = [];
        if (preg_match('/(?:HeadlessChrome|PhantomJS|Puppeteer|Playwright|Selenium)(*MARK:headless)|(?:python-requests|python-urllib|aiohttp|httpx|Python\/)(*MARK:python)'
            . '|(?:^curl\/)(*MARK:curl)|(?:^Wget\/)(*MARK:wget)|(?:Go-http-client)(*MARK:go)|(?:^Java\/|okhttp|Apache-HttpClient)(*MARK:java)'
            . '|(?:node-fetch|axios|undici|^got |Node\.js)(*MARK:node)|(?:GuzzleHttp|^PHP\/|Symfony HttpClient)(*MARK:php)|(?:libwww-perl|^LWP)(*MARK:perl)'
            . '|(?:Scrapy)(*MARK:scrapy)|(?:bot\b|crawler|spider|scraper|fetcher)(*MARK:other)/i', $userAgent, $m) !== 1) {
            return null;
        }
        return isset($m['MARK']) ? (string) $m['MARK'] : 'other';
    }
}
}
}

// src/Settings.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * The configuration array, checked once and turned into typed values. A
 * value of the wrong type is an error at once -- with the key named -- not
 * a check that quietly does something else on a live site.
 */
final class Settings
{
    /**
     * @var list<string>
     */
    public array $trustedProxies;
    public bool $stripUntrustedForwarded;
    /**
     * @var list<string>
     */
    public array $methods;
    /**
     * @var list<string>
     */
    public array $hosts;
    public int $maxUri;
    public int $maxQueryParameters;
    public int $maxHeaderBytes;
    /**
     * @var list<string>
     */
    public array $blockedPaths;
    /**
     * @var list<string>|null
     */
    public ?array $cacheablePaths;
    /**
     * @var list<string>|null
     */
    public ?array $cacheableQuery;
    /**
     * @var array<string, Budget>
     */
    public array $budgets;
    /**
     * @var list<string>
     */
    public array $exemptIps;
    public int $ipv6Prefix;
    public string $store;
    public string $storeDir;
    public bool $debugHeader;
    public ChallengeSettings $challenge;
    /**
     * @var array<string, array<string, string>>
     */
    public array $origins = [];
    /**
     * @var list<array{paths: list<string>, ips: list<string>}>
     */
    public array $restricted = [];
    /**
     * @var array<string, list<string>>
     */
    public array $methodPaths = [];
    public ?string $logFile = null;
    public string $logLevel = 'stop';
    public string $logIp = 'masked';
    public int $logMaxSize = 10485760;
    /**
     * @var list<array{paths: list<string>, patterns: list<string>|null, ips: list<string>}>
     */
    public array $blockExceptions = [];
    public bool $appChallenge = false;
    /**
     * @var list<array{target: string, patterns: list<string>}>
     */
    public array $contentRules = [];
    /**
     * @var array<string, string>
     */
    public array $contentIndex = [];
    public string $blockedIndex = '';
    /**
     * @var array<string, list<string>>
     */
    public array $contentHints = [];
    public array $queryParams = [];
    public bool $queryStrict = false;
    public array $queryDrop = [];
    public array $queryIndex = ['exact' => [], 'globs' => [], 'local' => []];
    public string $mode = 'enforce';
    public int $uncachedWeight = 1;
    public ?Settings $monitor = null;
    public array $crawlers = [];
    public string $crawlerIndex = '';
    public array $crawlerIds = [];
    public string $crawlerVerify = 'both';
    public array $crawlerPolicy = [];
    public string $dashboardPath = '/rs';
    public array $plugins = [];
    public array $pluginFiles = [];
    public array $sites = [];
    public ?string $site = null;
    public string $siteFrom = 'server-name';
    public array $deny = [];
    public array $denyTable = [];
    public int $denyCount = 0;
    public int $listsUntil = 0;
    public ?string $listsDir = null;
    public array $bans = [];
    public int $banGrowth = 2;
    public int $banMax = 86400;
    public bool $liveEnabled = false;
    public int $liveKeep = 3600;
    public string $banKeep = 'memory';
    public array $feeds = [];
    public array $feedTables = [];
    public array $feedsAt = [];
    public array $feedWeights = [];
    public int $feedsMaxAge = 259200;
    public array $dashboardAccess = [];
    public int $dashboardSession = 28800;
    public ?array $postOrigin = null;
    public array $backend = [];
    public array $ext = [];
    public array $hooks = [];
    public array $routes = [];
    public array $routeBases = [];
    public string $docsUrl = Help::DOCS;
    public array $errorPages = [];
    public ?array $learn = null;
    public int $fileMode = 0600;
    public int $dirMode = 0700;
    public array $cacheableIgnore = [];
    public string $cacheableUnknown = 'uncached';
    /**
     * @param list<string> $trustedProxies
     * @param list<string> $methods
     * @param list<string> $hosts
     * @param list<string> $blockedPaths
     * @param list<string>|null $cacheablePaths
     * @param list<string>|null $cacheableQuery
     * @param array<string, Budget> $budgets
     * @param list<string> $exemptIps
     * @param array<string, array<string, string>> $origins setting => pattern or budget => where it was set (rule files)
     * @param list<array{paths: list<string>, ips: list<string>}> $restricted
     * @param array<string, list<string>> $methodPaths
     * @param list<array{paths: list<string>, patterns: list<string>|null, ips: list<string>}> $blockExceptions
     * @param list<array{target: string, patterns: list<string>}> $contentRules
     * @param array<string, string> $contentIndex
     * @param array<string, list<string>> $contentHints
     */
    private function __construct(
        array $trustedProxies,
        bool $stripUntrustedForwarded,
        array $methods,
        array $hosts,
        int $maxUri,
        int $maxQueryParameters,
        int $maxHeaderBytes,
        array $blockedPaths,
        ?array $cacheablePaths,
        ?array $cacheableQuery,
        array $budgets,
        array $exemptIps,
        int $ipv6Prefix,
        string $store,
        string $storeDir,
        bool $debugHeader,
        ChallengeSettings $challenge,
        array $origins = [],
        array $restricted = [],
        array $methodPaths = [],
        ?string $logFile = null,
        string $logLevel = 'stop',
        string $logIp = 'masked',
        int $logMaxSize = 10485760,
        array $blockExceptions = [],
        bool $appChallenge = false,
        array $contentRules = [],
        array $contentIndex = [],
        string $blockedIndex = '',
        array $contentHints = [],
        array $queryParams = [],
        bool $queryStrict = false,
        array $queryDrop = [],
        array $queryIndex = ['exact' => [], 'globs' => [], 'local' => []],
        string $mode = 'enforce',
        int $uncachedWeight = 1,
        ?Settings $monitor = null,
        array $crawlers = [],
        string $crawlerIndex = '',
        array $crawlerIds = [],
        string $crawlerVerify = 'both',
        array $crawlerPolicy = [],
        string $dashboardPath = '/rs',
        array $plugins = [],
        array $pluginFiles = [],
        array $sites = [],
        ?string $site = null,
        string $siteFrom = 'server-name',
        array $deny = [],
        array $denyTable = [],
        int $denyCount = 0,
        int $listsUntil = 0,
        ?string $listsDir = null,
        array $bans = [],
        int $banGrowth = 2,
        int $banMax = 86400,
        bool $liveEnabled = false,
        int $liveKeep = 3600,
        string $banKeep = 'memory',
        array $feeds = [],
        array $feedTables = [],
        array $feedsAt = [],
        array $feedWeights = [],
        int $feedsMaxAge = 259200,
        array $dashboardAccess = [],
        int $dashboardSession = 28800,
        ?array $postOrigin = null,
        array $backend = [],
        array $ext = [],
        array $hooks = [],
        array $routes = [],
        array $routeBases = [],
        string $docsUrl = Help::DOCS,
        array $errorPages = [],
        ?array $learn = null,
        int $fileMode = 0600,
        int $dirMode = 0700,
        array $cacheableIgnore = [],
        string $cacheableUnknown = 'uncached'
    ) {
        /** @readonly */
        $this->trustedProxies = $trustedProxies;
        /** @readonly */
        $this->stripUntrustedForwarded = $stripUntrustedForwarded;
        /** @readonly */
        $this->methods = $methods;
        /** @readonly */
        $this->hosts = $hosts;
        /** @readonly */
        $this->maxUri = $maxUri;
        /** @readonly */
        $this->maxQueryParameters = $maxQueryParameters;
        /** @readonly */
        $this->maxHeaderBytes = $maxHeaderBytes;
        /** @readonly */
        $this->blockedPaths = $blockedPaths;
        /** @readonly */
        $this->cacheablePaths = $cacheablePaths;
        /** @readonly */
        $this->cacheableQuery = $cacheableQuery;
        /** @readonly */
        $this->budgets = $budgets;
        /** @readonly */
        $this->exemptIps = $exemptIps;
        /** @readonly */
        $this->ipv6Prefix = $ipv6Prefix;
        /** @readonly */
        $this->store = $store;
        /** @readonly */
        $this->storeDir = $storeDir;
        /** @readonly */
        $this->debugHeader = $debugHeader;
        /** @readonly */
        $this->challenge = $challenge;
        /** @readonly */
        $this->origins = $origins;
        /** @readonly */
        $this->restricted = $restricted;
        /** @readonly */
        $this->methodPaths = $methodPaths;
        /** @readonly */
        $this->logFile = $logFile;
        /** @readonly */
        $this->logLevel = $logLevel;
        /** @readonly */
        $this->logIp = $logIp;
        /** @readonly */
        $this->logMaxSize = $logMaxSize;
        /** @readonly */
        $this->blockExceptions = $blockExceptions;
        /** @readonly */
        $this->appChallenge = $appChallenge;
        /** @readonly */
        $this->contentRules = $contentRules;
        /** @readonly target => all of its patterns in one expression */
        $this->contentIndex = $contentIndex;
        /** @readonly all blocked paths in one expression; '' when they cannot be combined */
        $this->blockedIndex = $blockedIndex;
        /**
         * @readonly target => texts one of which every pattern needs; a target without is always matched
         * @var array<string, list<string>>
         */
        $this->contentHints = $contentHints;
        /**
         * @readonly the known query parameters (QueryRule)
         * @var list<array{paths: list<string>|null, exact: array<string, string>, globs: array<string, string>}>
         */
        $this->queryParams = $queryParams;
        /** @readonly anything but a known parameter of its type: 404 */
        $this->queryStrict = $queryStrict;
        /**
         * @readonly where an unknown parameter, or one not of its type, is dropped instead (query drop):
         *   path patterns; the request goes on without it (QueryRule, Shield::queryForCaches())
         * @var list<string>
         */
        $this->queryDrop = $queryDrop;
        /**
         * @readonly queryParams as one lookup (QueryRule::index()), built once
         * @var array{exact: array<string, string>, globs: array<string, string>, local: list<array{paths: list<string>, exact: array<string, string>, globs: array<string, string>}>}
         */
        $this->queryIndex = $queryIndex;
        /** @readonly off, monitor, enforce or strict */
        $this->mode = $mode;
        /** @readonly how often a request a cache must not keep counts against the budgets (strict: 2) */
        $this->uncachedWeight = $uncachedWeight;
        /** @readonly the rules with those marked "monitor": decided alongside, only logged; null: none */
        $this->monitor = $monitor;
        /**
         * @readonly the known crawlers, each with what the site does with it (policy)
         * @var array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>
         */
        $this->crawlers = $crawlers;
        /** @readonly every crawler's User-Agent pattern in one expression, (*MARK:<n>) naming it; '' for none */
        $this->crawlerIndex = $crawlerIndex;
        /** @var list<string> @readonly crawler IDs in the order of the MARKs */
        $this->crawlerIds = $crawlerIds;
        /** @readonly both, ranges or dns */
        $this->crawlerVerify = $crawlerVerify;
        /** @var array<string, string> @readonly the policies as written: kind or crawler ID => allow, check, block */
        $this->crawlerPolicy = $crawlerPolicy;
        /** @readonly where the statistics pages live: <path>/dashboard, /stats, /shield */
        $this->dashboardPath = $dashboardPath;
        /** @var list<class-string> @readonly the plugins the rules name, and those the extensions add at compile time (Extension::plugins(): the statistics with "set stats on") */
        $this->plugins = $plugins;
        /** @var array<class-string, string> @readonly plugin class => the file that holds it (plugin … from <file>), loaded only when the shield makes its plugins (0031 D.2) */
        $this->pluginFiles = $pluginFiles;
        /** @var array<string, string> @readonly website name (a.de, *.b.de, default) => its site block (the block's first name); [] without site blocks */
        $this->sites = $sites;
        /** @readonly the site block these settings are (null: the base, for every website) */
        $this->site = $site;
        /** @readonly which name picks the site: server-name (the web server's, the default) or host (the Host header) */
        $this->siteFrom = $siteFrom;
        /** @var list<array{ips: list<string>, until: ?int, rule: string}> @readonly addresses kept out (deny), the ones in force -- the first DENY_SHOWN, for the pages */
        $this->deny = $deny;
        /** @var array{4: string, 6: string, ids: string, dir?: string}|array{} @readonly all of them, as a sorted table (IpTable); [] none */
        $this->denyTable = $denyTable;
        /** @readonly how many entries are in force */
        $this->denyCount = $denyCount;
        /** @readonly when the next list entry ends (a Unix time; 0: none) -- the settings are built again then */
        $this->listsUntil = $listsUntil;
        /** @readonly where the list files are (allow.rules, deny.rules); null: none */
        $this->listsDir = $listsDir;
        /** @var list<array{after: int, signal: string, in: int, for: int, rule: string}> @readonly automatic, temporary bans */
        $this->bans = $bans;
        /** @readonly a ban within a day of the last lasts this many times longer */
        $this->banGrowth = $banGrowth;
        /** @readonly the longest ban, in seconds */
        $this->banMax = $banMax;
        /** @readonly the live view's memory (APCu): the last requests stopped, with the full address */
        $this->liveEnabled = $liveEnabled;
        /** @readonly how long an entry stays in it, in seconds */
        $this->liveKeep = $liveKeep;
        /** @readonly where a ban is kept: memory (the store), or file (also a file in store-dir: it survives a restart of APCu) */
        $this->banKeep = $banKeep;
        /** @var list<array{name: string, title: string, action: string, weight: int, paths: list<string>, rule: string, terms: string, urls: list<string>, format: string, every: int, wideOk: bool, count: int, fetched: int, state: string, file: ?string}> @readonly the public blocklists named, as the pages show them */
        $this->feeds = $feeds;
        /** @var array<string, array{4: string, 6: string, ids: string, dir?: string}> @readonly per action (deny, check, signal): the feeds without "at", as one table */
        $this->feedTables = $feedTables;
        /** @var list<array{action: string, table: array{4: string, 6: string, ids: string, dir?: string}, paths: list<string>}> @readonly the feeds with "at <paths>", each its own table */
        $this->feedsAt = $feedsAt;
        /** @var array<string, int> @readonly ban-signal: rule => how many signals a request from its list counts as */
        $this->feedWeights = $feedWeights;
        /** @readonly a fetched list older than this is no longer used, in seconds */
        $this->feedsMaxAge = $feedsMaxAge;
        /** @var list<array{who: string, hash: string, until: ?int, rule: string}> @readonly dashboard-access: who may open the dashboard's pages -- '*' (everything) or an opaque principal (customer-a; what it may see is the pages' business) -- by a token's SHA-256, in force */
        $this->dashboardAccess = $dashboardAccess;
        /** @readonly how long a login to the dashboard lasts, in seconds (set dashboard-session; 8 hours) */
        $this->dashboardSession = $dashboardSession;
        /** @var array{missing: string, except: list<string>}|null @readonly post-origin same: forms only from the website's own pages; null: off */
        $this->postOrigin = $postOrigin;
        /** @var list<string> @readonly the editors' area (backend <paths>): its forms counted apart, per area; as patterns */
        $this->backend = $backend;
        /** @var array<string, array<string, mixed>> @readonly the extensions' checked settings by extension id (ext.<id>.*; Extension::compile() fills it, 0031 B.2) -- plugins read their own, the core never does */
        $this->ext = $ext;
        /** @var array<string, list<class-string>> @readonly which plugins provide which capability (hook name => classes), recorded at compile time by instanceof (Settings::HOOKS), so a request costs one array access to know; ruleCounts (0031 B.8), sink (B.9), pages (B.10), ruleProvider (C.3), handler (C.4) */
        $this->hooks = $hooks;
        /** @var array<string, array{key: string, ext: ?string, tab: ?array{0: string, 1: string}, role: string, order: int}> @readonly the dashboard's pages, full path => entry (Routes; the core's, the extensions', in the tabs' order), compiled by compiledExt() -- served by the shield from 0031 B.6 */
        $this->routes = $routes;
        /** @var list<string> @readonly the prefixes the routes lie below (Routes::bases()): dashboard-path, and the path of a page outside it (set stats-path /admin/statistics) -- the request path's pre-filter, one stripos each */
        $this->routeBases = $routeBases;
        /** @readonly where the pages' "?" links point (set docs-url, Help): the docs' folder; "" with the links off */
        $this->docsUrl = $docsUrl;
        /** @var array<int|string, array<string, string>> @readonly the site's own error pages (set error-page): status or 4xx => language ("" for all) => HTML, read when the rules were compiled (0030) */
        $this->errorPages = $errorPages;
        /** @var array{until: int, token: string, from: list<string>}|null @readonly a learning run (0016: request-shield learn … start), read from <store-dir>/learn.json when compiled; null: none */
        $this->learn = $learn;
        /** @readonly the mode of a new file the shield writes (set file-mode; Files) */
        $this->fileMode = $fileMode;
        /** @readonly the mode of a new folder the shield makes (set dir-mode; Files) */
        $this->dirMode = $dirMode;
        /** @var list<string> @readonly cache-ignore (0048): parameter names (globs, as PHP names them) no cache key holds -- taken out before a cache and the application run */
        $this->cacheableIgnore = $cacheableIgnore;
        /** @readonly set cache-unknown-query (0048): "uncached" (a parameter not in cache-query: never kept) or "hit-only" (answered from the key without it, never kept) */
        $this->cacheableUnknown = $cacheableUnknown;
        // The modes for everything written from here on: every request and every command makes its
        // settings first. Files is loaded only for modes not its defaults, or when it is loaded already.
        if ($fileMode !== 0600 || $dirMode !== 0700 || class_exists(Files::class, false)) {
            Files::modes($fileMode, $dirMode);
        }
    }

    /**
     * @param array<mixed> $config see Config::defaults()
     * @throws \InvalidArgumentException naming the key that is wrong
     */
    public static function from(array $config): self
    {
        $c = Config::merge($config);
        $verify = self::string($c, 'crawlerVerify', 'crawlerVerify', 'both');
        if (!in_array($verify, ['both', 'ranges', 'dns'], true)) {
            throw self::wrong('crawlerVerify', 'both, ranges or dns');
        }
        $mode = self::string($c, 'mode', 'mode', 'enforce');
        if (!in_array($mode, self::MODES, true)) {
            throw self::wrong('mode', implode(', ', self::MODES));
        }
        $monitorRules = $c['monitorRules'] ?? null;
        if ($monitorRules !== null && !is_array($monitorRules)) {
            throw self::wrong('monitorRules', 'null or the settings with the monitored rules');
        }
        if ($mode === 'monitor' && $monitorRules !== null) {
            // Everything is only logged anyway: the monitored rules count like the others.
            return self::from(['mode' => 'monitor', 'monitorRules' => null] + array_intersect_key($c, ['fileMode' => 1, 'dirMode' => 1]) + $monitorRules);
        }
        if ($monitorRules !== null && is_array($monitorRules['feeds'] ?? null)) {
            // The watched rules' settings: only the watched lists (feed … count, monitor feed …);
            // the others are enforced already, and a big list is read once.
            $monitorRules['feeds'] = array_values(array_filter($monitorRules['feeds'], static fn ($f): bool => is_array($f) && ($f['watched'] ?? false) === true));
        }
        $strict = $mode === 'strict';
        $limits = self::map($c, 'limits');
        $cacheable = self::map($c, 'cacheable');
        $exempt = self::map($c, 'exempt');
        $log = self::map($c, 'log');

        $restricted = [];
        foreach (self::map($c, 'restricted') as $i => $r) {
            if (!is_array($r)) {
                throw self::wrong("restricted.$i", "an array of 'paths' and 'ips'");
            }
            $restricted[] = ['paths' => self::strings($r, 'paths', "restricted.$i.paths"), 'ips' => self::strings($r, 'ips', "restricted.$i.ips")];
        }
        $exceptions = [];
        foreach (self::map($c, 'blockExceptions') as $i => $x) {
            if (!is_array($x)) {
                throw self::wrong("blockExceptions.$i", "an array of 'paths', 'patterns' and 'ips'");
            }
            $exceptions[] = ['paths' => self::strings($x, 'paths', "blockExceptions.$i.paths"),
                'patterns' => self::stringsOrNull($x, 'patterns', "blockExceptions.$i.patterns"), 'ips' => self::strings($x, 'ips', "blockExceptions.$i.ips")];
        }
        [$contentRules, $contentIndex] = self::contentRules(self::map($c, 'contentRules'));
        $blocked = self::strings($c, 'blockedPaths');
        $methodPaths = [];
        foreach (self::map($c, 'methodPaths') as $method => $paths) {
            $methodPaths[strtoupper((string) $method)] = self::strings(['p' => $paths], 'p', "methodPaths.$method");
        }
        $level = self::string($log, 'level', 'log.level', 'stop');
        if (!in_array($level, Log::LEVELS, true)) {
            throw self::wrong('log.level', implode(', ', Log::LEVELS));
        }
        $ip = self::string($log, 'ip', 'log.ip', 'masked');
        if ($ip !== 'masked' && $ip !== 'full') {
            throw self::wrong('log.ip', 'masked or full');
        }
        $logFile = $log['file'] ?? null;
        if ($logFile !== null && (!is_string($logFile) || $logFile === '')) {
            throw self::wrong('log.file', 'null or a path');
        }

        $budgets = [];
        foreach (self::map($c, 'budgets') as $name => $budget) {
            if (!is_array($budget)) {
                throw self::wrong("budgets.$name", 'an array');
            }
            $b = Budget::from((string) $name, $budget, $strict);
            if ($b !== null) {
                $budgets[(string) $name] = $b;
            }
        }

        return self::compiledExt(new self(
            self::strings($c, 'trustedProxies'),
            self::bool($c, 'stripUntrustedForwarded'),
            array_map(static fn (string $m): string => strtoupper($m), self::strings($c, 'methods')),
            array_map(static fn (string $h): string => strtolower($h), self::strings($c, 'hosts')),
            self::int($limits, 'uri', 'limits.uri'),
            self::int($limits, 'queryParameters', 'limits.queryParameters'),
            self::int($limits, 'headerBytes', 'limits.headerBytes'),
            $blocked,
            self::stringsOrNull($cacheable, 'paths', 'cacheable.paths'),
            self::stringsOrNull($cacheable, 'query', 'cacheable.query'),
            $budgets,
            array_values(array_unique(array_merge(self::strings($exempt, 'ips', 'exempt.ips'), self::exemptForNow($c)))),
            max(0, min(128, self::int($c, 'ipv6Prefix'))),
            self::string($c, 'store'),
            self::string($c, 'storeDir'),
            self::bool($c, 'debugHeader'),
            ChallengeSettings::from(self::map($c, 'challenge'), $strict),
            self::origins(self::map($c, 'origins')),
            $restricted,
            $methodPaths,
            $level === 'off' ? null : $logFile,
            $level,
            $ip,
            max(4096, self::int($log, 'maxSize', 'log.maxSize', 10485760)),
            $exceptions,
            self::bool($c, 'appChallenge'),
            $contentRules,
            $contentIndex,
            self::combine($blocked),
            self::hints($contentRules),
            $query = self::queryParams(self::map($c, 'queryParams')),
            self::bool($c, 'queryStrict'),
            self::patternList(self::listOf($c, 'queryDrop'), 'queryDrop'),
            \CjwNetwork\RequestShield\Rule\QueryRule::index($query),
            $mode,
            $strict ? 2 : 1,
            $monitorRules === null ? null : self::from(['mode' => $mode, 'monitorRules' => null] + $monitorRules),
            ...self::knownCrawlers($c, $verify),
            ...[self::dashboardPath($c), self::plugins($c), self::pluginFiles($c)],
            ...self::sites($c),
            ...self::withFeeds(self::lists($c, $budgets), $feeds = self::feeds($c), self::accessNext($c)),
            ...self::live($c),
            ...array_slice($feeds, 0, 5),
            ...self::dashboardAccess($c),
            ...[self::postOrigin($c), self::patternList($c['backend'] ?? [], 'backend')],
            ...[self::ext($c), self::hooks($c), self::routes($c), [], self::docsUrl($c), self::errorPages($c), self::learn($c)],
            ...self::modesOf($c),
            ...self::queryClasses($cacheable),
        ));
    }

    /**
     * The query parameters a cache leaves out of its key (0048): cache-ignore's
     * names, and what a parameter cache-query does not name is.
     *
     * @param array<mixed> $cacheable
     * @return array{0: list<string>, 1: string}
     */
    private static function queryClasses(array $cacheable): array
    {
        $ignore = self::strings($cacheable, 'ignore', 'cacheable.ignore');
        foreach ($ignore as $name) {
            if (preg_match('/^[A-Za-z0-9_*\[\]-]{1,128}$/', $name) !== 1) {
                throw self::wrong('cacheable.ignore', 'parameter names as PHP names them, * for any characters (utm_* gclid)');
            }
        }
        $unknown = $cacheable['unknown'] ?? 'uncached';
        if ($unknown !== 'uncached' && $unknown !== 'hit-only') {
            throw self::wrong('cacheable.unknown', 'uncached or hit-only');
        }
        return [$ignore, $unknown];
    }

    /**
     * The modes of new files and folders (set file-mode, set dir-mode): a
     * server's rules set exactly -- never writable for everyone, never one that
     * keeps PHP from writing (Files).
     *
     * @param array<mixed> $c
     * @return array{0: int, 1: int}
     */
    private static function modesOf(array $c): array
    {
        $out = [];
        foreach (['fileMode' => [0600, 'file-mode: the owner reads and writes, nobody else writes, no x bit (0600, 0640, 0660, 0644)'],
            'dirMode' => [0700, 'dir-mode: the owner rwx, nobody else writes (0700, 0750, 0770, 02770, 0755)']] as $key => [$default, $what]) {
            $v = $c[$key] ?? $default;
            $mode = is_int($v) ? $v : (is_string($v) ? Files::parseMode($v) : null);
            if ($mode === null || !($key === 'fileMode' ? Files::fileModeOk($mode) : Files::dirModeOk($mode))) {
                throw self::wrong($key, $what);
            }
            $out[] = $mode;
        }
        return [$out[0], $out[1]];
    }

    /**
     * The extensions check what the rules wrote into their slot, with the
     * whole base settings in hand (Extension::compile(), ADR 0008): an id no
     * offered extension owns keeps its values as they are -- nothing reads
     * them. A wrong value is an InvalidArgumentException like any other
     * setting's: on the request path the last good compiled settings stay.
     * The plugins an extension runs per request (Extension::plugins(), 0031
     * B.4) join the list the rules named, once each, so a request reads one
     * list and never the slots. The pages (Extension::routes(), 0031 B.5)
     * join the core's in one table, Routes::compile(): the settings array's
     * own routes, the core's below dashboard-path, every offered extension's
     * from its compiled slot.
     */
    private static function compiledExt(self $s): self
    {
        $checked = $s->ext;
        $plugins = $s->plugins;
        $routes = [];
        // Every offered extension compiles -- with an empty slot when the rules said nothing
        // of it: its defaults, its routes and its plugins apply all the same (0031 B.6).
        foreach (\CjwNetwork\RequestShield\Rules\Vocabulary::extensions() as $id => $class) {
            $checked[$id] = $class::compile($s->ext[$id] ?? [], $s);
            foreach ($class::plugins($checked[$id]) as $plugin) {
                if (!in_array($plugin, $plugins, true)) {
                    $plugins[] = $plugin;
                }
            }
            $routes[$id] = $class::routes($checked[$id]);
        }
        // The plugins' capabilities (0031 B.8): which class has which hook, recorded here
        // by instanceof, so a request -- or a page -- asks one array and never a plugin.
        $hooks = $s->hooks;
        foreach ($plugins as $class) {
            if (!class_exists($class) && isset($s->pluginFiles[$class]) && is_file($s->pluginFiles[$class])) {
                try {
                    require_once $s->pluginFiles[$class];   // plugin … from <file>: so its capabilities can be recorded
                } catch (\Throwable $e) {
                    Shield::failed('plugins', "$class could not be loaded from {$s->pluginFiles[$class]}, left out: " . $e->getMessage());
                    continue;
                }
            }
            if (!class_exists($class)) {
                continue;
            }
            foreach (self::HOOKS as $hook => $interface) {
                if (is_subclass_of($class, $interface) && !in_array($class, $hooks[$hook] ?? [], true)) {
                    $hooks[$hook][] = $class;
                }
            }
        }
        // The same settings with the slots, the plugins and the pages filled in:
        // the value objects (budgets, challenge, monitor) are immutable and shared,
        // so no export()/import() round trip. Positional, in declaration order
        // (as import()): unpacking string keys into named arguments needs PHP 8.1.
        /** @var array<string, mixed> $e */
        $e = get_object_vars($s);
        $e['ext'] = $checked;
        $e['plugins'] = $plugins;
        $e['routes'] = Routes::compile($s->routes, $s->dashboardPath, $routes);
        $e['routeBases'] = Routes::bases($e['routes'], $s->dashboardPath);
        $e['hooks'] = $hooks;
        /** @phpstan-ignore argument.type */
        return new self(...array_values($e));
    }

    /**
     * The known crawlers with the site's policies, their expression and IDs,
     * crawler-verify and the policies as written. The shipped list comes
     * ready (Shipped::crawlers()): settings from a PHP array only apply the
     * site's policies to it.
     *
     * @param array<mixed> $c
     * @return array{0: array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>, 1: string, 2: list<string>, 3: string, 4: array<string, string>}
     */
    private static function knownCrawlers(array $c, string $verify): array
    {
        $policies = self::crawlerPolicy($c);
        $engines = is_array($c['challenge'] ?? null) ? ($c['challenge']['searchEngines'] ?? true) : true;
        if ($engines === true && ($c['crawlers'] ?? null) === null) {
            $ready = Rules\Shipped::crawlers();
            $crawlers = $ready['crawlers'];
            foreach ($policies as $key => $policy) {
                if (!in_array($policy, Rules\RuleFile::POLICIES, true) || (!isset($crawlers[$key]) && !in_array($key, Rules\RuleFile::KINDS, true))) {
                    throw self::wrong("crawlerPolicy.$key", 'allow, check or block, for a kind (' . implode(', ', Rules\RuleFile::KINDS) . ') or a crawler\'s ID');
                }
            }
            if ($policies !== []) {
                foreach ($crawlers as $id => $x) {
                    $crawlers[$id]['policy'] = $policies[$id] ?? $policies[$x['kind']] ?? 'allow';
                }
            }
            return [$crawlers, $ready['index'], $ready['ids'], $verify, $policies];
        }
        $crawlers = self::crawlers($c);
        return array_merge([$crawlers], self::crawlerIndex($crawlers), [$verify, $policies]);
    }

    /**
     * The known crawlers: the shipped list, a site's own, the old
     * challenge.searchEngines map (pattern => DNS suffixes), or none.
     *
     * @param array<mixed> $c
     * @return array<string, array{kind: string, ua: string, dns: list<string>, ranges: list<string>, lists: array<string, array<string, ?string>>, policy: string, nets: array<string, list<array{0: string, 1: int}>>}>
     */
    private static function crawlers(array $c): array
    {
        $engines = is_array($c['challenge'] ?? null) ? ($c['challenge']['searchEngines'] ?? true) : true;
        if ($engines === false) {
            return [];
        }
        if (is_array($engines)) {
            $list = [];
            $i = 0;
            foreach ($engines as $pattern => $suffixes) {
                $list['searchEngines[' . $i++ . ']'] = ['kind' => 'search', 'ua' => (string) $pattern, 'dns' => $suffixes, 'ranges' => []];
            }
        } else {
            $list = $c['crawlers'] ?? [];
        }
        if (!is_array($list)) {
            throw self::wrong('crawlers', 'null or an array of ID => crawler');
        }
        $policies = self::map($c, 'crawlerPolicy');
        $out = [];
        foreach ($list as $id => $x) {
            $id = (string) $id;
            if (!is_array($x) || !in_array($x['kind'] ?? null, Rules\RuleFile::KINDS, true)
                || !is_string($x['ua'] ?? null) || @preg_match($x['ua'], '') === false) {
                throw self::wrong("crawlers.$id", "an array of 'kind' (" . implode(', ', Rules\RuleFile::KINDS) . "), 'ua' (a regex), 'dns' and 'ranges'");
            }
            $ranges = self::strings($x, 'ranges', "crawlers.$id.ranges");
            foreach ($ranges as $r) {
                if (!Rules\CrawlerLists::isRange($r)) {
                    throw self::wrong("crawlers.$id.ranges", 'addresses or ranges (192.0.2.0/24)');
                }
            }
            $policy = $policies[$id] ?? $policies[$x['kind']] ?? 'allow';
            if (!in_array($policy, Rules\RuleFile::POLICIES, true)) {
                throw self::wrong("crawlerPolicy.$id", implode(', ', Rules\RuleFile::POLICIES));
            }
            /** @var array<string, array<string, ?string>> $lists */
            $lists = is_array($x['lists'] ?? null) ? $x['lists'] : [];
            // The ranges as a lookup, built once (compiled with the settings).
            $nets = IpAddress::index($ranges);
            $out[$id] = ['kind' => $x['kind'], 'ua' => $x['ua'], 'dns' => self::strings($x, 'dns', "crawlers.$id.dns"), 'ranges' => $ranges, 'lists' => $lists, 'policy' => (string) $policy, 'nets' => $nets];
        }
        foreach ($policies as $key => $policy) {
            if (!isset($out[$key]) && !in_array($key, Rules\RuleFile::KINDS, true)) {
                throw self::wrong("crawlerPolicy.$key", 'a kind (' . implode(', ', Rules\RuleFile::KINDS) . ') or a crawler\'s ID');
            }
        }
        return $out;
    }

    /**
     * plugin … from <file>: plugin class => the file that holds it, as given
     * (absolute by the time the rules are compiled).
     *
     * @param array<mixed> $c
     * @return array<class-string, string>
     */
    private static function pluginFiles(array $c): array
    {
        $out = [];
        foreach (self::map($c, 'pluginFiles') as $class => $file) {
            if (!is_string($class) || !preg_match('/^[A-Za-z_][A-Za-z0-9_]*(\\\\[A-Za-z_][A-Za-z0-9_]*)*$/', $class) || !is_string($file) || $file === '') {
                throw self::wrong('pluginFiles', 'a map of plugin class names to the files that hold them');
            }
            /** @var class-string $class */
            $out[$class] = $file;
        }
        return $out;
    }

    /**
     * Plugins by their class names (Vendor\Package\MyPlugin): checked for their
     * form here; whether the class is there and a Plugin, when the shield makes
     * them (and by "check").
     *
     * @param array<mixed> $c
     * @return list<class-string>
     */
    private static function plugins(array $c): array
    {
        $out = [];
        foreach ((array) ($c['plugins'] ?? []) as $class) {
            if (!is_string($class) || !preg_match('/^\\\\?[A-Za-z_][A-Za-z0-9_]*(\\\\[A-Za-z_][A-Za-z0-9_]*)*$/', $class)) {
                throw self::wrong('plugins', 'class names such as Vendor\\Package\\MyPlugin');
            }
            /** @var class-string $name */
            $name = ltrim($class, '\\');
            $out[] = $name;
        }
        return array_values(array_unique($out));
    }

    /**
     * The extensions' settings: extension id => its checked values. Nothing
     * here is read by the core; an extension's compile() (0031 B.2) writes
     * what its plugin reads at request time.
     *
     * @param array<mixed> $c
     * @return array<string, array<string, mixed>>
     */
    private static function ext(array $c): array
    {
        $out = [];
        foreach (self::map($c, 'ext') as $id => $values) {
            if (!is_string($id) || !preg_match('/^[a-z][a-z0-9-]{0,31}$/', $id) || !is_array($values)) {
                throw self::wrong('ext', 'a map of extension ids (letters, digits, "-") to their settings');
            }
            /** @var array<string, mixed> $values */
            $out[$id] = $values;
        }
        return $out;
    }

    /**
     * Which plugins provide which capability: hook name => the classes, as the
     * compiler recorded them (instanceof at compile time, 0031 B.2), so a
     * request asks one array instead of every plugin.
     *
     * @param array<mixed> $c
     * @return array<string, list<class-string>>
     */
    private static function hooks(array $c): array
    {
        $out = [];
        foreach (self::map($c, 'hooks') as $hook => $classes) {
            if (!is_string($hook) || !preg_match('/^[a-z][a-zA-Z0-9]{0,31}$/', $hook) || !is_array($classes)) {
                throw self::wrong('hooks', 'a map of hook names to lists of plugin classes');
            }
            $out[$hook] = self::plugins(['plugins' => $classes]);
        }
        return $out;
    }

    /**
     * Pages given in the settings array (for tests and a site's own): path
     * => entry as Routes has them (key, tab, role, order; ext optional).
     * compiledExt() adds the core's and the extensions' pages to them.
     *
     * @param array<mixed> $c
     * @return array<string, array{key: string, ext: ?string, tab: ?array{0: string, 1: string}, role: string, order: int}>
     */
    private static function routes(array $c): array
    {
        $out = [];
        foreach (self::map($c, 'routes') as $path => $route) {
            if (!is_string($path) || $path === '' || $path[0] !== '/' || !is_array($route)) {
                throw self::wrong('routes', 'a map of paths (starting with "/") to what each page is');
            }
            $out[$path] = Routes::entry($route, 'routes', $path);
        }
        return $out;
    }

    /**
     * The addresses let in for a while (exempt … until), those still in force.
     *
     * @param array<mixed> $c
     * @return list<string>
     */
    private static function exemptForNow(array $c): array
    {
        $out = [];
        $now = time();
        foreach ((array) ($c['exemptUntil'] ?? []) as $e) {
            if (is_array($e) && (!is_int($e['until'] ?? null) || $e['until'] > $now)) {
                foreach ((array) ($e['ips'] ?? []) as $ip) {
                    if (is_string($ip)) {
                        $out[] = $ip;
                    }
                }
            }
        }
        return $out;
    }

    /**
     * The deny list (the entries in force, and as a lookup), when the next
     * entry ends (exempt … until included), the list files' directory, and
     * the automatic bans.
     *
     * @param array<mixed> $c
     * @param array<string, Budget> $budgets
     * @return array{0: list<array{ips: list<string>, until: ?int, rule: string}>, 1: array{4: string, 6: string, ids: string, dir?: string}|array{}, 2: int, 3: int, 4: ?string, 5: list<array{after: int, signal: string, in: int, for: int, rule: string}>, 6: int, 7: int}
     */
    private static function lists(array $c, array $budgets): array
    {
        $now = time();
        $next = 0;
        $deny = [];
        $entries = [];
        foreach ((array) ($c['deny'] ?? []) as $i => $e) {
            if (!is_array($e) || !is_array($e['ips'] ?? null)) {
                throw self::wrong("deny[$i]", "['ips' => [addresses], 'until' => a Unix time or null]");
            }
            $until = is_int($e['until'] ?? null) ? $e['until'] : null;
            if ($until !== null && $until <= $now) {
                continue;                       // over: left out
            }
            $list = [];
            foreach ($e['ips'] as $ip) {
                $slash = is_string($ip) ? strpos($ip, '/') : false;
                if (!is_string($ip) || @inet_pton($slash === false ? $ip : (string) substr($ip, 0, $slash)) === false) {
                    throw self::wrong("deny[$i].ips", 'addresses or ranges (203.0.113.7, 198.51.100.0/24, 2001:db8::/32)');
                }
                $list[] = $ip;
            }
            $rule = is_string($e['rule'] ?? null) ? $e['rule'] : "deny[$i]";
            $entries[] = [$list, $rule];
            if (count($deny) < self::DENY_SHOWN) {
                $deny[] = ['ips' => $list, 'until' => $until, 'rule' => $rule];
            }
            if ($until !== null && ($next === 0 || $until < $next)) {
                $next = $until;
            }
        }
        foreach ((array) ($c['exemptUntil'] ?? []) as $e) {
            $until = is_array($e) && is_int($e['until'] ?? null) ? $e['until'] : 0;
            if ($until > $now && ($next === 0 || $until < $next)) {
                $next = $until;
            }
        }
        $bans = [];
        foreach ((array) ($c['bans'] ?? []) as $i => $b) {
            if (!is_array($b) || !is_int($b['after'] ?? null) || !is_string($b['signal'] ?? null) || !is_int($b['in'] ?? null) || !is_int($b['for'] ?? null)
                || $b['after'] < 1 || $b['in'] < 1 || $b['for'] < 1) {
                throw self::wrong("bans[$i]", "['after' => n, 'signal' => limits|refusals|checks|<budget>, 'in' => seconds, 'for' => seconds]");
            }
            if (!in_array($b['signal'], ['limits', 'refusals', 'checks'], true) && !isset($budgets[$b['signal']])) {
                throw self::wrong("bans[$i].signal", "limits, refusals, checks or a budget's name -- there is no budget \"{$b['signal']}\"");
            }
            $bans[] = ['after' => $b['after'], 'signal' => $b['signal'], 'in' => $b['in'], 'for' => $b['for'], 'rule' => is_string($b['rule'] ?? null) ? $b['rule'] : "bans[$i]"];
        }
        $growth = $c['banGrowth'] ?? 2;
        $max = $c['banMax'] ?? 86400;
        if (!is_int($growth) || $growth < 1 || !is_int($max) || $max < 1) {
            throw self::wrong('banGrowth/banMax', 'a whole number of at least 1');
        }
        $dir = $c['listsDir'] ?? null;
        return [$deny, $entries === [] ? [] : IpTable::build($entries), count($entries), $next, is_string($dir) && $dir !== '' ? $dir : null, $bans, $growth, $max];
    }

    /**
     * post-origin same: what to do without Origin and Referer, and the paths it never applies to.
     *
     * @param array<mixed> $c
     * @return array{missing: string, except: list<string>}|null
     */
    private static function postOrigin(array $c): ?array
    {
        $p = $c['postOrigin'] ?? null;
        if ($p === null) {
            return null;
        }
        if (!is_array($p)) {
            throw self::wrong('postOrigin', "null or ['missing' => 'check', 'except' => [path patterns]]");
        }
        if (($p['same'] ?? true) !== true) {
            return null;                        // a rule file's "post-origin except" without "post-origin same": off
        }
        $missing = self::string($p, 'missing', 'postOrigin.missing', 'check');
        if (!in_array($missing, ['check', 'allow', 'refuse'], true)) {
            throw self::wrong('postOrigin.missing', 'check (the browser check, the default), allow or refuse');
        }
        return ['missing' => $missing, 'except' => self::patternList($p['except'] ?? [], 'postOrigin.except')];
    }

    /**
     * A setting that must be a list: missing is empty, anything else but an array a mistake (said, not ignored).
     *
     * @param array<mixed> $c
     * @return mixed
     */
    private static function listOf(array $c, string $key)
    {
        if (!isset($c[$key])) {
            return [];
        }
        if (!is_array($c[$key])) {
            throw self::wrong($key, 'a list of path patterns');
        }
        return $c[$key];
    }

    /**
     * A list of path patterns (regular expressions, as the rule files compile them), each checked.
     *
     * @return list<string>
     * @param mixed $list
     */
    private static function patternList($list, string $key): array
    {
        $out = [];
        foreach (is_array($list) ? $list : [] as $i => $p) {
            if (!is_string($p) || @preg_match($p, '') === false) {
                throw self::wrong("{$key}[$i]", 'a path pattern (stats-skip **/osm-proxy/** in a rule file)');
            }
            $out[] = $p;
        }
        return $out;
    }

    /**
     * The lists with the feeds' next end: the settings are built again when a
     * fetched list grows too old (as when a list entry ends).
     *
     * @param array{0: list<array{ips: list<string>, until: ?int, rule: string}>, 1: array{4: string, 6: string, ids: string, dir?: string}|array{}, 2: int, 3: int, 4: ?string, 5: list<array{after: int, signal: string, in: int, for: int, rule: string}>, 6: int, 7: int} $lists
     * @param array{0: list<mixed>, 1: array<string, mixed>, 2: list<mixed>, 3: array<string, int>, 4: int, 5: int} $feeds
     * @return array{0: list<array{ips: list<string>, until: ?int, rule: string}>, 1: array{4: string, 6: string, ids: string, dir?: string}|array{}, 2: int, 3: int, 4: ?string, 5: list<array{after: int, signal: string, in: int, for: int, rule: string}>, 6: int, 7: int}
     */
    private static function withFeeds(array $lists, array $feeds, int $more = 0): array
    {
        foreach ([$feeds[5], $more] as $next) {
            if ($next > 0 && ($lists[3] === 0 || $next < $lists[3])) {
                $lists[3] = $next;
            }
        }
        return $lists;
    }

    /**
     * When the next dashboard-access entry ends: the settings are built again then.
     *
     * @param array<mixed> $c
     */
    private static function accessNext(array $c): int
    {
        $next = 0;
        foreach ((array) ($c['dashboardAccess'] ?? []) as $a) {
            $until = is_array($a) && is_int($a['until'] ?? null) ? $a['until'] : 0;
            if ($until > time() && ($next === 0 || $until < $next)) {
                $next = $until;
            }
        }
        return $next;
    }

    /**
     * The public blocklists (feed …, proposal 0025): each fetched list read
     * from <store-dir>/feeds, unless it is older than feeds-max-age (then left
     * out, and said so); per action one table of the lists without "at", each
     * list with "at" its own. Returns [feeds, tables, at, weights, max age,
     * when the next list grows too old].
     *
     * @param array<mixed> $c
     * @return array{0: list<array{name: string, title: string, action: string, weight: int, paths: list<string>, rule: string, terms: string, urls: list<string>, format: string, every: int, wideOk: bool, count: int, fetched: int, state: string, file: ?string}>, 1: array<string, array{4: string, 6: string, ids: string, dir?: string}>, 2: list<array{action: string, table: array{4: string, 6: string, ids: string, dir?: string}, paths: list<string>}>, 3: array<string, int>, 4: int, 5: int}
     */
    private static function feeds(array $c): array
    {
        $maxAge = $c['feedsMaxAge'] ?? 259200;
        if (!is_int($maxAge) || $maxAge < 3600) {
            throw self::wrong('feedsMaxAge', 'seconds, at least an hour');
        }
        $dir = is_string($c['storeDir'] ?? null) && $c['storeDir'] !== '' ? $c['storeDir'] . '/feeds' : null;
        $now = time();
        $feeds = [];
        $entries = [];
        $at = [];
        $weights = [];
        $next = 0;
        foreach ((array) ($c['feeds'] ?? []) as $i => $f) {
            if (!is_array($f) || !is_string($f['name'] ?? null) || preg_match('/^[a-z0-9][a-z0-9-]{0,40}$/', $f['name']) !== 1
                || !in_array($f['action'] ?? null, ['deny', 'check', 'signal'], true)) {
                throw self::wrong("feeds[$i]", "['name' => a name, 'action' => deny|check|signal, …] (feed <name> <action> in a rule file)");
            }
            $name = $f['name'];
            $rule = is_string($f['rule'] ?? null) ? $f['rule'] : "feeds[$i]";
            $paths = array_values(array_filter((array) ($f['paths'] ?? []), 'is_string'));
            $file = is_string($f['file'] ?? null) ? $f['file'] : null;
            if ($file !== null) {
                // feed … from <file>: the site's own list, as current as the rules (no fetch, no age).
                $body = @file_get_contents($file);
                $ranges = $body === false ? [] : \CjwNetwork\RequestShield\Rules\Feeds::clean(\CjwNetwork\RequestShield\Rules\Feeds::parse($body,
                    is_string($f['format'] ?? null) ? $f['format'] : 'plain'), (bool) ($f['wideOk'] ?? false))['ranges'];
                $meta = ['checked' => (int) @filemtime($file), 'count' => count($ranges)];
                $state = $body === false ? 'not fetched' : 'in force';
            } else {
                $meta = $dir === null ? ['checked' => 0, 'count' => 0] : \CjwNetwork\RequestShield\Rules\Feeds::meta($dir, $name);
                $text = $dir === null ? false : @file_get_contents("$dir/$name.txt");
                $state = 'in force';
                if ($text === false) {
                    $state = 'not fetched';
                } elseif ($now - $meta['checked'] > $maxAge) {
                    $state = 'too old';
                }
                $ranges = $state === 'in force' ? array_values(array_filter(explode("\n", (string) $text), static fn (string $l): bool => $l !== '')) : [];
            }
            if ($state === 'in force') {
                if ($file === null) {
                    $until = $meta['checked'] + $maxAge + 1;
                    $next = $next === 0 ? $until : min($next, $until);
                }
                if ($paths === []) {
                    $entries[$f['action']][] = [$ranges, $rule];
                } else {
                    $at[] = ['action' => (string) $f['action'], 'table' => \CjwNetwork\RequestShield\IpTable::build([[$ranges, $rule]]), 'paths' => $paths];
                }
            }
            if ($f['action'] === 'signal') {
                $weights[$rule] = max(1, min(99, is_int($f['weight'] ?? null) ? $f['weight'] : 1));
            }
            $feeds[] = [
                'name' => $name, 'title' => is_string($f['title'] ?? null) ? $f['title'] : $name, 'action' => (string) $f['action'], 'weight' => $weights[$rule] ?? 1,
                'paths' => $paths, 'rule' => $rule, 'terms' => is_string($f['terms'] ?? null) ? $f['terms'] : '',
                'urls' => array_values(array_filter((array) ($f['urls'] ?? []), 'is_string')), 'format' => is_string($f['format'] ?? null) ? $f['format'] : 'plain',
                'every' => is_int($f['every'] ?? null) ? $f['every'] : 3600, 'wideOk' => (bool) ($f['wideOk'] ?? false),
                'count' => count($ranges), 'fetched' => $meta['checked'], 'state' => $state, 'file' => $file,
            ];
        }
        $tables = [];
        foreach ($entries as $action => $list) {
            $tables[(string) $action] = \CjwNetwork\RequestShield\IpTable::build($list);
        }
        return [$feeds, $tables, $at, $weights, $maxAge, $next];
    }

    /**
     * The live view's memory: on or off, and how long an entry stays (at most
     * a day); and where a ban is kept (memory, or also a file).
     *
     * @param array<mixed> $c
     * @return array{0: bool, 1: int, 2: string}
     */
    private static function live(array $c): array
    {
        $l = $c['live'] ?? [];
        $l = is_array($l) ? $l : ['enabled' => $l];
        $on = $l['enabled'] ?? false;
        $keep = $l['keep'] ?? 3600;
        if (!is_bool($on) || !is_int($keep) || $keep < 60 || $keep > 86400) {
            throw self::wrong('live', "['enabled' => true|false, 'keep' => seconds from 60 to 86400]");
        }
        $banKeep = $c['banKeep'] ?? 'memory';
        if (!in_array($banKeep, ['memory', 'file'], true)) {
            throw self::wrong('banKeep', 'memory or file');
        }
        return [$on, $keep, $banKeep];
    }

    /**
     * The site blocks (from a rule file): website name => block, this block,
     * and which name picks one.
     *
     * @param array<mixed> $c
     * @return array{0: array<string, string>, 1: ?string, 2: string}
     */
    private static function sites(array $c): array
    {
        $map = [];
        foreach ((array) ($c['sites'] ?? []) as $name => $id) {
            if (!is_string($id)) {
                throw self::wrong('sites', 'website name => site block');
            }
            $map[(string) $name] = $id;
        }
        $site = $c['site'] ?? null;
        $from = $c['siteFrom'] ?? 'server-name';
        if (!in_array($from, ['server-name', 'host'], true)) {
            throw self::wrong('siteFrom', 'server-name or host');
        }
        return [$map, is_string($site) ? $site : null, $from];
    }

    /**
     * The site block a request belongs to, or null (the base): its name --
     * the web server's (SERVER_NAME) or, with site-from host, the Host header
     * (from a trusted proxy: X-Forwarded-Host) -- in lower case, without its
     * port and a trailing dot; looked up as itself, as *.<the rest>, then
     * "default". Two isset(), no expression.
     *
     * @param array<mixed> $server $_SERVER
     */
    public function siteFor(array $server): ?string
    {
        return $this->sites === [] ? null : self::pick($this->sites, $this->siteFrom, $this->trustedProxies, $server);
    }

    /**
     * siteFor() on the plain values -- for loadFor(), which picks the website
     * before it makes any settings.
     *
     * @param array<string, string> $sites
     * @param list<string> $trusted
     * @param array<mixed> $server
     */
    private static function pick(array $sites, string $from, array $trusted, array $server): ?string
    {
        $name = $server['SERVER_NAME'] ?? '';
        if ($from === 'host') {
            $name = $server['HTTP_HOST'] ?? $name;
            $forwarded = $server['HTTP_X_FORWARDED_HOST'] ?? null;
            $peer = $server['REMOTE_ADDR'] ?? '';
            if (is_string($forwarded) && is_string($peer) && $peer !== '' && $trusted !== [] && IpAddress::inRanges($peer, $trusted)) {
                $name = trim(explode(',', $forwarded)[0]);
            }
        }
        $name = is_string($name) ? strtolower($name) : '';
        // Without its port and a trailing dot -- string functions, no expression.
        $colon = strrpos($name, ':');
        if ($colon !== false && ctype_digit(substr($name, $colon + 1))) {
            $name = (string) substr($name, 0, $colon);
        }
        $name = rtrim($name, '.');
        if ($name !== '' && isset($sites[$name])) {
            return $sites[$name];
        }
        $dot = strpos($name, '.');
        if ($dot !== false && isset($sites['*' . substr($name, $dot)])) {
            return $sites['*' . substr($name, $dot)];
        }
        return $sites['default'] ?? null;
    }

    /** @param array<mixed> $c */
    /**
     * dashboard-access: who may open the dashboard's pages, by a token's hash --
     * '*' (everything) or an opaque principal (customer-a): what a principal
     * may see is the pages' business (the statistics map it to a group's
     * websites), the core only knows the id. Ended lines are left out.
     * Plus dashboard-session, the login's lifetime.
     *
     * @param array<mixed> $c
     * @return array{0: list<array{who: string, hash: string, until: ?int, rule: string}>, 1: int}
     */
    private static function dashboardAccess(array $c): array
    {
        $out = [];
        foreach ((array) ($c['dashboardAccess'] ?? []) as $i => $a) {
            if (!is_array($a) || !is_string($a['who'] ?? null) || !is_string($a['hash'] ?? null) || preg_match('/^[0-9a-f]{64}$/', $a['hash']) !== 1) {
                throw self::wrong("dashboardAccess[$i]", "['who' => '*' or a principal, 'hash' => the token's SHA-256 in hex]");
            }
            $who = $a['who'] === '*' ? '*' : self::principal($a['who']);
            if ($who === '') {
                throw self::wrong("dashboardAccess[$i]", "* or a principal of letters and digits -- not \"{$a['who']}\"");
            }
            $until = is_int($a['until'] ?? null) ? $a['until'] : null;
            if ($until !== null && $until <= time()) {
                continue;                               // ended: left out
            }
            $out[] = ['who' => $who, 'hash' => $a['hash'], 'until' => $until, 'rule' => is_string($a['rule'] ?? null) ? $a['rule'] : "dashboardAccess[$i]"];
        }
        $session = $c['dashboardSession'] ?? 28800;
        if (!is_int($session) || $session < 60 || $session > 2592000) {
            throw self::wrong('dashboardSession', 'seconds from 60 to 2592000 (30 days)');
        }
        return [$out, $session];
    }

    /** A principal's id, as the dashboard and its links name it: "Customer A" -> customer-a. */
    public static function principal(string $name): string
    {
        return trim((string) preg_replace('/[^a-z0-9]+/', '-', strtolower($name)), '-');
    }

    /**
     * A learning run (0016), as Learn::read() found it when the rules were compiled.
     *
     * @param array<mixed> $c
     * @return array{until: int, token: string, from: list<string>}|null
     */
    private static function learn(array $c): ?array
    {
        $l = $c['learn'] ?? null;
        if ($l === null) {
            return null;
        }
        if (!is_array($l) || !is_int($l['until'] ?? null) || !is_string($l['token'] ?? null) || preg_match('/^[0-9a-f]{64}$/', $l['token']) !== 1
            || !is_array($l['from'] ?? null) || array_filter($l['from'], static fn ($a): bool => !is_string($a)) !== []) {
            throw self::wrong('learn', "until (a time), token (a SHA-256 in hex), from (addresses) -- what request-shield learn writes");
        }
        /** @var list<string> $from */
        $from = array_values($l['from']);
        return ['until' => $l['until'], 'token' => $l['token'], 'from' => $from];
    }

    /**
     * @param array<mixed> $c
     * @return array<int|string, array<string, string>> status (a number keeps its key as one) => language => HTML
     */
    private static function errorPages(array $c): array
    {
        $pages = $c['errorPages'] ?? [];
        if (!is_array($pages)) {
            throw self::wrong('errorPages', 'status => language => HTML (set error-page in a rule file)');
        }
        $out = [];
        foreach ($pages as $status => $byLang) {
            if (!in_array((string) $status, ErrorPage::STATUSES, true) || !is_array($byLang)) {
                throw self::wrong("errorPages.$status", 'a status the shield refuses with (' . implode(', ', ErrorPage::STATUSES) . ') => language => HTML');
            }
            foreach ($byLang as $lang => $html) {
                if (!is_string($html) || strlen($html) > ErrorPage::MAX || ($lang !== '' && preg_match('/^[a-z]{2,3}(-[a-z0-9]{2,8})?$/', (string) $lang) !== 1)) {
                    throw self::wrong("errorPages.$status.$lang", 'HTML of at most 64 KB, by a language code ("" for all)');
                }
                $out[(string) $status][(string) $lang] = $html;
            }
        }
        return $out;
    }

    /** @param array<mixed> $c the docs' folder: an http(s) address or a path on the site; "off" (or "") for no links */
    private static function docsUrl(array $c): string
    {
        $u = $c['docsUrl'] ?? Help::DOCS;
        if ($u === 'off' || $u === '') {
            return '';
        }
        if (!is_string($u) || preg_match('#^(https?://[^\s"<>]+|/(?!/)[^\s"<>]*)$#i', $u) !== 1) {
            throw self::wrong('docsUrl', 'an address such as https://docs.example.org/request-shield, a path such as /docs, or off');
        }
        return rtrim($u, '/');
    }

    /** @param array<mixed> $c */
    private static function dashboardPath(array $c): string
    {
        $p = $c['dashboardPath'] ?? '/rs';
        // Names of letters, digits and . _ ~ -, but no "." or ".." of their own.
        if (!is_string($p) || !preg_match('#^(/[A-Za-z0-9._~-]+)+$#', $p) || preg_match('#/\.+(/|$)#', $p)) {
            throw self::wrong('dashboardPath', 'a path such as /rs or /admin/rs');
        }
        return $p;
    }

    /**
     * @param array<mixed> $c
     * @return array<string, string>
     */
    private static function crawlerPolicy(array $c): array
    {
        $out = [];
        foreach (self::map($c, 'crawlerPolicy') as $key => $policy) {
            if (!is_string($policy)) {
                throw self::wrong("crawlerPolicy.$key", implode(', ', Rules\RuleFile::POLICIES));
            }
            $out[(string) $key] = $policy;
        }
        return $out;
    }

    /**
     * Every crawler's User-Agent pattern in one expression: a request that
     * names none costs one match. (*MARK:n) says which one matched.
     *
     * @param array<string, array{ua: string}> $crawlers
     * @return array{0: string, 1: list<string>}
     */
    public static function crawlerIndex(array $crawlers): array
    {
        $parts = [];
        $ids = [];
        foreach ($crawlers as $id => $x) {
            // '#…#i' or '/…/i': the expression between the delimiters.
            $d = $x['ua'][0];
            $end = strrpos($x['ua'], $d);
            $inner = (string) substr($x['ua'], 1, (int) $end - 1);
            // Into '#…#': a "#" of another delimiter's expression needs its backslash.
            $inner = $d === '#' ? $inner : str_replace('#', '\#', str_replace('\\' . $d, $d, $inner));
            $parts[] = '(?:' . $inner . ')(*MARK:' . count($ids) . ')';
            $ids[] = $id;
        }
        $index = $parts === [] ? '' : '#' . implode('|', $parts) . '#i';
        if ($index !== '' && @preg_match($index, '') === false) {
            throw self::wrong('crawlers', 'User-Agent patterns that go into one expression (no back references)');
        }
        return [$index, $ids];
    }

    /**
     * @param array<mixed> $list
     * @return list<array{paths: list<string>|null, exact: array<string, string>, globs: array<string, string>}>
     */
    private static function queryParams(array $list): array
    {
        $out = [];
        $type = static function ($t, string $where): string {
            if (!is_string($t) || !(in_array($t, ['int', 'number', 'word', 'id', 'list', 'text', 'any'], true)
                || (strncmp($t, '#', 1) === 0 && @preg_match($t, '') !== false))) {
                throw self::wrong($where, 'int, number, word, id, list, text, any or a regex');
            }
            return $t;
        };
        foreach ($list as $i => $r) {
            if (!is_array($r)) {
                throw self::wrong("queryParams.$i", "an array of 'paths', 'exact' and 'globs'");
            }
            $exact = [];
            foreach (self::map($r, 'exact', "queryParams.$i.exact") as $name => $t) {
                $exact[(string) $name] = $type($t, "queryParams.$i.exact.$name");
            }
            $globs = [];
            foreach (self::map($r, 'globs', "queryParams.$i.globs") as $glob => $t) {
                if (@preg_match((string) $glob, '') === false) {
                    throw self::wrong("queryParams.$i.globs", 'regular expressions as keys');
                }
                $globs[(string) $glob] = $type($t, "queryParams.$i.globs");
            }
            $out[] = ['paths' => self::stringsOrNull($r, 'paths', "queryParams.$i.paths"), 'exact' => $exact, 'globs' => $globs];
        }
        return $out;
    }

    /**
     * For each target, the texts every one of its patterns starts with --
     * "${" for "\$\{(jndi|...)" -- when there are such: the request is then
     * normalised and matched only if its raw value holds one of them, or a
     * "%" (an encoding). Normalising can decode, lower-case and merge white
     * space, none of which makes such a text appear. A target where any
     * pattern can start otherwise gets none, and is always matched.
     *
     * @param list<array{target: string, patterns: list<string>}> $rules
     * @return array<string, list<string>>
     */
    public static function hints(array $rules): array
    {
        $by = [];
        $none = [];
        foreach ($rules as $r) {
            foreach ($r['patterns'] as $p) {
                if (!preg_match('/^#(.*)#i?$/s', $p, $m)) {
                    $none[$r['target']] = true;
                    continue;
                }
                foreach (self::alternatives($m[1]) as $alt) {
                    $lit = self::leadingLiteral($alt);
                    if (strlen($lit) < 2) {
                        $none[$r['target']] = true;
                        continue 2;
                    }
                    $by[$r['target']][strtolower($lit)] = true;
                }
            }
        }
        $out = [];
        foreach ($by as $target => $lits) {
            if (isset($none[$target])) {
                continue;
            }
            // A text that holds a shorter one is found with it: only the shorter.
            $keep = [];
            foreach (array_keys($lits) as $l) {
                foreach (array_keys($lits) as $other) {
                    if ($other !== $l && strpos((string) $l, (string) $other) !== false) {
                        continue 2;
                    }
                }
                $keep[] = (string) $l;
            }
            $out[$target] = $keep;
        }
        return $out;
    }

    /** @return list<string> an expression's top-level alternatives */
    private static function alternatives(string $re): array
    {
        $out = [];
        $depth = 0;
        $class = false;
        $start = 0;
        for ($i = 0, $n = strlen($re); $i < $n; $i++) {
            $c = $re[$i];
            if ($c === '\\') {
                $i++;
            } elseif ($class) {
                $class = $c !== ']';
            } elseif ($c === '[') {
                $class = true;
            } elseif ($c === '(') {
                $depth++;
            } elseif ($c === ')') {
                $depth--;
            } elseif ($c === '|' && $depth === 0) {
                $out[] = (string) substr($re, $start, $i - $start);
                $start = $i + 1;
            }
        }
        $out[] = (string) substr($re, $start);
        return $out;
    }

    /** The plain text an alternative has to start with ("\$\{" -> "${"); '' if none. */
    private static function leadingLiteral(string $alt): string
    {
        $lit = '';
        for ($i = 0, $n = strlen($alt); $i < $n; $i++) {
            $c = $alt[$i];
            if ($c === '\\') {
                $next = $alt[$i + 1] ?? '';
                if ($next === '' || ctype_alnum($next)) {
                    break;                  // \s, \d, \b, \1 ...: not a plain character
                }
                $lit .= $next;
                $i++;
                $last = $i;
                continue;
            }
            if (strpos('.[](){}?*+|^$', $c) !== false) {
                break;
            }
            $lit .= $c;
        }
        // A quantifier that allows none takes the last character back.
        $after = $alt[$i] ?? '';
        if ($lit !== '' && ($after === '?' || $after === '*' || $after === '{')) {
            $lit = (string) substr($lit, 0, -1);
        }
        return $lit;
    }

    /**
     * Several expressions as one: "#a#", "#b#i" -> "#(?:a)|(?i:b)#". Only
     * where that means the same -- delimiters "#" or "/", no flags but "i",
     * no back references or named groups (they would point elsewhere);
     * otherwise '' and the patterns are matched one by one, as before.
     *
     * @param list<string> $patterns
     */
    public static function combine(array $patterns): string
    {
        if (count($patterns) < 2) {
            return '';
        }
        $parts = [];
        foreach ($patterns as $p) {
            if (!preg_match('~^([#/])(.*)\1(i?)$~s', $p, $m) || preg_match('/\\\\[1-9]|\\\\g\{?-?\d|\(\?P?[<\'=]|\(\?\|/', $m[2])) {
                return '';
            }
            $body = $m[1] === '/' ? str_replace(['\\/', '#'], ['/', '\\#'], $m[2]) : $m[2];
            $parts[] = ($m[3] === 'i' ? '(?i:' : '(?:') . $body . ')';
        }
        $all = '#' . implode('|', $parts) . '#';
        return @preg_match($all, '') === false ? '' : $all;
    }

    /**
     * The attack rules, and per target one expression of all its patterns --
     * a clean request then costs one match per target.
     *
     * @param array<mixed> $list
     * @return array{0: list<array{target: string, patterns: list<string>}>, 1: array<string, string>}
     */
    private static function contentRules(array $list): array
    {
        $rules = [];
        $bodies = [];
        foreach ($list as $i => $r) {
            if (!is_array($r)) {
                throw self::wrong("contentRules.$i", "an array of 'target' and 'patterns'");
            }
            $target = strtolower(self::string($r, 'target', "contentRules.$i.target"));
            if (!in_array($target, ['query', 'headers', 'anywhere'], true) && !preg_match('/^header:[a-z0-9-]+$/', $target)) {
                throw self::wrong("contentRules.$i.target", 'query, headers, anywhere or header:<name>');
            }
            $patterns = self::strings($r, 'patterns', "contentRules.$i.patterns");
            foreach ($patterns as $p) {
                if (!preg_match('/^#(.*)#i?$/s', $p, $m) || @preg_match($p, '') === false) {
                    throw self::wrong("contentRules.$i.patterns", 'regular expressions in #...# (flag i at most)');
                }
                // All of a target's patterns become one expression: a back
                // reference would point at another pattern's group, and a name
                // could be taken twice; a call or a condition by number ((?1), (?R),
                // \g<1>, (?(1)…)) would reach another pattern's group too. A look
                // around ((?<!…), (?=…)) or a relative call ((?-1)) is fine.
                if (preg_match('/\\\\[1-9]|\\\\g\{?-?\d|\\\\g[<\']\+?\d|\\\\k[<{\']|\(\?(P?<(?![=!])|\'|P[=>]|[R0-9]|\+\d|\((\d|R))/', $m[1])) {
                    throw self::wrong("contentRules.$i.patterns", 'expressions without back references, named groups or groups called by number');
                }
                $bodies[$target][] = '(?:' . $m[1] . ')';
            }
            $rules[] = ['target' => $target, 'patterns' => $patterns];
        }
        $index = [];
        foreach ($bodies as $target => $b) {
            $index[$target] = '#' . implode('|', $b) . '#i';
            if (@preg_match($index[$target], '') === false) {
                throw self::wrong('contentRules', 'patterns that also work together (' . $target . ')');
            }
        }
        return [$rules, $index];
    }

    /**
     * @param array<mixed> $o
     * @return array<string, array<string, string>>
     */
    private static function origins(array $o): array
    {
        $out = [];
        foreach ($o as $setting => $list) {
            if (!is_array($list)) {
                throw self::wrong("origins.$setting", 'an array');
            }
            foreach ($list as $what => $where) {
                if (!is_string($where)) {
                    throw self::wrong("origins.$setting", 'an array of strings');
                }
                $out[(string) $setting][(string) $what] = $where;
            }
        }
        return $out;
    }

    /**
     * Where the rule behind a pattern or budget was written ("site.rules:12",
     * "default @scanners.backups"); null for settings from a PHP array.
     */
    public function origin(string $setting, string $what): ?string
    {
        return $this->origins[$setting][$what] ?? null;
    }

    /**
     * The rule's name for the log and the pages: where the setting was written
     * (its ID or file:line), else $fallback -- printable characters only.
     */
    public function ruleName(string $setting, string $what, string $fallback): string
    {
        $origin = $this->origin($setting, $what) ?? $fallback;
        return preg_replace('/[^\x21-\x7e ]/', '?', $origin) ?? $fallback;
    }

    // ── Compiled: checked once, then loaded from OPcache ──────────────────

    /** Deny entries kept as they were written, for the pages; the rest only in the table. */
    public const DENY_SHOWN = 100;

    /** Bumped when the export's shape changes, so old compiled files are rebuilt. */
    /** The capabilities a Plugin may have: hook name => its interface (recorded by compiledExt()). */
    private const HOOKS = ['ruleCounts' => RuleCounts::class, 'sink' => Sink::class, 'pages' => Pages::class, 'ruleProvider' => RuleProvider::class, 'handler' => Handler::class, 'methodHandler' => MethodHandler::class, 'contextHandler' => ContextHandler::class, 'purger' => Purger::class];

    private const FORMAT = 67;       // 3: rule files, several sources, origins; 4: restricted, methodPaths, log; 5: blockExceptions; 6: challenge.language; 7: appChallenge; 8: challenge.home; 9: contentRules; 10: blockedIndex; 11: contentHints; 12: widget; 13: earnBack, apiPaths; 14: dnsLookups; 15: queryParams; 16: queryIndex; 17: mode, uncachedWeight, monitor, challenge.alwaysMaxAge; 18: crawlers; 19: stats, crawlerLog; 20: statsParts, statsFlush; 21: statsMonths; 22: challenge.logo; 23: dashboardPath; 24: statsDepth; 25: origins.queryParams; 26: plugins; 27: sites, site, siteFrom; 28: budget.site; 29: deny, lists, bans; 30: denyTable, denyCount; 31: liveEnabled, liveKeep, banKeep; 32: feeds, feedTables, feedsAt, feedWeights, feedsMaxAge; 33: statsHosts; 34: statsSkip, statsGroups; 36: statsPath; 37: statsAccess, statsSession; 38: budget.paths; 39: postOrigin; 40: backend, statsParts.forms; 41: ext, hooks, routes; 42: stats in ext.stats; 43: routes compiled, stats path in ext.stats; 44: dashboardAccess, dashboardSession (stats-group in ext.stats); 45: hooks recorded; 46: the sink hook; 47: the pages hook; 48: the ruleProvider hook; 49: the handler hook; 50: pluginFiles; 51: routeBases; 52: docsUrl; 53: errorPages; 54: the WAF's pages are a plugin (routes with ext waf); 55: challenge.alwaysMethods; 56: learn; 57: ext.stats.slow (0046); 58: fileMode, dirMode; 59: the methodHandler hook, the cache's purge settings; 60: the contextHandler hook, the cache's role settings; 61: the cache's user hash lookup; 62: the cache's memory and disk cap; 63: the purger hook; 64: cacheableIgnore, cacheableUnknown (0048); 65: ext.cache.page; 66: store-dir, lists-dir relative to the rule file; 67: queryDrop

    public const MODES = ['off', 'monitor', 'enforce', 'strict'];

    /**
     * The settings of a file, checked only when it changed. A ".rules" file
     * is a rule file (Rules\RuleFile), anything else a PHP file returning
     * the settings array; $sources are further rule files or globs read
     * before it (an adapter's extensions), each with its includes.
     *
     * The checked values are kept as a PHP file in $cacheDir, which OPcache
     * serves from memory. Whether the sources changed:
     *   - one file: its mtime and size, on every call (one stat());
     *   - several, with APCu: all of them, at most every "recheck" seconds
     *     (default 10) -- in between not a single stat();
     *   - several, without APCu: the main file on every call; the others
     *     when it changes (bin/request-shield reload touches it).
     * "set recheck 0" checks every source on every call.
     *
     * With site blocks (rules per website, 0024) the base is checked and, for
     * a website's block, $site loads its settings: the same sources, so no
     * check of its own -- one more include from OPcache.
     *
     * @param list<string> $sources
     * @param ?string $site a site block (siteFor() names it); null: the base
     * @param bool $failSafe never throw (the request path, see loadFor()): a file that does not compile
     *   leaves the last good compiled settings in force, or, without any, the shield switched off
     * @throws \InvalidArgumentException for a setting of the wrong type (Rules\RuleFileException: with file and line)
     * @throws \RuntimeException when the file cannot be read
     */
    public static function load(string $file, ?string $cacheDir = null, array $sources = [], ?string $site = null, bool $failSafe = false): self
    {
        $cacheDir ??= self::cacheDirFor($file);
        $key = hash(PHP_VERSION_ID >= 80100 ? 'xxh128' : 'md5', $file . "\0" . implode("\0", $sources));
        if ($site !== null) {
            return self::loadSite($file, $cacheDir, $sources, $site, $key, $failSafe);
        }
        $compiled = $cacheDir . '/settings-' . $key . '.php';
        $e = self::compiled($compiled, $file);
        if ($e !== null) {
            /** @var array{seen: array<string, array{0: int, 1: int}>, env: array<string, string|null>, recheck: int, settings: array<string, mixed>} $e */
            if (($e['env'] === [] || self::sameEnv($e['env'])) && self::inForce($e['settings']) && self::fresh($e['seen'], $e['recheck'], $key)) {
                self::$checked[$key] = $e['seen'];
                return self::imported($e['settings'], $compiled) ?? self::tryBuild($file, $cacheDir, $sources, $key, null, $failSafe);
            }
            if ($failSafe && self::stillBroken($cacheDir, $key)) {
                return self::imported($e['settings'], $compiled) ?? self::off($cacheDir, $file);     // as they were when they last failed: the last good ones
            }
            $lock = self::lock($cacheDir, $key);
            if ($lock === null) {
                return self::imported($e['settings'], $compiled) ?? self::tryBuild($file, $cacheDir, $sources, $key, null, $failSafe);     // another request is building them: the last ones meanwhile
            }
            try {
                return self::tryBuild($file, $cacheDir, $sources, $key, $e['settings'], $failSafe);
            } finally {
                self::unlock($lock);
            }
        }
        if ($failSafe && self::stillBroken($cacheDir, $key)) {
            return self::off($cacheDir, $file);
        }
        return self::tryBuild($file, $cacheDir, $sources, $key, null, $failSafe);
    }

    /**
     * Where the compiled settings go unless protectFile() names a directory:
     * .request-shield/ next to the settings file -- the owner's directory,
     * outside the document root as the file is; never the system's temp dir,
     * shared with other customers on a shared host. No realpath(): a stat.
     */
    public static function cacheDirFor(string $file): string
    {
        return dirname($file) . '/.request-shield';
    }

    /**
     * The compiled settings in a file: the array when it is this file's and
     * of this format, else null. A file that cannot even be parsed (cut short
     * by a full disk) is deleted, so the next request compiles anew. No
     * is_file() first: a stat costs more than everything else here, and an
     * include of a missing file just returns false.
     *
     * @return array<mixed>|null
     */
    private static function compiled(string $path, string $file): ?array
    {
        try {
            $e = @include $path;
        } catch (\Throwable $t) {
            @unlink($path);
            return null;
        }
        // Written by write() below, so trusted beyond its format, its file -- and its end: "whole"
        // comes last, so a file cut short (a full disk) that still parses lacks it. The constructor
        // would take a short array (its last arguments have defaults), and with PHP 8.1-8.3's JIT
        // not even a TypeError for a missing one stops it.
        return is_array($e) && ($e['format'] ?? 0) === self::FORMAT && ($e['file'] ?? '') === $file && ($e['whole'] ?? false) === true ? $e : null;
    }

    /**
     * import(), or null when the compiled array does not fit the constructor
     * (a file cut short inside the array): it is deleted and built anew.
     *
     * @param array<string, mixed> $settings
     */
    private static function imported(array $settings, string $path): ?self
    {
        try {
            return self::import($settings);
        } catch (\TypeError $t) {
            @unlink($path);
            return null;
        }
    }

    /**
     * build() -- and when the rule files cannot be compiled (a mistake in
     * them, a file that cannot be read), the site stays up (ADR 0007): the
     * last good compiled settings stay in force, or, without any, the shield
     * runs switched off. Noted in the error log once a minute; a marker keeps
     * the next requests from compiling again until a source changes.
     *
     * @param list<string> $sources
     * @param array<string, mixed>|null $last the last good compiled settings (export()), if any
     * @param bool $failSafe on the request path (loadFor()): never throw; a tool's load(): do
     */
    private static function tryBuild(string $file, string $cacheDir, array $sources, string $key, ?array $last, bool $failSafe): self
    {
        if (!$failSafe) {
            return self::build($file, $cacheDir, $sources, $key);     // a tool (check, the tests): a mistake is an error
        }
        try {
            $s = self::build($file, $cacheDir, $sources, $key);
        } catch (\InvalidArgumentException|\RuntimeException $e) {
            self::markBroken($cacheDir, $key, $file);
            Failure::note('settings', 'the rules cannot be compiled -- ' . ($last !== null ? 'the last good ones stay in force' : 'the shield runs switched off until they are fixed')
                . ': ' . $e->getMessage(), $cacheDir);
            return ($last !== null ? self::imported($last, $cacheDir . '/settings-' . $key . '.php') : null) ?? self::from(['mode' => 'off']);
        }
        @unlink($cacheDir . '/settings-' . $key . '.failed');
        return $s;
    }

    /** The shield switched off because the rules never compiled: said again, once a minute. */
    private static function off(string $cacheDir, string $file): self
    {
        Failure::note('settings', "the rules in $file still cannot be compiled -- the shield runs switched off until they are fixed (request-shield check $file says why)", $cacheDir);
        return self::from(['mode' => 'off']);
    }

    /**
     * Remembers that the sources, as they are now, do not compile: their
     * mtime and size, so the next requests see at one stat per file whether
     * anything changed.
     */
    private static function markBroken(string $cacheDir, string $key, string $file): void
    {
        // The main file: it is what changes on a fix (an included file that
        // changes alone is seen on the main file's next change, or by reload).
        clearstatcache();
        $seen = [$file => [(int) @filemtime($file), (int) @filesize($file)]];
        self::write($cacheDir . '/settings-' . $key . '.failed', "<?php\n// cjw-network/request-shield: these rules did not compile; checked again when they change.\nreturn " . var_export(['seen' => $seen], true) . ";\n");
    }

    /** Whether the sources are still exactly as they were when they last failed to compile. */
    private static function stillBroken(string $cacheDir, string $key): bool
    {
        $m = @include $cacheDir . '/settings-' . $key . '.failed';
        if (!is_array($m) || !is_array($m['seen'] ?? null) || $m['seen'] === []) {
            return false;
        }
        clearstatcache();
        foreach ($m['seen'] as $path => $stat) {
            if (!is_array($stat) || (int) @filemtime($path) !== ($stat[0] ?? null) || (int) @filesize($path) !== ($stat[1] ?? null)) {
                return false;
            }
        }
        return true;
    }

    /**
     * The settings for this request: load(), and with site blocks the
     * website's (siteFor()) -- picked from the compiled base before any
     * settings are made, so a website's request builds only its own.
     *
     * @param array<mixed> $server $_SERVER
     * @param list<string> $sources
     */
    public static function loadFor(string $file, array $server, ?string $cacheDir = null, array $sources = []): self
    {
        $cacheDir ??= self::cacheDirFor($file);
        $key = hash(PHP_VERSION_ID >= 80100 ? 'xxh128' : 'md5', $file . "\0" . implode("\0", $sources));
        $compiled = $cacheDir . '/settings-' . $key . '.php';
        $e = self::compiled($compiled, $file);
        if ($e !== null) {
            /** @var array{seen: array<string, array{0: int, 1: int}>, env: array<string, string|null>, recheck: int, settings: array{sites: array<string, string>, siteFrom: string, trustedProxies: list<string>}} $e */
            if (($e['env'] === [] || self::sameEnv($e['env'])) && self::inForce($e['settings']) && self::fresh($e['seen'], $e['recheck'], $key)) {
                self::$checked[$key] = $e['seen'];
                $raw = $e['settings'];
                $site = $raw['sites'] === [] ? null : self::pick($raw['sites'], $raw['siteFrom'], $raw['trustedProxies'], $server);
                if ($site !== null) {
                    return self::loadSite($file, $cacheDir, $sources, $site, $key, true);
                }
                return self::imported($raw, $compiled) ?? self::tryBuild($file, $cacheDir, $sources, $key, null, true);
            }
            if (self::stillBroken($cacheDir, $key)) {
                /** @var array<string, mixed> $raw */
                $raw = $e['settings'];
                return self::imported($raw, $compiled) ?? self::off($cacheDir, $file);     // as they were when they last failed: the last good ones
            }
            $lock = self::lock($cacheDir, $key);
            if ($lock === null) {
                // Another request is building them: the last ones meanwhile, the website's too.
                $raw = $e['settings'];
                $site = $raw['sites'] === [] ? null : self::pick($raw['sites'], $raw['siteFrom'], $raw['trustedProxies'], $server);
                $one = $site === null ? null : self::compiled($cacheDir . '/settings-' . $key . '-' . hash('crc32b', $site) . '.php', $file);    // whole, or not at all
                if ($one !== null && ($one['site'] ?? null) === $site) {
                    /** @var array{settings: array<string, mixed>} $one */
                    return self::import($one['settings']);
                }
                /** @var array<string, mixed> $raw */
                return self::import($raw);
            }
            try {
                /** @var array<string, mixed> $last */
                $last = $e['settings'];
                $base = self::tryBuild($file, $cacheDir, $sources, $key, $last, true);
            } finally {
                self::unlock($lock);
            }
            $site = $base->siteFor($server);
            return $site === null ? $base : self::loadSite($file, $cacheDir, $sources, $site, $key, true);
        }
        if (self::stillBroken($cacheDir, $key)) {
            return self::off($cacheDir, $file);
        }
        $base = self::tryBuild($file, $cacheDir, $sources, $key, null, true);
        $site = $base->siteFor($server);
        return $site === null ? $base : self::loadSite($file, $cacheDir, $sources, $site, $key, true);
    }

    /** @var array<string, array<string, array{0: int, 1: int}>> base key => the sources its last check found unchanged, this request */
    private static array $checked = [];

    /**
     * A website's settings (its site block on the base): checked with the
     * base -- the base just found the same sources unchanged, so the site's
     * compiled file is taken as it is (one include from OPcache, no stat).
     *
     * @param list<string> $sources
     */
    private static function loadSite(string $file, string $cacheDir, array $sources, string $site, string $key, bool $failSafe): self
    {
        if (!isset(self::$checked[$key])) {
            self::load($file, $cacheDir, $sources, null, $failSafe);         // the base, checked: its sources are the site's
        }
        $compiled = $cacheDir . '/settings-' . $key . '-' . hash('crc32b', $site) . '.php';
        $e = self::compiled($compiled, $file);
        if (self::isSite($e, $file, $site, $key)) {
            /** @var array{settings: array<string, mixed>} $e */
            $s = self::imported($e['settings'], $compiled);
            if ($s !== null) {
                return $s;
            }
        }
        // Missing, or from other sources: every website built again with the base.
        $base = self::tryBuild($file, $cacheDir, $sources, $key, null, $failSafe);
        $e = self::compiled($compiled, $file);
        if (self::isSite($e, $file, $site, $key)) {
            /** @var array{settings: array<string, mixed>} $e */
            return self::import($e['settings']);
        }
        return $base;                       // a site block that is gone: the base
    }

    /**
     * Whether an included file is the compiled settings of this site, from the sources the base just found unchanged.
     * @param mixed $e
     */
    private static function isSite($e, string $file, string $site, string $key): bool
    {
        return is_array($e) && ($e['format'] ?? 0) === self::FORMAT && ($e['file'] ?? '') === $file && ($e['site'] ?? null) === $site
            && ($e['seen'] ?? null) === (self::$checked[$key] ?? false);
    }

    /**
     * The right to build these settings: a handle, true when there is no lock
     * file to be had (built anyway, as before), or null while another request
     * holds it -- with a big list a build takes seconds, and every request
     * under load building at once would take the server down with it.
     *
     * @return resource|true|null
     */
    private static function lock(string $cacheDir, string $key)
    {
        if (!is_dir($cacheDir)) {
            @mkdir($cacheDir, 0700, true);
        }
        $h = @fopen($cacheDir . '/settings-' . $key . '.lock', 'c');
        if ($h === false) {
            return true;
        }
        if (!flock($h, LOCK_EX | LOCK_NB)) {
            fclose($h);
            return null;
        }
        return $h;
    }

    /** @param resource|true $lock */
    private static function unlock($lock): void
    {
        if (is_resource($lock)) {
            flock($lock, LOCK_UN);
            fclose($lock);
        }
    }

    /**
     * Reads and checks the settings, writes them compiled -- and, for a rule
     * file with site blocks, each website's settings beside them (all checked
     * now: a mistake in any block is an error here, not at that website's
     * first visitor). Every source any of them read is in "seen".
     *
     * @param list<string> $sources
     */
    private static function build(string $file, string $cacheDir, array $sources, string $key): self
    {
        try {
            return self::compile($file, $cacheDir, $sources, $key);
        } finally {
            Rules\RuleFile::forgetLists();         // read once per build, kept by no worker
        }
    }

    /** @param list<string> $sources */
    private static function compile(string $file, string $cacheDir, array $sources, string $key): self
    {
        $sites = [];
        if (substr($file, -6) === '.rules') {
            $files = $sources;
            $files[] = $file;
            $read = Rules\RuleFile::read($files);
            // The main file first: without APCu it is the one checked.
            $seen = [$file => $read['seen'][$file] ?? [0, 0]] + $read['seen'];
            $recheck = $read['recheck'];
            $config = $read['config'];
            $env = $read['env'];
            foreach ((array) ($config['sites'] ?? []) as $id) {
                if (!is_string($id) || isset($sites[$id])) {
                    continue;
                }
                $one = Rules\RuleFile::read($files, $id);
                $seen += $one['seen'];
                $env += $one['env'];
                $sites[$id] = self::from($one['config']);
            }
        } else {
            clearstatcache();
            $stat = Rules\RuleFile::stat($file);
            if ($stat === null) {
                throw new \RuntimeException("request-shield: cannot read the settings file $file");
            }
            // OPcache judges a file by its mtime, and a file rewritten within
            // the same second keeps it -- the old settings would be compiled
            // under the new size and stay for good.
            if (function_exists('opcache_invalidate')) {
                @opcache_invalidate($file, true);
            }
            $config = require $file;
            if (!is_array($config)) {
                throw new \RuntimeException("request-shield: $file must return an array");
            }
            if (!is_string($config['storeDir'] ?? null)) {
                $config['storeDir'] = dirname($file) . '/.request-shield/store';     // as a rule file's default: next to it
            }
            $seen = [$file => $stat];
            $recheck = 0;
            $env = [];
            if ($sources !== []) {
                throw new \RuntimeException('request-shield: further sources need a .rules main file');
            }
        }
        $settings = self::from($config);
        foreach ($sites as $id => $one) {
            self::write($cacheDir . '/settings-' . $key . '-' . hash('crc32b', $id) . '.php', "<?php\n// Compiled by cjw-network/request-shield from $file, site $id; rebuilt when it changes.\nreturn "
                . var_export(['format' => self::FORMAT, 'file' => $file, 'site' => $id, 'seen' => $seen, 'settings' => $one->export(), 'whole' => true], true) . ";\n");
        }
        self::write($cacheDir . '/settings-' . $key . '.php', "<?php\n// Compiled by cjw-network/request-shield from $file; rebuilt when it changes.\nreturn "
            . var_export(['format' => self::FORMAT, 'file' => $file, 'seen' => $seen, 'env' => $env, 'recheck' => $recheck, 'settings' => $settings->export(), 'whole' => true], true) . ";\n");
        if ($recheck > 0 && Capability::apcu()) {
            apcu_store('rshield:fresh:' . $key, true, $recheck);
        }
        self::$checked[$key] = $seen;
        return $settings;
    }

    /**
     * Whether compiled settings still hold: no list entry (deny … until,
     * exempt … until) has ended since -- one comparison.
     *
     * @param array<mixed> $settings what export() wrote
     */
    private static function inForce(array $settings): bool
    {
        $until = $settings['listsUntil'] ?? 0;
        return !is_int($until) || $until === 0 || time() < $until;
    }

    /** @param array<string, string|null> $env the environment variables a rule file used, with their values then */
    private static function sameEnv(array $env): bool
    {
        foreach ($env as $name => $value) {
            $now = getenv($name);
            if ((is_string($now) ? $now : null) !== $value) {
                return false;
            }
        }
        return true;
    }

    /**
     * Whether the sources are unchanged. Kept small and free of other
     * classes: it runs on every request.
     *
     * @param array<string, array{0: int, 1: int}> $seen path => [mtime, size], the main file first
     */
    private static function fresh(array $seen, int $recheck, string $key): bool
    {
        $apcu = $recheck > 0 && Capability::apcu();
        if ($apcu && apcu_fetch('rshield:fresh:' . $key) === true) {
            return true;
        }
        // PHP keeps the last stat() for the rest of the process: in a
        // long-running server (and a second load() in one request) the old
        // mtime and size would be compared, and a change never seen.
        clearstatcache();
        foreach ($seen as $path => $stat) {
            if (@filemtime($path) !== $stat[0] || @filesize($path) !== $stat[1]) {
                return false;
            }
            if ($recheck > 0 && !$apcu) {
                break;          // without APCu: only the main file
            }
        }
        if ($apcu) {
            apcu_store('rshield:fresh:' . $key, true, $recheck);
        }
        return true;
    }

    /** @return array<string, mixed> */
    public function export(): array
    {
        /** @var array<string, mixed> $e */
        $e = get_object_vars($this);
        $e['budgets'] = array_map(static fn (Budget $b): array => $b->export(), $this->budgets);
        $e['challenge'] = $this->challenge->export();
        $e['monitor'] = $this->monitor === null ? null : $this->monitor->export();
        return $e;
    }

    /** @param array<string, mixed> $e what export() returned (trusted: no checks) */
    public static function import(array $e): self
    {
        $budgets = [];
        foreach ((array) $e['budgets'] as $name => $b) {
            /** @var array<string, mixed> $b */
            $budgets[(string) $name] = Budget::import($b);
        }
        $e['budgets'] = $budgets;
        /** @var array<string, mixed> $challenge */
        $challenge = $e['challenge'];
        $e['challenge'] = ChallengeSettings::import($challenge);
        /** @var array<string, mixed>|null $monitor */
        $monitor = $e['monitor'];
        $e['monitor'] = $monitor === null ? null : self::import($monitor);
        // Positional, in declaration order (what export() returns): unpacking
        // string keys into named arguments needs PHP 8.1.
        /** @phpstan-ignore argument.type */
        return new self(...array_values($e));
    }

    private static function write(string $file, string $php): void
    {
        $dir = dirname($file);
        if (!is_dir($dir)) {
            @mkdir($dir, 0700, true);
        }
        $tmp = $file . '.' . bin2hex(random_bytes(4));
        if (@file_put_contents($tmp, $php) === false) {
            return;             // not cacheable here: checked again next time
        }
        @chmod($tmp, 0600);
        if (!@rename($tmp, $file)) {
            @unlink($tmp);
        } elseif (function_exists('opcache_invalidate')) {
            @opcache_invalidate($file, true);
        }
    }

    // ── Typed reading, shared with Budget and ChallengeSettings ────────────

    /**
     * @param array<mixed> $a
     * @return array<mixed>
     */
    public static function map(array $a, string $key, ?string $name = null): array
    {
        $v = $a[$key] ?? [];
        if (!is_array($v)) {
            throw self::wrong($name ?? $key, 'an array');
        }
        return $v;
    }

    /**
     * @param array<mixed> $a
     * @return list<string>
     */
    public static function strings(array $a, string $key, ?string $name = null): array
    {
        $v = $a[$key] ?? [];
        if (!is_array($v)) {
            throw self::wrong($name ?? $key, 'a list of strings');
        }
        $out = [];
        foreach ($v as $item) {
            if (!is_string($item)) {
                throw self::wrong($name ?? $key, 'a list of strings');
            }
            $out[] = $item;
        }
        return $out;
    }

    /**
     * @param array<mixed> $a
     * @return list<string>|null
     */
    public static function stringsOrNull(array $a, string $key, ?string $name = null): ?array
    {
        return ($a[$key] ?? null) === null ? null : self::strings($a, $key, $name);
    }

    /** @param array<mixed> $a */
    public static function int(array $a, string $key, ?string $name = null, int $default = 0): int
    {
        $v = $a[$key] ?? $default;
        if (is_int($v)) {
            return $v;
        }
        if (is_string($v) && preg_match('/^-?\d+$/', $v)) {
            return (int) $v;
        }
        throw self::wrong($name ?? $key, 'an integer');
    }

    /** @param array<mixed> $a */
    public static function intOrNull(array $a, string $key, ?string $name = null): ?int
    {
        return ($a[$key] ?? null) === null ? null : self::int($a, $key, $name);
    }

    /** @param array<mixed> $a */
    public static function bool(array $a, string $key, ?string $name = null, bool $default = false): bool
    {
        $v = $a[$key] ?? $default;
        if (!is_bool($v)) {
            throw self::wrong($name ?? $key, 'true or false');
        }
        return $v;
    }

    /** @param array<mixed> $a */
    public static function string(array $a, string $key, ?string $name = null, string $default = ''): string
    {
        $v = $a[$key] ?? $default;
        if (!is_string($v)) {
            throw self::wrong($name ?? $key, 'a string');
        }
        return $v;
    }

    public static function wrong(string $key, string $what): \InvalidArgumentException
    {
        return new \InvalidArgumentException("request-shield: '$key' must be $what");
    }
}
}
}

// src/Shield.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Challenge\Crawlers;
use CjwNetwork\RequestShield\Challenge\Gate;
use CjwNetwork\RequestShield\Challenge\Secret;
use CjwNetwork\RequestShield\Rule\BanRule;
use CjwNetwork\RequestShield\Rule\BlockedPathRule;
use CjwNetwork\RequestShield\Rule\BudgetRule;
use CjwNetwork\RequestShield\Rule\PostOriginRule;
use CjwNetwork\RequestShield\Rule\CacheableRule;
use CjwNetwork\RequestShield\Rule\ContentRule;
use CjwNetwork\RequestShield\Rule\CrawlerRule;
use CjwNetwork\RequestShield\Rule\DenyRule;
use CjwNetwork\RequestShield\Rule\FeedRule;
use CjwNetwork\RequestShield\Rule\Guarded;
use CjwNetwork\RequestShield\Rule\HostRule;
use CjwNetwork\RequestShield\Rule\LimitsRule;
use CjwNetwork\RequestShield\Rule\MethodPathRule;
use CjwNetwork\RequestShield\Rule\MethodRule;
use CjwNetwork\RequestShield\Rule\PathSanityRule;
use CjwNetwork\RequestShield\Rule\QueryRule;
use CjwNetwork\RequestShield\Rule\RestrictedPathRule;
use CjwNetwork\RequestShield\Rule\Step;
use CjwNetwork\RequestShield\Rule\Rule;
use CjwNetwork\RequestShield\Store\ApcuStore;
use CjwNetwork\RequestShield\Store\FileStore;
use CjwNetwork\RequestShield\Store\MemoryStore;
use CjwNetwork\RequestShield\Store\Store;

if (true) {
/**
 * The request shield: runs before the application and decides whether a
 * request reaches it, and whether its answer may be cached.
 *
 *   CjwNetwork\RequestShield\Shield::protect( require 'request-shield.php' );
 *
 * The checks run cheapest first -- method, sizes, path sanity, host, blocked
 * paths -- and stop at the first rejection, so a scanner's request costs a
 * few string comparisons. The cacheable definition and the budgets follow;
 * a request the budgets want challenged then goes through the gate.
 */
final class Shield
{
    /**
     * The library's version: the next release while on main ("-dev"), the tag
     * once released -- the release job refuses a tag that does not match.
     * BUILD is "source" in the repository; the single-file build (proposal
     * 0002) writes the tag and commit into it.
     */
    public const VERSION = '0.4.0';
    public const BUILD = 'v0.4.0';

    /** @var list<Rule> */
    private array $rules = [];

    /** @var list<Step>|null the rule chain, derived when asked (chain()) */
    private ?array $steps = null;

    /** @readonly */

    public Settings $settings;

    private Store $store;

    private static ?Decision $current = null;

    private static ?string $rule = null;

    /** The rule file the shield runs from (protectFile()): the dashboard touches it after a change to the lists. */
    private static ?string $ruleFile = null;

    private static ?self $active = null;

    /** The request protect() decided about. */
    private ?Request $request = null;

    /** Whether this request has passed the browser check (a pass, or a solution just now). */
    private bool $passed = false;

    /** Forms larger than this are not carried through the check (the visitor sends them again). */
    private const RESEND_MAX_BYTES = 262144;

    /**
     * How many refusals a page's own requests take for one ban: an unasked
     * refusal (unasked()) is counted on its own counter, against ten times
     * the ban's number.
     */
    public const UNASKED_REFUSALS = 10;

    /** What decide() found without the budgets: whether the answer may be cached. */
    private Decision $base;

    /** The max-age of the always-checked path this request is on (challenge … max-age), or null. */
    private ?int $alwaysAge = null;

    /** The rules with those marked "monitor", decided alongside for the log (built when needed). */
    private ?self $watcher = null;

    /**
     * @param array<mixed>|Settings $config see Config::defaults()
     * @param (callable(Request): ?bool)|null $known an adapter's URL index (see CacheableRule)
     * @throws \InvalidArgumentException for a setting of the wrong type
     */
    public function __construct($config = [], ?Store $store = null, ?callable $known = null)
    {
        $s = $this->settings = $config instanceof Settings ? $config : Settings::from($config);
        $this->store = $store ?? self::storeFor($s);
        self::$failedDir = $s->store === 'memory' ? false : $s->storeDir;     // where failed() keeps "already noted"
        $this->base = Decision::allow();
        if ($s->mode === 'off') {
            return;             // no checks at all
        }

        // Kept out (the deny list), then banned for a while: before anything else.
        // The order is Step::table()'s (ChainTest guards it): chain() derives the
        // steps from these rules when a trace or a page asks -- a request never does.
        if ($s->denyTable !== []) {
            $this->rules[] = new DenyRule($s->denyTable);
        }
        if (isset($s->feedTables['deny']) || self::hasAt($s, 'deny')) {
            $this->rules[] = new FeedRule($this);       // it calls feedHit(); no closure of it (FeedRule, JitTest)
        }
        if ($s->bans !== [] && $s->mode !== 'monitor') {
            if ($s->banKeep === 'file' && $this->store instanceof ApcuStore) {
                self::restoreBans($s, $this->store);
            }
            $this->rules[] = new BanRule($this->store, $s->exemptIps, $s->ipv6Prefix);
        }
        $this->rules[] = new MethodRule($s->methods);
        $this->rules[] = new LimitsRule($s->maxUri, $s->maxQueryParameters, $s->maxHeaderBytes);
        $this->rules[] = new PathSanityRule();
        if ($s->hosts !== []) {
            $this->rules[] = new HostRule($s->hosts);
        }
        $this->rules[] = new BlockedPathRule($s->blockedPaths, $s->blockExceptions, $s->blockedIndex);
        if ($s->methodPaths !== []) {
            $this->rules[] = new MethodPathRule($s->methodPaths);
        }
        // Forms only from the website itself (post-origin same).
        if ($s->postOrigin !== null) {
            $this->rules[] = new PostOriginRule(self::ownNames($s), $s->postOrigin['missing'], $s->postOrigin['except'],
                $s->challenge->apiPaths, $s->exemptIps);
        }
        if ($s->restricted !== []) {
            $this->rules[] = new RestrictedPathRule($s->restricted);
        }
        // Known crawlers the site refuses: only when there are such.
        foreach ($s->crawlers as $x) {
            if ($x['policy'] === 'block') {
                $this->rules[] = new CrawlerRule($this->crawlers());
                break;
            }
        }
        // Known parameters before the attack patterns: cheaper, and they say
        // which values the patterns need to look at.
        if ($s->queryParams !== [] || $s->queryStrict || $s->queryDrop !== []) {
            // set mode monitor watches: nothing is left out of a request then (query drop changes what the application gets).
            $this->rules[] = new QueryRule($s->queryIndex, $s->queryStrict, $s->challenge->widgetPath !== null ? $s->challenge->widgetPath . '/' : null,
                $s->mode === 'monitor' ? [] : $s->queryDrop);
        }
        if ($s->contentIndex !== []) {
            $this->rules[] = new ContentRule($s->contentIndex, $s->contentRules, $s->blockExceptions, $s->contentHints);
        }
        $this->rules[] = new CacheableRule($s->cacheablePaths, $s->cacheableQuery, $known, $s->cacheableIgnore);
        foreach ($s->budgets as $budget) {
            if (!$budget->onDemand) {
                $this->rules[] = $this->budgetRule($budget);
            }
        }
        if (($s->hooks['ruleProvider'] ?? []) !== []) {
            $this->provided($s);                    // the plugins' own rules, after their stage's (0031 C.3)
        }
    }

    /**
     * The rules the plugins with RuleProvider add (0031 C.3): each step after
     * the last step of its stage, never before the lists, its rule behind a
     * guard (a throw says nothing). A provider that throws, or a step at the
     * wrong place, is left out and noted once a minute. Only when a provider
     * is recorded: a shield without one never gets here.
     */
    private function provided(Settings $s): void
    {
        $steps = Step::fromRules($this->rules);
        $core = [];
        foreach ($steps as $st) {
            $core[$st->key] = true;
        }
        foreach ($s->hooks['ruleProvider'] ?? [] as $class) {
            if (!class_exists($class) || !is_subclass_of($class, RuleProvider::class)) {
                continue;
            }
            try {
                $added = (new $class($s))->rules($s, $this->store);
            } catch (\Throwable $e) {
                self::failed('rules', "$class failed to provide its rules, none added: " . $e->getMessage());
                continue;
            }
            foreach ($added as $st) {
                if ($st->rule === null || $st->key === '' || isset($core[$st->key]) || $st->stage === 'lists' || !in_array($st->stage, Step::STAGES, true)) {
                    self::failed('rules', "$class provided a step the chain cannot take (a rule, a key of its own, a stage after the lists) -- left out");
                    continue;
                }
                $core[$st->key] = true;
                $guarded = new Step($st->key, $st->stage, new Guarded($st->rule, $st->key), $st->describe);
                // After the last step of its stage; a stage with no step yet (no budgets): at the end.
                $at = count($steps);
                foreach ($steps as $i => $existing) {
                    if ($existing->stage === $st->stage) {
                        $at = $i + 1;
                    }
                }
                array_splice($steps, $at, 0, [$guarded]);
            }
        }
        // The table must have every core rule (ChainTest guards it); should it not,
        // keep the constructor's list and append the provided rules -- never drop a check.
        $derived = [];
        $own = [];
        foreach ($steps as $st) {
            if ($st->rule !== null) {
                $derived[] = $st->rule;
                if ($st->rule instanceof Guarded) {
                    $own[] = $st->rule;
                }
            }
        }
        if (array_values(array_filter($derived, static fn (Rule $r): bool => !$r instanceof Guarded)) !== $this->rules) {
            self::failed('rules', 'the chain table lags behind the shield: the plugins\' rules run after the core\'s, in the order given');
            $this->steps = null;
            foreach ($own as $rule) {
                $this->rules[] = $rule;
            }
            return;
        }
        $this->steps = $steps;
        $this->rules = $derived;
    }

    /**
     * The first plugin with the Handler capability that answers the request
     * (0031 C.4), or null: on to the application. A handler that throws is
     * noted once a minute and skipped -- the site stays up.
     */
    public function handle(Request $request, Decision $decision): ?Response
    {
        foreach ($this->plugins() as $plugin) {
            if (!$plugin instanceof Handler) {
                continue;
            }
            try {
                $response = $plugin->handle($request, $decision);
            } catch (\Throwable $e) {
                self::failed('handler', get_class($plugin) . ' failed to answer, the application runs: ' . $e->getMessage());
                continue;
            }
            if ($response !== null) {
                return $response;
            }
        }
        return null;
    }

    /**
     * The first plugin with the MethodHandler capability that answers a
     * request with a method the site does not take (0031 G.4), or null: the
     * rules decide. One that throws is noted once a minute and skipped.
     */
    public function handleMethod(Request $request): ?Response
    {
        foreach ($this->plugins() as $plugin) {
            if (!$plugin instanceof MethodHandler) {
                continue;
            }
            try {
                $response = $plugin->handleMethod($request);
            } catch (\Throwable $e) {
                self::failed('handler', get_class($plugin) . ' failed to answer ' . $request->method . ', the rules decide: ' . $e->getMessage());
                continue;
            }
            if ($response !== null) {
                return $response;
            }
        }
        return null;
    }

    /**
     * The application says who the visitor is (0031 G.4, proposal 0039):
     * Shield::active()?->cacheContext($roleKey) from an adapter while the
     * application runs. The plugins with the ContextHandler capability (the
     * HTTP cache) remember it for the session the request carries and, with
     * $shared, may keep this answer for everyone with the role. Nothing
     * happens without such a plugin, or before protect() ran; one that throws
     * is noted once a minute -- the application goes on.
     */
    public function cacheContext(string $context, bool $shared = false): void
    {
        $this->toContext(static function (ContextHandler $p, Request $r) use ($context, $shared): void {
            $p->cacheContext($r, $context, $shared);
        });
    }

    /** The visitor signed out: their session's role is forgotten (the logout hook of an adapter). */
    public function forgetContext(): void
    {
        $this->toContext(static function (ContextHandler $p, Request $r): void {
            $p->forgetContext($r);
        });
    }

    /**
     * The query as the caches and the application get it (0048): the
     * parameters cache-ignore names leave $_GET, $_REQUEST, QUERY_STRING and
     * REQUEST_URI (a copy as JSON in REQUEST_SHIELD_IGNORED: name => value);
     * with cache-unknown-query hit-only and a parameter cache-query does not
     * name, REQUEST_SHIELD_CACHE_LOOKUP is the address (path and the
     * cache-query parameters, sorted) a cache may answer from. Returns the
     * request as it is now.
     */
    private static function queryForCaches(Settings $s, Request $request, Decision $decision): Request
    {
        $kept = [];
        $gone = [];
        $dropped = $request->dropped();
        // What leaves, by the name PHP gives it in $_GET: a name cache-query names stays in the key, whatever a
        // glob of cache-ignore matches (p* and page); one query drop left out goes whatever cache-query says
        // (page=2' is no page).
        $goes = [];
        foreach ($request->queryPairs() as [$name, , $raw]) {
            if (isset($dropped[$name]) || (!in_array($name, (array) $s->cacheableQuery, true) && \CjwNetwork\RequestShield\Rule\CacheableRule::ignored($name, $s->cacheableIgnore))) {
                $goes[Request::phpKey($raw)] = true;
            }
        }
        // ... and every pair PHP puts under that key goes with it (" page", "items[per[page" are $_GET['page'],
        // $_GET['items_per_page']): what the application reads, the query and the cache key stay one and the same.
        foreach ($request->queryPairs() as [$name, $value, $raw]) {
            $key = Request::phpKey($raw);
            if (isset($goes[$key])) {
                $gone[$key] = $value;
            } else {
                $kept[] = [$name, $raw];
            }
        }
        $uri = is_string($_SERVER['REQUEST_URI'] ?? null) ? $_SERVER['REQUEST_URI'] : $request->rawUri;
        $path = (string) strtok($uri, '?');
        if ($gone !== []) {
            $query = implode('&', array_column($kept, 1));
            $_SERVER['QUERY_STRING'] = $query;
            $_SERVER['REQUEST_URI'] = $path . ($query === '' ? '' : '?' . $query);
            $_SERVER['REQUEST_SHIELD_IGNORED'] = (string) json_encode($gone, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
            // $_GET is what PHP's own parser makes of the query that is left -- not the old one with names
            // taken out: whatever PHP does with a name (folds it, drops it, lets a too deep one remove another),
            // the application reads exactly the query the cache key is made of.
            parse_str($query, $get);
            $_GET = $get;
            // $_REQUEST as PHP makes it: the sources request_order names, the later winning -- arrays merged.
            $merged = [];
            foreach (str_split(strtoupper((string) (ini_get('request_order') ?: ini_get('variables_order')))) as $source) {
                $merged = self::mergeInput($merged, $source === 'G' ? $_GET : ($source === 'P' ? $_POST : ($source === 'C' ? $_COOKIE : [])));
            }
            $_REQUEST = $merged;
            /** @var array<string, mixed> $server */
            $server = $_SERVER;
            $request = Request::fromServer($server, $s->trustedProxies);
        }
        if ($s->cacheableUnknown === 'hit-only' && $s->cacheableQuery !== null && !$decision->cacheable() && $decision->reason === 'query parameter') {
            $key = array_values(array_filter($kept, static fn (array $p): bool => in_array($p[0], (array) $s->cacheableQuery, true)));
            $pairs = array_column($key, 1);
            sort($pairs, SORT_STRING);
            $_SERVER['REQUEST_SHIELD_CACHE_LOOKUP'] = $path . ($pairs === [] ? '' : '?' . implode('&', $pairs));
        }
        return $request;
    }

    /**
     * Two input arrays as PHP merges them into $_REQUEST: the later wins, an
     * array under the same name in both is merged the same way (?a[x]=1 and a
     * cookie a[y]=2 are a = [x => 1, y => 2]).
     *
     * @param array<mixed> $into
     * @param array<mixed> $from
     * @return array<mixed>
     */
    private static function mergeInput(array $into, array $from): array
    {
        foreach ($from as $k => $v) {
            $into[$k] = is_array($v) && is_array($into[$k] ?? null) ? self::mergeInput($into[$k], $v) : $v;
        }
        return $into;
    }

    /**
     * The application changed content (0031 G.5, proposal 0039):
     * Shield::active()?->purge(['content-12', 'list']) from an adapter when
     * a page is published -- the plugins with the Purger capability (the
     * HTTP cache) make the answers with these tags out of date ("*":
     * everything), with no PURGE request. Nothing happens without such a
     * plugin; one that throws is noted once a minute -- the application goes
     * on.
     *
     * @param list<string> $tags
     */
    public function purge(array $tags): void
    {
        if ($tags === [] || ($this->settings->hooks['purger'] ?? []) === []) {
            return;
        }
        foreach ($this->plugins() as $plugin) {
            if (!$plugin instanceof Purger) {
                continue;
            }
            try {
                $plugin->purge($tags);
            } catch (\Throwable $e) {
                self::failed('handler', get_class($plugin) . ' failed to purge, the application goes on: ' . $e->getMessage());
            }
        }
    }

    /** @param \Closure(ContextHandler, Request): void $call */
    private function toContext(\Closure $call): void
    {
        $request = $this->request;
        if ($request === null || ($this->settings->hooks['contextHandler'] ?? []) === []) {
            return;
        }
        foreach ($this->plugins() as $plugin) {
            if (!$plugin instanceof ContextHandler) {
                continue;
            }
            try {
                $call($plugin, $request);
            } catch (\Throwable $e) {
                self::failed('handler', get_class($plugin) . ' failed to take the visitor\'s role, the application goes on: ' . $e->getMessage());
            }
        }
    }

    /**
     * The rule chain (0031 C.1): every step in the order the shield checks,
     * the stages' steps without a rule where their settings are not in use.
     * Derived from the rules when first asked (a trace, the rules page) --
     * a request pays nothing for it.
     *
     * @return list<Step>
     */
    public function chain(): array
    {
        return $this->steps ??= $this->settings->mode === 'off' ? [] : Step::fromRules($this->rules);
    }

    /**
     * The rules the request path runs, in order (the active steps of chain()).
     *
     * @return list<Rule>
     */
    public function rules(): array
    {
        return $this->rules;
    }

    /**
     * protect() with the settings of a file, checked only when it changed
     * (see Settings::load()): the way to run the shield on every request.
     * A ".rules" file is a rule file; $sources are further rule files or
     * globs read before it -- an adapter's, for its extensions.
     *
     * @param (callable(Request): ?bool)|null $known
     * @param list<string> $sources
     */
    public static function protectFile(string $file, ?callable $known = null, ?string $cacheDir = null, array $sources = []): Decision
    {
        // Where "already noted" is kept before any settings exist: with the compiled ones.
        self::$failedDir ??= $cacheDir ?? Settings::cacheDirFor($file);
        self::$ruleFile = $file;
        try {
            // With site blocks (rules per website): the settings of this request's website.
            $settings = Settings::loadFor($file, $_SERVER, $cacheDir, $sources);
        } catch (\Throwable $e) {
            return self::failedOpen($e, null);      // the settings cannot be had: the site stays up (ADR 0007)
        }
        return self::protect($settings, $known);
    }

    /**
     * The shield failed: the request goes on to the application, never
     * cached, and the error log gets one line a minute. What the application
     * sees is the same as for any uncached pass.
     */
    private static function failedOpen(\Throwable $e, ?Settings $s): Decision
    {
        $d = Decision::allowUncached('shield error');
        self::$current = $d;
        self::$rule = null;
        $_SERVER['REQUEST_SHIELD'] = $d->action;
        self::failed('shield', 'the shield failed and let the request through: ' . get_class($e) . ': ' . $e->getMessage()
            . ' in ' . $e->getFile() . ':' . $e->getLine());
        if ($s !== null && $s->debugHeader && !headers_sent()) {
            header('X-RS: ' . $d->action . ' ' . $d->reason);
        }
        return $d;
    }

    /**
     * Decides about the request in $_SERVER, answers it itself when the
     * application must not run (and ends the request), and returns the
     * decision otherwise. Also Shield::current() and
     * $_SERVER['REQUEST_SHIELD'] ("allow" or "allow-uncached") afterwards.
     *
     * An array is checked on every call; protectFile() checks it once.
     *
     * @param array<mixed>|Settings $config
     * @param (callable(Request): ?bool)|null $known
     */
    public static function protect($config = [], ?callable $known = null): Decision
    {
        // Fail safe (ADR 0007): whatever breaks inside the shield, the request
        // reaches the application -- uncached -- and PHP's error log hears it
        // once a minute. exit() is not a Throwable: the shield's own answers
        // (a refusal, the check page) are not affected.
        try {
            return self::run($config, $known);
        } catch (\Throwable $e) {
            return self::failedOpen($e, $config instanceof Settings ? $config : null);
        }
    }

    /**
     * What protect() does; apart.
     *
     * @param array<mixed>|Settings $config
     * @param (callable(Request): ?bool)|null $known
     */
    private static function run($config, ?callable $known): Decision
    {
        $shield = new self($config, null, $known);
        $s = $shield->settings;
        /** @var array<string, mixed> $server */
        $server = $_SERVER;
        $request = Request::fromServer($server, $s->trustedProxies);
        $shield->request = $request;
        self::$active = $shield;
        if ($s->mode === 'off') {
            // Switched off: nothing checked, counted or logged; the include stays.
            self::$current = Decision::allow();
            self::$rule = null;
            $_SERVER['REQUEST_SHIELD'] = Decision::ALLOW;
            return self::$current;
        }
        // A method the site does not take, answered by a plugin before the rules (MethodHandler,
        // 0031 G.4): an HTTP cache's PURGE from its purgers -- for a GET, one array access.
        if (($s->hooks['methodHandler'] ?? []) !== [] && !in_array($request->method, $s->methods, true)) {
            $response = $shield->handleMethod($request);
            if ($response !== null) {
                $response->send();
                exit;
            }
        }
        $now = microtime(true);
        $decided = $shield->decide($request, $now);
        // The endpoint of the check inside the form: answered here, before the
        // application -- after the checks, so budgets count it and a refused
        // client stays refused; a challenged one gets its task (that is what
        // it asks for).
        $w = $s->challenge->widgetPath;
        if ($w !== null && strncmp($request->path, $w . '/', strlen($w) + 1) === 0
            && ($decided->passes() || $decided->action === Decision::CHALLENGE)) {
            $shield->serveWidget((string) substr($request->path, strlen($w) + 1), $request, $now);
            exit;
        }
        $settled = $shield->settle($decided, $request, $now);
        $decision = $settled['decision'];
        $shield->passed = $settled['passed'];
        if (!$decision->passes() && ($s->bans !== [] || ($s->monitor !== null && $s->monitor->bans !== []))) {
            $shield->signals($decision, $request, $now);         // what may lead to a ban: only when refused, slowed or checked
        }
        // Which rule: looked up only for a request that was stopped or flagged
        // (or when every request is logged) -- a passing one costs nothing.
        $rule = null;
        $watched = null;
        $would = null;
        $reference = null;
        if ($s->mode === 'monitor' && !$decision->passes()) {
            $would = $decision;
            // Monitor: decided and counted, logged as it would be -- and let through,
            // never cached (whatever it is, it is not what a cache should keep).
            $watched = $shield->watched($decision, $request, $now, $shield);
            $decision = Decision::allowUncached('monitor');
            $settled = ['decision' => $decision, 'cookies' => $settled['cookies'], 'page' => null, 'json' => null, 'passed' => false];
        } elseif ($decision->action !== Decision::ALLOW || $s->logLevel === 'all') {
            $rule = $shield->explain($decision, $request);
            // A refusal the shield answers with its page (not the check page): a reference
            // on the page and in the log line (0030) -- made only then.
            $reference = !$decision->passes() && $settled['page'] === null && ($settled['json'] ?? null) === null ? ErrorPage::reference() : null;
            Log::note($s, $request, $decision, $rule, $now, false, $reference);
        }
        if ($s->monitor !== null && $decision->passes() && $watched === null) {
            // Rules marked "monitor": what they would decide, for the log.
            $watched = $shield->watch($request, $now);
        }
        self::$current = $decision;
        self::$rule = $rule;
        if ($s->learn !== null) {
            try {
                Learn::note($s, $request, $decision, $now);    // a learning run (0016): only its own requests, their shape
            } catch (\Throwable $e) {
                // A recording's trouble never turns a decision around: noted (once a minute), the request goes on.
                Failure::note('learn', $e->getMessage(), $s->storeDir);
            }
        }
        if ($shield->plugins() !== []) {
            // The plugins (the statistics, …): told now, and -- for a request that
            // goes on to the site -- again when it has ended, with the site's status.
            $shield->record($request, $decision, $rule, $now, $would, $decision->passes());
        }
        if (!headers_sent()) {
            foreach ($settled['cookies'] as $cookie) {
                header('Set-Cookie: ' . $cookie, false);
            }
        }

        if (!$request->viaTrustedProxy && $s->stripUntrustedForwarded) {
            foreach (array_keys($_SERVER) as $name) {
                if (is_string($name) && strncmp($name, 'HTTP_X_FORWARDED_', 17) === 0) {
                    unset($_SERVER[$name]);
                }
            }
            unset($_SERVER['HTTP_FORWARDED']);
        }

        if (!$decision->passes() && ($settled['json'] ?? null) !== null) {
            echo (new Responder())->api($decision, $settled['json'], $s->debugHeader, $rule);
            exit;
        }
        if (!$decision->passes()) {
            $c = $s->challenge;
            (new Responder())->send($decision, $request, $s->debugHeader, $settled['page'], $rule,
                Texts::all(Texts::language($c->language, $request->header('accept-language'), $c->texts), $c->texts), $c->home, PageHook::asker($s),
                $c->logo, $settled['page'] === null && $shield->isApi($request), $reference, $s->errorPages);
            exit;
        }
        // The dashboard's own pages (0031 B.6): a route is answered here, before the
        // application -- for the many requests that are none, one stripos.
        $route = Dashboard::routeFor($s, $request);
        if ($route !== null) {
            /** @var array<mixed> $get */
            $get = $_GET;
            /** @var array<mixed> $post */
            $post = $_POST;
            Dashboard::serve($s, $request, $route, $get, $post, self::$ruleFile)->send();
            exit;
        }
        // The query for the caches (0048): decided, logged and counted on the whole query above;
        // the parameters no cache key holds leave it now, before a cache and the application run.
        if (($s->cacheableIgnore !== [] || $s->cacheableUnknown !== 'uncached' || ($s->queryDrop !== [] && $request->dropped() !== [])) && ($request->method === 'GET' || $request->method === 'HEAD')) {
            $request = self::queryForCaches($s, $request, $decision);
        }
        // A plugin that answers passing requests itself (Handler, 0031 C.4): an HTTP
        // cache hit, a page of its own -- one array access when none has it.
        if (($s->hooks['handler'] ?? []) !== []) {
            $response = $shield->handle($request, $decision);
            if ($response !== null) {
                $_SERVER['REQUEST_SHIELD'] = $decision->action;
                if ($s->debugHeader && !headers_sent()) {
                    header(self::serverTiming($now));       // the shield and the plugin that answered (a cache hit)
                }
                $response->send();
                exit;
            }
        }
        if ($s->appChallenge && ($request->method === 'GET' || $request->method === 'HEAD')) {
            $shield->watchForChallengeHeader();
        }
        $_SERVER['REQUEST_SHIELD'] = $decision->action;
        if ($rule !== null) {
            $_SERVER['REQUEST_SHIELD_RULE'] = $rule;
        }
        if ($s->debugHeader && !headers_sent()) {
            header(self::serverTiming($now));
            header('X-RS: ' . ($watched !== null && $s->mode === 'monitor' ? 'monitor ' . $watched
                : $decision->action . ($decision->reason !== '' ? ' ' . $decision->reason : '') . ($rule !== null ? '; rule=' . $rule : '')));
            if ($watched !== null && $s->mode !== 'monitor') {
                header('X-RS-Monitor: ' . $watched);
            }
        }
        return $decision;
    }

    /**
     * The shield's own time for the browser's network tab (0046 step 3), with
     * debug-header on only: from its decision's start to here, in
     * milliseconds -- "Server-Timing: shield;dur=0.042;desc=request-shield".
     * The site's time is not over when the headers go out; for every visitor
     * it would tell that a shield is in front and cost bytes on every answer.
     */
    private static function serverTiming(float $start): string
    {
        return 'Server-Timing: shield;dur=' . number_format(max(0.0, microtime(true) - $start) * 1000, 3, '.', '') . ';desc=request-shield';
    }

    /**
     * What the rules marked "monitor" would decide about a request the
     * enforced rules let through: logged, never acted on. Returns it in
     * words ("reject blocked path; rule=SITE-OLD") or null when they would
     * let it through too.
     */
    private function watch(Request $request, float $now): ?string
    {
        $w = $this->watcher($request);
        if ($w === null) {
            return null;
        }
        $d = $w->decide($request, $now);
        if ($d->passes()) {
            return null;
        }
        // A check the visitor has passed already (a pass cookie) is no refusal.
        $d = $w->settle($d, $request, $now)['decision'];
        return $d->passes() ? null : $this->watched($d, $request, $now, $w);
    }

    /**
     * Tells the plugins what was decided (the statistics: counted for the
     * dashboard, a crawler's log -- see StatsPlugin). protect() calls it; code
     * that runs decide() and settle() itself calls it after them. Without a
     * plugin it costs nothing.
     *
     * @param Decision|null $would what monitor mode would have done
     * @param bool $atEnd the request goes on to the site: the plugins hear
     *   again when it ends, with the status the site answered
     */
    public function record(Request $request, Decision $decision, ?string $rule, float $now, ?Decision $would = null, bool $atEnd = false): void
    {
        $plugins = $this->plugins();
        if ($plugins === []) {
            return;
        }
        $seen = new Seen($request, $this);
        foreach ($plugins as $plugin) {
            try {
                $plugin->decided($request, $decision, $rule, $seen, $now, $atEnd, $would);
            } catch (\Throwable $e) {
                self::pluginFailed($plugin, $e);
            }
        }
        if (!$atEnd) {
            return;
        }
        // The site answers: when it is done, the plugins hear its status.
        register_shutdown_function(static function () use ($plugins, $request, $seen, $now): void {
            $status = http_response_code();
            $headers = headers_list();
            foreach ($plugins as $plugin) {
                try {
                    $plugin->ended($request, is_int($status) && $status > 0 ? $status : 0, $headers, $seen, $now);
                } catch (\Throwable $e) {
                    self::pluginFailed($plugin, $e);
                }
            }
        });
    }

    /**
     * The website's own names, for post-origin: the host rule's, and in a site
     * block that block's names ("default" is none); [] when there are none --
     * then the name the request was sent to.
     *
     * @return list<string>
     */
    public static function ownNames(Settings $s): array
    {
        $names = $s->hosts;
        if ($s->site !== null) {
            foreach ($s->sites as $name => $block) {
                if ($block === $s->site && $name !== 'default') {
                    $names[] = $name;
                }
            }
        }
        return array_values(array_unique(array_map('strtolower', $names)));
    }

    /**
     * The signals a decision gives for the bans: past a limit (a pause, a spent
     * check), a refusal for what only attackers ask for, a check page shown.
     * protect() gives them after settling a request that did not pass;
     * request-shield test does the same, so an example can reach a ban.
     */
    public function signals(Decision $d, Request $request, float $now): void
    {
        if ($d->action === Decision::THROTTLE && $d->reason !== 'banned') {
            $this->signal('limits', $request, $now);
        } elseif ($d->action === Decision::CHALLENGE) {
            $this->signal('checks', $request, $now);
            if ($d->spent) {
                $this->signal('limits', $request, $now);
            }
        } elseif ($d->action === Decision::REJECT && ($d->reason === 'blocked path' || $d->reason === 'attack')
            && !self::wellKnown($d, $request)) {
            $this->signal('refusals', $request, $now, self::unasked($request));
        }
    }

    /**
     * A refusal the browser says its visitor did not ask for: a page asked
     * for it by itself -- an image, a script, a fetch() (Sec-Fetch-Mode other
     * than "navigate") -- or another website sent the visitor (Sec-Fetch-Site:
     * cross-site). Refused all the same, and counted, but on a counter of its
     * own against UNASKED_REFUSALS times the ban's number: a foreign page with
     * twenty <img src="https://this.site/.env">, or an old link elsewhere to
     * an address refused today, bans nobody; a scanner that forges these
     * headers to dodge the ban is banned all the same, only later.
     */
    private static function unasked(Request $request): bool
    {
        $mode = $request->header('Sec-Fetch-Mode');
        if ($mode !== null && strcasecmp(trim($mode), 'navigate') !== 0) {
            return true;
        }
        $site = $request->header('Sec-Fetch-Site');
        return $site !== null && strcasecmp(trim($site), 'cross-site') === 0;
    }

    /**
     * A blocked path below /.well-known/ (RFC 8615): browsers, phones,
     * prefetch proxies and password managers ask there unprompted
     * (traffic-advice, apple-app-site-association, assetlinks.json,
     * passkey-endpoints ...), one proxy address for many people and many
     * websites. Refused, never counted. Only a blocked path: an attack
     * pattern sent there counts like anywhere else. (A path with "/../"
     * never gets this far: PathSanityRule refuses it.)
     */
    private static function wellKnown(Decision $d, Request $request): bool
    {
        return $d->reason === 'blocked path' && strncasecmp($request->matchPath(), '/.well-known/', 13) === 0;
    }

    /**
     * One signal: counted for every ban that names it; past its number, the
     * ban (or, watched, a line in the log). $unasked: a refusal a page asked
     * for by itself (unasked()), on its own counter.
     */
    private function signal(string $name, Request $request, float $now, bool $unasked = false): void
    {
        $s = $this->settings;
        $enforced = $s->mode === 'monitor' ? [] : $s->bans;
        $rules = array_column($enforced, 'rule');
        // Watched: every ban in monitor mode, and those marked "monitor ban".
        $watched = $s->mode === 'monitor' ? $s->bans : [];
        foreach ($s->monitor !== null ? $s->monitor->bans : [] as $b) {
            if (!in_array($b['rule'], $rules, true) && !in_array($b, $watched, true)) {
                $watched[] = $b;
            }
        }
        foreach ([[$enforced, false], [$watched, true]] as [$bans, $watch]) {
            foreach ($bans as $b) {
                if ($b['signal'] === $name) {
                    $this->countBan($b, $request, $now, $watch, $unasked);
                }
            }
        }
    }

    /**
     * A signal for one ban: past its number in its window, the client is
     * banned -- longer each time within a day (ban-growth), at most ban-max.
     * Never an address let in (exempt), a trusted proxy or a verified crawler.
     * $unasked: on a counter of its own, past UNASKED_REFUSALS times the number.
     *
     * @param array{after: int, signal: string, in: int, for: int, rule: string} $b
     */
    private function countBan(array $b, Request $request, float $now, bool $watch, bool $unasked = false): void
    {
        $s = $this->settings;
        $ip = $request->clientIp;
        if (IpAddress::inRanges($ip, $s->exemptIps) || IpAddress::inRanges($ip, $s->trustedProxies)) {
            return;
        }
        $bucket = IpAddress::bucket($ip, $s->ipv6Prefix);
        // On a public blocklist named "ban-signal <n>": one signal counts n times.
        $weight = 1;
        if ($s->feedWeights !== [] && ($feed = $this->feedHit($request, 'signal')) !== null) {
            $weight = $s->feedWeights[$feed] ?? 1;
        }
        $count = 0.0;
        for ($i = 0; $i < $weight; $i++) {
            $count = $this->store->hit(($watch ? 'monitor:' : '') . 'ban:' . $b['rule'] . ':' . ($unasked ? 'unasked:' : '') . $bucket, $b['in'], $now);
        }
        if ($count < $b['after'] * ($unasked ? self::UNASKED_REFUSALS : 1)) {
            return;
        }
        $id = $s->crawlers === [] ? null : $this->crawlers()->claims((string) $request->header('user-agent'));
        if ($id !== null && $this->crawlers()->verified($ip, $id)) {
            return;                                         // a verified crawler gets the pause it understands, never a ban
        }
        if ($watch) {
            Log::note($s, $request, Decision::throttle('banned', $b['for']), $b['rule'], $now, true);
            return;
        }
        $offences = (int) round($this->store->hit('bans:' . $bucket, 86400, $now));
        $duration = (int) min($s->banMax, $b['for'] * $s->banGrowth ** max(0, min($offences - 1, 30)));
        $until = (int) $now + $duration;
        if ($this->store->marked('ban:' . $bucket, $now) >= $until) {
            return;                                         // banned longer already
        }
        $this->store->mark('ban:' . $bucket, $until, $now);
        if ($s->banKeep === 'file' && !$this->store instanceof FileStore) {
            (new FileStore($s->storeDir))->mark('ban:' . $bucket, $until, $now);     // survives a restart of APCu
        }
        Log::note($s, $request, Decision::throttle('banned', $duration), $b['rule'], $now);
    }

    /**
     * set ban-keep file: after a restart of APCu (empty), the first request
     * copies the bans still running from their files back -- once: apcu_add()
     * lets one process do it. Every other request: that one call.
     */
    private static function restoreBans(Settings $s, Store $store): void
    {
        if (!Capability::apcu() || !apcu_add('rshield-bans-restored:' . hash('crc32b', $s->storeDir), 1)) {
            return;
        }
        $now = microtime(true);
        foreach ((new FileStore($s->storeDir))->marks('ban:', $now) as $key => $until) {
            if ($store->marked($key, $now) < $until) {
                $store->mark($key, $until, $now);
            }
        }
    }

    /**
     * Lifts a ban at once, wherever it is kept: the store and, with
     * ban-keep file, its file. False when the address is not banned.
     */
    public static function liftBan(Settings $s, Store $store, string $bucket, ?float $now = null): bool
    {
        $now ??= microtime(true);
        $key = 'ban:' . $bucket;
        $was = $store->marked($key, $now) > 0;
        $store->mark($key, 0, $now);
        if ($s->banKeep === 'file' && !$store instanceof FileStore) {
            $file = new FileStore($s->storeDir);
            $was = $was || $file->marked($key, $now) > 0;
            $file->mark($key, 0, $now);
        }
        return $was;
    }

    /** @var list<Plugin>|null */
    private ?array $plugins = null;

    /**
     * The plugins of these settings, made once: those the rules name ("plugin
     * …") and those the extensions added when the rules were compiled (the
     * statistics with "set stats" or "set crawler-log": StatsExtension::plugins()).
     * A class that is missing or no Plugin is left out (and logged).
     *
     * @return list<Plugin>
     */
    public function plugins(): array
    {
        if ($this->plugins !== null) {
            return $this->plugins;
        }
        $s = $this->settings;
        $made = [];
        foreach ($s->plugins as $class) {
            try {
                if (!class_exists($class) && isset($s->pluginFiles[$class]) && is_file($s->pluginFiles[$class])) {
                    require_once $s->pluginFiles[$class];   // plugin … from <file> (0031 D.2): only here, only with plugins
                }
                $plugin = class_exists($class) && is_subclass_of($class, Plugin::class) ? new $class($s) : null;
            } catch (\Throwable $e) {
                $plugin = null;
            }
            if ($plugin instanceof Plugin) {
                $made[] = $plugin;
            } else {
                self::pluginFailed($class, null);
            }
        }
        return $this->plugins = $made;
    }

    /**
     * Where failed() keeps "already noted" across requests and workers: the
     * site's store directory; null before any settings were made (the
     * temp dir then); false with the memory store (nothing persists: in
     * this process only -- the tests' case).
     * @var string|false|null
     */
    private static $failedDir = null;

    /** Something failed and the request went on: noted once a minute per cause (Failure). */
    public static function failed(string $what, string $message): void
    {
        Failure::note($what, $message, self::$failedDir);
    }

    /**
     * A plugin that failed.
     * @param \CjwNetwork\RequestShield\Plugin|string $plugin
     */
    private static function pluginFailed($plugin, ?\Throwable $e): void
    {
        $name = is_string($plugin) ? $plugin : get_class($plugin);
        self::failed($name, 'plugin ' . (is_string($plugin) ? $plugin . ' is missing or no ' . Plugin::class : get_class($plugin) . ' failed: ' . ($e !== null ? $e->getMessage() : '?')));
    }

    /** The shield of the rules marked "monitor" (null: there are none), built once. */
    private function watcher(Request $request): ?self
    {
        $m = $this->settings->monitor;
        if ($m === null) {
            return null;
        }
        if ($this->watcher === null) {
            // Their own budgets are counted; those the enforced rules have, only looked at.
            $own = array_fill_keys(array_keys(array_diff_key($m->budgets, $this->settings->budgets)), true);
            $this->watcher = new self($m, new \CjwNetwork\RequestShield\Store\MonitorStore($this->store, $own));
            $this->watcher->request = $request;
        }
        return $this->watcher;
    }

    /** Logs what would have been decided ("monitor-reject …") and returns it in words for the header. */
    private function watched(Decision $d, Request $request, float $now, self $by): string
    {
        $s = $this->settings;
        $rule = $by->explain($d, $request);
        Log::note($s, $request, $d, $rule, $now, true);
        return $d->action . ($d->reason !== '' ? ' ' . $d->reason : '') . ($rule !== null ? '; rule=' . $rule : '');
    }

    /** The decision protect() made for this request, if it ran. */
    public static function current(): ?Decision
    {
        return self::$current;
    }

    /**
     * The shield protect() ran with, to count on-demand budgets against the
     * same settings and request: Shield::active()?->consume('searches').
     */
    public static function active(): ?self
    {
        return self::$active;
    }

    /** The rule behind current(), when it was not a plain "allow" (see explain()). */
    public static function currentRule(): ?string
    {
        return self::$rule;
    }

    /**
     * The rule behind a decision, as the log and the pages name it: asked from
     * the chain's rules (Rule::explain(), 0031 C.2); what no rule produces --
     * the always-checked paths, a "check" feed, the application's own check --
     * is named here.
     */
    public function explain(Decision $d, Request $request): ?string
    {
        $s = $this->settings;
        switch ($d->reason) {
            case 'app':
                return 'application';
            case 'always':
                foreach ($s->challenge->alwaysPaths as $i => $p) {
                    if (@preg_match($p, $request->path) === 1 && $s->challenge->alwaysFor($p, $request->method)) {
                        return $s->ruleName('challenge.alwaysPaths', $s->challenge->alwaysPaths[$i], "challenge.alwaysPaths[$i]");
                    }
                }
                return null;
        }
        foreach ($this->rules as $rule) {
            $name = $rule->explain($d, $request, $s);
            if ($name !== null) {
                return $name;
            }
        }
        // A "check" feed is decide()'s own step after the chain (the deny feeds are FeedRule's).
        if ($d->reason === 'feed') {
            return $this->feedHit($request, $d->action === Decision::CHALLENGE ? 'check' : 'deny');
        }
        // A budget the site counts itself (on-demand, consume()): no step of the chain.
        if (isset($s->budgets[$d->reason])) {
            return $s->ruleName('budgets', $d->reason, "budgets.$d->reason");
        }
        return null;
    }

    public function decide(Request $request, float $now): Decision
    {
        $base = Decision::allow();
        $budget = null;
        $this->alwaysAge = null;
        // The dashboard's own pages, opened from an address their restrict rule
        // allows: not counted against the pace (the live view asks every few seconds).
        $ownPage = $this->settings->restricted !== [] && $this->dashboardOnly($request);
        foreach ($this->rules as $rule) {
            if ($ownPage && $rule instanceof BudgetRule) {
                continue;
            }
            // strict: a request a cache must not keep counts twice -- the pattern
            // of floods that bust the cache with made-up addresses.
            $wants = $rule instanceof BudgetRule
                ? $rule->check($request, $now, $base->action === Decision::ALLOW_UNCACHED ? $this->settings->uncachedWeight : 1)
                : $rule->check($request, $now);
            if ($wants === null) {
                continue;
            }
            if ($wants->action === Decision::REJECT || $rule instanceof BanRule) {
                return $this->base = $wants;            // a banned client: one lookup, and the answer
            }
            if ($rule instanceof BudgetRule || ($rule instanceof PostOriginRule && $wants->action === Decision::CHALLENGE)) {
                // A check -- a budget's, or a form without Origin and Referer -- goes through the gate.
                $budget = $budget === null ? $wants : $budget->stricter($wants);
            } else {
                $base = $base->stricter($wants);
            }
        }
        $this->base = $base;
        // Paths that are always checked (a login page): challenged whatever the
        // budgets say, every method -- a bot must not POST to a login without
        // having loaded it -- or only the methods the rule names (challenge POST
        // **: every form sent, not the pages that show them). The gate lets a
        // client with a pass cookie through; a form without one gets the page,
        // which sends it again once the check is done.
        $always = $this->settings->challenge->alwaysPaths;
        // An address let in (exempt, the allow list) never meets the check.
        if ($always !== [] && !($this->settings->exemptIps !== [] && IpAddress::inRanges($request->clientIp, $this->settings->exemptIps))) {
            foreach ($always as $pattern) {
                if (@preg_match($pattern, $request->path) === 1 && $this->settings->challenge->alwaysFor($pattern, $request->method)) {
                    $budget = $budget === null ? Decision::challenge('always') : $budget->stricter(Decision::challenge('always'));
                    $this->alwaysAge = $this->settings->challenge->alwaysMaxAge[$pattern] ?? null;
                    break;
                }
            }
        }
        // On a public blocklist named "check": the browser check, as on an
        // always-checked page -- a pass lets the visitor through.
        if ((isset($this->settings->feedTables['check']) || self::hasAt($this->settings, 'check')) && $this->feedHit($request, 'check') !== null) {
            $budget = $budget === null ? Decision::challenge('feed') : $budget->stricter(Decision::challenge('feed'));
        }
        return $budget === null ? $base : $base->stricter($budget);
    }

    /**
     * Whether a request is for one of the dashboard's pages (the compiled
     * routes: /rs/waf/live, /rs/stats/visitors … -- also below a prefix,
     * /demo/rs/waf/live) from an address the restrict rule over that path
     * allows. Without such a rule the pages count like any other: an open
     * dashboard keeps its flood guard. Only called with restrict rules in
     * force; the routes are a handful of string comparisons.
     */
    private function dashboardOnly(Request $request): bool
    {
        $s = $this->settings;
        $path = $request->matchPath();
        if (Routes::match($s, $path) === null) {
            return false;                                   // the common case: a search or two
        }
        foreach ($s->restricted as $r) {
            foreach ($r['paths'] as $pattern) {
                if (@preg_match($pattern, $path) === 1) {
                    return IpAddress::inRanges($request->clientIp, $r['ips']);
                }
            }
        }
        return false;
    }

    /** @var array<string, ?string> client|action => the rule found, this request */
    private array $feedHits = [];

    /**
     * The rule of the public blocklist that holds this client for an action
     * (deny, check, signal) -- null when none does, or when the client is let
     * in, a trusted proxy, or a crawler that proved who it is.
     */
    public function feedHit(Request $request, string $action): ?string
    {
        $key = $request->clientIp . '|' . $action . '|' . $request->path;
        if (array_key_exists($key, $this->feedHits)) {
            return $this->feedHits[$key];
        }
        $s = $this->settings;
        $rule = isset($s->feedTables[$action]) ? IpTable::find($request->clientIp, $s->feedTables[$action]) : null;
        foreach ($rule === null ? $s->feedsAt : [] as $f) {
            if ($f['action'] !== $action || ($id = IpTable::find($request->clientIp, $f['table'])) === null) {
                continue;
            }
            foreach ($f['paths'] as $p) {
                if (@preg_match($p, $request->path) === 1) {
                    $rule = $id;
                    break 2;
                }
            }
        }
        if ($rule !== null && (IpAddress::inRanges($request->clientIp, $s->exemptIps) || IpAddress::inRanges($request->clientIp, $s->trustedProxies))) {
            $rule = null;
        }
        if ($rule !== null && $s->crawlers !== []) {
            $id = $this->crawlers()->claims((string) $request->header('user-agent'));
            if ($id !== null && $this->crawlers()->verified($request->clientIp, $id)) {
                $rule = null;                               // a crawler that proved who it is: never by a list
            }
        }
        if (count($this->feedHits) > 64) {
            $this->feedHits = [];
        }
        return $this->feedHits[$key] = $rule;
    }

    private static function hasAt(Settings $s, string $action): bool
    {
        foreach ($s->feedsAt as $f) {
            if ($f['action'] === $action) {
                return true;
            }
        }
        return false;
    }

    /**
     * The request after the budgets: a challenged request goes through the
     * gate (pass cookie, solution, crawler, exempt path, or the page).
     *
     * @return array{decision: Decision, cookies: list<string>, page: ?string, json: ?array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string}, passed: bool}
     */
    public function settle(Decision $decision, Request $request, float $now): array
    {
        if ($decision->action !== Decision::CHALLENGE) {
            return ['decision' => $decision, 'cookies' => [], 'page' => null, 'json' => null, 'passed' => false];
        }
        $r = $this->gate()->resolve($decision, $this->base, $request, $now, $this->gateOptions($decision, $request));
        return $r + ['passed' => $r['decision']->passes()];
    }

    /**
     * How the gate answers this request: an API gets the task as JSON; a
     * form comes back after the check (a pause would lose what was typed);
     * a spent budget's solution starts the budget's counter again.
     *
     * @return array{solution: ?string, fresh: ?int, api: bool, earn: array{window: int}|null, resend: array{action: string, fields: list<array{0: string, 1: string}>}|false|null}
     */
    private function gateOptions(Decision $d, Request $request): array
    {
        $api = $this->isApi($request);
        $budget = $d->spent ? ($this->settings->budgets[$d->reason] ?? null) : null;
        return [
            'solution' => $this->postedSolution(),
            // challenge … max-age: a pass issued at most that long ago.
            'fresh' => $d->reason === 'always' ? $this->alwaysAge : null,
            'api' => $api,
            'earn' => $budget !== null ? ['window' => $budget->window, 'counter' => $budget->counter()] : null,
            'resend' => !$api && $request->method !== 'GET' && $request->method !== 'HEAD' ? self::resendFields($request) : null,
        ];
    }

    /**
     * Whether a request is an API's: it asks for or sends JSON, a page's
     * script sent it in the background (isBackground()), or its path is one
     * the site named (api-path). A check is then a header, not a page.
     */
    public function isApi(Request $request): bool
    {
        if (self::isBackground($request)) {
            return true;
        }
        $sent = $this->request === $request ? ($_SERVER['CONTENT_TYPE'] ?? '') : '';
        foreach ([(string) $request->header('accept'), is_string($sent) ? $sent : ''] as $type) {
            if ($type !== '' && preg_match('#application/(?:[\w.+-]+\+)?json#i', $type) === 1 && stripos($type, 'text/html') === false) {
                return true;
            }
        }
        foreach ($this->settings->challenge->apiPaths as $p) {
            if (@preg_match($p, $request->matchPath()) === 1) {
                return true;
            }
        }
        return false;
    }

    /**
     * Whether a page's script sent the request in the background -- fetch() or
     * XMLHttpRequest, not the browser for a page, a frame or an image: the
     * browser says so (Sec-Fetch-Dest: empty), and libraries do
     * (X-Requested-With: XMLHttpRequest) where an older browser does not.
     * Such a request cannot show the check page or run it: it gets the check
     * as JSON (429, Request-Shield-Challenge) like an API, so the script can
     * tell a check from the content it asked for. A client that sends the
     * headers without being one gets that answer too -- no way past the check.
     */
    public static function isBackground(Request $request): bool
    {
        return strcasecmp((string) $request->header('sec-fetch-dest'), 'empty') === 0
            || strcasecmp((string) $request->header('x-requested-with'), 'XMLHttpRequest') === 0;
    }

    /**
     * The answer the check inside the form sent with a form (hidden field),
     * taken out of $_POST once read -- the application never sees it.
     */
    private function postedSolution(): ?string
    {
        if ($this->settings->challenge->widgetPath === null) {
            return null;
        }
        $field = $this->settings->challenge->solutionCookie;
        $v = $_POST[$field] ?? null;
        unset($_POST[$field]);
        if (is_string($v) && $v !== '') {
            $this->posted = $v;
        }
        return $this->posted;
    }

    private ?string $posted = null;

    /**
     * The placeholder for the check inside a form, and (once per page) the
     * script: echo Shield::active()?->widget(); -- empty while the widget is
     * off (set widget-path ...).
     *
     * @param string $start "input" (the first input into the form), "load" or "submit"
     */
    public function widget(string $start = 'input'): string
    {
        try {
            $w = $this->settings->challenge->widgetPath;
            return $w === null || $this->settings->mode === 'off' ? '' : \CjwNetwork\RequestShield\Challenge\Widget::html($w, $start);
        } catch (\Throwable $e) {
            self::failed('widget', 'widget() failed, the form has no check: ' . $e->getMessage());
            return '';                              // fail safe: the form works without the check
        }
    }

    /** Whether widget() gives a check (set widget-path, mode not off) -- asking it costs nothing and sends no script. */
    public function hasWidget(): bool
    {
        return $this->settings->challenge->widgetPath !== null && $this->settings->mode !== 'off';
    }

    /** <widgetPath>/challenge (a task as JSON) and <widgetPath>/widget.js. */
    private function serveWidget(string $what, Request $request, float $now): void
    {
        $c = $this->settings->challenge;
        if ($what === 'widget.js') {
            $js = \CjwNetwork\RequestShield\Challenge\Widget::script();
            $etag = '"' . substr(hash('sha256', $js), 0, 16) . '"';
            header('Content-Type: text/javascript; charset=utf-8');
            header('Cache-Control: public, max-age=86400');
            header('ETag: ' . $etag);
            if (($request->header('if-none-match') ?? '') === $etag) {
                http_response_code(304);
                return;
            }
            echo $js;
            return;
        }
        if ($what !== 'challenge') {
            http_response_code(404);
            return;
        }
        $texts = Texts::all(Texts::language($c->language, $request->header('accept-language'), $c->texts), $c->texts);
        $task = $this->gate()->widgetTask($request, $now);
        $until = $task === null ? $this->gate()->passUntil($request, $now) : 0;
        header('Content-Type: application/json; charset=utf-8');
        header('Cache-Control: no-store');
        header('Vary: Accept-Language');
        header('X-Robots-Tag: noindex');
        echo json_encode([
            'passed' => $task === null,
            // With a pass: until when it holds; the widget fetches a task before then.
            'until' => $task === null ? $until : null,
            'challenge' => $task,
            'field' => $c->solutionCookie,
            'texts' => ['checking' => $texts['widget-checking'], 'checked' => $texts['widget-checked'], 'failed' => $texts['widget-failed']],
            // The box's "?": the check in plain words, for visitors (set docs-url off: none).
            'about' => ($about = Help::explained($this->settings->docsUrl)) !== null ? ['url' => $about, 'text' => $texts['about']] : null,
        ], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP);
    }

    /**
     * For the application: go on only with a browser that passed the check.
     * With a valid pass (issued in the last $fresh seconds, when given) this
     * returns; otherwise the visitor gets the check page and the request
     * ends here -- for a form, with its fields, which are sent again once the
     * check is done, so nothing typed is lost:
     *
     *   Shield::active()?->requirePass();        // before saving a comment
     *   Shield::active()?->requirePass(300);     // a pass from the last 5 minutes
     *
     * Call it before acting on the request. Forms with files, or larger than
     * 256 KB, cannot be carried through: the visitor is asked to send them
     * again (better: require the pass on the form's page, before).
     */
    public function requirePass(?int $fresh = null): void
    {
        try {
            $this->requirePassNow($fresh);
        } catch (\Throwable $e) {
            self::failed('requirePass', 'requirePass() failed and let the request through: ' . $e->getMessage());
        }
    }

    /** requirePass() proper. */
    private function requirePassNow(?int $fresh): void
    {
        $request = $this->request;
        if ($request === null || $this->settings->mode === 'off' || ($this->passed && $fresh === null)) {
            return;
        }
        $now = microtime(true);
        // The answer out of the form first: a used one must not be sent again with it.
        $solution = $this->postedSolution();
        $resend = $request->method === 'GET' || $request->method === 'HEAD' ? null : self::resendFields($request);
        $r = $this->gate()->resolve(Decision::challenge('app'), Decision::allowUncached('app'), $request, $now,
            ['forced' => true, 'fresh' => $fresh, 'resend' => $resend, 'solution' => $solution]);
        if (!headers_sent()) {
            foreach ($r['cookies'] as $cookie) {
                header('Set-Cookie: ' . $cookie, false);
            }
        }
        if ($r['decision']->passes()) {
            $this->passed = true;
            return;
        }
        if ($this->settings->mode === 'monitor') {
            $this->watched($r['decision'], $request, $now, $this);
            return;
        }
        $this->stop($r['decision'], $request, $r['page'], $now);
        exit;
    }

    /** Answers with the check page (or a status page) instead of the application's. */
    /** @param array{algorithm: string, challenge: string, maxnumber: int, salt: string, signature: string}|null $json the task for an API */
    private function stop(Decision $d, Request $request, ?string $page, float $now, bool $echo = true, ?array $json = null, bool $log = true): string
    {
        $s = $this->settings;
        $rule = $this->explain($d, $request);
        $reference = $page === null && $json === null ? ErrorPage::reference() : null;      // a refusal page's reference (0030)
        if ($log) {
            Log::note($s, $request, $d, $rule, $now, false, $reference);
        }
        while ($echo && ob_get_level() > 0) {
            ob_end_clean();                 // nothing of the application's page
        }
        if ($json !== null) {
            $body = (new Responder())->api($d, $json, $s->debugHeader, $rule);
            if ($echo) {
                echo $body;
            }
            return $body;
        }
        $c = $s->challenge;
        $texts = Texts::all(Texts::language($c->language, $request->header('accept-language'), $c->texts), $c->texts);
        $responder = new Responder();
        if ($page === null && $this->isApi($request)) {
            // A program: the refusal as JSON (0030).
            $responder->headers($d, $s->debugHeader, $rule, false, true);
            $body = $request->method === 'HEAD' ? '' : json_encode(ErrorPage::json($d, $reference), JSON_UNESCAPED_SLASHES) . "\n";
        } else {
            [$body, $builtIn] = $responder->page($d, $page, $texts, $c->home, PageHook::asker($s), $request, $c->logo, $reference, $s->errorPages);
            $responder->headers($d, $s->debugHeader, $rule, $builtIn);
            $body = $request->method === 'HEAD' ? '' : $body;
        }
        if ($echo) {
            echo $body;
        }
        return $body;
    }

    /**
     * A form's fields as the application got them, to put in the check page;
     * false when they cannot be carried (files, too large, too many).
     *
     * @return array{action: string, fields: list<array{0: string, 1: string}>}|false
     */
    private static function resendFields(Request $request)
    {
        foreach ($_FILES as $file) {
            if (is_array($file) && ($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
                return false;
            }
        }
        $fields = [];
        $bytes = 0;
        $walk = static function (array $values, string $prefix) use (&$walk, &$fields, &$bytes): bool {
            foreach ($values as $key => $value) {
                $name = $prefix === '' ? (string) $key : $prefix . '[' . $key . ']';
                if (is_array($value)) {
                    if (!$walk($value, $name)) {
                        return false;
                    }
                    continue;
                }
                $value = is_scalar($value) ? (string) $value : '';
                $fields[] = [$name, $value];
                $bytes += strlen($name) + strlen($value);
                if ($bytes > self::RESEND_MAX_BYTES || count($fields) > 1000) {
                    return false;
                }
            }
            return true;
        };
        /** @var array<mixed> $post */
        $post = $_POST;
        return $walk($post, '') ? ['action' => $request->rawUri, 'fields' => $fields] : false;
    }

    /**
     * X-RS-Check: 1[; fresh=<seconds>] from the application, on a page (a
     * form's): the page is kept back until it is finished; without a pass the
     * visitor gets the check page instead. The header never reaches the
     * browser.
     */
    private function watchForChallengeHeader(): void
    {
        $decided = null;
        ob_start(function (string $buffer, int $phase) use (&$decided): string {
            try {
                if ($decided === null) {
                    $decided = '';
                    foreach (headers_list() as $h) {
                        if (preg_match('/^X-RS-Check:\s*(.*)$/i', $h, $m)) {
                            header_remove('X-RS-Check');
                            $page = $this->challengeFor(trim($m[1]));
                            if ($page !== null) {
                                $decided = $page;
                            }
                            break;
                        }
                    }
                    if ($decided !== '') {
                        return $decided;
                    }
                    $decided = false;
                }
                return $decided === false ? $buffer : '';     // after the check page: nothing of the application's
            } catch (\Throwable $e) {
                self::failed('app-challenge', 'the check the application asked for failed, its page went out: ' . $e->getMessage());
                $decided = false;
                return $buffer;                               // fail safe: the application's page as it is
            }
        });
    }

    /** The check page for a page the application marked, or null when the visitor has a pass. */
    private function challengeFor(string $value): ?string
    {
        $request = $this->request;
        if ($request === null || !preg_match('/^1\s*(?:;|$)/', $value)) {
            return null;
        }
        $fresh = preg_match('/fresh=(\d+)/', $value, $m) ? (int) $m[1] : null;
        if ($this->passed && $fresh === null) {
            return null;
        }
        $now = microtime(true);
        $r = $this->gate()->resolve(Decision::challenge('app'), Decision::allowUncached('app'), $request, $now, ['forced' => true, 'fresh' => $fresh]);
        foreach ($r['cookies'] as $cookie) {
            header('Set-Cookie: ' . $cookie, false);
        }
        if ($r['decision']->passes()) {
            $this->passed = true;
            return null;
        }
        if ($this->settings->mode === 'monitor') {
            $this->watched($r['decision'], $request, $now, $this);
            return null;
        }
        return $this->stop($r['decision'], $request, $r['page'], $now, false);
    }

    /**
     * Counts one event against a budget that no rule counts by itself -- a
     * cache miss, a failed sign-in -- and says what the client has earned.
     * Budgets marked 'onDemand' => true in the configuration are only counted here.
     */
    public function consume(string $budget, ?Request $request = null, ?float $now = null, bool $answer = false): Decision
    {
        try {
            return $this->consumeNow($budget, $request, $now, $answer);
        } catch (\Throwable $e) {
            self::failed('consume', "consume($budget) failed and let the request through: " . $e->getMessage());
            return Decision::allowUncached('shield error');
        }
    }

    /** consume() proper. */
    private function consumeNow(string $budget, ?Request $request, ?float $now, bool $answer): Decision
    {
        $b = $this->settings->budgets[$budget] ?? null;
        $request ??= $this->request;
        if ($request === null || $this->settings->mode === 'off') {
            return Decision::allow();
        }
        $now ??= microtime(true);
        if ($b === null) {
            // Only a rule marked "monitor" has it: counted and logged, never acted on.
            $this->watchBudget($budget, $request, $now);
            return Decision::allow();
        }
        $times = $this->base->action === Decision::ALLOW_UNCACHED ? $this->settings->uncachedWeight : 1;
        $d = $this->budgetRule($b)->check($request, $now, $times) ?? Decision::allow();
        if (!$d->passes()) {
            $this->signal($budget, $request, $now);              // ban after 10 logins in 15m
        }
        if ($this->settings->mode === 'monitor') {
            if (!$d->passes()) {
                $this->watched($d, $request, $now, $this);
                return Decision::allowUncached($budget);
            }
            return $d;
        }
        if ($d->passes()) {
            $this->watchBudget($budget, $request, $now);
        }
        // A spent budget that lets its client earn it back: a solution sent
        // with this request (the form again, an API's header) starts it again.
        if ($d->spent) {
            $r = $this->gate()->resolve($d, Decision::allowUncached($budget), $request, $now, $this->gateOptions($d, $request));
            if (!headers_sent()) {
                foreach ($r['cookies'] as $cookie) {
                    header('Set-Cookie: ' . $cookie, false);
                }
            }
            if ($r['decision']->passes()) {
                return $r['decision'];
            }
            if ($answer) {
                $this->stop($r['decision'], $request, $r['page'], $now, true, $r['json']);
                exit;
            }
            return $d;
        }
        if ($d->action !== Decision::ALLOW && ($this->settings->logFile !== null || $this->settings->liveEnabled)) {
            Log::note($this->settings, $request, $d, $this->explain($d, $request), $now);
        }
        // answer: true -- the shield answers a refusal itself (a pause, the
        // check) and the request ends here: Shield::active()?->consume('posts', answer: true)
        if ($answer && !$d->passes()) {
            $this->stop($d, $request, null, $now, true, null, false);
            exit;
        }
        return $d;
    }

    /** An on-demand budget of the rules marked "monitor": what it would decide, logged. */
    private function watchBudget(string $budget, Request $request, float $now): void
    {
        $m = $this->settings->monitor;
        $w = $this->watcher($request);
        if ($m === null || $w === null || !isset($m->budgets[$budget])) {
            return;
        }
        $d = $w->budgetRule($m->budgets[$budget])->check($request, $now);
        if ($d !== null && !$d->passes()) {
            $this->watched($d, $request, $now, $w);
        }
    }

    private function budgetRule(Budget $b): BudgetRule
    {
        return new BudgetRule($this->store, $b->name, $b->limit, $b->window, $b->challengeAt,
            $this->settings->exemptIps, $this->settings->ipv6Prefix, $b->earnBack, $b->counter(), $b->paths);
    }

    private function gate(): Gate
    {
        $c = $this->settings->challenge;
        return new Gate($c, Secret::resolve($c->secret, $this->settings->storeDir),
            $this->settings->crawlers === [] ? null : $this->crawlers(), $this->settings->ipv6Prefix, $this->store,
            PageHook::asker($this->settings), $this->settings->docsUrl);
    }

    private ?Crawlers $crawlers = null;

    /**
     * The known crawlers, with what verifying them costs remembered for a day
     * per address (APCu, else files in store-dir) and DNS lookups limited
     * (dns-lookups a minute, for all requests together).
     */
    public function crawlers(): Crawlers
    {
        if ($this->crawlers !== null) {
            return $this->crawlers;
        }
        $c = $this->settings->challenge;
        $dir = $this->settings->storeDir;
        $apcu = ApcuStore::usable();
        return $this->crawlers = Crawlers::of($this->settings,
            static function (string $key) use ($apcu, $dir): ?string {
                if ($apcu) {
                    $v = apcu_fetch('rshield:' . $key);
                    return is_string($v) ? $v : null;
                }
                $f = $dir . '/se/' . md5($key);
                $mtime = @filemtime($f);
                if ($mtime === false || $mtime <= time() - 86400) {
                    return null;
                }
                $v = @file_get_contents($f);
                return is_string($v) ? $v : null;
            },
            static function (string $key, string $value) use ($apcu, $dir): void {
                if ($apcu) {
                    apcu_store('rshield:' . $key, $value, 86400);
                    return;
                }
                Files::write($dir . '/se/' . md5($key), $value);
            },
            // New DNS lookups per minute, for all requests together (the store).
            function () use ($c): bool {
                return $c->dnsLookups > 0 && $this->store->hit('se-lookups', 60, microtime(true)) <= $c->dnsLookups;
            },
        );
    }

    /**
     * The store this shield counts in -- for a page that shows what a request
     * would meet now (the demo's answer, Inspector), never written through here.
     */
    public function store(): Store
    {
        return $this->store;
    }

    /** The store the settings ask for ("auto": APCu when usable, else files). */
    public static function storeFor(Settings $s): Store
    {
        switch ($s->store) {
            case 'apcu':
                return new ApcuStore();
            case 'file':
                return new FileStore($s->storeDir);
            case 'memory':
                return new MemoryStore();
            default:
                return ApcuStore::usable() ? new ApcuStore() : new FileStore($s->storeDir);
        }
    }
}
}
}

// src/Store/Store.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/**
 * Counters for the budgets: how many requests a key made in a window.
 *
 * A sliding window from two fixed ones: the count in the current window plus
 * the previous window's count weighted by how much of it still overlaps. Two
 * integers per key and window, no timestamps per request, and good enough to
 * tell a visitor from a flood.
 */
interface Store
{
    /**
     * Counts one request for $key and returns the estimated number of requests
     * in the last $window seconds, this one included.
     */
    public function hit(string $key, int $window, float $now): float;

    /** The estimate without counting a request. */
    public function peek(string $key, int $window, float $now): float;

    /** Forgets what was counted for $key in this window and the one before: a fresh start. */
    public function reset(string $key, int $window, float $now): void;

    /**
     * Remembers $key until the Unix time $until (a ban), then forgets it by
     * itself; $until 0 forgets it at once.
     */
    public function mark(string $key, int $until, float $now): void;

    /** Until when $key is marked (a Unix time); 0 when it is not, or no longer. */
    public function marked(string $key, float $now): int;

    /**
     * The keys marked now that start with $prefix, and until when -- for a
     * list of the active bans; never asked while a request is decided.
     *
     * @return array<string, int> key => until
     */
    public function marks(string $prefix, float $now): array;
}
}
}

// src/Store/ApcuStore.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/**
 * Counters in APCu: one atomic apcu_inc() per request. Shared by the processes
 * of one PHP pool (FPM, LSAPI, a forking server), not across servers.
 */
final class ApcuStore implements Store
{
    private string $prefix = 'rshield:';
    public function __construct(string $prefix = 'rshield:')
    {
        $this->prefix = $prefix;
    }

    public static function usable(): bool
    {
        return \CjwNetwork\RequestShield\Capability::apcu();
    }

    public function hit(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        $k = $this->prefix . $window . ':' . $key . ':';
        $ok = false;
        $current = apcu_inc($k . $slot, 1, $ok, $window * 2 + 1);
        if (!$ok || $current === false) {
            $current = 1;
        }
        return SlidingWindow::estimate($current, self::count($k . ($slot - 1)), $weight);
    }

    public function reset(string $key, int $window, float $now): void
    {
        [$slot] = SlidingWindow::position($window, $now);
        $k = $this->prefix . $window . ':' . $key . ':';
        apcu_delete([$k . $slot, $k . ($slot - 1)]);
    }

    public function mark(string $key, int $until, float $now): void
    {
        if ($until <= $now) {
            apcu_delete($this->prefix . 'mark:' . $key);
            return;
        }
        apcu_store($this->prefix . 'mark:' . $key, $until, max(1, $until - (int) $now));
    }

    public function marked(string $key, float $now): int
    {
        $until = apcu_fetch($this->prefix . 'mark:' . $key);
        return is_int($until) && $until > $now ? $until : 0;
    }

    public function marks(string $prefix, float $now): array
    {
        $out = [];
        $start = $this->prefix . 'mark:';
        if (!class_exists(\APCUIterator::class)) {
            return $out;
        }
        foreach (new \APCUIterator('/^' . preg_quote($start . $prefix, '/') . '/', APC_ITER_KEY | APC_ITER_VALUE) as $item) {
            /** @var array{key: string, value: mixed} $item */
            if (is_int($item['value']) && $item['value'] > $now) {
                $out[substr($item['key'], strlen($start))] = $item['value'];
            }
        }
        return $out;
    }

    public function peek(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        $k = $this->prefix . $window . ':' . $key . ':';
        return SlidingWindow::estimate(self::count($k . $slot), self::count($k . ($slot - 1)), $weight);
    }

    private static function count(string $key): int
    {
        $v = apcu_fetch($key);
        return is_int($v) ? $v : 0;
    }
}
}
}

// src/Store/FileStore.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/**
 * Counters in files, for hosting without APCu.
 *
 * A request appends one byte to the file of its key and window; the file's
 * size is the count. An O_APPEND write of one byte is atomic, so neither a
 * lock nor a read-modify-write is needed, and concurrent PHP processes never
 * lose a count. Files of past windows are removed by a small sweep that runs
 * on a fraction of the requests.
 */
final class FileStore implements Store
{
    private string $dir;
    private float $sweepChance = 0.001;
    private int $sweepBudget = 500;
    public function __construct(string $dir, float $sweepChance = 0.001, int $sweepBudget = 500)
    {
        $this->dir = $dir;
        $this->sweepChance = $sweepChance;
        $this->sweepBudget = $sweepBudget;
    }

    public function hit(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        $file = $this->path($key, $window, $slot);
        $fh = @fopen($file, 'ab');
        // The directory is missing on the first hits. Processes creating it at
        // the same moment can make a recursive mkdir() fail in one of them (a
        // parent appeared in between) -- so try again a few times, or that hit
        // would not be counted.
        for ($try = 0; $fh === false && $try < 3; $try++) {
            \CjwNetwork\RequestShield\Files::dir(dirname($file));
            $fh = @fopen($file, 'ab');
        }
        if ($fh === false) {
            return 0.0;     // cannot count: never stop a request for it
        }
        fwrite($fh, "\n");
        $stat = fstat($fh);
        fclose($fh);
        $current = $stat === false ? 1 : (int) $stat['size'];
        if ($this->sweepChance > 0 && mt_rand() / mt_getrandmax() < $this->sweepChance) {
            $this->sweep($now);
        }
        return SlidingWindow::estimate($current, $this->size($this->path($key, $window, $slot - 1)), $weight);
    }

    public function reset(string $key, int $window, float $now): void
    {
        [$slot] = SlidingWindow::position($window, $now);
        @unlink($this->path($key, $window, $slot));
        @unlink($this->path($key, $window, $slot - 1));
    }

    public function peek(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        return SlidingWindow::estimate(
            $this->size($this->path($key, $window, $slot)),
            $this->size($this->path($key, $window, $slot - 1)),
            $weight
        );
    }

    /**
     * A mark is a small file holding its end; written whole (a temporary file,
     * then renamed), so a reader never sees half of one. Read on every request
     * while bans are on: one failed open when there is none.
     */
    public function mark(string $key, int $until, float $now): void
    {
        $file = $this->markPath($key);
        if ($until <= $now) {
            @unlink($file);
            return;
        }
        // The key after the time, for marks(): the file name is only its hash. The key holds an
        // address: file-mode, as the log.
        \CjwNetwork\RequestShield\Files::write($file, $until . "\n" . $key);
    }

    public function marked(string $key, float $now): int
    {
        $file = $this->markPath($key);
        // Nearly always asked for an address nobody banned: a stat is far
        // cheaper than a failed open (whose warning PHP builds, then drops).
        clearstatcache(false, $file);
        if (!is_file($file)) {
            return 0;
        }
        $until = (int) @file_get_contents($file);
        if ($until > $now) {
            return $until;
        }
        if ($until > 0) {
            @unlink($file);                 // over: gone
        }
        return 0;
    }

    public function marks(string $prefix, float $now): array
    {
        $out = [];
        foreach (glob($this->dir . '/*/*.m', GLOB_NOSORT) ?: [] as $file) {
            $text = (string) @file_get_contents($file);
            $nl = strpos($text, "\n");
            $until = (int) $text;
            if ($nl === false || $until <= $now) {
                if ($until > 0 && $until <= $now) {
                    @unlink($file);                 // over: gone
                }
                continue;
            }
            $key = (string) substr($text, $nl + 1);
            if (strncmp($key, $prefix, strlen($prefix)) === 0) {
                $out[$key] = $until;
            }
        }
        return $out;
    }

    private function markPath(string $key): string
    {
        $hash = substr(hash('sha256', 'mark:' . $key), 0, 24);
        return $this->dir . '/' . substr($hash, 0, 2) . '/' . $hash . '.m';
    }

    /** Removes counter files whose window ended more than one window ago. */
    public function sweep(float $now): int
    {
        $removed = 0;
        $seen = 0;
        foreach (glob($this->dir . '/*/*.c', GLOB_NOSORT) ?: [] as $file) {
            if (++$seen > $this->sweepBudget) {
                break;
            }
            // <window>-<slot>-<hash>.c
            if (preg_match('#/(\d+)-(\d+)-[0-9a-f]+\.c$#', $file, $m)
                && ((int) $m[2] + 2) * (int) $m[1] < $now && @unlink($file)) {
                $removed++;
            }
        }
        return $removed;
    }

    private function path(string $key, int $window, int $slot): string
    {
        $hash = substr(hash('sha256', $key), 0, 24);
        return $this->dir . '/' . substr($hash, 0, 2) . '/' . $window . '-' . $slot . '-' . $hash . '.c';
    }

    private function size(string $file): int
    {
        clearstatcache(false, $file);
        $size = @filesize($file);
        return $size === false ? 0 : $size;
    }
}
}
}

// src/Store/MemoryStore.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/** Counters for one process only: tests, and a long-running server's own loop. */
final class MemoryStore implements Store
{
    /** @var array<string, int> */
    private array $counts = [];

    /** @var array<string, int> key => until */
    private array $marks = [];

    public function mark(string $key, int $until, float $now): void
    {
        if ($until <= $now) {
            unset($this->marks[$key]);
            return;
        }
        $this->marks[$key] = $until;
    }

    public function marked(string $key, float $now): int
    {
        $until = $this->marks[$key] ?? 0;
        return $until > $now ? $until : 0;
    }

    public function marks(string $prefix, float $now): array
    {
        $out = [];
        foreach ($this->marks as $key => $until) {
            if ($until > $now && strncmp($key, $prefix, strlen($prefix)) === 0) {
                $out[$key] = $until;
            }
        }
        return $out;
    }

    public function hit(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        $k = $window . ':' . $key . ':';
        $this->counts[$k . $slot] = ($this->counts[$k . $slot] ?? 0) + 1;
        return SlidingWindow::estimate($this->counts[$k . $slot], $this->counts[$k . ($slot - 1)] ?? 0, $weight);
    }

    public function reset(string $key, int $window, float $now): void
    {
        [$slot] = SlidingWindow::position($window, $now);
        $k = $window . ':' . $key . ':';
        unset($this->counts[$k . $slot], $this->counts[$k . ($slot - 1)]);
    }

    public function peek(string $key, int $window, float $now): float
    {
        [$slot, $weight] = SlidingWindow::position($window, $now);
        $k = $window . ':' . $key . ':';
        return SlidingWindow::estimate($this->counts[$k . $slot] ?? 0, $this->counts[$k . ($slot - 1)] ?? 0, $weight);
    }
}
}
}

// src/Store/MonitorStore.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/**
 * The store of the rules marked "monitor": a budget only they have ("monitor
 * limit searches 10/min") is counted; one the enforced rules count already is
 * only looked at -- counted once, whichever rules ask. Never forgets anything:
 * a watched rule starts no counter again.
 */
final class MonitorStore implements Store
{
    private Store $store;
    /**
     * @var array<string, true>
     */
    private array $own;
    /** @param array<string, true> $own the budgets only the monitored rules have */
    public function __construct(Store $store, array $own)
    {
        $this->store = $store;
        $this->own = $own;
    }

    public function hit(string $key, int $window, float $now): float
    {
        $budget = strstr($key, ':', true);
        return $budget !== false && isset($this->own[$budget])
            ? $this->store->hit('monitor:' . $key, $window, $now)
            // Counted by the enforced rules a moment ago (this request included).
            : $this->store->peek($key, $window, $now);
    }

    public function peek(string $key, int $window, float $now): float
    {
        $budget = strstr($key, ':', true);
        return $this->store->peek($budget !== false && isset($this->own[$budget]) ? 'monitor:' . $key : $key, $window, $now);
    }

    public function reset(string $key, int $window, float $now): void
    {
    }

    /** A watched rule bans nobody. */
    public function mark(string $key, int $until, float $now): void
    {
    }

    public function marked(string $key, float $now): int
    {
        return $this->store->marked($key, $now);
    }

    public function marks(string $prefix, float $now): array
    {
        return $this->store->marks($prefix, $now);
    }
}
}
}

// src/Store/PeekStore.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/**
 * A store that only looks: hit() answers what a real hit would count, without
 * counting. For trying a request (Inspector) without spending a
 * visitor's budget.
 */
final class PeekStore implements Store
{
    private Store $store;
    public function __construct(Store $store)
    {
        $this->store = $store;
    }

    public function hit(string $key, int $window, float $now): float
    {
        return $this->store->peek($key, $window, $now) + 1;
    }

    public function peek(string $key, int $window, float $now): float
    {
        return $this->store->peek($key, $window, $now);
    }

    /** Only looks: forgets nothing. */
    public function reset(string $key, int $window, float $now): void
    {
    }

    /** Only looks: marks nothing. */
    public function mark(string $key, int $until, float $now): void
    {
    }

    public function marked(string $key, float $now): int
    {
        return $this->store->marked($key, $now);
    }

    public function marks(string $prefix, float $now): array
    {
        return $this->store->marks($prefix, $now);
    }
}
}
}

// src/Store/SlidingWindow.php
namespace CjwNetwork\RequestShield\Store {
if (true) {
/** The arithmetic every store shares. */
final class SlidingWindow
{
    /**
     * @return array{0: int, 1: float} the current window's number and the
     *         weight of the previous window (1 at its start, 0 at its end)
     */
    public static function position(int $window, float $now): array
    {
        $window = max(1, $window);
        $slot = (int) floor($now / $window);
        $elapsed = ($now - $slot * $window) / $window;
        return [$slot, 1.0 - $elapsed];
    }

    public static function estimate(int $current, int $previous, float $weight): float
    {
        return $current + $previous * $weight;
    }
}
}
}

// src/Texts.php
namespace CjwNetwork\RequestShield {
if (true) {
/**
 * What visitors read -- the browser check, a pause, "not found" -- in their
 * language: the one their browser asks for (Accept-Language) among those
 * there are texts for, else English. Built in: English and German; a site
 * adds or changes texts per language ("set text.de.title ...") or for all
 * languages at once ("set text.title ...").
 *
 * Only used for the answers the shield gives itself, never on a passing
 * request.
 */
final class Texts
{
    /** The keys a site can set. */
    public const KEYS = ['title', 'text', 'noscript', 'nocookies', 'failed', 'sending', 'send-again', 'resend-lost', 'back', 'home', 'widget-checking', 'widget-checked', 'widget-failed', 'spent', 'about',
        'bad-request', 'no-access', 'not-found', 'not-allowed', 'too-long', 'too-many', 'too-large', 'error',
        'bad-request-text', 'no-access-text', 'not-found-text', 'not-allowed-text', 'too-long-text', 'too-many-text', 'too-large-text', 'error-text', 'reference'];

    public const BUILT_IN = [
        'en' => [
            'title' => 'One moment, please',
            'text' => 'Your browser is being checked. This takes a moment and happens only once.',
            'noscript' => 'Please enable JavaScript to continue.',
            'nocookies' => 'Please allow cookies for this site to continue.',
            'failed' => 'The check did not succeed. Please reload the page.',
            'sending' => 'Your browser is being checked; then what you entered is sent. This takes a moment.',
            'send-again' => 'Send again',
            'resend-lost' => 'For your protection, your browser had to be checked first. Please go back and send the form again.',
            'back' => 'Back to the form',
            'home' => 'To the home page',
            'widget-checking' => 'Checking your browser …',
            'widget-checked' => 'Browser checked',
            'widget-failed' => 'Your browser will be checked when you send the form.',
            'about' => 'What is this check?',
            'spent' => 'You sent many requests in a short time. After a quick check of your browser you can go on.',
            'bad-request' => 'Bad request',
            'no-access' => 'No access',
            'not-found' => 'Not found',
            'not-allowed' => 'Not here',
            'too-long' => 'Address too long',
            'too-many' => 'Too many requests',
            'too-large' => 'Request too large',
            'error' => 'Error',
            // The error pages' sentences (0030): what to do, never why.
            'bad-request-text' => 'The address could not be read.',
            'no-access-text' => 'This address is not open to you.',
            'not-found-text' => 'This address does not exist here.',
            'not-allowed-text' => 'This kind of request is not taken at this address.',
            'too-long-text' => 'The address is longer than this site takes.',
            'too-many-text' => 'Please wait %s seconds, then try again.',
            'too-large-text' => 'The request carries more than this site takes.',
            'error-text' => 'This request could not be answered.',
            'reference' => 'Reference',
        ],
        'de' => [
            'title' => 'Einen Moment, bitte',
            'text' => 'Ihr Browser wird geprüft. Das dauert nur einen Moment und geschieht nur einmal.',
            'noscript' => 'Bitte aktivieren Sie JavaScript, um fortzufahren.',
            'nocookies' => 'Bitte erlauben Sie Cookies für diese Website, um fortzufahren.',
            'failed' => 'Die Prüfung ist nicht gelungen. Bitte laden Sie die Seite neu.',
            'sending' => 'Ihr Browser wird geprüft, danach wird gesendet, was Sie eingegeben haben. Das dauert nur einen Moment.',
            'send-again' => 'Erneut senden',
            'resend-lost' => 'Zu Ihrem Schutz musste Ihr Browser zuerst geprüft werden. Bitte gehen Sie zurück und senden Sie das Formular noch einmal.',
            'back' => 'Zurück zum Formular',
            'home' => 'Zur Startseite',
            'widget-checking' => 'Ihr Browser wird geprüft …',
            'widget-checked' => 'Browser geprüft',
            'widget-failed' => 'Ihr Browser wird beim Senden geprüft.',
            'about' => 'Was ist diese Prüfung?',
            'spent' => 'Sie haben in kurzer Zeit viele Anfragen gesendet. Nach einer kurzen Prüfung Ihres Browsers geht es weiter.',
            'bad-request' => 'Ungültige Anfrage',
            'no-access' => 'Kein Zugriff',
            'not-found' => 'Nicht gefunden',
            'not-allowed' => 'Hier nicht erlaubt',
            'too-long' => 'Adresse zu lang',
            'too-many' => 'Zu viele Anfragen',
            'too-large' => 'Anfrage zu groß',
            'error' => 'Fehler',
            'bad-request-text' => 'Die Adresse konnte nicht gelesen werden.',
            'no-access-text' => 'Diese Adresse ist für Sie nicht geöffnet.',
            'not-found-text' => 'Diese Adresse gibt es hier nicht.',
            'not-allowed-text' => 'Diese Art von Anfrage wird unter dieser Adresse nicht angenommen.',
            'too-long-text' => 'Die Adresse ist länger, als diese Website annimmt.',
            'too-many-text' => 'Bitte warten Sie %s Sekunden und versuchen Sie es dann noch einmal.',
            'too-large-text' => 'Die Anfrage ist größer, als diese Website annimmt.',
            'error-text' => 'Diese Anfrage konnte nicht beantwortet werden.',
            'reference' => 'Referenz',
        ],
    ];

    private const STATUS = [400 => 'bad-request', 403 => 'no-access', 404 => 'not-found', 405 => 'not-allowed',
        414 => 'too-long', 429 => 'too-many', 431 => 'too-large'];

    /**
     * The language to answer in: $setting when it names one, else the best
     * of Accept-Language among the languages there are texts for, else "en".
     *
     * @param array<string, string> $own the site's texts ("title", "de.title", "fr.title")
     */
    public static function language(string $setting, ?string $accept, array $own = []): string
    {
        if ($setting !== 'auto') {
            return $setting;
        }
        $available = self::BUILT_IN;
        foreach (array_keys($own) as $key) {
            $dot = strrpos($key, '.');
            if ($dot !== false) {
                $available[substr($key, 0, $dot)] = [];
            }
        }
        $best = 'en';
        $bestQ = 0.0;
        foreach (explode(',', (string) $accept) as $i => $part) {
            $bits = explode(';', trim($part));
            $tag = strtolower(trim($bits[0]));
            $q = 1.0;
            if (isset($bits[1]) && preg_match('/q=([0-9.]+)/', $bits[1], $m)) {
                $q = (float) $m[1];
            }
            $q -= $i * 0.0001;          // equal weights: the first wins
            foreach ([$tag, explode('-', $tag)[0]] as $try) {
                if ($try !== '' && isset($available[$try]) && $q > $bestQ) {
                    [$best, $bestQ] = [$try, $q];
                    break;
                }
            }
        }
        return $best;
    }

    /**
     * Every text in one language: the site's own for that language, else its
     * own for all languages, else the built-in one, else English.
     *
     * @param array<string, string> $own
     * @return array<string, string> key => text, and "lang"
     */
    public static function all(string $lang, array $own = []): array
    {
        $base = explode('-', $lang)[0];
        $out = ['lang' => $lang];
        foreach (self::KEYS as $key) {
            $out[$key] = $own["$lang.$key"] ?? $own["$base.$key"] ?? $own[$key]
                ?? self::BUILT_IN[$lang][$key] ?? self::BUILT_IN[$base][$key] ?? self::BUILT_IN['en'][$key];
        }
        return $out;
    }

    /**
     * The heading of a status page (404: "Not Found", "Nicht gefunden").
     *
     * @param array<string, string> $texts
     */
    public static function status(int $status, array $texts): string
    {
        return $texts[self::key($status)] ?? 'Error';
    }

    /**
     * A status's sentence for the error page (0030): what to do, never why.
     *
     * @param array<string, string> $texts
     */
    public static function sentence(int $status, array $texts): string
    {
        return $texts[self::key($status) . '-text'] ?? $texts['error-text'] ?? '';
    }

    /** The key of a status's texts: not-found, too-many …; error for any other. */
    public static function key(int $status): string
    {
        return self::STATUS[$status] ?? 'error';
    }
}
}
}

// src/Tier.php
namespace CjwNetwork\RequestShield {
use CjwNetwork\RequestShield\Store\ApcuStore;

if (true) {
/**
 * What this installation can do (ADR 0013): PHP is the only requirement;
 * a writable directory and APCu are tiers the shield detects. For the CLI
 * (check, version) -- it stats directories, so never on a request path.
 *
 *   S0 stateless: no writable directory, no APCu -- stateless rules only;
 *      settings compiled on every request; nothing counted.
 *   S1 file: a writable store directory, no APCu -- everything, in files.
 *   S2 APCu: counters in shared memory.
 */
final class Tier
{
    /**
     * @return array{tier: string, store: string, why: list<string>, off: list<string>, chosen: list<string>} the tier,
     *   the store in use, what decided it, what the environment leaves inactive (worth a warning), and what
     *   the settings chose to leave inactive (worth a note, not a warning)
     */
    public static function of(Settings $s, string $cacheDir): array
    {
        $apcu = ApcuStore::usable();
        $store = $s->store === 'auto' ? ($apcu ? 'apcu' : 'file') : $s->store;
        $why = [];
        $off = [];
        $chosen = [];
        $why[] = $apcu ? 'APCu is available' : 'APCu is not available' . (PHP_SAPI === 'cli' ? ' to the CLI (the web server may differ; apc.enable_cli=1 switches it on here)' : '');
        $storeOk = self::writable($s->storeDir);
        $cacheOk = self::writable($cacheDir);
        $why[] = "store-dir $s->storeDir is " . ($storeOk ? 'writable' : 'not writable');
        $why[] = "the compiled settings' directory $cacheDir is " . ($cacheOk ? 'writable' : 'not writable');
        if (!$cacheOk) {
            $off[] = 'the settings are compiled on every request (slow, but correct)';
        }
        if ($store === 'memory') {
            $tier = 'S0';
            $chosen[] = 'set store memory: nothing is counted beyond this request (budgets, bans), no secret is kept (the pass cookie does not outlast a request)';
        } elseif ($store === 'apcu') {
            $tier = 'S2';
            if (!$storeOk) {
                $off[] = 'the secret is not kept (store-dir not writable): a pass cookie does not outlast the APCu memory; lists, feeds, crawler updates and statistics have nowhere to go';
            }
        } elseif ($storeOk) {
            $tier = 'S1';
        } else {
            $tier = 'S0';
            $off[] = 'nothing is counted (budgets, bans, the pace), no secret is kept (the pass cookie does not outlast a request), lists, feeds, crawler updates and statistics have nowhere to go -- stateless rules decide as usual';
        }
        return ['tier' => $tier, 'store' => $store, 'why' => $why, 'off' => $off, 'chosen' => $chosen];
    }

    /** Whether the directory can be written, or made (its nearest existing parent can be written). */
    private static function writable(string $dir): bool
    {
        $d = $dir;
        for ($i = 0; $i < 8 && !is_dir($d); $i++) {
            $parent = dirname($d);
            if ($parent === $d) {
                return false;
            }
            $d = $parent;
        }
        return is_dir($d) && is_writable($d);
    }
}
}
}

namespace {
    // The shipped extensions, by name (as bootstrap.php): a statistics file loaded
    // before the rules are compiled is offered; without it, nothing is loaded.
    if (!defined('REQUEST_SHIELD_EXTENSIONS')) {
        define('REQUEST_SHIELD_EXTENSIONS', ['CjwNetwork\\RequestShield\\Stats\\StatsExtension', 'CjwNetwork\\RequestShield\\Api\\ApiExtension', 'CjwNetwork\\RequestShield\\Cache\\CacheExtension']);
    }
    (static function (): void {
        if (defined('REQUEST_SHIELD_DONE')) {
            return;
        }
        if (PHP_SAPI === 'cli') {
            // Run directly: the command line. Required by a script or a test runner: no effect.
            $argv = $_SERVER['argv'] ?? null;
            if (is_array($argv) && isset($argv[0]) && realpath((string) $argv[0]) === __FILE__) {
                define('REQUEST_SHIELD_DONE', true);
                exit(\CjwNetwork\RequestShield\Cli::main(array_values(array_map('strval', $argv))));
            }
            return;
        }
        define('REQUEST_SHIELD_DONE', true);
        $named = defined('REQUEST_SHIELD_CONFIG') ? constant('REQUEST_SHIELD_CONFIG') : getenv('REQUEST_SHIELD_CONFIG');
        if (is_string($named) && $named !== '') {
            if (is_file($named)) {
                \CjwNetwork\RequestShield\Shield::protectFile($named);
            }
            return;             // named, and not there: nothing -- not another file by surprise
        }
        foreach ([__DIR__ . '/request-shield.rules', __DIR__ . '/config/request-shield.rules', __DIR__ . '/config/request-shield.php'] as $file) {
            if (is_file($file)) {
                \CjwNetwork\RequestShield\Shield::protectFile($file);
                return;
            }
        }
    })();
}
